CREATE OR REPLACE FUNCTION public.accept_tournament_team_invitation(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_invitation public.tournament_team_invitations%rowtype;
  v_user_email text;
  v_email_verified_at timestamptz;
  v_email_has_edge_space boolean;
begin
  if auth.uid() is null or char_length(coalesce(p_token, '')) <> 64 then
    raise exception using errcode = '42501', message = 'TORNEOS_INVITATION_INVALID';
  end if;
  select * into v_invitation from public.tournament_team_invitations
  where token_hash = encode(public.digest(p_token, 'sha256'), 'hex');
  if v_invitation.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_INVITATION_INVALID';
  end if;
  perform 1
  from public.tournament_team_entries entry
  where entry.id = v_invitation.team_entry_id
    and entry.organization_id = v_invitation.organization_id
  for update;
  select * into v_invitation from public.tournament_team_invitations
  where token_hash = encode(public.digest(p_token, 'sha256'), 'hex') for update;
  if v_invitation.id is null or v_invitation.status <> 'pending' then
    raise exception using errcode = '42501', message = 'TORNEOS_INVITATION_INVALID';
  end if;
  if v_invitation.expires_at <= now() then
    raise exception using errcode = '42501', message = 'TORNEOS_INVITATION_EXPIRED';
  end if;
  if not exists (
    select 1
    from public.tournament_organizations organization
    join public.tournament_team_entries entry
      on entry.organization_id = organization.id
    join public.tournaments tournament
      on tournament.organization_id = entry.organization_id
      and tournament.id = entry.tournament_id
    join public.tournament_categories category
      on category.organization_id = entry.organization_id
      and category.tournament_id = entry.tournament_id
      and category.id = entry.category_id
    where organization.id = v_invitation.organization_id
      and organization.status = 'active'
      and entry.id = v_invitation.team_entry_id
      and entry.status in ('invited', 'in_progress', 'changes_requested')
      and tournament.id = v_invitation.tournament_id
      and tournament.status = 'registration'
      and (
        tournament.registration_opens_at is null
        or now() >= tournament.registration_opens_at
      )
      and (
        tournament.registration_closes_at is null
        or now() <= tournament.registration_closes_at
      )
      and category.status = 'active'
  ) or not exists (
    select 1
    from public.tournament_team_managers manager
    where manager.id = v_invitation.manager_id
      and manager.organization_id = v_invitation.organization_id
      and manager.team_entry_id = v_invitation.team_entry_id
      and manager.status = 'pending'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_INVITATION_INVALID';
  end if;
  select lower(email), email_confirmed_at, email is distinct from btrim(email)
  into v_user_email, v_email_verified_at, v_email_has_edge_space
  from auth.users
  where id = auth.uid();
  if v_email_verified_at is null
    or v_email_has_edge_space
    or v_user_email is distinct from v_invitation.email_normalized
  then
    raise exception using errcode = '42501', message = 'TORNEOS_INVITATION_INVALID';
  end if;
  update public.tournament_team_managers set
    user_id = auth.uid(), status = 'active', accepted_at = now()
  where id = v_invitation.manager_id
    and organization_id = v_invitation.organization_id
    and team_entry_id = v_invitation.team_entry_id
    and status = 'pending';
  update public.tournament_team_invitations set status = 'accepted', accepted_at = now()
  where id = v_invitation.id;
  update public.tournament_team_entries set status = case when status = 'invited' then 'in_progress' else status end
  where id = v_invitation.team_entry_id;
  perform public.append_tournament_audit(
    v_invitation.organization_id, 'team_manager.invitation_accepted',
    'team_manager', v_invitation.manager_id, v_invitation.team_entry_id,
    v_invitation.tournament_id, '{}'::jsonb
  );
  return jsonb_build_object(
    'teamEntryId', v_invitation.team_entry_id,
    'organizationId', v_invitation.organization_id,
    'status', 'accepted'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.acknowledge_tournament_document(p_version_id uuid, p_confirm boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_document public.tournament_documents%rowtype;
  v_version public.tournament_document_versions%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select version.* into v_version
  from public.tournament_document_versions version
  where version.id = p_version_id and version.status = 'published';
  select * into v_document
  from public.tournament_documents document
  where document.id = v_version.document_id
    and document.active_version_id = p_version_id
    and document.status = 'published';
  if v_document.id is null
    or not public.can_access_tournament_communications(v_document.tournament_id)
    or (
      v_document.category_id is not null
      and not public.can_read_tournament_participant_hub(
        v_document.tournament_id,v_document.category_id
      )
      and not public.has_tournament_communications_capability(
        v_document.organization_id,'documents.read'
      )
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_DOCUMENT_FORBIDDEN';
  end if;
  insert into public.tournament_document_acknowledgements (
    organization_id,document_id,version_id,user_id,status,confirmed_at
  ) values (
    v_document.organization_id,v_document.id,p_version_id,auth.uid(),
    case when p_confirm then 'confirmed' else 'read' end,
    case when p_confirm then now() else null end
  )
  on conflict (version_id,user_id) do update set
    status = case when p_confirm then 'confirmed'
      else public.tournament_document_acknowledgements.status end,
    confirmed_at = case when p_confirm then
      coalesce(public.tournament_document_acknowledgements.confirmed_at,now())
      else public.tournament_document_acknowledgements.confirmed_at end;
  return jsonb_build_object(
    'documentId',v_document.id,'versionId',p_version_id,
    'status',case when p_confirm then 'confirmed' else 'read' end,
    'confirmationIsLegalAcceptance',false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.activate_verified_fake_tournament_purchase(p_purchase_id uuid, p_provider_payment_id text DEFAULT NULL::text, p_simulated_activation_error_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_environment text;
begin
  select provider_environment into v_environment
  from public.tournament_purchases where id = p_purchase_id;
  return public.activate_verified_tournament_purchase(
    p_purchase_id,'FAKE',v_environment,'approved',null,p_provider_payment_id,
    p_simulated_activation_error_code
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.activate_verified_tournament_purchase(p_purchase_id uuid, p_provider text, p_provider_environment text, p_provider_status text, p_provider_status_detail text DEFAULT NULL::text, p_provider_payment_id text DEFAULT NULL::text, p_simulated_activation_error_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_purchase public.tournament_purchases%rowtype;
  v_offer public.tournament_commercial_offers%rowtype;
  v_product public.tournament_commercial_products%rowtype;
  v_grant_id uuid;
  v_from_status text;
begin
  select * into v_purchase from public.tournament_purchases where id = p_purchase_id for update;
  if v_purchase.id is null or v_purchase.provider <> p_provider
    or v_purchase.provider_environment <> p_provider_environment
    or v_purchase.provider_preference_id is null
    or (p_provider = 'MERCADO_PAGO' and (p_provider_environment <> 'test' or p_provider_payment_id is null)) then
    raise exception using errcode = '22023', message = 'TORNEOS_PURCHASE_INVALID';
  end if;
  if v_purchase.status = 'approved' and v_purchase.entitlement_activated_at is not null then
    if p_provider_payment_id is not null
      and v_purchase.approved_provider_payment_id is distinct from p_provider_payment_id then
      raise exception using errcode = '55000', message = 'TORNEOS_PAYMENT_CONFLICT';
    end if;
    return public.tournament_purchase_projection(v_purchase) || jsonb_build_object('idempotentReplay',true);
  end if;
  if v_purchase.status not in ('preference_created','pending','approved') then
    raise exception using errcode = '55000', message = 'TORNEOS_PURCHASE_TRANSITION_INVALID';
  end if;
  v_from_status := v_purchase.status;
  update public.tournament_purchases
  set activation_attempts = activation_attempts + 1,last_verified_at = now()
  where id = v_purchase.id returning * into v_purchase;
  if p_simulated_activation_error_code is not null then
    update public.tournament_purchases
    set activation_error_code = left(p_simulated_activation_error_code,80)
    where id = v_purchase.id returning * into v_purchase;
    insert into public.tournament_purchase_events (
      purchase_id,organization_id,event_type,from_status,to_status,provider_status,actor_type,metadata
    ) values (
      v_purchase.id,v_purchase.organization_id,'activation.failed',v_purchase.status,
      v_purchase.status,p_provider_status,'service',
      jsonb_build_object('errorCode',v_purchase.activation_error_code,'seasonId',v_purchase.season_id)
    );
    return public.tournament_purchase_projection(v_purchase);
  end if;
  select * into v_offer from public.tournament_commercial_offers
  where product_code = v_purchase.product_code and offer_code = v_purchase.offer_code
    and offer_version = v_purchase.offer_version;
  select * into v_product from public.tournament_commercial_products
  where product_code = v_purchase.product_code;
  if v_offer.product_code is null or v_product.plan_code <> 'PREMIUM'
    or v_product.scope <> 'season' or v_product.billing_model <> 'one_time'
    or v_offer.list_amount <> v_purchase.list_amount_snapshot
    or v_offer.amount <> v_purchase.amount_snapshot
    or v_offer.currency <> v_purchase.currency then
    update public.tournament_purchases set activation_error_code = 'snapshot_mismatch'
    where id = v_purchase.id returning * into v_purchase;
    return public.tournament_purchase_projection(v_purchase);
  end if;
  v_grant_id := public.grant_tournament_season_premium(
    v_purchase.organization_id,v_purchase.season_id,v_purchase.id,
    'Pago ' || v_purchase.provider || ' verificado para la temporada y compra ' || v_purchase.id::text
  );
  insert into public.tournament_season_plan_grant_events (
    season_grant_id,purchase_id,event_type,reason_code,reason,actor_type
  ) select v_grant_id,v_purchase.id,'granted','payment_approved',
    'Premium de temporada activado por pago verificado','provider'
  where not exists (
    select 1 from public.tournament_season_plan_grant_events event
    where event.season_grant_id = v_grant_id and event.event_type = 'granted'
  );
  update public.tournament_purchases set
    status = 'approved',provider_status = left(btrim(p_provider_status),80),
    provider_status_detail = nullif(left(btrim(p_provider_status_detail),120),''),
    approved_provider_payment_id = coalesce(approved_provider_payment_id,p_provider_payment_id,'fake_pay_' || id::text),
    approved_at = coalesce(approved_at,now()),activation_error_code = null,
    entitlement_activated_at = coalesce(entitlement_activated_at,now()),last_verified_at = now()
  where id = v_purchase.id returning * into v_purchase;
  insert into public.tournament_purchase_events (
    purchase_id,organization_id,event_type,from_status,to_status,provider_status,
    provider_status_detail,actor_type,metadata
  ) values (
    v_purchase.id,v_purchase.organization_id,'payment.approved',v_from_status,'approved',
    v_purchase.provider_status,v_purchase.provider_status_detail,'provider',
    jsonb_build_object('providerPaymentId',v_purchase.approved_provider_payment_id,
      'seasonGrantId',v_grant_id,'seasonId',v_purchase.season_id)
  );
  insert into public.tournament_audit_log (
    organization_id,actor_user_id,actor_type,action,resource_type,resource_id,
    tournament_id,metadata
  ) values (
    v_purchase.organization_id,null,'system','billing.season_purchase_activated',
    'tournament_purchase',v_purchase.id,v_purchase.tournament_id,
    jsonb_build_object('seasonGrantId',v_grant_id,'seasonId',v_purchase.season_id)
  );
  return public.tournament_purchase_projection(v_purchase) || jsonb_build_object('idempotentReplay',false);
end;
$function$

CREATE OR REPLACE FUNCTION public.add_tournament_match_event(p_organization_id uuid, p_match_operation_id uuid, p_event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_operation public.tournament_match_operations%rowtype;
  v_event public.tournament_match_events%rowtype;
  v_related_event public.tournament_match_events%rowtype;
  v_is_on_field boolean;
  v_sequence integer;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null or v_operation.status <> 'draft'
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_events.create'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if (p_event->>'teamEntryId')::uuid not in (
    v_operation.home_team_entry_id, v_operation.away_team_entry_id
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_EVENT_TEAM_MISMATCH';
  end if;
  if p_event->>'rosterPlayerId' is not null and not exists (
    select 1 from public.tournament_match_operation_players player
    where player.match_operation_id = v_operation.id
      and player.roster_player_id = (p_event->>'rosterPlayerId')::uuid
      and (
        (p_event->>'eventType' = 'own_goal'
          and player.team_entry_id <> (p_event->>'teamEntryId')::uuid)
        or (p_event->>'eventType' <> 'own_goal'
          and player.team_entry_id = (p_event->>'teamEntryId')::uuid)
      )
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_EVENT_PLAYER_MISMATCH';
  end if;
  if p_event->>'relatedRosterPlayerId' is not null and not exists (
    select 1 from public.tournament_match_operation_players player
    where player.match_operation_id = v_operation.id
      and player.roster_player_id = (p_event->>'relatedRosterPlayerId')::uuid
      and player.team_entry_id = (p_event->>'teamEntryId')::uuid
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_EVENT_PLAYER_MISMATCH';
  end if;
  if p_event->>'eventType' not in ('assist', 'substitution_in')
    and (
      p_event->>'relatedEventId' is not null
      or p_event->>'relatedRosterPlayerId' is not null
    )
  then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_EVENT_RELATION_INVALID';
  end if;
  if p_event->>'eventType' = 'assist'
    and p_event->>'relatedRosterPlayerId' is not null
  then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_EVENT_RELATION_INVALID';
  end if;
  if p_event->>'eventType' = 'assist' and (
    p_event->>'relatedEventId' is null or not exists (
      select 1 from public.tournament_match_events goal
      where goal.id = (p_event->>'relatedEventId')::uuid
        and goal.match_operation_id = v_operation.id
        and goal.team_entry_id = (p_event->>'teamEntryId')::uuid
        and goal.event_type in ('goal', 'penalty_goal')
        and not (goal.event_type = 'penalty_goal' and goal.period = 'penalties')
        and goal.roster_player_id is not null
        and goal.roster_player_id <> (p_event->>'rosterPlayerId')::uuid
        and goal.voided_at is null
    )
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_ASSIST_WITHOUT_GOAL';
  end if;
  if p_event->>'rosterPlayerId' is not null and exists (
    select 1
    from public.tournament_match_operation_players player
    where player.match_operation_id = v_operation.id
      and player.roster_player_id = (p_event->>'rosterPlayerId')::uuid
      and player.attendance_status in ('absent', 'excused')
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_PLAYER_ABSENT';
  end if;
  if p_event->>'rosterPlayerId' is not null
    and p_event->>'eventType' not in ('incident', 'substitution_out')
    and exists (
      select 1 from public.tournament_match_events earlier
      where earlier.match_operation_id = v_operation.id
        and earlier.roster_player_id = (p_event->>'rosterPlayerId')::uuid
        and earlier.event_type in ('red_card', 'second_yellow')
        and earlier.voided_at is null
    )
  then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_PLAYER_ALREADY_SENT_OFF';
  end if;
  if p_event->>'eventType' = 'second_yellow' and not exists (
    select 1 from public.tournament_match_events earlier
    where earlier.match_operation_id = v_operation.id
      and earlier.roster_player_id = (p_event->>'rosterPlayerId')::uuid
      and earlier.event_type = 'yellow_card'
      and earlier.voided_at is null
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_SECOND_YELLOW_WITHOUT_FIRST';
  end if;
  if p_event->>'eventType' = 'substitution_out' then
    select (
      (
        player.lineup_status = 'starter'
        or exists (
          select 1
          from public.tournament_match_events entered
          where entered.match_operation_id = v_operation.id
            and entered.roster_player_id = player.roster_player_id
            and entered.event_type = 'substitution_in'
            and entered.voided_at is null
        )
      )
      and coalesce((
        select max(entered.sequence_number)
        from public.tournament_match_events entered
        where entered.match_operation_id = v_operation.id
          and entered.roster_player_id = player.roster_player_id
          and entered.event_type = 'substitution_in'
          and entered.voided_at is null
      ), 0) >= coalesce((
        select max(exited.sequence_number)
        from public.tournament_match_events exited
        where exited.match_operation_id = v_operation.id
          and exited.roster_player_id = player.roster_player_id
          and exited.event_type = 'substitution_out'
          and exited.voided_at is null
      ), 0)
    ) into v_is_on_field
    from public.tournament_match_operation_players player
    where player.match_operation_id = v_operation.id
      and player.roster_player_id = (p_event->>'rosterPlayerId')::uuid;
    if not coalesce(v_is_on_field, false) then
      raise exception using errcode = '23514', message = 'TORNEOS_MATCH_PLAYER_NOT_ON_FIELD';
    end if;
  end if;
  if p_event->>'eventType' = 'substitution_in' then
    if p_event->>'relatedEventId' is null
      or p_event->>'relatedRosterPlayerId' is null
      or (p_event->>'relatedRosterPlayerId')::uuid
        = (p_event->>'rosterPlayerId')::uuid
    then
      raise exception using errcode = '23514', message = 'TORNEOS_MATCH_SUBSTITUTION_INVALID';
    end if;
    select * into v_related_event
    from public.tournament_match_events
    where id = (p_event->>'relatedEventId')::uuid
      and match_operation_id = v_operation.id
      and team_entry_id = (p_event->>'teamEntryId')::uuid
      and roster_player_id = (p_event->>'relatedRosterPlayerId')::uuid
      and event_type = 'substitution_out'
      and voided_at is null;
    if v_related_event.id is null
      or v_related_event.minute is distinct from (p_event->>'minute')::smallint
      or v_related_event.period is distinct from coalesce(p_event->>'period', 'unknown')
    then
      raise exception using errcode = '23514', message = 'TORNEOS_MATCH_SUBSTITUTION_INVALID';
    end if;
    if exists (
      select 1
      from public.tournament_match_events entered
      where entered.match_operation_id = v_operation.id
        and entered.related_event_id = v_related_event.id
        and entered.event_type = 'substitution_in'
        and entered.voided_at is null
    ) then
      raise exception using errcode = '23514', message = 'TORNEOS_MATCH_SUBSTITUTION_INVALID';
    end if;
    select (
      (
        player.lineup_status = 'starter'
        or exists (
          select 1
          from public.tournament_match_events entered
          where entered.match_operation_id = v_operation.id
            and entered.roster_player_id = player.roster_player_id
            and entered.event_type = 'substitution_in'
            and entered.voided_at is null
        )
      )
      and coalesce((
        select max(entered.sequence_number)
        from public.tournament_match_events entered
        where entered.match_operation_id = v_operation.id
          and entered.roster_player_id = player.roster_player_id
          and entered.event_type = 'substitution_in'
          and entered.voided_at is null
      ), 0) >= coalesce((
        select max(exited.sequence_number)
        from public.tournament_match_events exited
        where exited.match_operation_id = v_operation.id
          and exited.roster_player_id = player.roster_player_id
          and exited.event_type = 'substitution_out'
          and exited.voided_at is null
      ), 0)
    ) into v_is_on_field
    from public.tournament_match_operation_players player
    where player.match_operation_id = v_operation.id
      and player.roster_player_id = (p_event->>'rosterPlayerId')::uuid;
    if coalesce(v_is_on_field, false) then
      raise exception using errcode = '23514', message = 'TORNEOS_MATCH_PLAYER_ALREADY_ON_FIELD';
    end if;
  end if;
  select coalesce(max(sequence_number), 0) + 1 into v_sequence
  from public.tournament_match_events where match_operation_id = v_operation.id;
  insert into public.tournament_match_events (
    organization_id, match_operation_id, match_id, team_entry_id,
    roster_player_id, related_roster_player_id, related_event_id,
    event_type, minute, period, sequence_number, unidentified_player_reason,
    metadata, created_by
  ) values (
    p_organization_id, v_operation.id, v_operation.match_id,
    (p_event->>'teamEntryId')::uuid,
    (p_event->>'rosterPlayerId')::uuid,
    (p_event->>'relatedRosterPlayerId')::uuid,
    (p_event->>'relatedEventId')::uuid,
    p_event->>'eventType', (p_event->>'minute')::smallint,
    coalesce(p_event->>'period', 'unknown'), v_sequence,
    nullif(btrim(p_event->>'unidentifiedPlayerReason'), ''),
    coalesce(p_event->'metadata', '{}'::jsonb), auth.uid()
  ) returning * into v_event;
  if v_event.event_type = 'assist' and (
    v_event.related_event_id is null or not exists (
      select 1 from public.tournament_match_events goal
      where goal.id = v_event.related_event_id
        and goal.match_operation_id = v_operation.id
        and goal.team_entry_id = v_event.team_entry_id
        and goal.event_type in ('goal', 'penalty_goal')
        and not (goal.event_type = 'penalty_goal' and goal.period = 'penalties')
        and goal.roster_player_id is not null
        and goal.roster_player_id <> v_event.roster_player_id
        and goal.voided_at is null
    )
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_ASSIST_WITHOUT_GOAL';
  end if;
  perform public.append_tournament_audit(
    p_organization_id, 'match_event.added', 'match_event', v_event.id,
    v_event.team_entry_id, v_operation.tournament_id,
    jsonb_build_object('eventType', v_event.event_type, 'sequence', v_event.sequence_number)
  );
  return to_jsonb(v_event);
end;
$function$

CREATE OR REPLACE FUNCTION public.add_tournament_roster_player(p_organization_id uuid, p_team_entry_id uuid, p_roster_id uuid, p_arma2_user_id uuid, p_provisional_player_id uuid, p_display_name text, p_avatar_url text, p_shirt_number smallint, p_primary_position text, p_secondary_position text, p_is_goalkeeper boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_entry public.tournament_team_entries%rowtype;
  v_roster public.tournament_rosters%rowtype;
  v_settings public.tournament_roster_settings%rowtype;
  v_player public.tournament_roster_players%rowtype;
  v_count integer;
  v_constraint_name text;
begin
  select * into v_entry from public.tournament_team_entries
  where id = p_team_entry_id and organization_id = p_organization_id;
  select * into v_roster from public.tournament_rosters
  where id = p_roster_id and team_entry_id = p_team_entry_id
    and organization_id = p_organization_id for update;
  if auth.uid() is null or v_entry.id is null or v_roster.id is null
    or v_roster.status not in ('draft', 'changes_requested')
    or not public.can_edit_tournament_team_entry(
      p_organization_id,
      p_team_entry_id
    )
  then raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN'; end if;
  if num_nonnulls(p_arma2_user_id, p_provisional_player_id) <> 1 then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_PLAYER_IDENTITY';
  end if;
  select * into v_settings from public.tournament_roster_settings
  where tournament_id = v_entry.tournament_id
    and organization_id = p_organization_id;
  if v_settings.tournament_id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if p_provisional_player_id is not null then
    if not v_settings.allow_provisional_players
      or not v_settings.allow_players_without_account
      or not exists (
      select 1 from public.tournament_provisional_players
      where id = p_provisional_player_id and organization_id = p_organization_id
    ) then raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN'; end if;
  elsif not exists (select 1 from auth.users where id = p_arma2_user_id) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_roster_id::text, 0));
  select count(*) into v_count from public.tournament_roster_players
  where roster_id = p_roster_id and status = 'active';
  if v_count >= v_settings.maximum_players then
    raise exception using errcode = '23514', message = 'TORNEOS_ROSTER_MAXIMUM_REACHED';
  end if;
  if v_settings.unique_shirt_numbers and p_shirt_number is not null and exists (
    select 1 from public.tournament_roster_players
    where roster_id = p_roster_id and status = 'active' and shirt_number = p_shirt_number
  ) then raise exception using errcode = '23505', message = 'TORNEOS_DUPLICATE_SHIRT_NUMBER'; end if;
  insert into public.tournament_roster_players (
    organization_id, team_entry_id, roster_id, arma2_user_id,
    provisional_player_id, display_name, avatar_url, shirt_number,
    primary_position, secondary_position, is_goalkeeper, added_by
  ) values (
    p_organization_id, p_team_entry_id, p_roster_id, p_arma2_user_id,
    p_provisional_player_id, btrim(p_display_name), p_avatar_url, p_shirt_number,
    p_primary_position, p_secondary_position, coalesce(p_is_goalkeeper, false), auth.uid()
  ) returning * into v_player;
  perform public.append_tournament_audit(
    p_organization_id, 'roster_player.added', 'roster_player', v_player.id,
    p_team_entry_id, v_entry.tournament_id,
    jsonb_build_object('identityType', case when p_arma2_user_id is null then 'provisional' else 'arma2_user' end)
  );
  return jsonb_build_object('id', v_player.id, 'displayName', v_player.display_name, 'status', v_player.status);
exception when unique_violation then
  get stacked diagnostics v_constraint_name = constraint_name;
  if v_constraint_name in (
    'tournament_roster_players_active_user_unique',
    'tournament_roster_players_active_provisional_unique'
  ) then
    raise exception using errcode = '23505', message = 'TORNEOS_DUPLICATE_PLAYER';
  end if;
  raise;
end;
$function$

CREATE OR REPLACE FUNCTION public.append_tournament_audit(p_organization_id uuid, p_action text, p_resource_type text, p_resource_id uuid, p_team_entry_id uuid DEFAULT NULL::uuid, p_tournament_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_id bigint;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if jsonb_typeof(coalesce(p_metadata, '{}'::jsonb)) <> 'object'
    or pg_column_size(coalesce(p_metadata, '{}'::jsonb)) > 8192
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_AUDIT_METADATA';
  end if;
  insert into public.tournament_audit_log (
    organization_id, actor_user_id, actor_type, action, resource_type,
    resource_id, team_entry_id, tournament_id, metadata
  ) values (
    p_organization_id, auth.uid(), 'user', p_action, p_resource_type,
    p_resource_id, p_team_entry_id, p_tournament_id, coalesce(p_metadata, '{}'::jsonb)
  ) returning id into v_id;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.append_tournament_playoff_phase(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_source_phase_id uuid, p_qualifier_count integer, p_double_leg boolean, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_version public.tournament_fixture_versions%rowtype;
  v_source_phase public.tournament_phases%rowtype;
  v_phase public.tournament_phases%rowtype;
  v_sources jsonb := '[]'::jsonb;
  v_index integer;
  v_sequence integer;
  v_participant_count integer;
  v_previous_phase_count integer;
  v_previous_round_count integer;
  v_previous_match_count integer;
  v_round_count integer;
  v_match_count integer;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if p_idempotency_key is null then
    raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;
  if p_qualifier_count not in (2, 4, 8, 16) then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_QUALIFIERS';
  end if;

  if not public.has_tournament_organization_capability(
    p_organization_id, 'fixture.publish'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournaments tournament
    where tournament.id = p_tournament_id
      and tournament.organization_id = p_organization_id
      and tournament.status in ('completed', 'archived')
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_COMPETITION_READ_ONLY';
  end if;

  perform public.assert_tournament_fixture_scope(
    p_organization_id, p_tournament_id, p_category_id,
    'fixture.publish', array['registration', 'scheduled', 'active']::text[]
  );
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:fixture:' || p_tournament_id::text || ':' || p_category_id::text, 0
  ));

  select fixture.* into v_version
  from public.tournament_fixture_versions fixture
  where fixture.organization_id = p_organization_id
    and fixture.tournament_id = p_tournament_id
    and fixture.category_id = p_category_id
    and fixture.status = 'published'
    and fixture.invalidated_at is null
  for update;
  if v_version.id is null then
    raise exception using errcode = '23514', message = 'TORNEOS_PUBLISHED_FIXTURE_REQUIRED';
  end if;

  select phase.* into v_phase
  from public.tournament_phases phase
  where phase.fixture_version_id = v_version.id
    and phase.configuration->>'appendOperationKey' = p_idempotency_key::text;
  if v_phase.id is not null then
    return jsonb_build_object(
      'tournamentId', p_tournament_id,
      'fixtureVersionId', v_version.id,
      'sourcePhaseId', v_phase.configuration->>'sourcePhaseId',
      'phaseId', v_phase.id,
      'status', 'published',
      'roundCount', (select count(*) from public.tournament_rounds where phase_id = v_phase.id),
      'matchCount', (select count(*) from public.tournament_matches where phase_id = v_phase.id)
    );
  end if;

  select phase.* into v_source_phase
  from public.tournament_phases phase
  where phase.id = p_source_phase_id
    and phase.organization_id = p_organization_id
    and phase.tournament_id = p_tournament_id
    and phase.category_id = p_category_id
    and phase.fixture_version_id = v_version.id
    and phase.phase_type = 'league'
    and phase.status <> 'archived'
  for share;
  if v_source_phase.id is null then
    raise exception using errcode = '23514', message = 'TORNEOS_PLAYOFF_SOURCE_INVALID';
  end if;

  if exists (
    select 1 from public.tournament_phases phase
    where phase.fixture_version_id = v_version.id
      and phase.phase_type in (
        'round_of_32', 'round_of_16', 'quarterfinal',
        'semifinal', 'third_place', 'final', 'custom_knockout'
      )
      and phase.status <> 'archived'
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_PLAYOFF_PHASE_EXISTS';
  end if;

  select count(*) into v_participant_count
  from public.tournament_competition_participants participant
  where participant.participant_set_id = v_version.participant_set_id
    and participant.status = 'active';
  if p_qualifier_count > v_participant_count then
    raise exception using errcode = '23514', message = 'TORNEOS_INVALID_QUALIFIERS';
  end if;

  select count(*) into v_previous_phase_count
  from public.tournament_phases where fixture_version_id = v_version.id;
  select count(*) into v_previous_round_count
  from public.tournament_rounds where fixture_version_id = v_version.id;
  select count(*) into v_previous_match_count
  from public.tournament_matches where fixture_version_id = v_version.id;
  select coalesce(max(phase.sequence_number), 0) + 1 into v_sequence
  from public.tournament_phases phase
  where phase.fixture_version_id = v_version.id;

  -- El builder distribuye la primera mitad en slots locales y la segunda en
  -- slots visitantes. Invertir esta última conserva el seeding 1-vs-N,
  -- 2-vs-(N-1), etc., sin hardcodear cruces ni materializar participantes.
  for v_index in 1..(p_qualifier_count / 2) loop
    v_sources := v_sources || jsonb_build_array(jsonb_build_object(
      'type', 'league_position',
      'phaseId', v_source_phase.id,
      'rankNumber', v_index
    ));
  end loop;
  for v_index in reverse p_qualifier_count..(p_qualifier_count / 2 + 1) loop
    v_sources := v_sources || jsonb_build_array(jsonb_build_object(
      'type', 'league_position',
      'phaseId', v_source_phase.id,
      'rankNumber', v_index
    ));
  end loop;

  insert into public.tournament_phases (
    organization_id, tournament_id, category_id, fixture_version_id,
    name, phase_type, sequence_number, status, configuration
  ) values (
    p_organization_id, p_tournament_id, p_category_id, v_version.id,
    'Playoffs', 'custom_knockout', v_sequence, 'generated',
    jsonb_build_object(
      'sourcePhaseId', v_source_phase.id,
      'qualifiers', p_qualifier_count,
      'seeding', 'league_ranking',
      'knockoutLegs', case when p_double_leg then 'double' else 'single' end,
      'appendOperationKey', p_idempotency_key
    )
  ) returning * into v_phase;

  perform public.build_tournament_knockout(
    v_version.id, v_phase.id, v_sources, coalesce(p_double_leg, false), false
  );

  select count(*) into v_round_count
  from public.tournament_rounds where phase_id = v_phase.id;
  select count(*) into v_match_count
  from public.tournament_matches where phase_id = v_phase.id;

  perform public.append_tournament_audit(
    p_organization_id, 'fixture.phase_appended', 'phase', v_phase.id,
    null, p_tournament_id,
    jsonb_build_object(
      'categoryId', p_category_id,
      'fixtureVersionId', v_version.id,
      'sourcePhaseId', v_source_phase.id,
      'qualifierCount', p_qualifier_count,
      'doubleLeg', coalesce(p_double_leg, false),
      'previousPhaseCount', v_previous_phase_count,
      'previousRoundCount', v_previous_round_count,
      'previousMatchCount', v_previous_match_count,
      'appendedRoundCount', v_round_count,
      'appendedMatchCount', v_match_count
    )
  );

  return jsonb_build_object(
    'tournamentId', p_tournament_id,
    'fixtureVersionId', v_version.id,
    'sourcePhaseId', v_source_phase.id,
    'phaseId', v_phase.id,
    'status', 'published',
    'roundCount', v_round_count,
    'matchCount', v_match_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_fake_tournament_payment_status(p_purchase_id uuid, p_status text, p_provider_status_detail text DEFAULT NULL::text, p_provider_payment_id text DEFAULT NULL::text, p_simulated_activation_error_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_purchase public.tournament_purchases%rowtype; v_target text; v_from_status text;
begin
  if p_status = 'approved' then
    return public.activate_verified_fake_tournament_purchase(
      p_purchase_id,p_provider_payment_id,p_simulated_activation_error_code
    );
  end if;
  if p_status not in ('pending','rejected','expired') then
    raise exception using errcode = '22023', message = 'TORNEOS_FAKE_STATUS_INVALID';
  end if;
  select * into v_purchase from public.tournament_purchases where id = p_purchase_id for update;
  if v_purchase.id is null or v_purchase.provider <> 'FAKE'
    or v_purchase.status not in ('preference_created','pending') then
    raise exception using errcode = '55000', message = 'TORNEOS_PURCHASE_TRANSITION_INVALID';
  end if;
  v_from_status := v_purchase.status;
  v_target := p_status;
  update public.tournament_purchases set
    status = v_target,provider_status = p_status,
    provider_status_detail = nullif(left(btrim(p_provider_status_detail),120),''),
    last_verified_at = now(),
    cancelled_at = case when v_target = 'rejected' then now() else cancelled_at end
  where id = v_purchase.id returning * into v_purchase;
  insert into public.tournament_purchase_events (
    purchase_id,organization_id,event_type,from_status,to_status,provider_status,
    provider_status_detail,actor_type
  ) values (
    v_purchase.id,v_purchase.organization_id,'payment.' || v_target,
    v_from_status,
    v_target,p_status,v_purchase.provider_status_detail,'provider'
  );
  return public.tournament_purchase_projection(v_purchase);
end;
$function$

CREATE OR REPLACE FUNCTION public.apply_tournament_purchase_reversal(p_purchase_id uuid, p_action text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_purchase public.tournament_purchases%rowtype;
  v_grant public.tournament_season_plan_grants%rowtype;
  v_event_type text;
  v_reason_code text;
  v_from_status text;
begin
  if p_action not in ('refund','chargeback_disputed','chargeback_restored','chargeback_buyer_won')
    or p_reason is null or char_length(btrim(p_reason)) not between 8 and 500 then
    raise exception using errcode = '22023', message = 'TORNEOS_REVERSAL_INVALID';
  end if;
  select * into v_purchase from public.tournament_purchases where id = p_purchase_id for update;
  if v_purchase.id is null or v_purchase.entitlement_activated_at is null then
    raise exception using errcode = '22023', message = 'TORNEOS_PURCHASE_INVALID';
  end if;
  v_from_status := v_purchase.status;
  select * into v_grant from public.tournament_season_plan_grants
  where origin_purchase_id = v_purchase.id for update;
  if v_grant.id is null then
    raise exception using errcode = '55000', message = 'TORNEOS_PURCHASE_GRANT_MISSING';
  end if;
  v_event_type := case p_action
    when 'chargeback_disputed' then 'suspended'
    when 'chargeback_restored' then 'restored' else 'revoked' end;
  v_reason_code := case p_action
    when 'refund' then 'total_refund'
    when 'chargeback_disputed' then 'chargeback_disputed'
    when 'chargeback_restored' then 'chargeback_restored'
    else 'chargeback_buyer_won' end;
  if (select event_type from public.tournament_season_plan_grant_events
      where season_grant_id = v_grant.id order by id desc limit 1) = v_event_type then
    return public.tournament_purchase_projection(v_purchase) || jsonb_build_object('idempotentReplay',true);
  end if;
  insert into public.tournament_season_plan_grant_events (
    season_grant_id,purchase_id,event_type,reason_code,reason,actor_type
  ) values (v_grant.id,v_purchase.id,v_event_type,v_reason_code,btrim(p_reason),'provider');
  update public.tournament_purchases set
    status = case p_action when 'refund' then 'refunded'
      when 'chargeback_restored' then 'approved' else 'charged_back' end,
    provider_status = p_action,
    refunded_at = case when p_action = 'refund' then now() else refunded_at end,
    charged_back_at = case when p_action in ('chargeback_disputed','chargeback_buyer_won')
      then coalesce(charged_back_at,now()) else charged_back_at end,
    last_verified_at = now()
  where id = v_purchase.id returning * into v_purchase;
  insert into public.tournament_purchase_events (
    purchase_id,organization_id,event_type,from_status,to_status,provider_status,actor_type,metadata
  ) values (
    v_purchase.id,v_purchase.organization_id,'payment.' || p_action,v_from_status,
    v_purchase.status,p_action,'provider',
    jsonb_build_object('seasonGrantEvent',v_event_type,'seasonId',v_purchase.season_id)
  );
  return public.tournament_purchase_projection(v_purchase) || jsonb_build_object('idempotentReplay',false);
end;
$function$

CREATE OR REPLACE FUNCTION public.approve_tournament_team_entry(p_organization_id uuid, p_team_entry_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  return public.review_tournament_team_entry(
    p_organization_id,
    p_team_entry_id,
    'approved',
    p_reason,
    '[]'::jsonb
  );
