$function$

CREATE OR REPLACE FUNCTION public.archive_tournament_announcement(p_announcement_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_announcement public.tournament_announcements%rowtype;
begin
  select * into v_announcement
  from public.tournament_announcements announcement
  where announcement.id = p_announcement_id
  for update;
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if v_announcement.id is null
    or not public.has_tournament_communications_capability(
      v_announcement.organization_id,'announcements.archive'
    )
    or v_announcement.status not in ('published','superseded')
  then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  update public.tournament_announcements
  set status = 'archived',archived_at = now()
  where id = p_announcement_id;
  perform public.append_tournament_audit(
    v_announcement.organization_id,'communications.announcement_archive','announcement',
    p_announcement_id,null,v_announcement.tournament_id,'{}'::jsonb
  );
  return p_announcement_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.archive_tournament_document(p_document_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_document public.tournament_documents%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_document
  from public.tournament_documents document
  where document.id = p_document_id
  for update;
  if v_document.id is null
    or not public.has_tournament_communications_capability(
      v_document.organization_id,'documents.archive'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_DOCUMENT_FORBIDDEN';
  end if;
  update public.tournament_documents
  set status = 'archived',archived_at = now()
  where id = p_document_id;
  perform public.append_tournament_audit(
    v_document.organization_id,'communications.document_archive','tournament_document',
    p_document_id,null,v_document.tournament_id,'{}'::jsonb
  );
  return p_document_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.archive_tournament_fixture(p_organization_id uuid, p_fixture_version_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_version public.tournament_fixture_versions%rowtype;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if auth.uid() is null or char_length(v_reason) not between 3 and 500
    or not public.has_tournament_organization_capability(
      p_organization_id, 'fixture.archive'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  update public.tournament_fixture_versions
  set status = 'archived', archived_at = now()
  where id = p_fixture_version_id
    and organization_id = p_organization_id
    and status = 'draft'
  returning * into v_version;
  if v_version.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  perform public.append_tournament_audit(
    p_organization_id, 'fixture.archived', 'fixture_version', v_version.id,
    null, v_version.tournament_id, jsonb_build_object('reason', v_reason)
  );
  return jsonb_build_object('fixtureVersionId', v_version.id, 'status', 'archived');
end;
$function$

CREATE OR REPLACE FUNCTION public.archive_tournament_team_entry(p_organization_id uuid, p_team_entry_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_entry public.tournament_team_entries%rowtype;
begin
  if auth.uid() is null or not public.has_tournament_organization_capability(
    p_organization_id,
    'team_entries.archive'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) not between 3 and 1200 then
    raise exception using errcode = '22023', message = 'TORNEOS_REASON_REQUIRED';
  end if;
  select * into v_entry
  from public.tournament_team_entries
  where id = p_team_entry_id
    and organization_id = p_organization_id
    and status <> 'archived'
  for update;
  if v_entry.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  update public.tournament_team_invitations
  set status = 'revoked', revoked_at = now()
  where team_entry_id = v_entry.id and status = 'pending';
  update public.tournament_team_entries
  set status = 'archived', archived_at = now()
  where id = v_entry.id
  returning * into v_entry;
  perform public.append_tournament_audit(
    p_organization_id,
    'team_entry.archived',
    'team_entry',
    v_entry.id,
    v_entry.id,
    v_entry.tournament_id,
    jsonb_build_object('reason', left(btrim(p_reason), 240))
  );
  return jsonb_build_object('entryId', v_entry.id, 'status', v_entry.status);
end;
$function$

CREATE OR REPLACE FUNCTION public.assign_first_free_plan_on_tournament_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(new.organization_id::text,41)
  );
  IF EXISTS (
    SELECT 1 FROM public.tournament_organization_plan_state state
    WHERE state.organization_id = new.organization_id
  ) THEN
    RETURN new;
  END IF;

  INSERT INTO public.tournament_organization_plan_state (
    organization_id,first_free_consumed_at,first_free_tournament_id,
    initialization_source
  ) VALUES (new.organization_id,now(),new.id,'first_free');

  INSERT INTO public.tournament_plan_grants (
    organization_id,tournament_id,plan_code,source,reason
  ) VALUES (
    new.organization_id,new.id,'FREE','first_free',
    'Primer torneo gratuito asignado automáticamente por el dominio'
  );
  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.assign_tournament_media_photographer(p_gallery_id uuid, p_user_id uuid, p_revoke boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_gallery public.tournament_media_galleries%rowtype;
begin
  select * into v_gallery from public.tournament_media_galleries where id = p_gallery_id;
  if v_gallery.id is null or not public.has_tournament_media_capability(
    v_gallery.organization_id,'media.update_gallery'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_gallery.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_gallery_id::text,1)
  );
  select * into v_gallery
  from public.tournament_media_galleries
  where id = p_gallery_id
  for update;
  if not p_revoke and v_gallery.status not in ('draft','under_review') then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_GALLERY_IMMUTABLE';
  end if;
  if not exists (select 1 from auth.users where id = p_user_id) then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_ASSIGNMENT_INVALID';
  end if;
  insert into public.tournament_media_assignments (
    organization_id,tournament_id,gallery_id,user_id,status,
    assigned_by,revoked_at
  ) values (
    v_gallery.organization_id,v_gallery.tournament_id,p_gallery_id,p_user_id,
    case when p_revoke then 'revoked' else 'active' end,
    auth.uid(),case when p_revoke then now() else null end
  ) on conflict (gallery_id,user_id) do update set
    can_upload = not p_revoke,
    status = case when p_revoke then 'revoked' else 'active' end,
    revoked_at = case when p_revoke then now() else null end,
    assigned_by = auth.uid();
  perform public.append_tournament_audit(
    v_gallery.organization_id,
    case when p_revoke then 'media.photographer.revoked' else 'media.photographer.assigned' end,
    'media_gallery',p_gallery_id,null,v_gallery.tournament_id,
    jsonb_build_object('scope','upload_only')
  );
  if p_revoke then
    update public.tournament_media_upload_sessions
    set status = 'revoked'
    where gallery_id = p_gallery_id
      and requested_by = p_user_id
      and status = 'issued';
  end if;
  return jsonb_build_object(
    'galleryId',p_gallery_id,'status',case when p_revoke then 'revoked' else 'active' end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.assign_tournament_season_member(p_organization_id uuid, p_season_id uuid, p_membership_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_assignment public.tournament_season_member_assignments%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_season_capability(
    p_organization_id,p_season_id,'members.invite'
  ) then
