CREATE OR REPLACE FUNCTION public.authorize_tournament_social_export(p_organization_id uuid, p_tournament_id uuid, p_piece text, p_theme text, p_include_arma2_branding boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_season_id uuid;
  v_policy jsonb;
  v_premium boolean;
  v_effective_branding boolean;
begin
  select season_id into v_season_id from public.tournaments
  where organization_id=p_organization_id and id=p_tournament_id;
  if v_season_id is null
    or not public.has_tournament_season_access(p_organization_id,v_season_id)
    or not public.has_tournament_social_capability(p_organization_id,'social.export') then
    raise exception using errcode='42501',message='TORNEOS_SOCIAL_EXPORT_FORBIDDEN';
  end if;

  if p_theme not in ('base','heritage','street','scoreboard','editorial') then
    raise exception using errcode='22023',message='TORNEOS_SOCIAL_THEME_UNKNOWN';
  end if;
  if p_piece not in (
    'round_results','next_fixture','standings','mvp','final','champion',
    'scorers','discipline','best_eleven','round_summary','semifinals'
  ) then
    raise exception using errcode='22023',message='TORNEOS_SOCIAL_PIECE_UNKNOWN';
  end if;

  v_policy:=public.resolve_effective_tournament_season_entitlements_at(
    p_organization_id,v_season_id,now(),false,p_tournament_id
  );
  v_premium:=coalesce(
    (v_policy->'capabilities'->>'social_studio.premium')::boolean,
    false
  );

  if not v_premium and (
    p_theme <> 'base'
    or p_piece not in ('round_results','standings','next_fixture')
  ) then
    raise exception using errcode='42501',message='TORNEOS_SOCIAL_PREMIUM_REQUIRED';
  end if;

  if p_theme = 'base' then
    if not v_premium and not p_include_arma2_branding then
      raise exception using errcode='42501',message='TORNEOS_BRANDING_PREMIUM_REQUIRED';
    end if;
    v_effective_branding:=case when v_premium then p_include_arma2_branding else true end;
  else
    -- Every Premium theme is intrinsically white-label, irrespective of input.
    v_effective_branding:=false;
  end if;

  return jsonb_build_object(
    'authorized',true,
    'organizationId',p_organization_id,
    'seasonId',v_season_id,
    'tournamentId',p_tournament_id,
    'piece',p_piece,
    'theme',p_theme,
    'plan',v_policy->>'plan',
    'capability','social_studio.premium',
    'includeArma2Branding',v_effective_branding
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.authorize_tournament_team_photo_read(p_actor_user_id uuid, p_team_photo_id uuid, p_variant text, p_audience text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_photo public.tournament_team_photos%ROWTYPE;
  v_allowed boolean;
BEGIN
  IF p_variant <> 'original' OR p_audience <> 'authenticated_team' THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_TEAM_PHOTO_AUDIENCE_DISABLED';
  END IF;
  SELECT * INTO v_photo
  FROM public.tournament_team_photos photo
  WHERE photo.id = p_team_photo_id
    AND photo.lifecycle_status = 'active';
  IF v_photo.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_TEAM_PHOTO_FORBIDDEN';
  END IF;
  v_allowed := CASE v_photo.editorial_status
    -- Vigente: la ve quien ya veía la inscripción.
    WHEN 'approved' THEN public.can_read_tournament_team_photo_as(
      v_photo.organization_id, v_photo.team_entry_id, p_actor_user_id)
    -- Candidata y rechazada: sólo quien gestiona o quien modera. Nadie más
    -- recibe una firma de material sin publicar.
    ELSE public.can_manage_tournament_team_visual_assets_as(
      v_photo.organization_id, v_photo.team_entry_id, p_actor_user_id,
      'team_entries.update')
      OR public.can_moderate_tournament_team_visual_assets_as(
        v_photo.organization_id, v_photo.team_entry_id, p_actor_user_id,
        'team_entries.update')
  END;
  IF v_allowed IS NOT TRUE THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_TEAM_PHOTO_FORBIDDEN';
  END IF;
  RETURN jsonb_build_object(
    'bucket', v_photo.bucket, 'objectPath', v_photo.object_path,
    'mimeType', v_photo.mime_type, 'width', v_photo.width,
    'height', v_photo.height, 'audience', p_audience
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.auto_schedule_tournament_matches(p_organization_id uuid, p_fixture_version_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_version public.tournament_fixture_versions%rowtype;
  v_tournament public.tournaments%rowtype;
  v_match record;
  v_candidate record;
  v_validation jsonb;
  v_scheduled integer := 0;
  v_unscheduled integer := 0;
  v_unscheduled_details jsonb := '[]'::jsonb;
  v_last_validation jsonb;
  v_done boolean;
begin
  if auth.uid() is null or not public.has_tournament_organization_capability(
    p_organization_id, 'matches.schedule'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  select version.* into v_version from public.tournament_fixture_versions version
  where version.id = p_fixture_version_id
    and version.organization_id = p_organization_id
    and version.status in ('draft', 'published')
    and version.invalidated_at is null;
  select tournament.* into v_tournament from public.tournaments tournament
  where tournament.id = v_version.tournament_id;
  if v_version.id is null or v_tournament.start_date is null or v_tournament.end_date is null
    or v_tournament.end_date - v_tournament.start_date > 366
  then
    raise exception using errcode = '23514', message = 'TORNEOS_AUTOSCHEDULE_RANGE_REQUIRED';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:auto-schedule:' || v_version.id::text, 0
  ));
  for v_match in
    select match_row.*
    from public.tournament_matches match_row
    join public.tournament_rounds round_row on round_row.id = match_row.round_id
    join public.tournament_phases phase on phase.id = match_row.phase_id
    where match_row.fixture_version_id = v_version.id
      and match_row.status = 'unscheduled'
    order by phase.sequence_number, round_row.sort_order,
      round_row.round_number, match_row.match_number
  loop
    if v_match.home_participant_id is null or v_match.away_participant_id is null then
      v_unscheduled := v_unscheduled + 1;
      v_unscheduled_details := v_unscheduled_details || jsonb_build_array(
        jsonb_build_object(
          'matchId', v_match.id,
          'reason', 'unresolved_sources'
        )
      );
      continue;
    end if;
    v_done := false;
    v_last_validation := null;
    for v_candidate in
      with dates as (
        select day::date as slot_date
        from generate_series(
          v_tournament.start_date::timestamp,
          v_tournament.end_date::timestamp,
          interval '1 day'
        ) day
      )
      select
        schedule_window.id as schedule_window_id,
        schedule_window.venue_id,
        schedule_window.court_id,
        (
          dates.slot_date
          + schedule_window.starts_at
          + make_interval(
            mins => slot.step * (
              schedule_window.slot_duration_minutes + schedule_window.buffer_minutes
            )
          )
        ) at time zone venue.timezone as scheduled_at,
        schedule_window.slot_duration_minutes as duration_minutes
      from public.tournament_schedule_windows schedule_window
      join public.tournament_venues venue
        on venue.id = schedule_window.venue_id and venue.status = 'active'
      join public.tournament_courts court
        on court.id = schedule_window.court_id and court.status = 'active'
      cross join dates
      cross join lateral generate_series(
        0,
        greatest(
          floor(
            extract(epoch from (
              schedule_window.ends_at - schedule_window.starts_at
            )) / 60
            / (
              schedule_window.slot_duration_minutes + schedule_window.buffer_minutes
            )
          )::integer - 1,
          0
        )
      ) slot(step)
      where schedule_window.organization_id = p_organization_id
        and schedule_window.tournament_id = v_version.tournament_id
        and schedule_window.status = 'active'
        and schedule_window.window_type = 'availability'
        and schedule_window.court_id is not null
        and (
          schedule_window.category_id is null
          or schedule_window.category_id = v_version.category_id
        )
        and (
          schedule_window.specific_date = dates.slot_date
          or schedule_window.day_of_week = extract(isodow from dates.slot_date)::smallint
        )
        and court.sport_modality = v_tournament.sport_modality
      order by scheduled_at, schedule_window.court_id,
        schedule_window.id, slot.step
    loop
      v_validation := public.validate_tournament_match_schedule(
        p_organization_id, v_match.id, v_candidate.scheduled_at,
        v_candidate.venue_id, v_candidate.court_id, v_candidate.duration_minutes
      );
      v_last_validation := v_validation;
      if jsonb_array_length(v_validation->'blockers') = 0
        and jsonb_array_length(v_validation->'warnings') = 0
      then
        perform public.schedule_tournament_match(
          p_organization_id, v_match.id, v_candidate.scheduled_at,
          v_candidate.venue_id, v_candidate.court_id, v_candidate.duration_minutes,
          false, null
        );
        v_scheduled := v_scheduled + 1;
        v_done := true;
        exit;
      end if;
    end loop;
    if not v_done then
      v_unscheduled := v_unscheduled + 1;
      v_unscheduled_details := v_unscheduled_details || jsonb_build_array(
        jsonb_build_object(
          'matchId', v_match.id,
          'reason', 'no_valid_slot',
          'lastBlockers', coalesce(v_last_validation->'blockers', '[]'::jsonb),
          'lastWarnings', coalesce(v_last_validation->'warnings', '[]'::jsonb)
        )
      );
    end if;
  end loop;
  perform public.append_tournament_audit(
    p_organization_id, 'matches.auto_scheduled', 'fixture_version', v_version.id,
    null, v_version.tournament_id,
    jsonb_build_object('scheduledCount', v_scheduled, 'unscheduledCount', v_unscheduled)
  );
  return jsonb_build_object(
    'fixtureVersionId', v_version.id,
    'scheduledCount', v_scheduled,
    'unscheduledCount', v_unscheduled,
    'unscheduled', v_unscheduled_details
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.begin_tournament_media_asset_delete(p_actor_user_id uuid, p_asset_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_asset public.tournament_media_assets%rowtype;
  v_previous_claim text := coalesce(
    pg_catalog.current_setting('request.jwt.claim.sub', true), ''
  );
  v_object_names jsonb;
BEGIN
  IF p_actor_user_id IS NULL OR p_asset_id IS NULL THEN
    RAISE EXCEPTION USING
      errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  END IF;

  SELECT * INTO v_asset
  FROM public.tournament_media_assets
  WHERE id = p_asset_id;
  IF v_asset.id IS NULL THEN
    RAISE EXCEPTION USING
      errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  END IF;

  PERFORM pg_catalog.set_config(
    'request.jwt.claim.sub', p_actor_user_id::text, true
  );
  BEGIN
    IF NOT public.has_tournament_media_capability(
      v_asset.organization_id, 'media.revoke'
    ) THEN
      RAISE EXCEPTION USING
        errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(v_asset.organization_id::text, 0)
    );
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(v_asset.gallery_id::text, 1)
    );
    SELECT * INTO v_asset
    FROM public.tournament_media_assets
    WHERE id = p_asset_id
    FOR UPDATE;
    IF v_asset.id IS NULL THEN
      RAISE EXCEPTION USING
        errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
    END IF;
    IF v_asset.status IN ('uploading', 'processing') THEN
      RAISE EXCEPTION USING
        errcode = '22023', message = 'TORNEOS_MEDIA_PROCESSING_REQUIRED';
    END IF;

    -- Object names are accepted only from the canonical tenant/tournament/
    -- gallery/UUID path contract. No user filename participates in security.
    IF v_asset.bucket <> 'tournament-media'
      OR v_asset.internal_path !~
        '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}(-(?:thumbnail|grid|detail|original))?\.(jpg|png|webp)$'
      OR EXISTS (
        SELECT 1
        FROM public.tournament_media_variants variant
        WHERE variant.asset_id = p_asset_id
          AND (
            variant.bucket <> 'tournament-media'
            OR variant.internal_path !~
              '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}-(thumbnail|grid|detail|original)\.(jpg|png|webp)$'
          )
      )
    THEN
      RAISE EXCEPTION USING
        errcode = '55000', message = 'TORNEOS_MEDIA_STORAGE_PATH_INVALID';
    END IF;

    IF v_asset.storage_state = 'active' THEN
      UPDATE public.tournament_media_assets
      SET storage_state = 'retention_marked',
          retention_marked_at = pg_catalog.now(),
          storage_purged_at = NULL,
          retention_reason = 'USER_REQUESTED_DELETE:' || v_asset.status,
          updated_at = pg_catalog.now()
      WHERE id = p_asset_id;
    ELSIF NOT (
      v_asset.storage_state = 'retention_marked'
      AND v_asset.retention_reason LIKE 'USER_REQUESTED_DELETE:%'
    ) THEN
      RAISE EXCEPTION USING
        errcode = '22023', message = 'TORNEOS_MEDIA_DELETE_INVALID';
    END IF;

    SELECT coalesce(jsonb_agg(name ORDER BY name), '[]'::jsonb)
    INTO v_object_names
    FROM (
      SELECT v_asset.internal_path AS name
      UNION
      SELECT variant.internal_path
      FROM public.tournament_media_variants variant
      WHERE variant.asset_id = p_asset_id
    ) objects;
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_catalog.set_config(
      'request.jwt.claim.sub', v_previous_claim, true
    );
    RAISE;
  END;
  PERFORM pg_catalog.set_config(
    'request.jwt.claim.sub', v_previous_claim, true
  );

  RETURN jsonb_build_object(
    'assetId', p_asset_id,
    'bucket', 'tournament-media',
    'objectNames', v_object_names,
    'deletePending', true
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.begin_tournament_player_portrait_delete(p_actor_user_id uuid, p_portrait_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_portrait public.tournament_player_portraits%ROWTYPE;
BEGIN
  SELECT * INTO v_portrait FROM public.tournament_player_portraits portrait
  WHERE portrait.id = p_portrait_id
    AND portrait.lifecycle_status IN ('active', 'delete_pending') FOR UPDATE;
  IF v_portrait.id IS NULL OR NOT public.can_manage_tournament_player_portrait_as(
    v_portrait.organization_id, v_portrait.roster_player_id, p_actor_user_id
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_PORTRAIT_FORBIDDEN';
  END IF;
  IF v_portrait.lifecycle_status = 'active' THEN
    UPDATE public.tournament_player_portraits
    SET lifecycle_status = 'delete_pending', publication_consent = 'revoked',
        consent_actor_user_id = p_actor_user_id, consent_changed_at = now(),
        updated_at = now()
    WHERE id = p_portrait_id;
  END IF;
  RETURN jsonb_build_object('bucket', v_portrait.bucket,
    'objectPath', v_portrait.object_path);
END;
$function$

CREATE OR REPLACE FUNCTION public.begin_tournament_team_photo_delete(p_actor_user_id uuid, p_team_photo_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_photo public.tournament_team_photos%ROWTYPE;
  v_is_current boolean;
BEGIN
  SELECT * INTO v_photo
  FROM public.tournament_team_photos photo
  WHERE photo.id = p_team_photo_id
    AND photo.lifecycle_status IN ('active', 'delete_pending')
  FOR UPDATE;
  IF v_photo.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_TEAM_PHOTO_FORBIDDEN';
  END IF;
  v_is_current := v_photo.editorial_status = 'approved';
  IF NOT (
    CASE WHEN v_is_current
      THEN public.can_moderate_tournament_team_visual_assets_as(
        v_photo.organization_id, v_photo.team_entry_id, p_actor_user_id,
        'team_entries.update')
      ELSE public.can_manage_tournament_team_visual_assets_as(
        v_photo.organization_id, v_photo.team_entry_id, p_actor_user_id,
        'team_entries.update')
    END
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_TEAM_PHOTO_FORBIDDEN';
  END IF;
  IF v_photo.lifecycle_status = 'active' THEN
    UPDATE public.tournament_team_photos
    SET lifecycle_status = 'delete_pending', updated_at = now()
    WHERE id = p_team_photo_id;
  END IF;
  RETURN jsonb_build_object(
    'bucket', v_photo.bucket, 'objectPath', v_photo.object_path
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.build_tournament_knockout(p_fixture_version_id uuid, p_phase_id uuid, p_sources jsonb, p_double_leg boolean, p_third_place boolean)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_version public.tournament_fixture_versions%rowtype;
  v_source_count integer;
  v_bracket_size integer := 1;
  v_slots jsonb;
  v_round_size integer;
  v_round_number integer := 0;
  v_tie integer;
  v_leg integer;
  v_round_id uuid;
  v_match_id uuid;
  v_match_number integer;
  v_duration integer;
  v_home_source jsonb;
  v_away_source jsonb;
  v_previous_sources jsonb := '[]'::jsonb;
  v_current_sources jsonb;
  v_advancement_source jsonb;
  v_loser_source jsonb;
  v_semifinal_loser_sources jsonb := '[]'::jsonb;
  v_last_match_id uuid;
  v_tie_key text;
  v_index integer;
  v_legs integer;
begin
  select version.* into v_version
  from public.tournament_fixture_versions version
  where version.id = p_fixture_version_id
    and version.status in ('draft', 'published');
  if v_version.id is null or jsonb_typeof(p_sources) <> 'array' then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_KNOCKOUT';
  end if;
  v_source_count := jsonb_array_length(p_sources);
  if v_source_count < 2 or v_source_count > 64 then
    raise exception using errcode = '23514', message = 'TORNEOS_NOT_ENOUGH_PARTICIPANTS';
  end if;
  while v_bracket_size < v_source_count loop
    v_bracket_size := v_bracket_size * 2;
  end loop;
  v_slots := '[]'::jsonb;
  for v_index in 0..v_bracket_size - 1 loop
    v_slots := v_slots || jsonb_build_array(jsonb_build_object('type', 'bye'));
  end loop;
  for v_index in 0..v_source_count - 1 loop
    v_slots := jsonb_set(
      v_slots,
      array[case
        when v_index < (v_bracket_size / 2)
          then (v_index * 2)::text
        else ((v_index - (v_bracket_size / 2)) * 2 + 1)::text
      end],
      p_sources->v_index
    );
  end loop;
  select modality.suggested_duration_minutes into v_duration
  from public.tournaments tournament
  join public.tournament_sport_modalities modality
    on modality.code = tournament.sport_modality
  where tournament.id = v_version.tournament_id;
  select coalesce(max(match_row.match_number), 0) into v_match_number
  from public.tournament_matches match_row
  where match_row.fixture_version_id = p_fixture_version_id;
  v_round_size := v_bracket_size;
  while v_round_size >= 2 loop
    v_round_number := v_round_number + 1;
    insert into public.tournament_rounds (
      organization_id, tournament_id, category_id, fixture_version_id,
      phase_id, round_number, name, status, sort_order
    ) values (
      v_version.organization_id, v_version.tournament_id, v_version.category_id,
      v_version.id, p_phase_id, v_round_number,
      case v_round_size
        when 2 then 'Final'
        when 4 then 'Semifinal'
        when 8 then 'Cuartos de final'
        when 16 then 'Octavos de final'
        when 32 then 'Dieciseisavos de final'
        else 'Ronda de ' || v_round_size
      end,
      'draft', v_round_number - 1
    ) returning id into v_round_id;
    v_current_sources := '[]'::jsonb;
    for v_tie in 1..(v_round_size / 2) loop
      if v_round_number = 1 then
        v_home_source := v_slots->((v_tie - 1) * 2);
        v_away_source := v_slots->((v_tie - 1) * 2 + 1);
      else
        v_home_source := v_previous_sources->((v_tie - 1) * 2);
        v_away_source := v_previous_sources->((v_tie - 1) * 2 + 1);
      end if;
      if v_home_source->>'type' = 'bye' and v_away_source->>'type' = 'bye' then
        v_current_sources := v_current_sources
          || jsonb_build_array(jsonb_build_object('type', 'bye'));
        continue;
      elsif v_home_source->>'type' = 'bye' then
        v_current_sources := v_current_sources || jsonb_build_array(v_away_source);
        continue;
      elsif v_away_source->>'type' = 'bye' then
        v_current_sources := v_current_sources || jsonb_build_array(v_home_source);
        continue;
      end if;
      v_tie_key := v_version.id::text || ':' || v_round_number || ':' || v_tie;
      v_legs := case when p_double_leg and v_round_size > 2 then 2 else 1 end;
      for v_leg in 1..v_legs loop
        v_match_number := v_match_number + 1;
        insert into public.tournament_matches (
          organization_id, season_id, tournament_id, category_id,
          participant_set_id, fixture_version_id, phase_id, round_id,
          match_number, leg_number, tie_key, home_participant_id,
          away_participant_id, status, duration_minutes, created_by
        ) values (
          v_version.organization_id, v_version.season_id, v_version.tournament_id,
          v_version.category_id, v_version.participant_set_id, v_version.id,
          p_phase_id, v_round_id, v_match_number, v_leg,
          case when v_legs = 2 then v_tie_key else null end,
          case when v_leg = 1 and v_home_source->>'type' = 'participant'
            then (v_home_source->>'participantId')::uuid
            when v_leg = 2 and v_away_source->>'type' = 'participant'
            then (v_away_source->>'participantId')::uuid else null end,
          case when v_leg = 1 and v_away_source->>'type' = 'participant'
            then (v_away_source->>'participantId')::uuid
            when v_leg = 2 and v_home_source->>'type' = 'participant'
            then (v_home_source->>'participantId')::uuid else null end,
          'unscheduled', v_duration, v_version.created_by
        ) returning id into v_match_id;
        perform public.insert_tournament_match_source(
          v_match_id, 'home', case when v_leg = 2 then v_away_source else v_home_source end
        );
        perform public.insert_tournament_match_source(
          v_match_id, 'away', case when v_leg = 2 then v_home_source else v_away_source end
        );
        v_last_match_id := v_match_id;
      end loop;
      if v_legs = 2 then
        v_advancement_source := jsonb_build_object(
          'type', 'winner_of_tie', 'tieKey', v_tie_key
        );
        v_loser_source := jsonb_build_object(
          'type', 'loser_of_tie', 'tieKey', v_tie_key
        );
      else
        v_advancement_source := jsonb_build_object(
          'type', 'winner_of_match', 'matchId', v_last_match_id
        );
        v_loser_source := jsonb_build_object(
          'type', 'loser_of_match', 'matchId', v_last_match_id
        );
      end if;
      v_current_sources := v_current_sources || jsonb_build_array(v_advancement_source);
      if v_round_size = 4 then
        v_semifinal_loser_sources := v_semifinal_loser_sources
          || jsonb_build_array(v_loser_source);
      end if;
    end loop;
    v_previous_sources := v_current_sources;
    v_round_size := v_round_size / 2;
  end loop;
  if p_third_place and jsonb_array_length(v_semifinal_loser_sources) = 2 then
    v_round_number := v_round_number + 1;
    insert into public.tournament_rounds (
      organization_id, tournament_id, category_id, fixture_version_id,
      phase_id, round_number, name, status, sort_order
    ) values (
      v_version.organization_id, v_version.tournament_id, v_version.category_id,
      v_version.id, p_phase_id, v_round_number, 'Tercer puesto', 'draft', v_round_number - 1
    ) returning id into v_round_id;
    v_match_number := v_match_number + 1;
    insert into public.tournament_matches (
      organization_id, season_id, tournament_id, category_id,
      participant_set_id, fixture_version_id, phase_id, round_id,
      match_number, status, duration_minutes, created_by
    ) values (
      v_version.organization_id, v_version.season_id, v_version.tournament_id,
      v_version.category_id, v_version.participant_set_id, v_version.id,
      p_phase_id, v_round_id, v_match_number, 'unscheduled', v_duration, v_version.created_by
    ) returning id into v_match_id;
    perform public.insert_tournament_match_source(
      v_match_id, 'home', v_semifinal_loser_sources->0
    );
    perform public.insert_tournament_match_source(
      v_match_id, 'away', v_semifinal_loser_sources->1
    );
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.build_tournament_round_robin(p_fixture_version_id uuid, p_phase_id uuid, p_group_id uuid, p_participants uuid[], p_double_round boolean)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_version public.tournament_fixture_versions%rowtype;
  v_rotation uuid[] := p_participants;
  v_original uuid[];
  v_count integer;
  v_round_count integer;
  v_round_index integer;
  v_pair_index integer;
  v_leg integer;
  v_home uuid;
  v_away uuid;
  v_temp uuid;
  v_round_id uuid;
  v_match_id uuid;
  v_match_number integer;
  v_duration integer;
begin
  select version.* into v_version
  from public.tournament_fixture_versions version
  where version.id = p_fixture_version_id and version.status = 'draft';
  v_count := coalesce(array_length(v_rotation, 1), 0);
  if v_version.id is null or v_count < 2 then
    raise exception using errcode = '23514', message = 'TORNEOS_NOT_ENOUGH_PARTICIPANTS';
  end if;
  if mod(v_count, 2) = 1 then
    v_rotation := array_append(v_rotation, null::uuid);
    v_count := v_count + 1;
  end if;
  v_original := v_rotation;
  v_round_count := v_count - 1;
  select modality.suggested_duration_minutes into v_duration
  from public.tournaments tournament
  join public.tournament_sport_modalities modality
    on modality.code = tournament.sport_modality
  where tournament.id = v_version.tournament_id;
  select coalesce(max(match_row.match_number), 0) into v_match_number
  from public.tournament_matches match_row
  where match_row.fixture_version_id = p_fixture_version_id;
  for v_leg in 1..case when p_double_round then 2 else 1 end loop
    v_rotation := v_original;
    for v_round_index in 1..v_round_count loop
      insert into public.tournament_rounds (
        organization_id, tournament_id, category_id, fixture_version_id,
        phase_id, group_id, round_number, name, status, sort_order
      ) values (
        v_version.organization_id, v_version.tournament_id, v_version.category_id,
        v_version.id, p_phase_id, p_group_id,
        (v_leg - 1) * v_round_count + v_round_index,
        'Fecha ' || ((v_leg - 1) * v_round_count + v_round_index),
        'draft', (v_leg - 1) * v_round_count + v_round_index - 1
      ) returning id into v_round_id;
      for v_pair_index in 1..(v_count / 2) loop
        v_home := v_rotation[v_pair_index];
        v_away := v_rotation[v_count - v_pair_index + 1];
        if mod(v_round_index + v_pair_index, 2) = 1 then
          v_temp := v_home;
          v_home := v_away;
          v_away := v_temp;
        end if;
        if v_leg = 2 then
          v_temp := v_home;
          v_home := v_away;
          v_away := v_temp;
        end if;
        if v_home is not null and v_away is not null then
          v_match_number := v_match_number + 1;
          insert into public.tournament_matches (
            organization_id, season_id, tournament_id, category_id,
            participant_set_id, fixture_version_id, phase_id, group_id, round_id,
            match_number, leg_number, home_participant_id, away_participant_id, status,
            duration_minutes, created_by
          ) values (
            v_version.organization_id, v_version.season_id, v_version.tournament_id,
            v_version.category_id, v_version.participant_set_id, v_version.id,
            p_phase_id, p_group_id, v_round_id, v_match_number, v_leg, v_home, v_away,
            'unscheduled', v_duration, v_version.created_by
          ) returning id into v_match_id;
          perform public.insert_tournament_match_source(
            v_match_id, 'home',
            jsonb_build_object('type', 'participant', 'participantId', v_home)
          );
          perform public.insert_tournament_match_source(
            v_match_id, 'away',
            jsonb_build_object('type', 'participant', 'participantId', v_away)
          );
        end if;
      end loop;
      v_temp := v_rotation[v_count];
      for v_pair_index in reverse v_count..3 loop
        v_rotation[v_pair_index] := v_rotation[v_pair_index - 1];
      end loop;
      v_rotation[2] := v_temp;
    end loop;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.bulk_schedule_tournament_matches(p_organization_id uuid, p_assignments jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_assignment jsonb;
  v_result jsonb;
  v_results jsonb := '[]'::jsonb;
begin
  if auth.uid() is null or jsonb_typeof(p_assignments) <> 'array'
    or jsonb_array_length(p_assignments) not between 1 and 100
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_SCHEDULE_BATCH';
  end if;
  for v_assignment in select value from jsonb_array_elements(p_assignments)
  loop
    v_result := public.schedule_tournament_match(
      p_organization_id,
      (v_assignment->>'matchId')::uuid,
      (v_assignment->>'scheduledAt')::timestamptz,
      (v_assignment->>'venueId')::uuid,
      (v_assignment->>'courtId')::uuid,
      (v_assignment->>'durationMinutes')::integer,
      coalesce((v_assignment->>'overrideWarnings')::boolean, false),
      v_assignment->>'overrideReason'
    );
    v_results := v_results || jsonb_build_array(v_result);
  end loop;
  return jsonb_build_object('scheduledCount', jsonb_array_length(v_results), 'results', v_results);
end;
$function$

CREATE OR REPLACE FUNCTION public.can_write_tournament_branding_object(p_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_organization_id uuid;
  v_entity_id uuid;
  v_kind text;
BEGIN
  IF auth.uid() IS NULL OR NOT public.is_tournament_branding_path(p_name) THEN
    RETURN false;
  END IF;

  v_organization_id := split_part(p_name, '/', 1)::uuid;
  v_kind := split_part(p_name, '/', 2);
  v_entity_id := split_part(p_name, '/', 3)::uuid;

  IF v_kind = 'organizations' THEN
    RETURN v_entity_id = v_organization_id
      AND public.has_tournament_organization_capability(
        v_organization_id,
        'organization.update'
      );
  END IF;

  IF v_kind = 'tournaments' THEN
    RETURN public.has_tournament_organization_capability(
      v_organization_id,
      'tournaments.update'
    ) AND EXISTS (
      SELECT 1
      FROM public.tournaments tournament
      WHERE tournament.id = v_entity_id
        AND tournament.organization_id = v_organization_id
        AND tournament.status <> 'archived'
    );
  END IF;

  IF v_kind = 'teams' THEN
    RETURN public.can_update_tournament_team_branding(
      v_organization_id,
      v_entity_id
    );
  END IF;

  RETURN false;
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_tournament_media_upload_session(p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_session public.tournament_media_upload_sessions%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_session
  from public.tournament_media_upload_sessions
  where id = p_session_id;
  if v_session.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_session.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_session.gallery_id::text,1)
  );
  select * into v_session
  from public.tournament_media_upload_sessions
  where id = p_session_id
  for update;
  if v_session.requested_by <> auth.uid()
    and not public.has_tournament_media_capability(
      v_session.organization_id,'media.update_gallery'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  if v_session.status = 'revoked' then
    return jsonb_build_object('sessionId',p_session_id,'status','revoked');
  end if;
  if v_session.status <> 'issued' then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_UPLOAD_SESSION_INVALID';
  end if;
  update public.tournament_media_upload_sessions
  set status = 'revoked'
  where id = p_session_id;
  perform public.append_tournament_audit(
    v_session.organization_id,'media.upload_session.cancelled',
    'media_upload_session',p_session_id,null,v_session.tournament_id,
    jsonb_build_object('galleryId',v_session.gallery_id)
  );
  return jsonb_build_object('sessionId',p_session_id,'status','revoked');
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_tournament_purchase(p_purchase_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_purchase public.tournament_purchases%rowtype; v_from_status text;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_purchase from public.tournament_purchases
  where id = p_purchase_id for update;
  if v_purchase.id is null or not (
    v_purchase.buyer_user_id = auth.uid()
    or public.has_tournament_organization_capability(v_purchase.organization_id,'billing.manage')
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_PURCHASE_FORBIDDEN';
  end if;
  if v_purchase.status = 'cancelled' then
    return public.tournament_purchase_projection(v_purchase) || jsonb_build_object('idempotentReplay',true);
  end if;
  if v_purchase.status not in ('created','preference_created','pending') then
    raise exception using errcode = '55000', message = 'TORNEOS_PURCHASE_TRANSITION_INVALID';
  end if;
  v_from_status := v_purchase.status;
  update public.tournament_purchases set
    status = 'cancelled',provider_status = 'cancelled',cancelled_at = now()
  where id = v_purchase.id returning * into v_purchase;
  insert into public.tournament_purchase_events (
    purchase_id,organization_id,event_type,from_status,to_status,provider_status,
    actor_type,actor_user_id
  ) values (
    v_purchase.id,v_purchase.organization_id,'purchase.cancelled',v_from_status,
    'cancelled','cancelled','user',auth.uid()
  );
  return public.tournament_purchase_projection(v_purchase) || jsonb_build_object('idempotentReplay',false);
end;
$function$

CREATE OR REPLACE FUNCTION public.change_tournament_media_gallery_state(p_gallery_id uuid, p_action text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_gallery public.tournament_media_galleries%rowtype;
  v_status text;
  v_capability text;
begin
  select * into v_gallery
  from public.tournament_media_galleries where id = p_gallery_id;
  if v_gallery.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_gallery.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_gallery_id::text,1)
  );
  select * into v_gallery
  from public.tournament_media_galleries where id = p_gallery_id for update;
  v_status := case p_action when 'archive' then 'archived' when 'revoke' then 'revoked' end;
  v_capability := case p_action when 'archive' then 'media.archive' when 'revoke' then 'media.revoke' end;
  if v_gallery.id is null or v_status is null
    or not public.has_tournament_media_capability(v_gallery.organization_id,v_capability)
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  if v_gallery.status in ('archived','revoked') then
    if v_gallery.status = v_status then
      return jsonb_build_object('galleryId',p_gallery_id,'status',v_status);
    end if;
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_TRANSITION_INVALID';
  end if;
  if p_reason is null or char_length(btrim(p_reason)) < 3 then
    raise exception using errcode = '22023', message = 'TORNEOS_REASON_REQUIRED';
  end if;
  update public.tournament_media_galleries
  set status = v_status,
      archived_at = case when v_status = 'archived' then now() else null end,
      revoked_at = case when v_status = 'revoked' then now() else null end,
      version = version + 1
  where id = p_gallery_id;
  update public.tournament_media_assets
  set status = case when v_status = 'revoked' then 'revoked' else 'hidden' end,
      hidden_at = case when v_status = 'archived' then now() else hidden_at end,
      revoked_at = case when v_status = 'revoked' then now() else revoked_at end
  where gallery_id = p_gallery_id
    and status in (
      'uploading','processing','pending_review','approved','published','hidden'
    );
  update public.tournament_media_upload_sessions
  set status = 'revoked'
  where gallery_id = p_gallery_id
    and status = 'issued';
  perform public.append_tournament_audit(
    v_gallery.organization_id,'media.gallery.' || p_action,'media_gallery',
    p_gallery_id,null,v_gallery.tournament_id,jsonb_build_object('reason',btrim(p_reason))
  );
  return jsonb_build_object('galleryId',p_gallery_id,'status',v_status);
end;
$function$

CREATE OR REPLACE FUNCTION public.change_tournament_status(p_organization_id uuid, p_tournament_id uuid, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tournament public.tournaments%rowtype;
  v_checklist jsonb;
  v_capability text := case
    when p_status = 'archived' then 'tournaments.archive'
    else 'tournaments.change_status'
  end;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(
    p_organization_id,
    v_capability
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  select tournament.* into v_tournament
  from public.tournaments tournament
  where tournament.id = p_tournament_id
    and tournament.organization_id = p_organization_id
  for update;

  if v_tournament.id is null
    or not (
      (v_tournament.status = 'draft' and p_status in ('registration', 'archived'))
      or (v_tournament.status = 'registration' and p_status in ('draft', 'archived'))
    )
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_TOURNAMENT_TRANSITION';
  end if;

  if p_status = 'registration' then
    v_checklist := public.tournament_registration_checklist(
      p_organization_id,
      p_tournament_id
    );
    if not (v_checklist->>'ready')::boolean then
      raise exception using
        errcode = '23514',
        message = 'TORNEOS_REGISTRATION_INCOMPLETE';
    end if;
  end if;

  update public.tournaments
  set status = p_status,
      archived_at = case when p_status = 'archived' then now() else null end
  where id = p_tournament_id
  returning * into v_tournament;

  if p_status = 'archived' then
    update public.user_tournament_context_preferences
    set active_tournament_id = null
    where organization_id = p_organization_id
      and active_tournament_id = p_tournament_id;
  end if;

  return jsonb_build_object(
    'id', v_tournament.id,
    'status', v_tournament.status,
    'checklist', case
      when p_status = 'archived' then null
      else coalesce(
        v_checklist,
        public.tournament_registration_checklist(
          p_organization_id,
          p_tournament_id
        )
      )
    end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_tournament_media_upload_sessions(p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_expired jsonb;
  v_purgeable jsonb;
begin
  if p_limit is null or p_limit < 1 or p_limit > 1000 then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_FILTER_INVALID';
  end if;
  with stale as (
    select id
    from public.tournament_media_upload_sessions
    where status = 'issued' and expires_at <= now()
    order by expires_at
    limit p_limit
    for update skip locked
  ), expired as (
    update public.tournament_media_upload_sessions session
    set status = 'expired'
    from stale
    where session.id = stale.id
    returning session.id, session.bucket, session.internal_path
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'sessionId',id,'bucket',bucket,'objectName',internal_path
  )),'[]'::jsonb) into v_expired from expired;

  -- Everything that may be deleted from the bucket: object names reserved by a
  -- session that will never be consumed, and whose name was not adopted by an
  -- asset. An asset's own paths are never purgeable through this contract.
  select coalesce(jsonb_agg(jsonb_build_object(
    'bucket',session.bucket,'objectName',session.internal_path
  )),'[]'::jsonb) into v_purgeable
  from public.tournament_media_upload_sessions session
  where session.status in ('expired','revoked','failed')
    and not exists (
      select 1 from public.tournament_media_assets asset
      where asset.internal_path = session.internal_path
    )
  limit p_limit;

  return jsonb_build_object(
    'expired',v_expired,'purgeable',v_purgeable,'checkedAt',now()
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.clear_tournament_entitlement_override(p_organization_id uuid, p_tournament_id uuid, p_capability text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_override_id uuid;
BEGIN
  IF p_tournament_id IS NULL THEN
    DELETE FROM public.tournament_organization_entitlement_overrides override_row
    WHERE override_row.organization_id = p_organization_id
      AND override_row.capability = p_capability
    RETURNING id INTO v_override_id;
  ELSE
    DELETE FROM public.tournament_entitlement_overrides override_row
    WHERE override_row.organization_id = p_organization_id
      AND override_row.tournament_id = p_tournament_id
      AND override_row.capability = p_capability
    RETURNING id INTO v_override_id;
  END IF;
  IF v_override_id IS NULL THEN
    RETURN false;
  END IF;
  INSERT INTO public.tournament_audit_log (
    organization_id,actor_user_id,actor_type,action,resource_type,
    resource_id,tournament_id,metadata
  ) VALUES (
    p_organization_id,NULL,'system','entitlement.override_removed',
    'entitlement_override',v_override_id,p_tournament_id,
    jsonb_build_object('capability',p_capability)
  );
  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_tournament_media_asset_delete(p_actor_user_id uuid, p_asset_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_asset public.tournament_media_assets%rowtype;
  v_gallery public.tournament_media_galleries%rowtype;
  v_previous_claim text := coalesce(
    pg_catalog.current_setting('request.jwt.claim.sub', true), ''
  );
  v_replacement uuid;
BEGIN
  IF p_actor_user_id IS NULL OR p_asset_id IS NULL THEN
    RAISE EXCEPTION USING
      errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  END IF;

  SELECT * INTO v_asset
  FROM public.tournament_media_assets
  WHERE id = p_asset_id;
  IF v_asset.id IS NULL THEN
    RAISE EXCEPTION USING
      errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  END IF;

  PERFORM pg_catalog.set_config(
    'request.jwt.claim.sub', p_actor_user_id::text, true
  );
  BEGIN
    IF NOT public.has_tournament_media_capability(
      v_asset.organization_id, 'media.revoke'
    ) THEN
      RAISE EXCEPTION USING
        errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(v_asset.organization_id::text, 0)
    );
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(v_asset.gallery_id::text, 1)
    );
    SELECT * INTO v_gallery
    FROM public.tournament_media_galleries
    WHERE id = v_asset.gallery_id
    FOR UPDATE;
    SELECT * INTO v_asset
    FROM public.tournament_media_assets
    WHERE id = p_asset_id
    FOR UPDATE;
    IF v_asset.id IS NULL THEN
      RAISE EXCEPTION USING
        errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
    END IF;
    IF NOT (
      v_asset.storage_state = 'retention_marked'
      AND v_asset.retention_reason LIKE 'USER_REQUESTED_DELETE:%'
    ) THEN
      RAISE EXCEPTION USING
        errcode = '22023', message = 'TORNEOS_MEDIA_DELETE_INVALID';
    END IF;

    IF v_gallery.cover_asset_id = p_asset_id THEN
      SELECT asset.id INTO v_replacement
      FROM public.tournament_media_gallery_items item
      JOIN public.tournament_media_assets asset ON asset.id = item.asset_id
      WHERE item.gallery_id = v_gallery.id
        AND asset.id <> p_asset_id
        AND asset.status IN ('approved', 'published')
        AND asset.storage_state = 'active'
      ORDER BY item.sort_order, asset.created_at
      LIMIT 1;

      UPDATE public.tournament_media_galleries
      SET cover_asset_id = v_replacement,
          status = CASE
            WHEN status = 'published' AND v_replacement IS NULL THEN 'archived'
            ELSE status
          END,
          archived_at = CASE
            WHEN status = 'published' AND v_replacement IS NULL
              THEN pg_catalog.now()
            ELSE archived_at
          END,
          version = version + 1,
          updated_at = pg_catalog.now()
      WHERE id = v_gallery.id;
    END IF;

    DELETE FROM public.tournament_media_gallery_items
    WHERE asset_id = p_asset_id;
    DELETE FROM public.tournament_media_consent_events
    WHERE asset_id = p_asset_id;
    DELETE FROM public.tournament_media_consents
    WHERE asset_id = p_asset_id;
    DELETE FROM public.tournament_media_reports
    WHERE asset_id = p_asset_id;
    DELETE FROM public.tournament_media_relations
    WHERE asset_id = p_asset_id;
    DELETE FROM public.tournament_media_moderation_actions
    WHERE asset_id = p_asset_id;
    DELETE FROM public.tournament_media_variants
    WHERE asset_id = p_asset_id;
    DELETE FROM public.tournament_media_processing_jobs
    WHERE asset_id = p_asset_id
       OR session_id IN (
         SELECT session.id
         FROM public.tournament_media_upload_sessions session
         WHERE session.asset_id = p_asset_id
       );
    DELETE FROM public.tournament_media_upload_sessions
    WHERE asset_id = p_asset_id;
    DELETE FROM public.tournament_media_assets
    WHERE id = p_asset_id;

    -- Domain rows are removed, while the general audit survives without a
    -- foreign key to the deleted asset.
    PERFORM public.append_tournament_audit(
      v_asset.organization_id,
      'media.asset.deleted',
      'media_asset',
      p_asset_id,
      NULL,
      v_asset.tournament_id,
      jsonb_build_object(
        'galleryId', v_asset.gallery_id,
        'storagePurged', true
      )
    );
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_catalog.set_config(
      'request.jwt.claim.sub', v_previous_claim, true
    );
    RAISE;
  END;
  PERFORM pg_catalog.set_config(
    'request.jwt.claim.sub', v_previous_claim, true
  );

  RETURN jsonb_build_object('assetId', p_asset_id, 'deleted', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_tournament_media_simple_upload(p_actor_user_id uuid, p_session_id uuid, p_token text, p_detected_mime text, p_byte_size bigint, p_width integer, p_height integer, p_checksum_sha256 text, p_metadata_stripped boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_session public.tournament_media_upload_sessions%rowtype;
  v_gallery public.tournament_media_galleries%rowtype;
  v_asset_id uuid;
  v_sort integer;
BEGIN
  SELECT * INTO v_session FROM public.tournament_media_upload_sessions
  WHERE id = p_session_id;
  IF v_session.id IS NULL OR v_session.processing_tier <> 'mvp_simple' THEN
    RAISE EXCEPTION USING errcode = '42501',
      message = 'TORNEOS_MEDIA_UPLOAD_SESSION_INVALID';
  END IF;
  PERFORM public.tournament_media_require_upload_tier('mvp_simple');
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_session.organization_id::text,0)
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_session.gallery_id::text,1)
  );
  SELECT * INTO v_gallery FROM public.tournament_media_galleries
  WHERE id = v_session.gallery_id FOR SHARE;
  SELECT * INTO v_session FROM public.tournament_media_upload_sessions
  WHERE id = p_session_id FOR UPDATE;
  IF v_session.status <> 'issued' OR v_session.expires_at <= now()
    OR p_actor_user_id IS NULL OR p_actor_user_id <> v_session.requested_by
    OR encode(public.digest(coalesce(p_token,''),'sha256'),'hex') <> v_session.token_hash
    OR v_gallery.status NOT IN ('draft','under_review')
    OR NOT public.tournament_media_mvp_user_can_upload(
      v_session.requested_by,v_session.gallery_id
    )
  THEN
    RAISE EXCEPTION USING errcode = '42501',
      message = 'TORNEOS_MEDIA_UPLOAD_SESSION_INVALID';
  END IF;
  -- Sin veredicto afirmativo no hay asset. Fail-closed ante NULL o false.
  IF p_metadata_stripped IS NOT TRUE THEN
    UPDATE public.tournament_media_upload_sessions SET status = 'failed'
    WHERE id = p_session_id;
    RAISE EXCEPTION USING errcode = '22023',
      message = 'TORNEOS_MEDIA_METADATA_NOT_STRIPPED';
  END IF;
  IF p_detected_mime <> v_session.requested_mime
    OR p_detected_mime NOT IN ('image/jpeg','image/png','image/webp')
    OR p_byte_size <> v_session.requested_size OR p_byte_size > 4194304
    OR p_width NOT BETWEEN 1 AND 1600 OR p_height NOT BETWEEN 1 AND 1600
    OR p_width::bigint * p_height::bigint > 2560000
    OR p_checksum_sha256 !~ '^[0-9a-f]{64}$'
  THEN
    UPDATE public.tournament_media_upload_sessions SET status = 'failed'
    WHERE id = p_session_id;
    RAISE EXCEPTION USING errcode = '22023', message = 'TORNEOS_MEDIA_FILE_INVALID';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.tournament_media_assets asset
    WHERE asset.organization_id = v_session.organization_id
      AND asset.checksum_sha256 = p_checksum_sha256 AND asset.status <> 'revoked'
  ) THEN
    RAISE EXCEPTION USING errcode = '23505', message = 'TORNEOS_MEDIA_DUPLICATE';
  END IF;

  INSERT INTO public.tournament_media_assets (
    organization_id,tournament_id,gallery_id,internal_path,safe_name,
    detected_mime,byte_size,width,height,checksum_sha256,status,uploaded_by,
    processing_tier,metadata_stripped,normalization_verified_at
  ) VALUES (
    v_session.organization_id,v_session.tournament_id,v_session.gallery_id,
    v_session.internal_path,v_session.safe_name,p_detected_mime,p_byte_size,
    p_width,p_height,p_checksum_sha256,'pending_review',v_session.requested_by,
    'mvp_simple',true,now()
  ) RETURNING id INTO v_asset_id;
  SELECT coalesce(max(sort_order),-1) + 1 INTO v_sort
  FROM public.tournament_media_gallery_items WHERE gallery_id = v_session.gallery_id;
  INSERT INTO public.tournament_media_gallery_items (
    organization_id,tournament_id,gallery_id,asset_id,sort_order,added_by
  ) VALUES (
    v_session.organization_id,v_session.tournament_id,v_session.gallery_id,
    v_asset_id,v_sort,v_session.requested_by
  );
  UPDATE public.tournament_media_upload_sessions
  SET status = 'consumed',consumed_at = now(),asset_id = v_asset_id
  WHERE id = p_session_id;
  INSERT INTO public.tournament_audit_log (
    organization_id,actor_user_id,actor_type,action,resource_type,
    resource_id,tournament_id,metadata
  ) VALUES (
    v_session.organization_id,v_session.requested_by,'system',
    'media.upload.simple_verified','media_asset',v_asset_id,v_session.tournament_id,
    jsonb_build_object(
      'galleryId',v_session.gallery_id,'byteSize',p_byte_size,
      'processingTier','mvp_simple','structuralValidation',true,
      'metadataStripped',true,
      'checksumSha256',p_checksum_sha256
    )
  );
  RETURN jsonb_build_object(
    'assetId',v_asset_id,'galleryId',v_session.gallery_id,
    'safeName',v_session.safe_name,'status','pending_review',
    'processingTier','mvp_simple','metadataStripped',true
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_tournament_media_upload(p_session_id uuid, p_token text, p_detected_mime text, p_byte_size bigint, p_width integer, p_height integer, p_checksum_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_session public.tournament_media_upload_sessions%rowtype;
  v_gallery public.tournament_media_galleries%rowtype;
  v_asset_id uuid;
  v_sort integer;
  v_extension text;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_session
  from public.tournament_media_upload_sessions
  where id = p_session_id;
  if v_session.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_UPLOAD_SESSION_INVALID';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_session.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_session.gallery_id::text,1)
  );
  select * into v_gallery
  from public.tournament_media_galleries
  where id = v_session.gallery_id
  for share;
  select * into v_session
  from public.tournament_media_upload_sessions
  where id = p_session_id
  for update;
  if v_session.id is null
    or v_session.status <> 'issued'
    or v_session.expires_at <= now()
    or encode(public.digest(coalesce(p_token,''),'sha256'),'hex') <> v_session.token_hash
    or auth.uid() <> v_session.requested_by
    or v_gallery.status not in ('draft','under_review')
    or not public.tournament_media_user_can_upload(
      v_session.requested_by,v_session.gallery_id
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_UPLOAD_SESSION_INVALID';
  end if;
  if p_detected_mime <> v_session.requested_mime
    or p_byte_size <> v_session.requested_size
    or p_detected_mime not in ('image/jpeg','image/png','image/webp')
    or p_width < 1 or p_height < 1
    or p_width > 12000 or p_height > 12000
    or p_width::bigint * p_height::bigint > 36000000
    or p_checksum_sha256 !~ '^[0-9a-f]{64}$'
  then
    update public.tournament_media_upload_sessions set status = 'failed'
    where id = p_session_id;
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_FILE_INVALID';
  end if;
  v_extension := case p_detected_mime
    when 'image/jpeg' then 'jpg' when 'image/png' then 'png' else 'webp' end;
  if right(v_session.internal_path,char_length(v_extension) + 1) <> '.' || v_extension then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_FILE_INVALID';
  end if;
  if exists (
    select 1 from public.tournament_media_assets asset
    where asset.organization_id = v_session.organization_id
      and asset.checksum_sha256 = p_checksum_sha256
      and asset.status <> 'revoked'
  ) then
    raise exception using errcode = '23505', message = 'TORNEOS_MEDIA_DUPLICATE';
  end if;

  insert into public.tournament_media_assets (
    organization_id,tournament_id,gallery_id,internal_path,safe_name,
    detected_mime,byte_size,width,height,checksum_sha256,status,uploaded_by
  ) values (
    v_session.organization_id,v_session.tournament_id,v_session.gallery_id,
    v_session.internal_path,v_session.safe_name,p_detected_mime,p_byte_size,
    p_width,p_height,p_checksum_sha256,'pending_review',v_session.requested_by
  ) returning id into v_asset_id;
  select coalesce(max(sort_order),-1) + 1 into v_sort
  from public.tournament_media_gallery_items
  where gallery_id = v_session.gallery_id;
  insert into public.tournament_media_gallery_items (
    organization_id,tournament_id,gallery_id,asset_id,sort_order,added_by
  ) values (
    v_session.organization_id,v_session.tournament_id,v_session.gallery_id,
    v_asset_id,v_sort,v_session.requested_by
  );
  insert into public.tournament_media_variants (
    organization_id,tournament_id,asset_id,kind,internal_path,
    detected_mime,byte_size,width,height,checksum_sha256,status
  ) values (
    v_session.organization_id,v_session.tournament_id,v_asset_id,'original',
    regexp_replace(v_session.internal_path,'\.(jpg|png|webp)$','-original.' || v_extension),
    p_detected_mime,p_byte_size,p_width,p_height,p_checksum_sha256,'ready'
  );
  insert into public.tournament_media_variants (
    organization_id,tournament_id,asset_id,kind,internal_path,
    detected_mime,byte_size,width,height,checksum_sha256,status
  )
  select
    v_session.organization_id,v_session.tournament_id,v_asset_id,variant.kind,
    regexp_replace(
      v_session.internal_path,
      '\.(jpg|png|webp)$',
      '-' || variant.kind || '.' || v_extension
    ),
    p_detected_mime,null,null,null,null,'processing'
  from unnest(array['thumbnail','grid','detail']::text[]) variant(kind);
  update public.tournament_media_upload_sessions
  set status = 'consumed',consumed_at = now(),asset_id = v_asset_id
  where id = p_session_id;
  insert into public.tournament_audit_log (
    organization_id,actor_user_id,actor_type,action,resource_type,
    resource_id,tournament_id,metadata
  ) values (
    v_session.organization_id,v_session.requested_by,'system',
    'media.upload.verified','media_asset',v_asset_id,v_session.tournament_id,
    jsonb_build_object('galleryId',v_session.gallery_id,'byteSize',p_byte_size)
  );
  return jsonb_build_object(
    'assetId',v_asset_id,'galleryId',v_session.gallery_id,
    'safeName',v_session.safe_name,'status','pending_review'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_tournament_media_upload_for_actor(p_actor_user_id uuid, p_session_id uuid, p_token text, p_detected_mime text, p_byte_size bigint, p_width integer, p_height integer, p_checksum_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_previous_claim text := coalesce(
    pg_catalog.current_setting('request.jwt.claim.sub', true), ''
  );
  v_result jsonb;
begin
  if p_actor_user_id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  perform public.tournament_media_require_pipeline_ready();
  perform pg_catalog.set_config(
    'request.jwt.claim.sub', p_actor_user_id::text, true
  );
  begin
    v_result := public.complete_tournament_media_upload(
      p_session_id, p_token, p_detected_mime, p_byte_size,
      p_width, p_height, p_checksum_sha256
    );
  exception when others then
    perform pg_catalog.set_config('request.jwt.claim.sub', v_previous_claim, true);
    raise;
  end;
  perform pg_catalog.set_config('request.jwt.claim.sub', v_previous_claim, true);
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_tournament_media_upload_for_job(p_job_id uuid, p_lease_token text, p_detected_mime text, p_byte_size bigint, p_width integer, p_height integer, p_checksum_sha256 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_job public.tournament_media_processing_jobs%rowtype;
  v_session public.tournament_media_upload_sessions%rowtype;
  v_token text := encode(public.gen_random_bytes(32),'hex');
begin
  perform public.tournament_media_require_pipeline_ready();
  select * into v_job
  from public.tournament_media_processing_jobs
  where id = p_job_id for update;
  if v_job.id is null
    or v_job.status <> 'leased'
    or v_job.lease_expires_at <= now()
    or p_lease_token is null
    or v_job.lease_token is distinct from p_lease_token
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_JOB_LEASE_INVALID';
  end if;
  select * into v_session
  from public.tournament_media_upload_sessions
  where id = v_job.session_id for update;
  if v_session.id is null
    or v_session.status <> 'issued'
    or v_session.expires_at <= now()
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_UPLOAD_SESSION_INVALID';
  end if;
  if p_byte_size is null
    or p_byte_size < 1
    or p_byte_size > v_session.max_size
  then
    update public.tournament_media_upload_sessions set status = 'failed'
    where id = v_session.id;
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_FILE_INVALID';
  end if;
  update public.tournament_media_upload_sessions
  set token_hash = encode(public.digest(v_token,'sha256'),'hex'),
      requested_size = p_byte_size
  where id = v_session.id;
  return public.complete_tournament_media_upload_for_actor(
    v_session.requested_by, v_session.id, v_token, p_detected_mime,
    p_byte_size, p_width, p_height, p_checksum_sha256
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.complete_tournament_player_portrait_delete(p_actor_user_id uuid, p_portrait_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_portrait public.tournament_player_portraits%ROWTYPE;
BEGIN
  SELECT * INTO v_portrait FROM public.tournament_player_portraits portrait
  WHERE portrait.id = p_portrait_id AND portrait.lifecycle_status = 'delete_pending'
  FOR UPDATE;
  IF v_portrait.id IS NULL OR NOT public.can_manage_tournament_player_portrait_as(
    v_portrait.organization_id, v_portrait.roster_player_id, p_actor_user_id
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_PORTRAIT_FORBIDDEN';
  END IF;
  UPDATE public.tournament_player_portraits
  SET lifecycle_status = 'removed', removed_at = now(),
      storage_purged_at = now(), updated_at = now()
  WHERE id = p_portrait_id;
  INSERT INTO public.tournament_audit_log (
    organization_id, actor_user_id, actor_type, action, resource_type,
    resource_id, team_entry_id, tournament_id, metadata
  ) VALUES (
    v_portrait.organization_id, p_actor_user_id, 'user', 'portrait.removed',
    'player_portrait', v_portrait.id, v_portrait.team_entry_id,
    v_portrait.tournament_id,
    jsonb_build_object('rosterPlayerId', v_portrait.roster_player_id)
  );
  RETURN jsonb_build_object('portraitId', p_portrait_id, 'deleted', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_tournament_team_photo_delete(p_actor_user_id uuid, p_team_photo_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_photo public.tournament_team_photos%ROWTYPE;
BEGIN
  SELECT * INTO v_photo
  FROM public.tournament_team_photos photo
  WHERE photo.id = p_team_photo_id
    AND photo.lifecycle_status = 'delete_pending'
  FOR UPDATE;
  IF v_photo.id IS NULL OR NOT (
    public.can_manage_tournament_team_visual_assets_as(
      v_photo.organization_id, v_photo.team_entry_id, p_actor_user_id,
      'team_entries.update')
    OR public.can_moderate_tournament_team_visual_assets_as(
      v_photo.organization_id, v_photo.team_entry_id, p_actor_user_id,
      'team_entries.update')
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_TEAM_PHOTO_FORBIDDEN';
  END IF;
  UPDATE public.tournament_team_photos
  SET lifecycle_status = 'removed', removed_at = now(),
      storage_purged_at = now(), updated_at = now()
  WHERE id = p_team_photo_id;
  INSERT INTO public.tournament_audit_log (
    organization_id, actor_user_id, actor_type, action, resource_type,
    resource_id, team_entry_id, tournament_id, metadata
  ) VALUES (
    v_photo.organization_id, p_actor_user_id, 'user', 'team_photo.removed',
    'team_photo', v_photo.id, v_photo.team_entry_id, v_photo.tournament_id,
    jsonb_build_object('editorialStatus', v_photo.editorial_status)
  );
  RETURN jsonb_build_object('teamPhotoId', p_team_photo_id, 'deleted', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.create_fake_tournament_purchase(p_organization_id uuid, p_tournament_id uuid, p_product_code text, p_idempotency_key uuid, p_provider_environment text DEFAULT 'local'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_offer public.tournament_commercial_offers%rowtype;
  v_purchase public.tournament_purchases%rowtype;
  v_product public.tournament_commercial_products%rowtype;
  v_id uuid := gen_random_uuid();
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(p_organization_id,'billing.manage') then
    raise exception using errcode = '42501', message = 'TORNEOS_BILLING_FORBIDDEN';
  end if;
  if p_idempotency_key is null or p_provider_environment not in ('local','qa') then
    raise exception using errcode = '22023', message = 'TORNEOS_PURCHASE_INVALID';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    p_organization_id::text || ':' || p_tournament_id::text || ':' || p_product_code,79
  ));

  if not exists (
    select 1 from public.tournaments tournament
    where tournament.organization_id = p_organization_id and tournament.id = p_tournament_id
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_PURCHASE_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournament_plan_grants grant_row
    where grant_row.organization_id = p_organization_id
      and grant_row.tournament_id = p_tournament_id
      and grant_row.plan_code = 'PREMIUM'
      and public.is_tournament_plan_grant_effective(grant_row.id)
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_ALREADY_PREMIUM';
  end if;

  select * into v_purchase from public.tournament_purchases
  where buyer_user_id = auth.uid() and idempotency_key = p_idempotency_key;
  if v_purchase.id is not null then
    return public.tournament_purchase_projection(v_purchase)
      || jsonb_build_object('idempotentReplay',true,'existingOpenPurchase',false);
  end if;

  select * into v_purchase from public.tournament_purchases
  where organization_id = p_organization_id and tournament_id = p_tournament_id
    and product_code = p_product_code
    and status in ('created','preference_created','pending')
  order by created_at limit 1 for update;
  if v_purchase.id is not null then
    return public.tournament_purchase_projection(v_purchase)
      || jsonb_build_object('idempotentReplay',false,'existingOpenPurchase',true);
  end if;

  select * into v_product from public.tournament_commercial_products
  where product_code = p_product_code and status = 'active';
  if v_product.product_code is null or v_product.plan_code <> 'PREMIUM'
    or v_product.scope <> 'tournament' or v_product.billing_model <> 'one_time' then
    raise exception using errcode = '22023', message = 'TORNEOS_PRODUCT_UNAVAILABLE';
  end if;
  select * into v_offer from public.tournament_commercial_offers offer
  where offer.product_code = p_product_code
    and offer.availability = 'available'
    and offer.valid_from <= statement_timestamp()
    and (offer.valid_until is null or offer.valid_until > statement_timestamp())
  order by offer.valid_from desc,offer.offer_version desc limit 1;
  if v_offer.product_code is null then
    raise exception using errcode = '22023', message = 'TORNEOS_OFFER_UNAVAILABLE';
  end if;

  insert into public.tournament_purchases (
    id,organization_id,tournament_id,buyer_user_id,product_code,offer_code,offer_version,
    list_amount_snapshot,amount_snapshot,currency,provider,provider_environment,
    provider_preference_id,external_reference,idempotency_key,status,provider_status,
    preference_expires_at
  ) values (
    v_id,p_organization_id,p_tournament_id,auth.uid(),p_product_code,
    v_offer.offer_code,v_offer.offer_version,v_offer.list_amount,v_offer.amount,
    v_offer.currency,'FAKE',p_provider_environment,null,
    'arma2:tournament:purchase:' || v_id::text,p_idempotency_key,
    'created',null,now() + interval '30 minutes'
  ) returning * into v_purchase;

  insert into public.tournament_purchase_events (
    purchase_id,organization_id,event_type,from_status,to_status,provider_status,
    actor_type,actor_user_id
  ) values
    (v_purchase.id,p_organization_id,'purchase.created',null,'created',null,'user',auth.uid());

  update public.tournament_purchases set
    status = 'preference_created',provider_status = 'created',
    provider_preference_id = 'fake_pref_' || v_id::text
  where id = v_id returning * into v_purchase;
  insert into public.tournament_purchase_events (
    purchase_id,organization_id,event_type,from_status,to_status,provider_status,
    actor_type,actor_user_id
  ) values (
    v_purchase.id,p_organization_id,'preference.created','created','preference_created',
    'created','service',auth.uid()
  );

  return public.tournament_purchase_projection(v_purchase)
    || jsonb_build_object('idempotentReplay',false,'existingOpenPurchase',false);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_fake_tournament_season_purchase(p_organization_id uuid, p_season_id uuid, p_product_code text, p_idempotency_key uuid, p_provider_environment text DEFAULT 'local'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_purchase jsonb;
begin
  v_purchase := public.create_tournament_season_purchase(
    p_organization_id,p_season_id,p_product_code,p_idempotency_key,
    'FAKE',p_provider_environment
  );
  if v_purchase->>'status' = 'created' then
    v_purchase := public.record_tournament_purchase_preference(
      (v_purchase->>'id')::uuid,'FAKE',p_provider_environment,
      'fake_pref_' || (v_purchase->>'id'),
      (v_purchase->>'preferenceExpiresAt')::timestamptz
    ) || jsonb_build_object(
      'existingOpenPurchase',coalesce((v_purchase->>'existingOpenPurchase')::boolean,false),
      'idempotentReplay',coalesce((v_purchase->>'idempotentReplay')::boolean,false)
    );
  end if;
  return v_purchase;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_manual_fixture_version(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_source_fixture_version_id uuid, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_set public.tournament_participant_sets%rowtype;
  v_source public.tournament_fixture_versions%rowtype;
  v_version public.tournament_fixture_versions%rowtype;
  v_number integer;
  v_phase record;
  v_group record;
  v_round record;
  v_match record;
  v_source_row record;
  v_new_id uuid;
  v_phase_map jsonb := '{}'::jsonb;
  v_group_map jsonb := '{}'::jsonb;
  v_round_map jsonb := '{}'::jsonb;
  v_match_map jsonb := '{}'::jsonb;
begin
  perform public.assert_tournament_fixture_scope(
    p_organization_id, p_tournament_id, p_category_id,
    'fixture.create_manual', array['registration', 'scheduled']::text[]
  );
  if p_idempotency_key is null then
    raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:fixture:' || p_tournament_id::text || ':' || p_category_id::text, 0
  ));
  select version.* into v_version
  from public.tournament_fixture_versions version
  where version.organization_id = p_organization_id
    and version.created_by = auth.uid()
    and version.idempotency_key = p_idempotency_key;
  if v_version.id is not null then
    return jsonb_build_object(
      'fixtureVersionId', v_version.id,
      'versionNumber', v_version.version_number,
      'status', v_version.status
    );
  end if;
  select participant_set.* into v_set
  from public.tournament_participant_sets participant_set
  where participant_set.organization_id = p_organization_id
    and participant_set.tournament_id = p_tournament_id
    and participant_set.category_id = p_category_id
    and participant_set.status = 'frozen'
  for update;
  if v_set.id is null then
    raise exception using errcode = '23514', message = 'TORNEOS_PARTICIPANTS_NOT_FROZEN';
  end if;
  if p_source_fixture_version_id is not null then
    select source.* into v_source
    from public.tournament_fixture_versions source
    where source.id = p_source_fixture_version_id
      and source.organization_id = p_organization_id
      and source.tournament_id = p_tournament_id
      and source.category_id = p_category_id
      and source.participant_set_id = v_set.id
      and source.status in ('published', 'superseded')
    for share;
    if v_source.id is null then
      raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
    end if;
  end if;
  select coalesce(max(version.version_number), 0) + 1 into v_number
  from public.tournament_fixture_versions version
  where version.tournament_id = p_tournament_id and version.category_id = p_category_id;
  insert into public.tournament_fixture_versions (
    organization_id, season_id, tournament_id, category_id, participant_set_id,
    version_number, status, generation_method, seed, participant_fingerprint,
    configuration_snapshot, created_by, idempotency_key
  ) values (
    p_organization_id, v_set.season_id, p_tournament_id, p_category_id, v_set.id,
    v_number, 'draft', 'manual', v_source.seed, v_set.participant_fingerprint,
    coalesce(v_source.configuration_snapshot, '{}'::jsonb)
      || jsonb_build_object('copiedFromVersionId', v_source.id),
    auth.uid(), p_idempotency_key
  ) returning * into v_version;
  if v_source.id is not null then
    for v_phase in
      select * from public.tournament_phases
      where fixture_version_id = v_source.id order by sequence_number
    loop
      insert into public.tournament_phases (
        organization_id, tournament_id, category_id, fixture_version_id,
        name, phase_type, sequence_number, status, configuration
      ) values (
        v_phase.organization_id, v_phase.tournament_id, v_phase.category_id,
        v_version.id, v_phase.name, v_phase.phase_type, v_phase.sequence_number,
        'generated', v_phase.configuration
      ) returning id into v_new_id;
      v_phase_map := v_phase_map || jsonb_build_object(v_phase.id::text, v_new_id);
    end loop;
    for v_group in
      select * from public.tournament_groups
      where fixture_version_id = v_source.id order by sort_order, code
    loop
      insert into public.tournament_groups (
        organization_id, tournament_id, category_id, participant_set_id,
        fixture_version_id, phase_id, name, code, sort_order, status, draw_seed
      ) values (
        v_group.organization_id, v_group.tournament_id, v_group.category_id,
        v_group.participant_set_id, v_version.id,
        (v_phase_map->>v_group.phase_id::text)::uuid,
        v_group.name, v_group.code, v_group.sort_order, 'published', v_group.draw_seed
      ) returning id into v_new_id;
      v_group_map := v_group_map || jsonb_build_object(v_group.id::text, v_new_id);
      insert into public.tournament_group_members (group_id, participant_id, position_seed)
      select v_new_id, member.participant_id, member.position_seed
      from public.tournament_group_members member where member.group_id = v_group.id;
    end loop;
    for v_round in
      select * from public.tournament_rounds
      where fixture_version_id = v_source.id order by sort_order, round_number
    loop
      insert into public.tournament_rounds (
        organization_id, tournament_id, category_id, fixture_version_id,
        phase_id, group_id, round_number, name, status, starts_at, ends_at, sort_order
      ) values (
        v_round.organization_id, v_round.tournament_id, v_round.category_id,
        v_version.id, (v_phase_map->>v_round.phase_id::text)::uuid,
        case when v_round.group_id is null then null
          else (v_group_map->>v_round.group_id::text)::uuid end,
        v_round.round_number, v_round.name,
        case when v_round.status = 'locked' then 'scheduled' else v_round.status end,
        v_round.starts_at, v_round.ends_at, v_round.sort_order
      ) returning id into v_new_id;
      v_round_map := v_round_map || jsonb_build_object(v_round.id::text, v_new_id);
    end loop;
    for v_match in
      select * from public.tournament_matches
      where fixture_version_id = v_source.id order by match_number
    loop
      insert into public.tournament_matches (
        organization_id, season_id, tournament_id, category_id,
        participant_set_id, fixture_version_id, phase_id, group_id, round_id,
        match_number, leg_number, tie_key, home_participant_id, away_participant_id,
        status, scheduled_at, venue_id, court_id, duration_minutes, created_by,
        postponed_at, cancelled_at
      ) values (
        v_match.organization_id, v_match.season_id, v_match.tournament_id,
        v_match.category_id, v_match.participant_set_id, v_version.id,
        (v_phase_map->>v_match.phase_id::text)::uuid,
        case when v_match.group_id is null then null
          else (v_group_map->>v_match.group_id::text)::uuid end,
        (v_round_map->>v_match.round_id::text)::uuid,
        v_match.match_number, v_match.leg_number,
        case when v_match.tie_key is null then null
          else replace(v_match.tie_key, v_source.id::text, v_version.id::text) end,
        v_match.home_participant_id, v_match.away_participant_id,
        case when v_match.status in ('ready', 'in_progress', 'completed', 'awarded', 'suspended')
          then 'scheduled' else v_match.status end,
        v_match.scheduled_at, v_match.venue_id, v_match.court_id,
        v_match.duration_minutes, auth.uid(),
        case when v_match.status = 'postponed' then v_match.postponed_at else null end,
        case when v_match.status = 'cancelled' then v_match.cancelled_at else null end
      ) returning id into v_new_id;
      v_match_map := v_match_map || jsonb_build_object(v_match.id::text, v_new_id);
    end loop;
    for v_source_row in
      select * from public.tournament_match_sources
      where fixture_version_id = v_source.id order by created_at, id
    loop
      insert into public.tournament_match_sources (
        organization_id, tournament_id, category_id, fixture_version_id,
        match_id, side, source_type, participant_id, source_match_id,
        group_id, source_phase_id, source_tie_key,
        position_number, seed_number, rank_number
      ) values (
        v_source_row.organization_id, v_source_row.tournament_id,
        v_source_row.category_id, v_version.id,
        (v_match_map->>v_source_row.match_id::text)::uuid,
        v_source_row.side, v_source_row.source_type, v_source_row.participant_id,
        case when v_source_row.source_match_id is null then null
          else (v_match_map->>v_source_row.source_match_id::text)::uuid end,
        case when v_source_row.group_id is null then null
          else (v_group_map->>v_source_row.group_id::text)::uuid end,
        case when v_source_row.source_phase_id is null then null
          else (v_phase_map->>v_source_row.source_phase_id::text)::uuid end,
        case when v_source_row.source_tie_key is null then null
          else replace(
            v_source_row.source_tie_key,
            v_source.id::text,
            v_version.id::text
          ) end,
        v_source_row.position_number, v_source_row.seed_number, v_source_row.rank_number
      );
    end loop;
  end if;
  perform public.append_tournament_audit(
    p_organization_id, 'fixture.manual_created', 'fixture_version', v_version.id,
    null, p_tournament_id,
    jsonb_build_object(
      'categoryId', p_category_id,
      'versionNumber', v_number,
      'sourceFixtureVersionId', v_source.id
    )
  );
  return jsonb_build_object(
    'fixtureVersionId', v_version.id,
    'versionNumber', v_number,
    'status', 'draft',
    'sourceFixtureVersionId', v_source.id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_tournament_announcement_draft(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_announcement_type text, p_title text, p_summary text, p_body text, p_priority text, p_acknowledgement_mode text, p_scheduled_for timestamp with time zone, p_supersedes_id uuid, p_correction_reason text, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tournament public.tournaments%rowtype;
  v_existing public.tournament_announcements%rowtype;
  v_id uuid;
  v_version integer := 1;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if p_idempotency_key is null then
    raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;
  if not public.has_tournament_communications_capability(
    p_organization_id,'announcements.create'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  select * into v_tournament
  from public.tournaments tournament
  where tournament.id = p_tournament_id
    and tournament.organization_id = p_organization_id
    and tournament.status <> 'archived';
  if v_tournament.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  if p_category_id is not null and not exists (
    select 1 from public.tournament_categories category
    where category.id = p_category_id
      and category.organization_id = p_organization_id
      and category.tournament_id = p_tournament_id
      and category.status = 'active'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  if p_scheduled_for is not null
    and not public.has_tournament_communications_capability(
      p_organization_id,'announcements.schedule'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  if (select count(*) from public.tournament_announcements announcement
      where announcement.organization_id = p_organization_id
        and announcement.author_user_id = auth.uid()
        and announcement.status in ('draft','scheduled')) >= 100
  then
    raise exception using errcode = '54000', message = 'TORNEOS_DRAFT_LIMIT_REACHED';
  end if;

  select * into v_existing
  from public.tournament_announcements announcement
  where announcement.organization_id = p_organization_id
    and announcement.author_user_id = auth.uid()
    and announcement.idempotency_key = p_idempotency_key;
  if v_existing.id is not null then
    if v_existing.tournament_id <> p_tournament_id
      or v_existing.category_id is distinct from p_category_id
      or v_existing.announcement_type <> p_announcement_type
      or v_existing.title <> btrim(p_title)
      or v_existing.summary <> btrim(p_summary)
      or v_existing.body <> btrim(p_body)
      or v_existing.priority <> coalesce(p_priority,'normal')
      or v_existing.acknowledgement_mode <> coalesce(p_acknowledgement_mode,'none')
      or v_existing.scheduled_for is distinct from p_scheduled_for
      or v_existing.supersedes_id is distinct from p_supersedes_id
      or v_existing.correction_reason is distinct from
        nullif(btrim(coalesce(p_correction_reason,'')),'')
    then
      raise exception using errcode = '23514', message = 'TORNEOS_IDEMPOTENCY_CONFLICT';
    end if;
    return v_existing.id;
  end if;

  if p_supersedes_id is not null then
    select coalesce(max(announcement.version),0) + 1 into v_version
    from public.tournament_announcements announcement
    where announcement.id = p_supersedes_id
      and announcement.organization_id = p_organization_id
      and announcement.tournament_id = p_tournament_id
      and announcement.status = 'published';
    if v_version = 1
      or p_correction_reason is null
      or char_length(btrim(p_correction_reason)) < 4
    then
      raise exception using errcode = '22023', message = 'TORNEOS_INVALID_CORRECTION';
    end if;
  end if;

  insert into public.tournament_announcements (
    organization_id,season_id,tournament_id,category_id,author_user_id,status,
    announcement_type,title,summary,body,priority,acknowledgement_mode,
    scheduled_for,version,supersedes_id,correction_reason,idempotency_key
  ) values (
    p_organization_id,v_tournament.season_id,p_tournament_id,p_category_id,
    auth.uid(),case when p_scheduled_for is null then 'draft' else 'scheduled' end,
    p_announcement_type,btrim(p_title),btrim(p_summary),btrim(p_body),
    coalesce(p_priority,'normal'),coalesce(p_acknowledgement_mode,'none'),
    p_scheduled_for,v_version,p_supersedes_id,
    nullif(btrim(coalesce(p_correction_reason,'')),''),p_idempotency_key
  ) returning id into v_id;

  perform public.append_tournament_audit(
    p_organization_id,'communications.announcement_create','announcement',
    v_id,null,p_tournament_id,
    jsonb_build_object(
      'type',p_announcement_type,'scheduled',p_scheduled_for is not null,
      'supersedesId',p_supersedes_id
    )
  );
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_tournament_court(p_organization_id uuid, p_venue_id uuid, p_name text, p_sport_modality text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_court public.tournament_courts%rowtype;
begin
  if auth.uid() is null
    or not public.has_tournament_organization_capability(p_organization_id, 'courts.create')
    or not exists (
      select 1 from public.tournament_venues venue
      where venue.id = p_venue_id and venue.organization_id = p_organization_id
        and venue.status = 'active'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  insert into public.tournament_courts (
    organization_id, venue_id, name, sport_modality, notes
  ) values (
    p_organization_id, p_venue_id, btrim(p_name), p_sport_modality,
    nullif(btrim(coalesce(p_notes, '')), '')
  ) returning * into v_court;
  perform public.append_tournament_audit(
    p_organization_id, 'court.created', 'court', v_court.id,
    null, null, jsonb_build_object('venueId', p_venue_id, 'name', v_court.name)
  );
  return jsonb_build_object(
    'id', v_court.id, 'venueId', v_court.venue_id,
    'name', v_court.name, 'status', v_court.status
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_tournament_disciplinary_override(p_suspension_id uuid, p_action text, p_matches integer, p_reason text, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_suspension public.tournament_player_suspensions%rowtype;
  v_override public.tournament_disciplinary_overrides%rowtype;
  v_previous jsonb;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_suspension from public.tournament_player_suspensions
  where id = p_suspension_id;
  if v_suspension.id is null or not public.has_tournament_organization_capability(
    v_suspension.organization_id, 'discipline.override'
  ) or not exists (
    select 1
    from public.tournament_standings_revisions revision
    where revision.id = v_suspension.revision_id
      and revision.status = 'published'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_DISCIPLINE_FORBIDDEN';
  end if;
  if p_action not in ('reduce', 'revoke', 'add_match')
    or char_length(btrim(coalesce(p_reason, ''))) < 3
    or p_idempotency_key is null
  then
    raise exception using errcode = '22023', message = 'TORNEOS_DISCIPLINE_OVERRIDE_INVALID';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    v_suspension.organization_id::text || ':' || v_suspension.tournament_id::text || ':'
    || v_suspension.category_id::text || ':' || v_suspension.phase_id::text || ':'
    || coalesce(v_suspension.group_id::text, 'all'),
    0
  ));
  select * into strict v_suspension from public.tournament_player_suspensions
  where id = p_suspension_id for update;
  if not exists (
    select 1
    from public.tournament_standings_revisions revision
    where revision.id = v_suspension.revision_id
      and revision.status = 'published'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_DISCIPLINE_FORBIDDEN';
  end if;
  select * into v_override from public.tournament_disciplinary_overrides
  where organization_id = v_suspension.organization_id
    and actor_user_id = auth.uid()
    and idempotency_key = p_idempotency_key;
  if v_override.id is not null then
    if v_override.suspension_id <> p_suspension_id
      or v_override.action <> p_action
      or v_override.reason <> btrim(p_reason)
      or (
        p_action = 'reduce'
        and (v_override.new_state->>'totalMatches')::integer <> p_matches
      )
      or (
        p_action = 'add_match'
        and (
          (v_override.new_state->>'totalMatches')::integer
          - (v_override.previous_state->>'totalMatches')::integer
        ) <> p_matches
      )
    then
      raise exception using errcode = '23514', message = 'TORNEOS_IDEMPOTENCY_CONFLICT';
    end if;
    return v_override.id;
  end if;
  v_previous := jsonb_build_object(
    'status', v_suspension.status, 'totalMatches', v_suspension.total_matches,
    'servedMatches', v_suspension.served_matches
  );

  if p_action = 'revoke' then
    update public.tournament_player_suspensions
    set status = 'revoked', updated_at = now()
    where id = v_suspension.id;
  elsif p_action = 'reduce' then
    if p_matches is null or p_matches < v_suspension.served_matches
      or p_matches >= v_suspension.total_matches
    then
      raise exception using errcode = '22023', message = 'TORNEOS_DISCIPLINE_OVERRIDE_INVALID';
    end if;
    update public.tournament_player_suspensions
    set total_matches = p_matches,
      status = case when served_matches >= p_matches then 'served' else 'reduced' end,
      updated_at = now()
    where id = v_suspension.id;
  else
    if p_matches is null or p_matches < 1
      or v_suspension.total_matches + p_matches > 24
    then
      raise exception using errcode = '22023', message = 'TORNEOS_DISCIPLINE_OVERRIDE_INVALID';
    end if;
    update public.tournament_player_suspensions
    set total_matches = total_matches + p_matches, status = 'active', updated_at = now()
    where id = v_suspension.id;
  end if;

  select * into v_suspension from public.tournament_player_suspensions
  where id = p_suspension_id;
  insert into public.tournament_disciplinary_overrides (
    organization_id, tournament_id, suspension_id, action, previous_state,
    new_state, reason, actor_user_id, idempotency_key
  ) values (
    v_suspension.organization_id, v_suspension.tournament_id, v_suspension.id,
    p_action, v_previous,
    jsonb_build_object(
      'status', v_suspension.status, 'totalMatches', v_suspension.total_matches,
      'servedMatches', v_suspension.served_matches
    ),
    btrim(p_reason), auth.uid(), p_idempotency_key
  ) returning * into v_override;

  perform public.append_tournament_audit(
    v_suspension.organization_id, 'discipline.override', 'player_suspension',
    v_suspension.id, v_suspension.team_entry_id, v_suspension.tournament_id,
    jsonb_build_object(
      'action', p_action, 'previous', v_previous,
      'new', v_override.new_state, 'reason', btrim(p_reason)
    )
  );
  return v_override.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_tournament_document(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_document_type text, p_title text, p_summary text, p_body text, p_acknowledgement_mode text, p_effective_at timestamp with time zone, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tournament public.tournaments%rowtype;
  v_document_id uuid;
  v_version_id uuid;
  v_existing public.tournament_documents%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if p_idempotency_key is null then
    raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;
  if not public.has_tournament_communications_capability(
    p_organization_id,'documents.create'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_DOCUMENT_FORBIDDEN';
  end if;
  select * into v_tournament
  from public.tournaments tournament
  where tournament.id = p_tournament_id
    and tournament.organization_id = p_organization_id
    and tournament.status <> 'archived';
  if v_tournament.id is null
    or (p_category_id is not null and not exists (
      select 1 from public.tournament_categories category
      where category.id = p_category_id
        and category.organization_id = p_organization_id
        and category.tournament_id = p_tournament_id
        and category.status = 'active'
    ))
  then
    raise exception using errcode = '42501', message = 'TORNEOS_DOCUMENT_FORBIDDEN';
  end if;
  select * into v_existing
  from public.tournament_documents document
  where document.organization_id = p_organization_id
    and document.created_by = auth.uid()
    and document.idempotency_key = p_idempotency_key;
  if v_existing.id is not null then
    if v_existing.tournament_id <> p_tournament_id
      or v_existing.category_id is distinct from p_category_id
      or v_existing.document_type <> p_document_type
      or v_existing.title <> btrim(p_title)
      or v_existing.acknowledgement_mode <>
        coalesce(p_acknowledgement_mode,'none')
    then
      raise exception using errcode = '23514',
        message = 'TORNEOS_IDEMPOTENCY_CONFLICT';
    end if;
    select version.id into v_version_id
    from public.tournament_document_versions version
    where version.document_id = v_existing.id
      and version.version = 1;
    return jsonb_build_object(
      'documentId',v_existing.id,'versionId',v_version_id
    );
  end if;

  insert into public.tournament_documents (
    organization_id,season_id,tournament_id,category_id,document_type,title,
    acknowledgement_mode,created_by,idempotency_key
  ) values (
    p_organization_id,v_tournament.season_id,p_tournament_id,p_category_id,
    p_document_type,btrim(p_title),coalesce(p_acknowledgement_mode,'none'),
    auth.uid(),p_idempotency_key
  ) returning id into v_document_id;
  insert into public.tournament_document_versions (
    organization_id,document_id,version,status,summary,body,effective_at,created_by
  ) values (
    p_organization_id,v_document_id,1,'draft',btrim(p_summary),btrim(p_body),
    p_effective_at,auth.uid()
  ) returning id into v_version_id;
  perform public.append_tournament_audit(
    p_organization_id,'communications.document_create','tournament_document',
    v_document_id,null,p_tournament_id,
    jsonb_build_object('versionId',v_version_id,'type',p_document_type)
  );
  return jsonb_build_object('documentId',v_document_id,'versionId',v_version_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_tournament_document_version(p_document_id uuid, p_summary text, p_body text, p_effective_at timestamp with time zone, p_correction_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_document public.tournament_documents%rowtype;
  v_version integer;
  v_id uuid;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_document
  from public.tournament_documents document
  where document.id = p_document_id
  for update;
  if v_document.id is null
    or v_document.status = 'archived'
    or not public.has_tournament_communications_capability(
      v_document.organization_id,'documents.update_draft'
    )
    or p_correction_reason is null
    or char_length(btrim(p_correction_reason)) < 4
  then
    raise exception using errcode = '42501', message = 'TORNEOS_DOCUMENT_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournament_document_versions version
    where version.document_id = p_document_id and version.status = 'draft'
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_DOCUMENT_DRAFT_EXISTS';
  end if;
  select coalesce(max(version),0) + 1 into v_version
  from public.tournament_document_versions
  where document_id = p_document_id;
  insert into public.tournament_document_versions (
    organization_id,document_id,version,status,summary,body,effective_at,
    correction_reason,created_by,source_version_id
  ) values (
    v_document.organization_id,p_document_id,v_version,'draft',
    btrim(p_summary),btrim(p_body),p_effective_at,btrim(p_correction_reason),
    auth.uid(),v_document.active_version_id
  ) returning id into v_id;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_tournament_media_gallery(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_round_id uuid, p_match_id uuid, p_title text, p_description text, p_visibility text, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_scope record;
  v_existing public.tournament_media_galleries%rowtype;
  v_id uuid;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if p_idempotency_key is null then
    raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;

  if not public.has_tournament_media_capability(
    p_organization_id, 'media.create_gallery'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      p_organization_id::text || ':' || auth.uid()::text || ':' || p_idempotency_key::text,
      3
    )
  );

  select tournament.season_id
  into v_scope
  from public.tournaments tournament
  where tournament.id = p_tournament_id
    and tournament.organization_id = p_organization_id
    and tournament.status <> 'archived';
  if v_scope.season_id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  if p_category_id is not null and not exists (
    select 1 from public.tournament_categories category
    where category.id = p_category_id
      and category.organization_id = p_organization_id
      and category.tournament_id = p_tournament_id
      and category.status = 'active'
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_SCOPE_INVALID';
  end if;
  if p_round_id is not null and not exists (
    select 1
    from public.tournament_rounds round
    join public.tournament_fixture_versions fixture
      on fixture.id = round.fixture_version_id
    where round.id = p_round_id
      and round.organization_id = p_organization_id
      and round.tournament_id = p_tournament_id
      and (p_category_id is null or round.category_id = p_category_id)
      and fixture.status = 'published'
      and fixture.invalidated_at is null
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_SCOPE_INVALID';
  end if;
  if p_match_id is not null and not exists (
    select 1
    from public.tournament_matches match
    join public.tournament_fixture_versions fixture
      on fixture.id = match.fixture_version_id
    where match.id = p_match_id
      and match.organization_id = p_organization_id
      and match.tournament_id = p_tournament_id
      and (p_category_id is null or match.category_id = p_category_id)
      and (p_round_id is null or match.round_id = p_round_id)
      and fixture.status = 'published'
      and fixture.invalidated_at is null
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_SCOPE_INVALID';
  end if;
  if p_visibility = 'match_participants' and p_match_id is null then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_VISIBILITY_INVALID';
  end if;

  select * into v_existing
  from public.tournament_media_galleries gallery
  where gallery.organization_id = p_organization_id
    and gallery.created_by = auth.uid()
    and gallery.idempotency_key = p_idempotency_key;
  if v_existing.id is not null then
    if v_existing.tournament_id is distinct from p_tournament_id
      or v_existing.category_id is distinct from p_category_id
      or v_existing.round_id is distinct from p_round_id
      or v_existing.match_id is distinct from p_match_id
      or v_existing.title is distinct from btrim(p_title)
      or v_existing.description is distinct from nullif(btrim(p_description),'')
      or v_existing.visibility is distinct from p_visibility
    then
      raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_IDEMPOTENCY_CONFLICT';
    end if;
    return v_existing.id;
  end if;

  insert into public.tournament_media_galleries (
    organization_id,season_id,tournament_id,category_id,round_id,match_id,
    title,description,visibility,created_by,idempotency_key
  ) values (
    p_organization_id,v_scope.season_id,p_tournament_id,p_category_id,p_round_id,
    p_match_id,btrim(p_title),nullif(btrim(p_description),''),
    p_visibility,auth.uid(),p_idempotency_key
  ) returning id into v_id;
  perform public.append_tournament_audit(
    p_organization_id,'media.gallery.created','media_gallery',v_id,
    null,p_tournament_id,jsonb_build_object('visibility',p_visibility)
  );
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_tournament_organization(p_name text, p_slug text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_name text := btrim(coalesce(p_name, ''));
  v_slug text := public.normalize_tournament_organization_slug(p_slug);
  v_organization public.tournament_organizations%rowtype;
  v_membership public.tournament_organization_members%rowtype;
  v_created_recently integer;
  v_constraint_name text;
  v_reserved_slugs constant text[] := array[
    'admin', 'api', 'app', 'auth', 'login', 'logout', 'profile',
    'torneos', 'tournaments', 'settings', 'support', 'www'
  ];
begin
  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'TORNEOS_AUTH_REQUIRED';
  end if;

  if p_idempotency_key is null then
    raise exception using
      errcode = '22023',
      message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;

  if char_length(v_name) not between 3 and 80 then
    raise exception using
      errcode = '22023',
      message = 'TORNEOS_INVALID_NAME';
  end if;

  if char_length(v_slug) not between 3 and 48
    or v_slug !~ '^[a-z0-9](?:[a-z0-9-]{1,46}[a-z0-9])$'
    or v_slug = any(v_reserved_slugs)
  then
    raise exception using
      errcode = '22023',
      message = 'TORNEOS_INVALID_SLUG';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(v_user_id::text, 0)
  );

  select organization.*
  into v_organization
  from public.tournament_organizations organization
  where organization.created_by = v_user_id
    and organization.creation_key = p_idempotency_key;

  if v_organization.id is null then
    select count(*)
    into v_created_recently
    from public.tournament_organizations organization
    where organization.created_by = v_user_id
      and organization.created_at > now() - interval '10 minutes';

    if v_created_recently >= 5 then
      raise exception using
        errcode = 'P0001',
        message = 'TORNEOS_CREATION_RATE_LIMITED';
    end if;

    begin
      insert into public.tournament_organizations (
        name,
        slug,
        status,
        created_by,
        creation_key
      )
      values (
        v_name,
        v_slug,
        'active',
        v_user_id,
        p_idempotency_key
      )
      returning * into v_organization;
    exception
      when unique_violation then
        get stacked diagnostics v_constraint_name = constraint_name;
        if v_constraint_name = 'tournament_organizations_slug_unique' then
          raise exception using
            errcode = '23505',
            message = 'TORNEOS_SLUG_TAKEN';
        elsif v_constraint_name = 'tournament_organizations_creation_unique' then
          select organization.*
          into v_organization
          from public.tournament_organizations organization
          where organization.created_by = v_user_id
            and organization.creation_key = p_idempotency_key;
          if v_organization.id is null then
            raise;
          end if;
        else
          raise;
        end if;
    end;

    if not exists (
      select 1
      from public.tournament_organization_members membership
      where membership.organization_id = v_organization.id
        and membership.user_id = v_user_id
    ) then
      insert into public.tournament_organization_members (
        organization_id,
        user_id,
        role,
        status,
        joined_at
      )
      values (
        v_organization.id,
        v_user_id,
        'owner',
        'active',
        now()
      )
      returning * into v_membership;
    end if;
  end if;

  if v_membership.id is null then
    select membership.*
    into v_membership
    from public.tournament_organization_members membership
    where membership.organization_id = v_organization.id
      and membership.user_id = v_user_id
      and membership.status = 'active';
  end if;

  if v_membership.id is null
    or v_membership.role <> 'owner'
    or v_membership.status <> 'active'
  then
    raise exception using
      errcode = '23514',
      message = 'TORNEOS_ACTIVE_OWNER_REQUIRED';
  end if;

  insert into public.user_workspace_preferences (
    user_id,
    workspace_type,
    active_organization_id
  )
  values (
    v_user_id,
    'tournament_organization',
    v_organization.id
  )
  on conflict (user_id) do update
  set workspace_type = excluded.workspace_type,
      active_organization_id = excluded.active_organization_id;

  return jsonb_build_object(
    'organization', jsonb_build_object(
      'id', v_organization.id,
      'name', v_organization.name,
      'slug', v_organization.slug,
      'logoPath', v_organization.logo_path,
      'status', v_organization.status,
      'createdAt', v_organization.created_at
    ),
    'membership', jsonb_build_object(
      'role', v_membership.role,
      'status', v_membership.status,
      'joinedAt', v_membership.joined_at,
      'capabilities', to_jsonb(
        public.tournament_role_capabilities(v_membership.role)
      )
    ),
    'preference', jsonb_build_object(
      'workspaceType', 'tournament_organization',
      'activeOrganizationId', v_organization.id
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_tournament_provisional_player(p_organization_id uuid, p_team_entry_id uuid, p_display_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_player public.tournament_provisional_players%rowtype;
  v_entry public.tournament_team_entries%rowtype;
begin
  select * into v_entry from public.tournament_team_entries
  where id = p_team_entry_id and organization_id = p_organization_id;
  if auth.uid() is null or v_entry.id is null
    or not public.can_edit_tournament_team_entry(
      p_organization_id,
      p_team_entry_id
    )
  then raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN'; end if;
  if char_length(btrim(coalesce(p_display_name, ''))) not between 2 and 100 then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_PLAYER';
  end if;
  insert into public.tournament_provisional_players (
    organization_id, display_name, normalized_name, created_by
  ) values (
    p_organization_id, btrim(p_display_name),
    public.normalize_tournament_person_name(p_display_name), auth.uid()
  ) returning * into v_player;
  perform public.append_tournament_audit(
    p_organization_id, 'provisional_player.created', 'provisional_player',
    v_player.id, p_team_entry_id, v_entry.tournament_id, '{}'::jsonb
  );
  return jsonb_build_object('id', v_player.id, 'displayName', v_player.display_name, 'claimStatus', v_player.claim_status);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_tournament_season(p_organization_id uuid, p_name text, p_slug text, p_start_date date, p_end_date date, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_name text := btrim(coalesce(p_name, ''));
  v_slug text := public.normalize_tournament_competition_slug(p_slug);
  v_season public.tournament_seasons%rowtype;
  v_constraint_name text;
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(
    p_organization_id,
    'seasons.create'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if p_idempotency_key is null then
    raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;
  if char_length(v_name) not between 3 and 80
    or char_length(v_slug) not between 3 and 48
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_SEASON';
  end if;
  if p_start_date is not null and p_end_date is not null and p_end_date < p_start_date then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_DATES';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    p_organization_id::text || ':' || v_user_id::text || ':season',
    0
  ));

  perform 1
  from public.tournament_organizations organization
  where organization.id = p_organization_id
    and organization.status = 'active'
  for share;

  if not found then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  select season.* into v_season
  from public.tournament_seasons season
  where season.organization_id = p_organization_id
    and season.created_by = v_user_id
    and season.creation_key = p_idempotency_key;

  if v_season.id is not null and v_season.status = 'archived' then
    raise exception using errcode = '23514', message = 'TORNEOS_IDEMPOTENCY_CONFLICT';
  end if;

  if v_season.id is null then
    begin
      insert into public.tournament_seasons (
        organization_id,
        name,
        slug,
        status,
        start_date,
        end_date,
        created_by,
        creation_key
      )
      values (
        p_organization_id,
        v_name,
        v_slug,
        'draft',
        p_start_date,
        p_end_date,
        v_user_id,
        p_idempotency_key
      )
      returning * into v_season;
    exception when unique_violation then
      get stacked diagnostics v_constraint_name = constraint_name;
      if v_constraint_name = 'tournament_seasons_slug_unique' then
        raise exception using errcode = '23505', message = 'TORNEOS_SEASON_SLUG_TAKEN';
      elsif v_constraint_name = 'tournament_seasons_creation_unique' then
        select season.* into v_season
        from public.tournament_seasons season
        where season.organization_id = p_organization_id
          and season.created_by = v_user_id
          and season.creation_key = p_idempotency_key;
      else
        raise;
      end if;
    end;
  end if;

  insert into public.user_tournament_context_preferences (
    user_id,
    organization_id,
    active_season_id,
    active_tournament_id
  )
  values (v_user_id, p_organization_id, v_season.id, null)
  on conflict (user_id, organization_id) do update
  set active_season_id = excluded.active_season_id,
      active_tournament_id = null;

  return jsonb_build_object(
    'id', v_season.id,
    'organizationId', v_season.organization_id,
    'name', v_season.name,
    'slug', v_season.slug,
    'status', v_season.status,
    'startDate', v_season.start_date,
    'endDate', v_season.end_date,
    'createdAt', v_season.created_at,
    'updatedAt', v_season.updated_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_tournament_season_purchase(p_organization_id uuid, p_season_id uuid, p_product_code text, p_idempotency_key uuid, p_provider text, p_provider_environment text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_offer public.tournament_commercial_offers%rowtype;
  v_purchase public.tournament_purchases%rowtype;
  v_product public.tournament_commercial_products%rowtype;
  v_id uuid := gen_random_uuid();
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(p_organization_id,'billing.manage') then
    raise exception using errcode = '42501', message = 'TORNEOS_BILLING_FORBIDDEN';
  end if;
  if p_idempotency_key is null or not (
    (p_provider = 'FAKE' and p_provider_environment in ('local','qa'))
    or (p_provider = 'MERCADO_PAGO' and p_provider_environment = 'test')
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_PURCHASE_INVALID';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_organization_id::text || ':' || p_season_id::text || ':' || p_product_code,79)
  );
  if not exists (
    select 1 from public.tournament_seasons season
    where season.organization_id = p_organization_id and season.id = p_season_id
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_PURCHASE_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournament_season_plan_grants grant_row
    where grant_row.organization_id = p_organization_id
      and grant_row.season_id = p_season_id
      and public.is_tournament_season_plan_grant_effective(grant_row.id)
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_SEASON_ALREADY_PREMIUM';
  end if;
  select * into v_purchase from public.tournament_purchases
  where buyer_user_id = auth.uid() and idempotency_key = p_idempotency_key;
  if v_purchase.id is not null then
    if v_purchase.organization_id <> p_organization_id
      or v_purchase.season_id <> p_season_id
      or v_purchase.product_code <> p_product_code
      or v_purchase.provider <> p_provider
      or v_purchase.provider_environment <> p_provider_environment then
      raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_CONFLICT';
    end if;
    return public.tournament_purchase_projection(v_purchase)
      || jsonb_build_object('idempotentReplay',true,'existingOpenPurchase',false);
  end if;
  select * into v_purchase from public.tournament_purchases
  where organization_id = p_organization_id and season_id = p_season_id
    and product_code = p_product_code and status in ('created','preference_created','pending')
  order by created_at limit 1 for update;
  if v_purchase.id is not null then
    if v_purchase.provider <> p_provider
      or v_purchase.provider_environment <> p_provider_environment then
      raise exception using errcode = '55000', message = 'TORNEOS_OPEN_PURCHASE_PROVIDER_CONFLICT';
    end if;
    return public.tournament_purchase_projection(v_purchase)
      || jsonb_build_object('idempotentReplay',false,'existingOpenPurchase',true);
  end if;
  select * into v_product from public.tournament_commercial_products
  where product_code = p_product_code and status = 'active';
  if v_product.product_code is null or v_product.plan_code <> 'PREMIUM'
    or v_product.scope <> 'season' or v_product.billing_model <> 'one_time' then
    raise exception using errcode = '22023', message = 'TORNEOS_PRODUCT_UNAVAILABLE';
  end if;
  select * into v_offer from public.tournament_commercial_offers offer
  where offer.product_code = p_product_code and offer.availability = 'available'
    and offer.valid_from <= statement_timestamp()
    and (offer.valid_until is null or offer.valid_until > statement_timestamp())
  order by offer.valid_from desc,offer.offer_version desc limit 1;
  if v_offer.product_code is null then
    raise exception using errcode = '22023', message = 'TORNEOS_OFFER_UNAVAILABLE';
  end if;
  insert into public.tournament_purchases (
    id,organization_id,season_id,tournament_id,buyer_user_id,product_code,
    offer_code,offer_version,list_amount_snapshot,amount_snapshot,currency,
    provider,provider_environment,external_reference,idempotency_key,status,
    preference_expires_at
  ) values (
    v_id,p_organization_id,p_season_id,null,auth.uid(),p_product_code,
    v_offer.offer_code,v_offer.offer_version,v_offer.list_amount,v_offer.amount,
    v_offer.currency,p_provider,p_provider_environment,
    'arma2:season:purchase:' || v_id::text,p_idempotency_key,'created',
    now() + interval '30 minutes'
  ) returning * into v_purchase;
  insert into public.tournament_purchase_events (
    purchase_id,organization_id,event_type,from_status,to_status,actor_type,actor_user_id,
    metadata
  ) values (
    v_purchase.id,p_organization_id,'purchase.created',null,'created','user',auth.uid(),
    jsonb_build_object('seasonId',p_season_id)
  );
  return public.tournament_purchase_projection(v_purchase)
    || jsonb_build_object('idempotentReplay',false,'existingOpenPurchase',false);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_tournament_team_entry(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_arma2_team_id uuid, p_name text, p_short_name text, p_primary_color text, p_secondary_color text, p_registration_source text, p_manager_user_id uuid, p_manager_email text, p_manager_display_name text, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_uid uuid := auth.uid();
  v_tournament public.tournaments%rowtype;
  v_category public.tournament_categories%rowtype;
  v_arma2_team public.teams%rowtype;
  v_entry public.tournament_team_entries%rowtype;
  v_roster public.tournament_rosters%rowtype;
  v_manager public.tournament_team_managers%rowtype;
  v_name text := btrim(coalesce(p_name, ''));
  v_slug text;
  v_source text := coalesce(p_registration_source, case when p_arma2_team_id is null then 'provisional' else 'arma2_team' end);
  v_email text := nullif(lower(btrim(coalesce(p_manager_email, ''))), '');
  v_primary_color text := p_primary_color;
  v_secondary_color text := p_secondary_color;
begin
  if v_uid is null then raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED'; end if;
  if not public.has_tournament_organization_capability(p_organization_id, 'team_entries.create') then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if p_idempotency_key is null then raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED'; end if;

  perform pg_advisory_xact_lock(hashtextextended(p_organization_id::text || ':' || p_tournament_id::text, 0));
  select * into v_entry from public.tournament_team_entries
  where organization_id = p_organization_id and created_by = v_uid
    and idempotency_key = p_idempotency_key;
  if v_entry.id is not null then
    select * into v_roster from public.tournament_rosters where team_entry_id = v_entry.id order by version desc limit 1;
    return jsonb_build_object('entryId', v_entry.id, 'rosterId', v_roster.id, 'status', v_entry.status);
  end if;

  select * into v_tournament from public.tournaments
  where id = p_tournament_id and organization_id = p_organization_id
    and status = 'registration' and archived_at is null
    and (registration_opens_at is null or now() >= registration_opens_at)
    and (registration_closes_at is null or now() <= registration_closes_at);
  select * into v_category from public.tournament_categories
  where id = p_category_id and organization_id = p_organization_id
    and tournament_id = p_tournament_id and status = 'active';
  if v_tournament.id is null or v_category.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_REGISTRATION_CLOSED';
  end if;
  if v_source not in ('manual', 'invitation', 'arma2_team', 'provisional')
    or ((v_source = 'arma2_team') <> (p_arma2_team_id is not null))
  then raise exception using errcode = '22023', message = 'TORNEOS_INVALID_TEAM_ENTRY'; end if;
  if p_manager_user_id is not null then
    raise exception using errcode = '22023', message = 'TORNEOS_MANAGER_INVITATION_REQUIRED';
  end if;
  if p_arma2_team_id is not null then
    select * into v_arma2_team
    from public.teams
    where id = p_arma2_team_id
      and is_active
      and public.team_user_is_admin_or_owner(id, v_uid);
    if v_arma2_team.id is null then
      raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
    end if;
    v_name := btrim(v_arma2_team.name);
    v_primary_color := v_arma2_team.color_primary;
    v_secondary_color := v_arma2_team.color_secondary;
  end if;
  if char_length(v_name) not between 2 and 100 then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_TEAM_ENTRY';
  end if;

  v_slug := public.normalize_tournament_competition_slug(v_name);
  if char_length(v_slug) < 2 then v_slug := 'equipo-' || substr(replace(public.gen_random_uuid()::text, '-', ''), 1, 8); end if;
  if exists (
    select 1 from public.tournament_team_entries
    where tournament_id = p_tournament_id and category_id = p_category_id and slug = v_slug
  ) then v_slug := left(v_slug, 54) || '-' || substr(replace(public.gen_random_uuid()::text, '-', ''), 1, 8); end if;

  insert into public.tournament_team_entries (
    organization_id, season_id, tournament_id, category_id, arma2_team_id,
    name, slug, short_name, primary_color, secondary_color, status,
    registration_source, created_by, idempotency_key
  ) values (
    p_organization_id, v_tournament.season_id, p_tournament_id, p_category_id,
    p_arma2_team_id, v_name, v_slug, nullif(btrim(coalesce(p_short_name, '')), ''),
    v_primary_color, v_secondary_color, 'draft',
    v_source, v_uid, p_idempotency_key
  ) returning * into v_entry;

  insert into public.tournament_rosters (
    organization_id, team_entry_id, version, status, created_by
  ) values (p_organization_id, v_entry.id, 1, 'draft', v_uid)
  returning * into v_roster;

  insert into public.tournament_roster_settings (
    tournament_id, organization_id, minimum_players, maximum_players,
    minimum_goalkeepers, roster_opens_at, roster_closes_at
  ) values (
    p_tournament_id, p_organization_id, v_tournament.team_size,
    least(80, v_tournament.team_size + coalesce(v_tournament.substitutes_limit, v_tournament.team_size)),
    1, v_tournament.registration_opens_at, v_tournament.registration_closes_at
  ) on conflict (tournament_id) do nothing;

  if v_email is not null then
    if char_length(btrim(coalesce(p_manager_display_name, ''))) not between 2 and 100 then
      raise exception using errcode = '22023', message = 'TORNEOS_INVALID_MANAGER';
    end if;
    insert into public.tournament_team_managers (
      organization_id, team_entry_id, user_id, email_normalized, display_name,
      role, status, invited_by, accepted_at
    ) values (
      p_organization_id, v_entry.id, null, v_email,
      btrim(p_manager_display_name), 'captain', 'pending',
      v_uid, null
    ) returning * into v_manager;
  end if;

  perform public.append_tournament_audit(
    p_organization_id, 'team_entry.created', 'team_entry', v_entry.id,
    v_entry.id, p_tournament_id,
    jsonb_build_object('source', v_source, 'categoryId', p_category_id, 'linked', p_arma2_team_id is not null)
  );
  return jsonb_build_object(
    'entryId', v_entry.id, 'rosterId', v_roster.id,
    'managerId', v_manager.id, 'status', v_entry.status
  );
exception when unique_violation then
  if p_arma2_team_id is not null then
    raise exception using errcode = '23505', message = 'TORNEOS_TEAM_ALREADY_REGISTERED';
  end if;
  raise;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_tournament_venue(p_organization_id uuid, p_name text, p_address text, p_place_id text DEFAULT NULL::text, p_latitude double precision DEFAULT NULL::double precision, p_longitude double precision DEFAULT NULL::double precision, p_locality text DEFAULT NULL::text, p_timezone text DEFAULT 'America/Argentina/Buenos_Aires'::text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_venue public.tournament_venues%rowtype;
begin
  if auth.uid() is null
    or not public.has_tournament_organization_capability(p_organization_id, 'venues.create')
    or not exists (
      select 1 from public.tournament_organizations organization
      where organization.id = p_organization_id and organization.status = 'active'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if not exists (
    select 1 from pg_catalog.pg_timezone_names zone where zone.name = p_timezone
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_TIMEZONE';
  end if;
  insert into public.tournament_venues (
    organization_id, name, address, place_id, latitude, longitude,
    locality, timezone, notes
  ) values (
    p_organization_id, btrim(p_name), btrim(p_address),
    nullif(btrim(coalesce(p_place_id, '')), ''), p_latitude, p_longitude,
    nullif(btrim(coalesce(p_locality, '')), ''), p_timezone,
    nullif(btrim(coalesce(p_notes, '')), '')
  ) returning * into v_venue;
  perform public.append_tournament_audit(
    p_organization_id, 'venue.created', 'venue', v_venue.id,
    null, null, jsonb_build_object('name', v_venue.name)
  );
  return jsonb_build_object(
    'id', v_venue.id, 'name', v_venue.name, 'status', v_venue.status
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.create_tournament_with_defaults(p_organization_id uuid, p_season_id uuid, p_name text, p_slug text, p_description text, p_sport_modality text, p_competition_format text, p_gender_category text, p_start_date date, p_end_date date, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_name text := btrim(coalesce(p_name, ''));
  v_slug text := public.normalize_tournament_competition_slug(p_slug);
  v_tournament public.tournaments%rowtype;
  v_team_size smallint;
  v_substitutes smallint;
  v_constraint_name text;
  v_format_settings jsonb;
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(
    p_organization_id,
    'tournaments.create'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if p_idempotency_key is null then
    raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;
  if char_length(v_name) not between 3 and 100
    or char_length(v_slug) not between 3 and 64
    or p_gender_category not in ('male', 'female', 'mixed', 'open')
    or p_competition_format not in (
      'league',
      'knockout',
      'groups',
      'groups_and_playoffs',
      'league_and_playoffs'
    )
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_TOURNAMENT';
  end if;
  if p_start_date is not null and p_end_date is not null and p_end_date < p_start_date then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_DATES';
  end if;

  select modality.team_size, modality.recommended_substitutes
  into v_team_size, v_substitutes
  from public.tournament_sport_modalities modality
  where modality.code = p_sport_modality;

  if v_team_size is null then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_MODALITY';
  end if;

  v_format_settings := case p_competition_format
    when 'league' then '{"rounds":"single","qualifiers":0}'::jsonb
    when 'knockout' then '{"legs":"single","thirdPlace":false}'::jsonb
    when 'groups' then '{"groupCount":2,"qualifiersPerGroup":1,"rounds":"single"}'::jsonb
    when 'groups_and_playoffs' then '{"groupCount":2,"qualifiersPerGroup":1,"groupRounds":"single","knockoutLegs":"single"}'::jsonb
    else '{"leagueRounds":"single","qualifiers":2,"knockoutLegs":"single"}'::jsonb
  end;

  perform pg_advisory_xact_lock(hashtextextended(
    p_organization_id::text || ':' || v_user_id::text || ':tournament',
    0
  ));

  perform 1
  from public.tournament_seasons season
  join public.tournament_organizations organization
    on organization.id = season.organization_id
  where season.id = p_season_id
    and season.organization_id = p_organization_id
    and season.status <> 'archived'
    and organization.status = 'active'
  for share of season, organization;

  if not found then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  select tournament.* into v_tournament
  from public.tournaments tournament
  where tournament.organization_id = p_organization_id
    and tournament.created_by = v_user_id
    and tournament.creation_key = p_idempotency_key;

  if v_tournament.id is not null and v_tournament.status = 'archived' then
    raise exception using errcode = '23514', message = 'TORNEOS_IDEMPOTENCY_CONFLICT';
  end if;

  if v_tournament.id is null then
    begin
      insert into public.tournaments (
        organization_id,
        season_id,
        name,
        slug,
        description,
        status,
        sport_modality,
        competition_format,
        gender_category,
        team_size,
        substitutes_limit,
        start_date,
        end_date,
        format_settings,
        created_by,
        creation_key
      )
      values (
        p_organization_id,
        p_season_id,
        v_name,
        v_slug,
        nullif(btrim(coalesce(p_description, '')), ''),
        'draft',
        p_sport_modality,
        p_competition_format,
        p_gender_category,
        v_team_size,
        v_substitutes,
        p_start_date,
        p_end_date,
        v_format_settings,
        v_user_id,
        p_idempotency_key
      )
      returning * into v_tournament;
    exception when unique_violation then
      get stacked diagnostics v_constraint_name = constraint_name;
      if v_constraint_name = 'tournaments_slug_unique' then
        raise exception using errcode = '23505', message = 'TORNEOS_TOURNAMENT_SLUG_TAKEN';
      elsif v_constraint_name = 'tournaments_creation_unique' then
        select tournament.* into v_tournament
        from public.tournaments tournament
        where tournament.organization_id = p_organization_id
          and tournament.created_by = v_user_id
          and tournament.creation_key = p_idempotency_key;
      else
        raise;
      end if;
    end;

    insert into public.tournament_scoring_rules (
      tournament_id,
      organization_id
    )
    values (v_tournament.id, p_organization_id);

    insert into public.tournament_tiebreak_rules (
      organization_id,
      tournament_id,
      criterion,
      sort_order
    )
    values
      (p_organization_id, v_tournament.id, 'goal_difference', 1),
      (p_organization_id, v_tournament.id, 'goals_for', 2),
      (p_organization_id, v_tournament.id, 'head_to_head', 3),
      (p_organization_id, v_tournament.id, 'fair_play', 4);

    insert into public.tournament_discipline_rules (
      tournament_id,
      organization_id
    )
    values (v_tournament.id, p_organization_id);
  end if;

  insert into public.user_tournament_context_preferences (
    user_id,
    organization_id,
    active_season_id,
    active_tournament_id
  )
  values (v_user_id, p_organization_id, v_tournament.season_id, v_tournament.id)
  on conflict (user_id, organization_id) do update
  set active_season_id = excluded.active_season_id,
      active_tournament_id = excluded.active_tournament_id;

  return jsonb_build_object(
    'id', v_tournament.id,
    'organizationId', v_tournament.organization_id,
    'seasonId', v_tournament.season_id,
    'name', v_tournament.name,
    'slug', v_tournament.slug,
    'status', v_tournament.status
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_tournament_media_gallery_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_season_id uuid;
  v_policy jsonb;
  v_limit integer;
  v_count integer;
begin
  select season_id into v_season_id from public.tournaments
  where organization_id = new.organization_id and id = new.tournament_id;
  if v_season_id is null then
    raise exception using errcode='22023',message='TORNEOS_MEDIA_SCOPE_INVALID';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(new.organization_id::text || ':' || v_season_id::text,43)
  );
  v_policy := public.resolve_effective_tournament_season_entitlements_at(
    new.organization_id,v_season_id,now(),false,new.tournament_id
  );
  v_limit := (v_policy->'media'->>'galleryAssetLimit')::integer;
  select
    (select count(*)
     from public.tournament_media_assets asset
     join public.tournaments tournament
       on tournament.organization_id=asset.organization_id and tournament.id=asset.tournament_id
     where asset.organization_id=new.organization_id and tournament.season_id=v_season_id
       and asset.status not in ('rejected','revoked','failed')
       and asset.storage_state <> 'storage_purged')
    +
    (select count(*)
     from public.tournament_media_upload_sessions session
     join public.tournaments tournament
       on tournament.organization_id=session.organization_id and tournament.id=session.tournament_id
     where session.organization_id=new.organization_id and tournament.season_id=v_season_id
       and session.status in ('issued','uploaded') and session.expires_at>now())
  into v_count;
  if v_limit is not null and v_count>=v_limit then
    raise exception using errcode='22023',message='TORNEOS_SEASON_MEDIA_QUOTA_EXCEEDED',
      detail=jsonb_build_object('seasonId',v_season_id,'usage',v_count,'limit',v_limit,
        'upgradeRequired',v_policy->>'plan'='FREE')::text;
  end if;
  new.quota_snapshot := coalesce(new.quota_snapshot,'{}'::jsonb) || jsonb_build_object(
    'scope','season','seasonId',v_season_id,'plan',v_policy->>'plan',
    'galleryAssetLimit',v_limit,'galleryAssetUsage',v_count
  );
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_tournament_media_matchday_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_round_id uuid;
  v_policy jsonb;
  v_max integer;
  v_count integer;
BEGIN
  v_round_id := public.tournament_media_gallery_sports_round(new.gallery_id);
  IF v_round_id IS NULL THEN
    RETURN new;
  END IF;
  -- Serialize the count/check/insert boundary for one official sports date.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      new.organization_id::text || ':' || new.tournament_id::text || ':' || v_round_id::text,
      23
    )
  );
  v_policy := public.resolve_effective_tournament_entitlements_at(
    new.organization_id,new.tournament_id,now(),false
  );
  v_max := (v_policy->'media'->>'maxPhotosPerMatchday')::integer;
  IF v_max IS NULL THEN
    RETURN new;
  END IF;

  SELECT
    (SELECT count(*)
     FROM public.tournament_media_assets asset
     WHERE asset.organization_id = new.organization_id
       AND asset.tournament_id = new.tournament_id
       AND asset.status <> 'revoked'
       AND asset.storage_state <> 'storage_purged'
       AND public.tournament_media_gallery_sports_round(asset.gallery_id) = v_round_id)
    +
    (SELECT count(*)
     FROM public.tournament_media_upload_sessions session
     WHERE session.organization_id = new.organization_id
       AND session.tournament_id = new.tournament_id
       AND session.status = 'issued'
       AND session.expires_at > now()
       AND public.tournament_media_gallery_sports_round(session.gallery_id) = v_round_id)
  INTO v_count;

  IF v_count >= v_max THEN
    RAISE EXCEPTION USING errcode = '22023', message = 'TORNEOS_MEDIA_QUOTA_EXCEEDED';
  END IF;
  RETURN new;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_tournament_premium_gate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_organization_id uuid; v_tournament_id uuid;
begin
  v_organization_id := new.organization_id;
  v_tournament_id := new.tournament_id;
  if public.tournament_requires_premium(v_organization_id,v_tournament_id) then
    raise exception using errcode = '42501', message = 'TORNEOS_PREMIUM_REQUIRED';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.enforce_tournament_purchase_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if new.status = old.status then return new; end if;
  if not (
    (old.status = 'created' and new.status in ('preference_created','cancelled'))
    or (old.status = 'preference_created' and new.status in ('pending','approved','rejected','cancelled','expired'))
    or (old.status = 'pending' and new.status in ('approved','rejected','cancelled','expired'))
    or (old.status = 'approved' and new.status in ('refunded','charged_back'))
    or (old.status = 'charged_back' and new.status = 'approved')
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_PURCHASE_TRANSITION_INVALID';
  end if;
  return new;
end;
$function$

