end;
$function$

CREATE OR REPLACE FUNCTION public.enqueue_tournament_media_processing_job(p_session_id uuid, p_token text, p_actor_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_target jsonb;
  v_job public.tournament_media_processing_jobs%rowtype;
  v_job_id uuid;
BEGIN
  v_target := public.authorize_tournament_media_upload_target(
    p_session_id,p_token,p_actor_user_id
  );
  IF coalesce(v_target->>'processingTier','') <> 'processor_external' THEN
    RAISE EXCEPTION USING errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  END IF;
  SELECT * INTO v_job FROM public.tournament_media_processing_jobs
  WHERE session_id = p_session_id;
  IF v_job.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'jobId',v_job.id,'status',v_job.status,'created',false
    );
  END IF;
  INSERT INTO public.tournament_media_processing_jobs (
    session_id,organization_id,tournament_id,gallery_id,requested_by,
    quarantine_path,declared_mime,expected_bytes
  ) VALUES (
    p_session_id,(v_target->>'organizationId')::uuid,
    (v_target->>'tournamentId')::uuid,(v_target->>'galleryId')::uuid,
    p_actor_user_id,v_target->>'objectName',v_target->>'contentType',
    (v_target->>'expectedBytes')::bigint
  ) RETURNING id INTO v_job_id;
  INSERT INTO public.tournament_audit_log (
    organization_id,actor_user_id,actor_type,action,resource_type,
    resource_id,tournament_id,metadata
  ) VALUES (
    (v_target->>'organizationId')::uuid,p_actor_user_id,'system',
    'media.processing_job.queued','media_processing_job',v_job_id,
    (v_target->>'tournamentId')::uuid,
    jsonb_build_object('galleryId',v_target->>'galleryId')
  );
  RETURN jsonb_build_object('jobId',v_job_id,'status','queued','created',true);
END;
$function$

CREATE OR REPLACE FUNCTION public.execute_tournament_group_draw(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_group_count integer, p_seed text, p_publish boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_set public.tournament_participant_sets%rowtype;
  v_participant record;
  v_group record;
  v_group_id uuid;
  v_count integer;
  v_min_size integer;
  v_max_size integer;
  v_seed text := btrim(coalesce(p_seed, ''));
begin
  perform public.assert_tournament_fixture_scope(
    p_organization_id, p_tournament_id, p_category_id,
    case when p_publish then 'draw.publish' else 'draw.execute' end,
    array['registration', 'scheduled']::text[]
  );
  if p_group_count not between 2 and 32 or char_length(v_seed) not between 1 and 160 then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_DRAW';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:draw:' || p_tournament_id::text || ':' || p_category_id::text, 0
  ));
  select participant_set.* into v_set
  from public.tournament_participant_sets participant_set
  where participant_set.organization_id = p_organization_id
    and participant_set.tournament_id = p_tournament_id
    and participant_set.category_id = p_category_id
    and participant_set.status = 'frozen'
  for update;
  select count(*) into v_count
  from public.tournament_competition_participants participant
  where participant.participant_set_id = v_set.id and participant.status = 'active';
  if v_set.id is null or v_count < p_group_count then
    raise exception using errcode = '23514', message = 'TORNEOS_INVALID_GROUP_COUNT';
  end if;
  if exists (
    select 1 from public.tournament_groups group_row
    where group_row.participant_set_id = v_set.id
      and group_row.fixture_version_id is null
      and group_row.status = 'published'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_DRAW_NOT_EDITABLE';
  end if;
  delete from public.tournament_group_members member
  using public.tournament_groups group_row
  where member.group_id = group_row.id
    and group_row.participant_set_id = v_set.id
    and group_row.fixture_version_id is null
    and group_row.status = 'draft';
  delete from public.tournament_groups group_row
  where group_row.participant_set_id = v_set.id
    and group_row.fixture_version_id is null
    and group_row.status = 'draft';
  for v_count in 1..p_group_count loop
    insert into public.tournament_groups (
      organization_id, tournament_id, category_id, participant_set_id,
      name, code, sort_order, status, draw_seed
    ) values (
      p_organization_id, p_tournament_id, p_category_id, v_set.id,
      'Grupo ' || v_count, 'G' || lpad(v_count::text, 2, '0'),
      v_count - 1, case when p_publish then 'published' else 'draft' end, v_seed
    );
  end loop;
  for v_participant in
    select participant.id, coalesce(participant.pot_number, 2147483647) as pot_number
    from public.tournament_competition_participants participant
    where participant.participant_set_id = v_set.id and participant.status = 'active'
    order by coalesce(participant.pot_number, 2147483647),
      encode(public.digest(v_seed || ':' || participant.id::text, 'sha256'), 'hex'),
      participant.id
  loop
    select candidate.id into v_group_id
    from public.tournament_groups candidate
    where candidate.participant_set_id = v_set.id
      and candidate.fixture_version_id is null
      and candidate.status = case when p_publish then 'published' else 'draft' end
    order by
      exists (
        select 1
        from public.tournament_group_members existing_member
        join public.tournament_competition_participants existing_participant
          on existing_participant.id = existing_member.participant_id
        where existing_member.group_id = candidate.id
          and coalesce(existing_participant.pot_number, 2147483647) = v_participant.pot_number
      ),
      (select count(*) from public.tournament_group_members size_member
       where size_member.group_id = candidate.id),
      encode(public.digest(v_seed || ':group:' || candidate.sort_order::text, 'sha256'), 'hex')
    limit 1;
    insert into public.tournament_group_members (group_id, participant_id)
    values (v_group_id, v_participant.id);
  end loop;
  select min(size), max(size) into v_min_size, v_max_size
  from (
    select count(member.participant_id)::integer as size
    from public.tournament_groups group_row
    left join public.tournament_group_members member on member.group_id = group_row.id
    where group_row.participant_set_id = v_set.id
      and group_row.fixture_version_id is null
      and group_row.status = case when p_publish then 'published' else 'draft' end
    group by group_row.id
  ) sizes;
  if v_max_size - v_min_size > 1 then
    raise exception using errcode = '23514', message = 'TORNEOS_GROUP_DRAW_IMPOSSIBLE';
  end if;
  perform public.append_tournament_audit(
    p_organization_id,
    case when p_publish then 'draw.published' else 'draw.executed' end,
    'participant_set', v_set.id, null, p_tournament_id,
    jsonb_build_object(
      'categoryId', p_category_id,
      'groupCount', p_group_count,
      'seed', v_seed,
      'participantFingerprint', v_set.participant_fingerprint
    )
  );
  return jsonb_build_object(
    'participantSetId', v_set.id,
    'status', case when p_publish then 'published' else 'draft' end,
    'groupCount', p_group_count,
    'seed', v_seed,
    'participantFingerprint', v_set.participant_fingerprint
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.fail_tournament_media_processing_job(p_job_id uuid, p_lease_token text, p_failure_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_job public.tournament_media_processing_jobs%rowtype;
  v_next text;
begin
  if p_failure_code is null or p_failure_code !~ '^[A-Z][A-Z0-9_]{2,80}$' then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_FAILURE_CODE_INVALID';
  end if;
  select * into v_job
  from public.tournament_media_processing_jobs
  where id = p_job_id for update;
  if v_job.id is null
    or v_job.status <> 'leased'
    or p_lease_token is null
    or v_job.lease_token is distinct from p_lease_token
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_JOB_LEASE_INVALID';
  end if;
  v_next := case when v_job.attempts >= v_job.max_attempts
    then 'abandoned' else 'queued' end;
  update public.tournament_media_processing_jobs
  set status = v_next, lease_token = null, lease_expires_at = null,
      last_error = p_failure_code, updated_at = now()
  where id = p_job_id;
  -- The last attempt closes the session too, which is what makes the
  -- quarantined object purgeable through the existing sweeper.
  if v_next = 'abandoned' then
    perform public.fail_tournament_media_upload_session(
      v_job.session_id, p_failure_code
    );
  end if;
  return jsonb_build_object(
    'jobId',p_job_id,'status',v_next,'attempts',v_job.attempts,
    'maxAttempts',v_job.max_attempts
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.fail_tournament_media_upload_session(p_session_id uuid, p_failure_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_session public.tournament_media_upload_sessions%rowtype;
begin
  if p_failure_code is null or p_failure_code !~ '^[A-Z][A-Z0-9_]{2,80}$' then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_FAILURE_CODE_INVALID';
  end if;
  select * into v_session
  from public.tournament_media_upload_sessions
  where id = p_session_id for update;
  if v_session.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_UPLOAD_SESSION_INVALID';
  end if;
  if v_session.status <> 'issued' then
    return jsonb_build_object(
      'sessionId',p_session_id,'status',v_session.status,'changed',false
    );
  end if;
  update public.tournament_media_upload_sessions
  set status = 'failed' where id = p_session_id;
  insert into public.tournament_audit_log (
    organization_id, actor_user_id, actor_type, action, resource_type,
    resource_id, tournament_id, metadata
  ) values (
    v_session.organization_id, v_session.requested_by, 'system',
    'media.upload.failed', 'media_upload_session', p_session_id,
    v_session.tournament_id,
    jsonb_build_object('galleryId', v_session.gallery_id, 'failureCode', p_failure_code)
  );
  return jsonb_build_object(
    'sessionId',p_session_id,'status','failed','changed',true,
    'objectName',v_session.internal_path,'bucket',v_session.bucket
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_tournament_media_variants(p_asset_id uuid, p_variants jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_asset public.tournament_media_assets%rowtype;
  v_kind text;
  v_entry jsonb;
  v_expected jsonb;
  v_extension text;
  v_ready integer;
begin
  perform public.tournament_media_require_pipeline_ready();
  if jsonb_typeof(coalesce(p_variants,'null'::jsonb)) <> 'object' then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_VARIANT_PAYLOAD_INVALID';
  end if;
  select * into v_asset
  from public.tournament_media_assets where id = p_asset_id;
  if v_asset.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_asset.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_asset.gallery_id::text,1)
  );
  select * into v_asset
  from public.tournament_media_assets where id = p_asset_id for update;
  if v_asset.status not in ('pending_review','processing') then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_TRANSITION_INVALID';
  end if;
  v_extension := case v_asset.detected_mime
    when 'image/jpeg' then 'jpg' when 'image/png' then 'png' else 'webp' end;

  foreach v_kind in array array['thumbnail','grid','detail'] loop
    v_entry := p_variants -> v_kind;
    v_expected := public.tournament_media_variant_geometry(
      v_kind, v_asset.width, v_asset.height
    );
    if v_entry is null or jsonb_typeof(v_entry) <> 'object' then
      raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_VARIANT_PAYLOAD_INVALID';
    end if;
    if coalesce(v_entry->>'detectedMime','') <> v_asset.detected_mime
      or coalesce((v_entry->>'width')::integer, -1) <> (v_expected->>'width')::integer
      or coalesce((v_entry->>'height')::integer, -1) <> (v_expected->>'height')::integer
      or coalesce((v_entry->>'byteSize')::bigint, 0) < 1
      or coalesce((v_entry->>'byteSize')::bigint, 0) > 12582912
      or coalesce(v_entry->>'checksumSha256','') !~ '^[0-9a-f]{64}$'
      or coalesce((v_entry->>'metadataStripped')::boolean, false) is not true
      -- The worker states, per object, that it re-encoded from decoded pixels
      -- and that the object passed the scanner. A payload without both is a
      -- browser rendition, and browser renditions are no longer publishable.
      or coalesce((v_entry->>'pixelTranscoded')::boolean, false) is not true
      or coalesce((v_entry->>'antivirusClean')::boolean, false) is not true
    then
      raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_VARIANT_PAYLOAD_INVALID';
    end if;
    update public.tournament_media_variants variant
    set byte_size = (v_entry->>'byteSize')::bigint,
        width = (v_expected->>'width')::integer,
        height = (v_expected->>'height')::integer,
        checksum_sha256 = v_entry->>'checksumSha256',
        detected_mime = v_asset.detected_mime,
        metadata_stripped = true,
        status = 'ready'
    where variant.asset_id = p_asset_id
      and variant.kind = v_kind
      and variant.status = 'processing'
      and variant.internal_path = regexp_replace(
        v_asset.internal_path, '\.(jpg|png|webp)$', '-' || v_kind || '.' || v_extension
      );
    if not found then
      raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_VARIANT_SLOT_INVALID';
    end if;
  end loop;

  select count(*) into v_ready
  from public.tournament_media_variants variant
  where variant.asset_id = p_asset_id
    and variant.kind in ('thumbnail','grid','detail','original')
    and variant.status = 'ready'
    and variant.metadata_stripped;
  if v_ready <> 4 then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_PROCESSING_REQUIRED';
  end if;

  insert into public.tournament_audit_log (
    organization_id, actor_user_id, actor_type, action, resource_type,
    resource_id, tournament_id, metadata
  ) values (
    v_asset.organization_id, v_asset.uploaded_by, 'system',
    'media.variants.ready', 'media_asset', p_asset_id, v_asset.tournament_id,
    jsonb_build_object('galleryId', v_asset.gallery_id, 'variants', 3)
  );
  return jsonb_build_object(
    'assetId',p_asset_id,'variantsReady',v_ready,'status',v_asset.status
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.finalize_tournament_player_portrait_upload(p_actor_user_id uuid, p_portrait_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_portrait public.tournament_player_portraits%ROWTYPE;
  v_previous_id uuid;
BEGIN
  SELECT * INTO v_portrait
  FROM public.tournament_player_portraits portrait
  WHERE portrait.id = p_portrait_id
    AND portrait.lifecycle_status = 'upload_pending'
  FOR UPDATE;
  IF v_portrait.id IS NULL
    OR v_portrait.uploaded_by IS DISTINCT FROM p_actor_user_id
    OR NOT public.can_manage_tournament_player_portrait_as(
      v_portrait.organization_id, v_portrait.roster_player_id, p_actor_user_id
    )
  THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_PORTRAIT_FORBIDDEN';
  END IF;

  PERFORM 1 FROM public.tournament_roster_players player
  WHERE player.id = v_portrait.roster_player_id FOR UPDATE;

  SELECT portrait.id INTO v_previous_id
  FROM public.tournament_player_portraits portrait
  WHERE portrait.roster_player_id = v_portrait.roster_player_id
    AND portrait.lifecycle_status = 'active'
  FOR UPDATE;

  IF v_previous_id IS NOT NULL THEN
    UPDATE public.tournament_player_portraits
    SET lifecycle_status = 'replaced', replaced_by_id = v_portrait.id,
        replaced_at = now(), updated_at = now()
    WHERE id = v_previous_id;
  END IF;
  UPDATE public.tournament_player_portraits
  SET lifecycle_status = 'active', updated_at = now()
  WHERE id = v_portrait.id;

  INSERT INTO public.tournament_audit_log (
    organization_id, actor_user_id, actor_type, action, resource_type,
    resource_id, team_entry_id, tournament_id, metadata
  ) VALUES (
    v_portrait.organization_id, p_actor_user_id, 'user',
    CASE WHEN v_previous_id IS NULL THEN 'portrait.uploaded' ELSE 'portrait.replaced' END,
    'player_portrait', v_portrait.id, v_portrait.team_entry_id,
    v_portrait.tournament_id,
    jsonb_build_object('rosterPlayerId', v_portrait.roster_player_id,
      'replacedPortraitId', v_previous_id)
  );
  RETURN jsonb_build_object(
    'imageRef', jsonb_build_object(
      'kind', 'player_portrait', 'id', v_portrait.id, 'variant', 'original'
    ),
    'replacedPortraitId', v_previous_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.finish_tournament_competition(p_organization_id uuid, p_tournament_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tournament public.tournaments%rowtype;
  v_pending integer;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(
    p_organization_id, 'tournaments.finish'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:competition-lifecycle:' || p_tournament_id::text, 0
  ));

  select tournament.* into v_tournament
  from public.tournaments tournament
  join public.tournament_organizations organization
    on organization.id = tournament.organization_id
    and organization.status = 'active'
  where tournament.id = p_tournament_id
    and tournament.organization_id = p_organization_id
  for update of tournament;

  if v_tournament.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  if v_tournament.status = 'completed' then
    return jsonb_build_object(
      'id', v_tournament.id,
      'status', v_tournament.status,
      'completedAt', v_tournament.completed_at,
      'alreadyCompleted', true,
      'pendingCommitments', 0
    );
  end if;

  if v_tournament.status <> 'active' then
    raise exception using errcode = '22023',
      message = 'TORNEOS_INVALID_TOURNAMENT_TRANSITION';
  end if;

  select count(*) into v_pending
  from public.tournament_competition_open_commitments(
    p_organization_id, p_tournament_id
  );

  if v_pending > 0 then
    raise exception using errcode = '22023',
      message = 'TORNEOS_COMPETITION_HAS_PENDING_COMMITMENTS',
      detail = v_pending::text;
  end if;

  update public.tournaments
  set status = 'completed',
      completed_at = now()
  where id = p_tournament_id
  returning * into v_tournament;

  perform public.append_tournament_audit(
    p_organization_id, 'tournament.finished', 'tournament', v_tournament.id,
    null, v_tournament.id,
    jsonb_build_object(
      'previousStatus', 'active',
      'nextStatus', 'completed'
    )
  );

  return jsonb_build_object(
    'id', v_tournament.id,
    'status', v_tournament.status,
    'completedAt', v_tournament.completed_at,
    'alreadyCompleted', false,
    'pendingCommitments', 0
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.freeze_tournament_participants(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_set public.tournament_participant_sets%rowtype;
  v_tournament public.tournaments%rowtype;
  v_count integer;
  v_fingerprint text;
  v_version integer;
  v_entry_ids uuid[];
begin
  perform public.assert_tournament_fixture_scope(
    p_organization_id, p_tournament_id, p_category_id,
    'participants.freeze', array['registration']::text[]
  );
  if p_idempotency_key is null then
    raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:participants:' || p_tournament_id::text || ':' || p_category_id::text,
    0
  ));
  select participant_set.* into v_set
  from public.tournament_participant_sets participant_set
  where participant_set.organization_id = p_organization_id
    and participant_set.frozen_by = auth.uid()
    and participant_set.idempotency_key = p_idempotency_key;
  if v_set.id is not null then
    return jsonb_build_object(
      'participantSetId', v_set.id,
      'versionNumber', v_set.version_number,
      'status', v_set.status,
      'participantFingerprint', v_set.participant_fingerprint,
      'participantCount', (
        select count(*) from public.tournament_competition_participants participant
        where participant.participant_set_id = v_set.id
      )
    );
  end if;
  if exists (
    select 1 from public.tournament_participant_sets participant_set
    where participant_set.tournament_id = p_tournament_id
      and participant_set.category_id = p_category_id
      and participant_set.status = 'frozen'
  ) then
    raise exception using errcode = '23505', message = 'TORNEOS_PARTICIPANTS_ALREADY_FROZEN';
  end if;
  if exists (
    select 1
    from public.tournament_team_entries entry
    where entry.organization_id = p_organization_id
      and entry.tournament_id = p_tournament_id
      and entry.category_id = p_category_id
      and entry.status in ('submitted', 'changes_requested')
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_PENDING_REGISTRATIONS';
  end if;
  select array_agg(eligible.id order by eligible.id)
  into v_entry_ids
  from (
    select entry.id
    from public.tournament_team_entries entry
    where entry.organization_id = p_organization_id
      and entry.tournament_id = p_tournament_id
      and entry.category_id = p_category_id
      and entry.status = 'approved'
      and exists (
        select 1 from public.tournament_rosters roster
        where roster.team_entry_id = entry.id
          and roster.status in ('approved', 'locked')
      )
    order by entry.id
    for share of entry
  ) eligible;
  v_count := coalesce(array_length(v_entry_ids, 1), 0);
  v_fingerprint := encode(public.digest(
    array_to_string(v_entry_ids, '|'),
    'sha256'
  ), 'hex');
  if v_count < 2 then
    raise exception using errcode = '23514', message = 'TORNEOS_NOT_ENOUGH_PARTICIPANTS';
  end if;
  select tournament.* into v_tournament
  from public.tournaments tournament
  where tournament.id = p_tournament_id
    and tournament.organization_id = p_organization_id
  for update;
  select coalesce(max(participant_set.version_number), 0) + 1
  into v_version
  from public.tournament_participant_sets participant_set
  where participant_set.tournament_id = p_tournament_id
    and participant_set.category_id = p_category_id;
  update public.tournament_participant_sets
  set status = 'superseded', invalidated_at = coalesce(invalidated_at, now())
  where tournament_id = p_tournament_id
    and category_id = p_category_id
    and status = 'reopened';
  insert into public.tournament_participant_sets (
    organization_id, season_id, tournament_id, category_id, version_number,
    status, participant_fingerprint, frozen_by, idempotency_key
  ) values (
    p_organization_id, v_tournament.season_id, p_tournament_id, p_category_id,
    v_version, 'frozen', v_fingerprint, auth.uid(), p_idempotency_key
  ) returning * into v_set;
  insert into public.tournament_competition_participants (
    organization_id, season_id, tournament_id, category_id, participant_set_id,
    team_entry_id, status, snapshot_name, snapshot_short_name,
    snapshot_shield_path, snapshot_primary_color, snapshot_secondary_color, frozen_at
  )
  select
    entry.organization_id, entry.season_id, entry.tournament_id, entry.category_id,
    v_set.id, entry.id, 'active', entry.name, entry.short_name, entry.shield_path,
    entry.primary_color, entry.secondary_color, v_set.frozen_at
  from public.tournament_team_entries entry
  where entry.id = any(v_entry_ids)
  order by entry.id;
  perform public.append_tournament_audit(
    p_organization_id, 'participants.frozen', 'participant_set', v_set.id,
    null, p_tournament_id,
    jsonb_build_object(
      'categoryId', p_category_id,
      'versionNumber', v_version,
      'participantCount', v_count,
      'participantFingerprint', v_fingerprint
    )
  );
  return jsonb_build_object(
    'participantSetId', v_set.id,
    'versionNumber', v_version,
    'status', 'frozen',
    'participantFingerprint', v_fingerprint,
    'participantCount', v_count,
    'frozenAt', v_set.frozen_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.generate_tournament_fixture(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_seed text, p_configuration jsonb, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_set public.tournament_participant_sets%rowtype;
  v_tournament public.tournaments%rowtype;
  v_version public.tournament_fixture_versions%rowtype;
  v_version_number integer;
  v_phase_id uuid;
  v_knockout_phase_id uuid;
  v_participants uuid[];
  v_sources jsonb := '[]'::jsonb;
  v_group record;
  v_new_group_id uuid;
  v_group_participants uuid[];
  v_group_map jsonb := '{}'::jsonb;
  v_group_count integer;
  v_qualifiers integer;
  v_index integer;
  v_double boolean;
  v_knockout_double boolean;
  v_snapshot jsonb;
  v_effective_seed text;
  v_draw_seed text;
  v_distinct_draw_seeds integer;
begin
  perform public.assert_tournament_fixture_scope(
    p_organization_id, p_tournament_id, p_category_id,
    'fixture.generate', array['registration', 'scheduled']::text[]
  );
  if p_idempotency_key is null
    or jsonb_typeof(coalesce(p_configuration, '{}'::jsonb)) <> 'object'
    or coalesce((p_configuration->>'minimumRestMinutes')::integer, 720)
      not between 1 and 10080
    or coalesce((p_configuration->>'maximumConsecutiveHome')::integer, 3)
      not between 1 and 20
    or coalesce((p_configuration->>'maximumMatchesPerDay')::integer, 1)
      not between 1 and 10
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_FIXTURE_CONFIGURATION';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:fixture:' || p_tournament_id::text || ':' || p_category_id::text, 0
  ));
  select version.* into v_version
  from public.tournament_fixture_versions version
  where version.organization_id = p_organization_id
    and version.created_by = auth.uid()
    and version.idempotency_key = p_idempotency_key;
  if v_version.id is not null then
    return jsonb_build_object(
      'fixtureVersionId', v_version.id,
      'versionNumber', v_version.version_number,
      'status', v_version.status
    );
  end if;
  select participant_set.* into v_set
  from public.tournament_participant_sets participant_set
  where participant_set.organization_id = p_organization_id
    and participant_set.tournament_id = p_tournament_id
    and participant_set.category_id = p_category_id
    and participant_set.status = 'frozen'
  for update;
  select tournament.* into v_tournament
  from public.tournaments tournament
  where tournament.organization_id = p_organization_id
    and tournament.id = p_tournament_id
  for update;
  if v_set.id is null or v_tournament.id is null then
    raise exception using errcode = '23514', message = 'TORNEOS_PARTICIPANTS_NOT_FROZEN';
  end if;
  select array_agg(participant.id order by participant.seed_number nulls last, participant.id)
  into v_participants
  from public.tournament_competition_participants participant
  where participant.participant_set_id = v_set.id and participant.status = 'active';
  if coalesce(array_length(v_participants, 1), 0) < 2 then
    raise exception using errcode = '23514', message = 'TORNEOS_NOT_ENOUGH_PARTICIPANTS';
  end if;
  v_effective_seed := nullif(btrim(coalesce(p_seed, '')), '');
  if v_tournament.competition_format in ('groups', 'groups_and_playoffs') then
    select
      min(nullif(btrim(group_row.draw_seed), '')),
      count(distinct nullif(btrim(group_row.draw_seed), ''))
    into v_draw_seed, v_distinct_draw_seeds
    from public.tournament_groups group_row
    where group_row.participant_set_id = v_set.id
      and group_row.fixture_version_id is null
      and group_row.status = 'published';
    if v_draw_seed is null or v_distinct_draw_seeds <> 1 then
      raise exception using errcode = '23514', message = 'TORNEOS_GROUP_DRAW_SEED_INVALID';
    end if;
    if v_effective_seed is not null and v_effective_seed <> v_draw_seed then
      raise exception using errcode = '23514', message = 'TORNEOS_GROUP_DRAW_SEED_MISMATCH';
    end if;
    v_effective_seed := v_draw_seed;
  end if;
  select coalesce(max(version.version_number), 0) + 1 into v_version_number
  from public.tournament_fixture_versions version
  where version.tournament_id = p_tournament_id and version.category_id = p_category_id;
  v_snapshot := jsonb_build_object(
    'competitionFormat', v_tournament.competition_format,
    'formatSettings', v_tournament.format_settings,
    'requestedConfiguration', coalesce(p_configuration, '{}'::jsonb),
    'minimumRestMinutes', coalesce((p_configuration->>'minimumRestMinutes')::integer, 720),
    'maximumConsecutiveHome', coalesce((p_configuration->>'maximumConsecutiveHome')::integer, 3),
    'maximumMatchesPerDay', coalesce((p_configuration->>'maximumMatchesPerDay')::integer, 1)
  );
  insert into public.tournament_fixture_versions (
    organization_id, season_id, tournament_id, category_id, participant_set_id,
    version_number, status, generation_method, seed, participant_fingerprint,
    configuration_snapshot, created_by, idempotency_key
  ) values (
    p_organization_id, v_set.season_id, p_tournament_id, p_category_id, v_set.id,
    v_version_number, 'draft',
    case when v_tournament.competition_format in ('groups', 'groups_and_playoffs')
      then 'draw' else 'automatic' end,
    v_effective_seed, v_set.participant_fingerprint,
    v_snapshot, auth.uid(), p_idempotency_key
  ) returning * into v_version;

  if v_tournament.competition_format in ('league', 'league_and_playoffs') then
    insert into public.tournament_phases (
      organization_id, tournament_id, category_id, fixture_version_id,
      name, phase_type, sequence_number, status, configuration
    ) values (
      p_organization_id, p_tournament_id, p_category_id, v_version.id,
      'Liga', 'league', 1, 'generated', v_tournament.format_settings
    ) returning id into v_phase_id;
    v_double := coalesce(
      v_tournament.format_settings->>'rounds',
      v_tournament.format_settings->>'leagueRounds',
      'single'
    ) = 'double';
    perform public.build_tournament_round_robin(
      v_version.id, v_phase_id, null, v_participants, v_double
    );
  end if;

  if v_tournament.competition_format in ('groups', 'groups_and_playoffs') then
    select count(*) into v_group_count
    from public.tournament_groups group_row
    where group_row.participant_set_id = v_set.id
      and group_row.fixture_version_id is null
      and group_row.status = 'published';
    if v_group_count < 2 then
      raise exception using errcode = '23514', message = 'TORNEOS_GROUP_DRAW_REQUIRED';
    end if;
    insert into public.tournament_phases (
      organization_id, tournament_id, category_id, fixture_version_id,
      name, phase_type, sequence_number, status, configuration
    ) values (
      p_organization_id, p_tournament_id, p_category_id, v_version.id,
      'Fase de grupos', 'groups', 1, 'generated', v_tournament.format_settings
    ) returning id into v_phase_id;
    for v_group in
      select group_row.*
      from public.tournament_groups group_row
      where group_row.participant_set_id = v_set.id
        and group_row.fixture_version_id is null
        and group_row.status = 'published'
      order by group_row.sort_order, group_row.code
    loop
      insert into public.tournament_groups (
        organization_id, tournament_id, category_id, participant_set_id,
        fixture_version_id, phase_id, name, code, sort_order, status, draw_seed
      ) values (
        p_organization_id, p_tournament_id, p_category_id, v_set.id,
        v_version.id, v_phase_id, v_group.name, v_group.code, v_group.sort_order,
        'published', v_group.draw_seed
      ) returning id into v_new_group_id;
      insert into public.tournament_group_members (group_id, participant_id, position_seed)
      select v_new_group_id, member.participant_id, member.position_seed
      from public.tournament_group_members member
      where member.group_id = v_group.id
      order by member.position_seed nulls last, member.participant_id;
      v_group_map := v_group_map || jsonb_build_object(v_group.id::text, v_new_group_id);
      select array_agg(member.participant_id order by member.position_seed nulls last, member.participant_id)
      into v_group_participants
      from public.tournament_group_members member
      where member.group_id = v_group.id;
      v_double := coalesce(
        v_tournament.format_settings->>'rounds',
        v_tournament.format_settings->>'groupRounds',
        'single'
      ) = 'double';
      perform public.build_tournament_round_robin(
        v_version.id, v_phase_id, v_new_group_id, v_group_participants, v_double
      );
    end loop;
  end if;

  if v_tournament.competition_format = 'knockout' then
    for v_index in 1..array_length(v_participants, 1) loop
      v_sources := v_sources || jsonb_build_array(jsonb_build_object(
        'type', 'participant', 'participantId', v_participants[v_index]
      ));
    end loop;
    insert into public.tournament_phases (
      organization_id, tournament_id, category_id, fixture_version_id,
      name, phase_type, sequence_number, status, configuration
    ) values (
      p_organization_id, p_tournament_id, p_category_id, v_version.id,
      'Eliminación directa', 'custom_knockout', 1, 'generated', v_tournament.format_settings
    ) returning id into v_phase_id;
    perform public.build_tournament_knockout(
      v_version.id, v_phase_id, v_sources,
      coalesce(v_tournament.format_settings->>'legs', 'single') = 'double',
      coalesce((v_tournament.format_settings->>'thirdPlace')::boolean, false)
    );
  elsif v_tournament.competition_format = 'groups_and_playoffs' then
    v_sources := '[]'::jsonb;
    v_qualifiers := coalesce((v_tournament.format_settings->>'qualifiersPerGroup')::integer, 2);
    if v_qualifiers < 1 or exists (
      select 1
      from public.tournament_groups group_row
      where group_row.fixture_version_id = v_version.id
        and (
          select count(*)
          from public.tournament_group_members member
          where member.group_id = group_row.id
        ) < v_qualifiers
    ) then
      raise exception using errcode = '23514', message = 'TORNEOS_INVALID_QUALIFIERS';
    end if;
    for v_group in
      select group_row.id
      from public.tournament_groups group_row
      where group_row.fixture_version_id = v_version.id
      order by group_row.sort_order, group_row.code
    loop
      for v_index in 1..v_qualifiers loop
        v_sources := v_sources || jsonb_build_array(jsonb_build_object(
          'type', 'group_position', 'groupId', v_group.id, 'positionNumber', v_index
        ));
      end loop;
    end loop;
    insert into public.tournament_phases (
      organization_id, tournament_id, category_id, fixture_version_id,
      name, phase_type, sequence_number, status, configuration
    ) values (
      p_organization_id, p_tournament_id, p_category_id, v_version.id,
      'Playoffs', 'custom_knockout', 2, 'generated', v_tournament.format_settings
    ) returning id into v_knockout_phase_id;
    perform public.build_tournament_knockout(
      v_version.id, v_knockout_phase_id, v_sources,
      coalesce(v_tournament.format_settings->>'knockoutLegs', 'single') = 'double',
      false
    );
  elsif v_tournament.competition_format = 'league_and_playoffs' then
    v_sources := '[]'::jsonb;
    v_qualifiers := coalesce((v_tournament.format_settings->>'qualifiers')::integer, 4);
    if v_qualifiers < 2 or v_qualifiers > array_length(v_participants, 1) then
      raise exception using errcode = '23514', message = 'TORNEOS_INVALID_QUALIFIERS';
    end if;
    for v_index in 1..v_qualifiers loop
      v_sources := v_sources || jsonb_build_array(jsonb_build_object(
        'type', 'league_position', 'phaseId', v_phase_id, 'rankNumber', v_index
      ));
    end loop;
    insert into public.tournament_phases (
      organization_id, tournament_id, category_id, fixture_version_id,
      name, phase_type, sequence_number, status, configuration
    ) values (
      p_organization_id, p_tournament_id, p_category_id, v_version.id,
      'Playoffs', 'custom_knockout', 2, 'generated', v_tournament.format_settings
    ) returning id into v_knockout_phase_id;
    perform public.build_tournament_knockout(
      v_version.id, v_knockout_phase_id, v_sources,
      coalesce(v_tournament.format_settings->>'knockoutLegs', 'single') = 'double',
      false
    );
  end if;
  perform public.append_tournament_audit(
    p_organization_id, 'fixture.generated', 'fixture_version', v_version.id,
    null, p_tournament_id,
    jsonb_build_object(
      'categoryId', p_category_id,
      'versionNumber', v_version_number,
      'method', v_version.generation_method,
      'seed', v_version.seed,
      'participantFingerprint', v_set.participant_fingerprint,
      'matchCount', (
        select count(*) from public.tournament_matches match_row
        where match_row.fixture_version_id = v_version.id
      )
    )
  );
  return jsonb_build_object(
    'fixtureVersionId', v_version.id,
    'versionNumber', v_version_number,
    'status', 'draft',
    'phaseCount', (
      select count(*) from public.tournament_phases phase
      where phase.fixture_version_id = v_version.id
    ),
    'roundCount', (
      select count(*) from public.tournament_rounds round_row
      where round_row.fixture_version_id = v_version.id
    ),
    'matchCount', (
      select count(*) from public.tournament_matches match_row
      where match_row.fixture_version_id = v_version.id
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_effective_tournament_entitlements(p_organization_id uuid, p_tournament_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_season_id uuid; v_result jsonb; v_usage integer;
begin
  if auth.uid() is null or p_tournament_id is null then
    raise exception using errcode='42501',message='TORNEOS_ENTITLEMENTS_FORBIDDEN';
  end if;
  select season_id into v_season_id from public.tournaments
  where organization_id=p_organization_id and id=p_tournament_id;
  if v_season_id is null or not public.has_tournament_season_access(p_organization_id,v_season_id) then
    raise exception using errcode='42501',message='TORNEOS_ENTITLEMENTS_FORBIDDEN';
  end if;
  v_result := public.resolve_effective_tournament_season_entitlements_at(
    p_organization_id,v_season_id,now(),false,p_tournament_id
  );
  select count(*)::integer into v_usage from public.tournament_season_member_assignments
  where organization_id=p_organization_id and season_id=v_season_id;
  return jsonb_set(v_result,'{administration,currentAdministrativeSeatUsage}',to_jsonb(v_usage),true);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_effective_tournament_season_entitlements(p_organization_id uuid, p_season_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_result jsonb; v_usage integer;
begin
  if auth.uid() is null then raise exception using errcode='42501',message='TORNEOS_AUTH_REQUIRED'; end if;
  if not public.has_tournament_season_access(p_organization_id,p_season_id) then
    raise exception using errcode='42501',message='TORNEOS_ENTITLEMENTS_FORBIDDEN';
  end if;
  v_result := public.resolve_effective_tournament_season_entitlements_at(
    p_organization_id,p_season_id,now(),false,null
  );
  select count(*)::integer into v_usage
  from public.tournament_season_member_assignments
  where organization_id=p_organization_id and season_id=p_season_id;
  return jsonb_set(v_result,'{administration,currentAdministrativeSeatUsage}',to_jsonb(v_usage),true);
end;
$function$

CREATE OR REPLACE FUNCTION public.get_my_tournament_notification_preferences(p_tournament_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tournament public.tournaments%rowtype;
  v_preference public.tournament_notification_preferences%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.can_access_tournament_communications(p_tournament_id) then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  select * into v_tournament from public.tournaments where id = p_tournament_id;
  select * into v_preference
  from public.tournament_notification_preferences preference
  where preference.tournament_id = p_tournament_id
    and preference.user_id = auth.uid();
  return jsonb_build_object(
    'tournamentId',p_tournament_id,
    'general',coalesce(v_preference.general_enabled,true),
    'matchChanges',coalesce(v_preference.match_changes_enabled,true),
    'callups',coalesce(v_preference.callups_enabled,true),
    'discipline',coalesce(v_preference.discipline_enabled,true),
    'documents',coalesce(v_preference.documents_enabled,true),
    'summaries',coalesce(v_preference.summaries_enabled,true),
    'mandatoryInbox',jsonb_build_array('own_match_urgent','own_discipline','required_document'),
    'channels',jsonb_build_object('internal',true,'push',false,'email',false)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_published_tournament_media(p_tournament_id uuid, p_category_id uuid DEFAULT NULL::uuid, p_match_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_result jsonb;
  v_readiness jsonb := public.tournament_media_pipeline_readiness();
  v_delivery jsonb;
begin
  if auth.uid() is null or not public.can_read_tournament_participant_hub(
    p_tournament_id,p_category_id
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  if p_limit < 1 or p_limit > 50 or p_offset < 0 then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_FILTER_INVALID';
  end if;
  if p_match_id is not null and not exists (
    select 1 from public.tournament_matches match
    where match.id = p_match_id and match.tournament_id = p_tournament_id
      and (p_category_id is null or match.category_id = p_category_id)
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  -- Reading requires the signer only. A missing processor blocks new uploads
  -- but must not hide media that was already published.
  v_delivery := jsonb_build_object(
    'status',case
      when (v_readiness->>'storageReady')::boolean
        and (v_readiness->>'signerReady')::boolean
      then 'signed_urls' else 'staging_required' end,
    'signedUrlTtlSeconds',300,'originalsRestricted',true
  );
  select jsonb_build_object(
    'delivery',v_delivery,
    'items',coalesce(jsonb_agg(jsonb_build_object(
      'id',gallery.id,'title',gallery.title,'description',gallery.description,
      'visibility',gallery.visibility,'matchId',gallery.match_id,
      'publishedAt',gallery.published_at,'coverAssetId',gallery.cover_asset_id,
      'assets',(
        select coalesce(jsonb_agg(jsonb_build_object(
          'id',asset.id,'safeName',asset.safe_name,
          'width',asset.width,'height',asset.height,
          'caption',item.caption,'sortOrder',item.sort_order,
          'thumbnailUrl',null,'gridUrl',null,'detailUrl',null,
          'originalAvailable',false
        ) order by item.sort_order),'[]'::jsonb)
        from public.tournament_media_gallery_items item
        join public.tournament_media_assets asset on asset.id = item.asset_id
        where item.gallery_id = gallery.id and asset.status = 'published'
      )
    ) order by gallery.published_at desc),'[]'::jsonb)
  ) into v_result
  from (
    select *
    from public.tournament_media_galleries gallery_page
    where gallery_page.tournament_id = p_tournament_id
      and gallery_page.status = 'published'
      and (p_category_id is null or gallery_page.category_id is null
        or gallery_page.category_id = p_category_id)
      and (p_match_id is null or gallery_page.match_id = p_match_id)
      and public.can_current_user_read_media_gallery(gallery_page.id)
    order by gallery_page.published_at desc
    limit p_limit offset p_offset
  ) gallery;
  return coalesce(v_result,jsonb_build_object(
    'delivery',v_delivery,'items','[]'::jsonb
  ));
end;
$function$

CREATE OR REPLACE FUNCTION public.get_tournament_branding_context(p_organization_id uuid, p_tournament_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_organization public.tournament_organizations%ROWTYPE;
  v_tournament public.tournaments%ROWTYPE;
  v_tournaments jsonb := '[]'::jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_AUTH_REQUIRED';
  END IF;

  SELECT organization.*
  INTO v_organization
  FROM public.tournament_organizations organization
  WHERE organization.id = p_organization_id
    AND organization.status = 'active';

  IF v_organization.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_RESOURCE_FORBIDDEN';
  END IF;

  IF p_tournament_id IS NULL THEN
    IF NOT public.has_tournament_organization_capability(
      p_organization_id,
      'tournaments.read'
    ) THEN
      RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_RESOURCE_FORBIDDEN';
    END IF;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', tournament.id,
      'logoPath', tournament.logo_path
    ) ORDER BY tournament.updated_at DESC, tournament.id), '[]'::jsonb)
    INTO v_tournaments
    FROM public.tournaments tournament
    WHERE tournament.organization_id = p_organization_id
      AND tournament.status <> 'archived';
  ELSE
    SELECT tournament.*
    INTO v_tournament
    FROM public.tournaments tournament
    WHERE tournament.id = p_tournament_id
      AND tournament.organization_id = p_organization_id
      AND tournament.status <> 'archived';

    IF v_tournament.id IS NULL OR NOT (
      public.has_tournament_organization_capability(
        p_organization_id,
        'tournaments.read'
      )
      OR public.can_read_tournament_participant_hub(p_tournament_id, NULL)
    ) THEN
      RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_RESOURCE_FORBIDDEN';
    END IF;

    v_tournaments := jsonb_build_array(jsonb_build_object(
      'id', v_tournament.id,
      'logoPath', v_tournament.logo_path
    ));
  END IF;

  RETURN jsonb_build_object(
    'organization', jsonb_build_object(
      'id', v_organization.id,
      'name', v_organization.name,
      'logoPath', v_organization.logo_path
    ),
    'tournaments', v_tournaments
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_tournament_competition_context(p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_payload jsonb;
  v_seasons jsonb;
  v_tournaments jsonb;
  v_preference jsonb;
  v_active_season_id uuid;
  v_active_tournament_id uuid;
begin
  if auth.uid() is null then raise exception using errcode='42501',message='TORNEOS_AUTH_REQUIRED'; end if;
  if not public.is_tournament_organization_member(p_organization_id) then
    raise exception using errcode='42501',message='TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  v_payload := public.get_tournament_competition_context_organization_legacy(p_organization_id);
  select coalesce(jsonb_agg(item order by item->>'updatedAt' desc),'[]'::jsonb) into v_seasons
  from jsonb_array_elements(v_payload->'seasons') item
  where public.has_tournament_season_access(p_organization_id,(item->>'id')::uuid);
  select coalesce(jsonb_agg(item order by item->>'updatedAt' desc),'[]'::jsonb) into v_tournaments
  from jsonb_array_elements(v_payload->'tournaments') item
  where public.has_tournament_season_access(p_organization_id,(item->>'seasonId')::uuid);
  v_preference := v_payload->'preference';
  v_active_season_id := nullif(v_preference->>'activeSeasonId','')::uuid;
  v_active_tournament_id := nullif(v_preference->>'activeTournamentId','')::uuid;
  if v_active_season_id is null or not public.has_tournament_season_access(p_organization_id,v_active_season_id) then
    select (item->>'id')::uuid into v_active_season_id from jsonb_array_elements(v_seasons) item limit 1;
    v_active_tournament_id := null;
  end if;
  if v_active_tournament_id is not null and not exists (
    select 1 from jsonb_array_elements(v_tournaments) item
    where (item->>'id')::uuid = v_active_tournament_id
  ) then v_active_tournament_id := null; end if;
  return v_payload || jsonb_build_object('seasons',v_seasons,'tournaments',v_tournaments,
    'preference',jsonb_build_object('organizationId',p_organization_id,
      'activeSeasonId',v_active_season_id,'activeTournamentId',v_active_tournament_id,
      'updatedAt',v_preference->'updatedAt'));
end;
$function$

CREATE OR REPLACE FUNCTION public.get_tournament_creation_eligibility(p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.is_tournament_organization_member(p_organization_id) then
    raise exception using errcode = '42501', message = 'TORNEOS_PLAN_FORBIDDEN';
  end if;
  return jsonb_build_object(
    'schemaVersion',2,
    'organizationId',p_organization_id,
    'status','free_available',
    'commercialUnit','season',
    'hasConsumedFreeTournament',false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.get_tournament_media_asset_processing_tiers(p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION USING errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  END IF;
  IF NOT public.has_tournament_media_capability(p_organization_id,'media.read') THEN
    RAISE EXCEPTION USING errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  END IF;
  RETURN coalesce((
    SELECT jsonb_object_agg(asset.id::text,asset.processing_tier)
    FROM public.tournament_media_assets asset
    WHERE asset.organization_id = p_organization_id
  ),'{}'::jsonb);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_tournament_media_upload_capability(p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION USING errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  END IF;
  IF NOT public.has_tournament_media_capability(p_organization_id,'media.read') THEN
    RAISE EXCEPTION USING errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  END IF;
  RETURN public.tournament_media_effective_readiness();
END;
$function$

CREATE OR REPLACE FUNCTION public.get_tournament_player_portrait_ref(p_organization_id uuid, p_roster_player_id uuid, p_variant text DEFAULT 'original'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE v_portrait_id uuid;
BEGIN
  IF auth.uid() IS NULL OR p_variant <> 'original'
    OR NOT public.can_read_tournament_player_portrait(
      p_organization_id, p_roster_player_id
    )
  THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_PORTRAIT_FORBIDDEN';
  END IF;
  SELECT id INTO v_portrait_id FROM public.tournament_player_portraits
  WHERE organization_id = p_organization_id
