CREATE OR REPLACE FUNCTION public.get_tournament_purchase(p_purchase_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_purchase public.tournament_purchases%rowtype;
begin
  if auth.uid() is null then
