CREATE OR REPLACE FUNCTION public.get_tournament_season_media_usage(p_organization_id uuid, p_season_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_policy jsonb; v_assets integer; v_pending integer; v_limit integer;
begin
  if not public.has_tournament_season_access(p_organization_id,p_season_id) then
    raise exception using errcode='42501',message='TORNEOS_MEDIA_FORBIDDEN';
  end if;
  v_policy:=public.resolve_effective_tournament_season_entitlements_at(
    p_organization_id,p_season_id,now(),false,null
  );
  select count(*)::integer into v_assets
  from public.tournament_media_assets asset join public.tournaments tournament
    on tournament.organization_id=asset.organization_id and tournament.id=asset.tournament_id
  where asset.organization_id=p_organization_id and tournament.season_id=p_season_id
    and asset.status not in ('rejected','revoked','failed') and asset.storage_state<>'storage_purged';
  select count(*)::integer into v_pending
  from public.tournament_media_upload_sessions session join public.tournaments tournament
    on tournament.organization_id=session.organization_id and tournament.id=session.tournament_id
  where session.organization_id=p_organization_id and tournament.season_id=p_season_id
    and session.status in ('issued','uploaded') and session.expires_at>now();
  v_limit:=(v_policy->'media'->>'galleryAssetLimit')::integer;
  return jsonb_build_object('schemaVersion',1,'organizationId',p_organization_id,
    'seasonId',p_season_id,'plan',v_policy->>'plan','assetCount',v_assets,
    'pendingCount',v_pending,'usage',v_assets+v_pending,'limit',v_limit,
    'remaining',greatest(v_limit-v_assets-v_pending,0));
end;
$function$

CREATE OR REPLACE FUNCTION public.get_tournament_social_snapshot(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_phase_id uuid, p_piece text, p_round_id uuid DEFAULT NULL::uuid, p_group_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_season_id uuid; v_policy jsonb; v_snapshot jsonb;
begin
  select season_id into v_season_id from public.tournaments
  where organization_id=p_organization_id and id=p_tournament_id;
  if v_season_id is null or not public.has_tournament_season_access(p_organization_id,v_season_id) then
    raise exception using errcode='42501',message='TORNEOS_SOCIAL_FORBIDDEN';
  end if;
  v_policy:=public.resolve_effective_tournament_season_entitlements_at(
    p_organization_id,v_season_id,now(),false,p_tournament_id
  );
  -- Snapshot access is preview/catalog access. Export authorization below is
  -- the product gate; FREE may inspect all eleven families without gaining use.
  v_snapshot:=public.get_tournament_social_snapshot_plan_legacy(
    p_organization_id,p_tournament_id,p_category_id,p_phase_id,p_piece,p_round_id,p_group_id
  );
  return v_snapshot || jsonb_build_object('seasonId',v_season_id,
    'plan',v_policy->>'plan','social',v_policy->'social','branding',v_policy->'branding');
end;
$function$

CREATE OR REPLACE FUNCTION public.get_tournament_social_snapshot_plan_legacy(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_phase_id uuid, p_piece text, p_round_id uuid DEFAULT NULL::uuid, p_group_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_scope jsonb;
  v_official jsonb;
  v_standings jsonb;
  v_statistics jsonb;
  v_player_candidates jsonb;
  v_next_fixture jsonb;
  v_round_name text;
  v_round_number integer;
  v_effective_round_id uuid;
  v_sport_modality text;
  v_team_size smallint;
  v_pieces text[] := ARRAY[
    'next_fixture','round_results','standings','scorers','discipline',
    'best_eleven','mvp','round_summary','semifinals','final','champion'
  ];
BEGIN
  IF NOT public.has_tournament_social_capability(p_organization_id, 'social.read') THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_SOCIAL_FORBIDDEN';
  END IF;
  IF p_piece IS NULL OR NOT (p_piece = ANY(v_pieces)) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TORNEOS_SOCIAL_PIECE_INVALID';
  END IF;

  v_scope := public.tournament_social_published_scope(
    p_organization_id, p_tournament_id, p_category_id, p_phase_id
  );
  IF v_scope IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_SOCIAL_SCOPE_UNAVAILABLE';
  END IF;

  SELECT coalesce(category.sport_modality, tournament.sport_modality),
    coalesce(category.team_size, tournament.team_size)
  INTO v_sport_modality, v_team_size
  FROM public.tournaments tournament
  JOIN public.tournament_categories category
    ON category.id = p_category_id
   AND category.tournament_id = tournament.id
   AND category.organization_id = tournament.organization_id
  WHERE tournament.id = p_tournament_id
    AND tournament.organization_id = p_organization_id;

  IF v_sport_modality IS NULL OR v_team_size IS NULL
    OR v_team_size <> ALL(ARRAY[5,6,7,8,9,11]::smallint[])
    OR NOT EXISTS (
      SELECT 1 FROM public.tournament_sport_modalities modality
      WHERE modality.code = v_sport_modality AND modality.team_size = v_team_size
    )
  THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TORNEOS_SOCIAL_TEAM_FORMAT_INVALID';
  END IF;

  IF p_piece = 'next_fixture' THEN
    v_next_fixture := public.tournament_social_next_fixture(
      (v_scope->>'fixtureVersionId')::uuid, p_phase_id, p_group_id
    );
    v_effective_round_id := (v_next_fixture->>'roundId')::uuid;
    v_round_name := v_next_fixture->>'roundName';
    v_round_number := (v_next_fixture->>'roundNumber')::integer;
  ELSE
    v_effective_round_id := p_round_id;
    IF p_round_id IS NOT NULL THEN
      SELECT round.name, round.round_number
      INTO v_round_name, v_round_number
      FROM public.tournament_rounds round
      WHERE round.id = p_round_id
        AND round.fixture_version_id = (v_scope->>'fixtureVersionId')::uuid
        AND round.phase_id = p_phase_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_SOCIAL_SCOPE_UNAVAILABLE';
      END IF;
    END IF;
  END IF;

  IF p_piece IN ('standings','round_summary','champion') THEN
    v_standings := public.get_published_tournament_standings(
      p_tournament_id, p_category_id, p_phase_id, p_group_id
    );
  END IF;
  IF p_piece IN ('scorers','discipline','best_eleven','mvp','round_summary') THEN
    v_statistics := public.get_published_tournament_statistics(
      p_tournament_id, p_category_id, p_phase_id, p_group_id
    );
  END IF;
  IF p_piece IN ('best_eleven','mvp') THEN
    v_player_candidates := public.tournament_social_player_candidates(
      (v_scope->>'fixtureVersionId')::uuid,
      coalesce(v_statistics->'players', '[]'::jsonb)
    );
  END IF;

  v_official := CASE p_piece
    WHEN 'next_fixture' THEN jsonb_build_object(
      'semantics', v_next_fixture->>'semantics',
      'matches', coalesce(v_next_fixture->'matches', '[]'::jsonb)
    )
    WHEN 'round_results' THEN jsonb_build_object(
      'matches', public.tournament_social_match_rows(
        (v_scope->>'fixtureVersionId')::uuid, p_phase_id, p_round_id, true
      )
    )
    WHEN 'semifinals' THEN jsonb_build_object(
      'matches', public.tournament_social_match_rows(
        (v_scope->>'fixtureVersionId')::uuid, p_phase_id, p_round_id, false
      )
    )
    WHEN 'final' THEN jsonb_build_object(
      'matches', public.tournament_social_match_rows(
        (v_scope->>'fixtureVersionId')::uuid, p_phase_id, p_round_id, false
      )
    )
    WHEN 'standings' THEN jsonb_build_object(
      'revision', v_standings->'revision',
      'rows', coalesce(v_standings->'standings', '[]'::jsonb)
    )
    WHEN 'scorers' THEN jsonb_build_object(
      'revisionId', v_statistics->'revisionId',
      'players', coalesce((
        SELECT jsonb_agg(player)
        FROM jsonb_array_elements(coalesce(v_statistics->'players','[]'::jsonb)) player
        WHERE (player->>'goals')::integer > 0
      ), '[]'::jsonb)
    )
    WHEN 'discipline' THEN jsonb_build_object(
      'revisionId', v_statistics->'revisionId',
      'players', coalesce((
        SELECT jsonb_agg(player)
        FROM jsonb_array_elements(coalesce(v_statistics->'discipline','[]'::jsonb)) player
        WHERE (player->>'fairPlayPoints')::integer > 0
      ), '[]'::jsonb)
    )
    WHEN 'round_summary' THEN jsonb_build_object(
      'matches', public.tournament_social_match_rows(
        (v_scope->>'fixtureVersionId')::uuid, p_phase_id, p_round_id, true
      ),
      'leaders', coalesce((
        SELECT jsonb_agg(player)
        FROM jsonb_array_elements(coalesce(v_statistics->'players','[]'::jsonb)) player
        WHERE (player->>'goals')::integer > 0
        LIMIT 5
      ), '[]'::jsonb),
      'topOfTable', coalesce(v_standings->'standings'->0, 'null'::jsonb)
    )
    WHEN 'best_eleven' THEN jsonb_build_object(
      'requiresHumanSelection', true,
      'sportModality', v_sport_modality,
      'teamSize', v_team_size,
      'candidates', v_player_candidates
    )
    WHEN 'mvp' THEN jsonb_build_object(
      'requiresHumanSelection', true,
      'candidates', v_player_candidates
    )
    WHEN 'champion' THEN jsonb_build_object(
      'requiresHumanSelection', true,
      'officialChampion', (
        SELECT jsonb_build_object(
          'participantId', standing->>'participantId',
          'teamName', standing->>'teamName',
          'shortName', standing->>'shortName',
          'shieldPath', standing->>'shieldPath'
        )
        FROM jsonb_array_elements(coalesce(v_standings->'standings','[]'::jsonb)) standing
        WHERE (standing->>'position')::integer = 1
          AND EXISTS (
            SELECT 1 FROM public.tournaments tournament
            WHERE tournament.id = p_tournament_id AND tournament.status = 'completed'
          )
        LIMIT 1
      ),
      'candidates', coalesce(v_standings->'standings', '[]'::jsonb)
    )
  END;

  RETURN jsonb_build_object(
    'schemaVersion', 2,
    'piece', p_piece,
    'generatedAt', now(),
    'source', jsonb_build_object(
      'organizationId', p_organization_id,
      'tournamentId', p_tournament_id,
      'categoryId', p_category_id,
      'phaseId', p_phase_id,
      'groupId', p_group_id,
      'roundId', v_effective_round_id,
      'fixtureVersionId', v_scope->>'fixtureVersionId',
      'standingsRevisionId', coalesce(
        v_standings->'revision'->>'id', v_statistics->>'revisionId'
      ),
      'standingsRevisionNumber', v_standings->'revision'->>'number'
    ),
    'competition', jsonb_build_object(
      'organizationName', v_scope->>'organizationName',
      'tournamentName', v_scope->>'tournamentName',
      'categoryName', v_scope->>'categoryName',
      'phaseName', v_scope->>'phaseName',
      'roundName', v_round_name,
      'roundNumber', v_round_number,
      'sportModality', v_sport_modality,
      'teamSize', v_team_size
    ),
    'official', coalesce(v_official, '{}'::jsonb),
    'capabilities', to_jsonb(
      public.current_user_tournament_social_capabilities(p_organization_id)
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_tournament_social_studio_context(p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_payload jsonb; v_tournaments jsonb;
begin
  v_payload:=public.get_tournament_social_studio_context_organization_legacy(p_organization_id);
  select coalesce(jsonb_agg(item),'[]'::jsonb) into v_tournaments
  from jsonb_array_elements(v_payload->'tournaments') item
  join public.tournaments tournament on tournament.id=(item->>'id')::uuid
  where tournament.organization_id=p_organization_id
    and public.has_tournament_season_access(p_organization_id,tournament.season_id);
  return v_payload || jsonb_build_object('tournaments',v_tournaments,
    'commercialUnit','season','freeBaseFamilies',
    jsonb_build_array('round_results','standings','next_fixture'));
end;
$function$

CREATE OR REPLACE FUNCTION public.get_tournament_team_photo_state(p_organization_id uuid, p_team_entry_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_can_manage boolean;
  v_can_moderate boolean;
  v_current public.tournament_team_photos%ROWTYPE;
  v_candidate public.tournament_team_photos%ROWTYPE;
BEGIN
  IF v_actor IS NULL OR NOT public.can_read_tournament_team_photo_as(
    p_organization_id, p_team_entry_id, v_actor
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_TEAM_PHOTO_FORBIDDEN';
  END IF;
  v_can_manage := public.can_manage_tournament_team_visual_assets_as(
    p_organization_id, p_team_entry_id, v_actor, 'team_entries.update');
  v_can_moderate := public.can_moderate_tournament_team_visual_assets_as(
    p_organization_id, p_team_entry_id, v_actor, 'team_entries.update');

  SELECT * INTO v_current FROM public.tournament_team_photos photo
  WHERE photo.organization_id = p_organization_id
    AND photo.team_entry_id = p_team_entry_id
    AND photo.lifecycle_status = 'active'
    AND photo.editorial_status = 'approved';

  IF v_can_manage OR v_can_moderate THEN
    SELECT * INTO v_candidate FROM public.tournament_team_photos photo
    WHERE photo.organization_id = p_organization_id
      AND photo.team_entry_id = p_team_entry_id
      AND photo.lifecycle_status = 'active'
      AND photo.editorial_status IN ('pending_review', 'rejected');
  END IF;

  RETURN jsonb_build_object(
    'organizationId', p_organization_id,
    'teamEntryId', p_team_entry_id,
    'canManage', v_can_manage,
    'canModerate', v_can_moderate,
    'current', CASE WHEN v_current.id IS NULL THEN NULL ELSE jsonb_build_object(
      'teamPhotoId', v_current.id,
      'ref', jsonb_build_object(
        'kind', 'team_photo', 'id', v_current.id, 'variant', 'original'),
      'width', v_current.width, 'height', v_current.height,
      'approvedAt', v_current.approved_at, 'updatedAt', v_current.updated_at
    ) END,
    'candidate', CASE WHEN v_candidate.id IS NULL THEN NULL ELSE jsonb_build_object(
      'teamPhotoId', v_candidate.id,
      'ref', jsonb_build_object(
        'kind', 'team_photo', 'id', v_candidate.id, 'variant', 'original'),
      'width', v_candidate.width, 'height', v_candidate.height,
      'editorialStatus', v_candidate.editorial_status,
      'reviewReason', v_candidate.review_reason,
      'createdAt', v_candidate.created_at, 'updatedAt', v_candidate.updated_at
    ) END
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_tournament_team_visual_policy(p_organization_id uuid, p_tournament_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_policy text;
BEGIN
  IF auth.uid() IS NULL
    OR NOT public.has_tournament_organization_capability(
      p_organization_id, 'tournaments.read'
    )
  THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_RESOURCE_FORBIDDEN';
  END IF;

  SELECT tournament.team_visual_management_policy
  INTO v_policy
  FROM public.tournaments tournament
  WHERE tournament.id = p_tournament_id
    AND tournament.organization_id = p_organization_id
    AND tournament.status <> 'archived';

  IF v_policy IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_RESOURCE_FORBIDDEN';
  END IF;

  RETURN jsonb_build_object(
    'organizationId', p_organization_id,
    'tournamentId', p_tournament_id,
    'policy', v_policy,
    -- Quien sólo puede leer ve la política pero no el control.
    'canUpdate', public.has_tournament_organization_capability(
      p_organization_id, 'tournaments.update'
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_tournament_workspace_context()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_preference public.user_workspace_preferences%rowtype;
  v_effective_workspace_type text;
  v_effective_organization_id uuid;
  v_organizations jsonb;
begin
  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'TORNEOS_AUTH_REQUIRED';
  end if;

  select preference.*
  into v_preference
  from public.user_workspace_preferences preference
  where preference.user_id = v_user_id;

  if v_preference.user_id is null
    or (
      v_preference.workspace_type = 'tournament_organization'
      and not public.has_tournament_organization_capability(
        v_preference.active_organization_id,
        'workspace.access'
      )
    )
  then
    v_effective_workspace_type := 'personal';
    v_effective_organization_id := null;
  else
    v_effective_workspace_type := v_preference.workspace_type;
    v_effective_organization_id := v_preference.active_organization_id;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', organization.id,
        'name', organization.name,
        'slug', organization.slug,
        'logoPath', organization.logo_path,
        'status', organization.status,
        'createdAt', organization.created_at,
        'role', membership.role,
        'membershipStatus', membership.status,
        'joinedAt', membership.joined_at,
        'capabilities', to_jsonb(
          public.tournament_role_capabilities(membership.role)
        )
      )
      order by lower(organization.name), organization.id
    ),
    '[]'::jsonb
  )
  into v_organizations
  from public.tournament_organization_members membership
  join public.tournament_organizations organization
    on organization.id = membership.organization_id
  where membership.user_id = v_user_id
    and membership.status = 'active'
    and organization.status = 'active';

  return jsonb_build_object(
    'preference', jsonb_build_object(
      'workspaceType', v_effective_workspace_type,
      'activeOrganizationId', v_effective_organization_id,
      'updatedAt', v_preference.updated_at
    ),
    'organizations', v_organizations
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.grant_tournament_season_premium(p_organization_id uuid, p_season_id uuid, p_purchase_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_grant_id uuid;
begin
  if p_purchase_id is null or p_reason is null or p_reason <> btrim(p_reason)
    or char_length(p_reason) not between 8 and 500
    or not exists (
      select 1 from public.tournament_seasons season
      where season.organization_id = p_organization_id and season.id = p_season_id
    ) then
    raise exception using errcode = '22023', message = 'TORNEOS_SEASON_PLAN_GRANT_INVALID';
  end if;
  insert into public.tournament_season_plan_grants (
    organization_id,season_id,plan_code,source,origin_purchase_id,reason
  ) values (
    p_organization_id,p_season_id,'PREMIUM','purchase',p_purchase_id,p_reason
  )
  on conflict (origin_purchase_id) do update set reason = public.tournament_season_plan_grants.reason
  returning id into v_grant_id;
  return v_grant_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.handle_tournament_media_report(p_report_id uuid, p_status text, p_resolution text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_report public.tournament_media_reports%rowtype;
begin
  select * into v_report
  from public.tournament_media_reports where id = p_report_id for update;
  if v_report.id is null or not public.has_tournament_media_capability(
    v_report.organization_id,'media.handle_reports'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  if p_status not in ('under_review','resolved','dismissed') then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_REPORT_INVALID';
  end if;
  if v_report.status = p_status then
    return jsonb_build_object('reportId',p_report_id,'status',p_status);
  end if;
  if v_report.status not in ('open','under_review')
    or (v_report.status = 'under_review' and p_status = 'under_review')
  then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_REPORT_INVALID';
  end if;
  update public.tournament_media_reports
  set status = p_status,
      handled_by = case when p_status in ('resolved','dismissed') then auth.uid() else null end,
      handled_at = case when p_status in ('resolved','dismissed') then now() else null end,
      resolution = case when p_status in ('resolved','dismissed')
        then nullif(btrim(p_resolution),'') else resolution end
  where id = p_report_id;
  perform public.append_tournament_audit(
    v_report.organization_id,'media.report.' || p_status,'media_report',
    p_report_id,null,v_report.tournament_id,jsonb_build_object('status',p_status)
  );
  return jsonb_build_object('reportId',p_report_id,'status',p_status);
end;
$function$

CREATE OR REPLACE FUNCTION public.has_organization_consumed_free_tournament(p_organization_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION USING errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  END IF;
  IF NOT public.is_tournament_organization_member(p_organization_id) THEN
    RAISE EXCEPTION USING errcode = '42501', message = 'TORNEOS_PLAN_FORBIDDEN';
  END IF;
  RETURN EXISTS (
    SELECT 1 FROM public.tournament_organization_plan_state state
    WHERE state.organization_id = p_organization_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.has_tournament_entitlement(p_organization_id uuid, p_tournament_id uuid, p_capability text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_entitlements jsonb;
BEGIN
  IF p_capability IS NULL OR p_tournament_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.tournament_entitlement_capabilities catalog
    WHERE catalog.capability = p_capability
  ) THEN
    RETURN false;
  END IF;
  BEGIN
    v_entitlements := public.get_effective_tournament_entitlements(
      p_organization_id,p_tournament_id
    );
  EXCEPTION WHEN insufficient_privilege THEN
    RETURN false;
  END;
  RETURN coalesce((v_entitlements->'capabilities'->>p_capability)::boolean,false);
END;
$function$

CREATE OR REPLACE FUNCTION public.has_tournament_social_capability(p_organization_id uuid, p_capability text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select auth.uid() is not null and p_capability = any(
