  );
$function$

CREATE OR REPLACE FUNCTION public.invite_tournament_team_manager(p_organization_id uuid, p_team_entry_id uuid, p_email text, p_display_name text, p_role text DEFAULT 'captain'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_entry public.tournament_team_entries%rowtype;
  v_manager public.tournament_team_managers%rowtype;
  v_invitation public.tournament_team_invitations%rowtype;
  v_email text := lower(btrim(coalesce(p_email, '')));
  v_token text;
begin
  select * into v_entry from public.tournament_team_entries
  where id = p_team_entry_id and organization_id = p_organization_id for update;
  if v_entry.id is null or not public.has_tournament_organization_capability(
    p_organization_id, 'team_managers.invite'
  ) or not public.can_edit_tournament_team_entry(
    p_organization_id,
    p_team_entry_id
  ) then raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN'; end if;
  if v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'
    or p_role not in ('captain','delegate','assistant')
    or char_length(btrim(coalesce(p_display_name,''))) not between 2 and 100
  then raise exception using errcode = '22023', message = 'TORNEOS_INVALID_MANAGER'; end if;
  if (
    select count(*) from public.tournament_team_invitations
    where created_by = auth.uid() and created_at > now() - interval '10 minutes'
  ) >= 10 then raise exception using errcode = 'P0001', message = 'TORNEOS_INVITATION_RATE_LIMITED'; end if;
  if (
    select count(*) from public.tournament_team_managers
    where team_entry_id = p_team_entry_id and status <> 'revoked'
  ) >= 20 and not exists (
    select 1 from public.tournament_team_managers
    where team_entry_id = p_team_entry_id
      and email_normalized = v_email
      and status <> 'revoked'
  ) then
    raise exception using errcode = 'P0001', message = 'TORNEOS_INVITATION_RATE_LIMITED';
  end if;
  update public.tournament_team_invitations set status = 'revoked', revoked_at = now()
  where team_entry_id = p_team_entry_id and email_normalized = v_email and status = 'pending';
  select * into v_manager from public.tournament_team_managers
  where team_entry_id = p_team_entry_id and email_normalized = v_email and status <> 'revoked'
  order by created_at desc limit 1;
  if v_manager.id is null then
    insert into public.tournament_team_managers (
      organization_id, team_entry_id, email_normalized, display_name,
      role, status, invited_by
    ) values (
      p_organization_id, p_team_entry_id, v_email, btrim(p_display_name),
      p_role, 'pending', auth.uid()
    ) returning * into v_manager;
  else
    update public.tournament_team_managers set
      display_name = btrim(p_display_name),
      role = p_role,
      invited_by = auth.uid(),
      invited_at = now()
    where id = v_manager.id
    returning * into v_manager;
  end if;
  v_token := encode(public.gen_random_bytes(32), 'hex');
  insert into public.tournament_team_invitations (
    organization_id, tournament_id, team_entry_id, manager_id,
    email_normalized, role, token_hash, expires_at, created_by
  ) values (
    p_organization_id, v_entry.tournament_id, p_team_entry_id, v_manager.id,
    v_email, p_role, encode(public.digest(v_token, 'sha256'), 'hex'),
    now() + interval '7 days', auth.uid()
  ) returning * into v_invitation;
  update public.tournament_team_entries set status = case when status = 'draft' then 'invited' else status end
  where id = p_team_entry_id;
  perform public.append_tournament_audit(
    p_organization_id, 'team_manager.invited', 'team_manager', v_manager.id,
    p_team_entry_id, v_entry.tournament_id,
    jsonb_build_object('role', p_role, 'expiresAt', v_invitation.expires_at)
  );
  return jsonb_build_object(
    'invitationId', v_invitation.id, 'token', v_token,
    'expiresAt', v_invitation.expires_at, 'environment', 'test-only'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.is_tournament_organization_slug_available(p_slug text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_slug text := public.normalize_tournament_organization_slug(p_slug);
  v_reserved_slugs constant text[] := array[
    'admin', 'api', 'app', 'auth', 'login', 'logout', 'profile',
    'torneos', 'tournaments', 'settings', 'support', 'www'
  ];
begin
  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'TORNEOS_AUTH_REQUIRED';
  end if;

  if char_length(v_slug) not between 3 and 48
    or v_slug !~ '^[a-z0-9](?:[a-z0-9-]{1,46}[a-z0-9])$'
    or v_slug = any(v_reserved_slugs)
  then
    return false;
  end if;

  return not exists (
    select 1
    from public.tournament_organizations organization
    where organization.slug = v_slug
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.is_valid_tournament_format_settings(p_format text, p_settings jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
begin
  if jsonb_typeof(p_settings) <> 'object' then
    return false;
  end if;

  case p_format
    when 'league' then
      if not (
        p_settings ?& array['rounds', 'qualifiers']
        and not exists (
          select 1 from jsonb_object_keys(p_settings) key
          where key not in ('rounds', 'qualifiers')
        )
        and jsonb_typeof(p_settings->'rounds') = 'string'
        and jsonb_typeof(p_settings->'qualifiers') = 'number'
      ) then
        return false;
      end if;
      return p_settings->>'rounds' in ('single', 'double')
        and (p_settings->>'qualifiers')::integer between 0 and 64;
    when 'knockout' then
      if not (
        p_settings ?& array['legs', 'thirdPlace']
        and not exists (
          select 1 from jsonb_object_keys(p_settings) key
          where key not in ('legs', 'thirdPlace')
        )
        and jsonb_typeof(p_settings->'legs') = 'string'
        and jsonb_typeof(p_settings->'thirdPlace') = 'boolean'
      ) then
        return false;
      end if;
      return p_settings->>'legs' in ('single', 'double')
        and (p_settings->>'thirdPlace')::boolean in (true, false);
    when 'groups' then
      if not (
        p_settings ?& array['groupCount', 'qualifiersPerGroup', 'rounds']
        and not exists (
          select 1 from jsonb_object_keys(p_settings) key
          where key not in ('groupCount', 'qualifiersPerGroup', 'rounds')
        )
        and jsonb_typeof(p_settings->'groupCount') = 'number'
        and jsonb_typeof(p_settings->'qualifiersPerGroup') = 'number'
        and jsonb_typeof(p_settings->'rounds') = 'string'
      ) then
        return false;
      end if;
      return (p_settings->>'groupCount')::integer between 2 and 32
        and (p_settings->>'qualifiersPerGroup')::integer between 1 and 16
        and p_settings->>'rounds' in ('single', 'double');
    when 'groups_and_playoffs' then
      if not (
        p_settings ?& array[
          'groupCount',
          'qualifiersPerGroup',
          'groupRounds',
          'knockoutLegs'
        ]
        and not exists (
          select 1 from jsonb_object_keys(p_settings) key
          where key not in (
            'groupCount',
            'qualifiersPerGroup',
            'groupRounds',
            'knockoutLegs'
          )
        )
        and jsonb_typeof(p_settings->'groupCount') = 'number'
        and jsonb_typeof(p_settings->'qualifiersPerGroup') = 'number'
        and jsonb_typeof(p_settings->'groupRounds') = 'string'
        and jsonb_typeof(p_settings->'knockoutLegs') = 'string'
      ) then
        return false;
      end if;
      return (p_settings->>'groupCount')::integer between 2 and 32
        and (p_settings->>'qualifiersPerGroup')::integer between 1 and 16
        and p_settings->>'groupRounds' in ('single', 'double')
        and p_settings->>'knockoutLegs' in ('single', 'double');
    when 'league_and_playoffs' then
      if not (
        p_settings ?& array['leagueRounds', 'qualifiers', 'knockoutLegs']
        and not exists (
          select 1 from jsonb_object_keys(p_settings) key
          where key not in ('leagueRounds', 'qualifiers', 'knockoutLegs')
        )
        and jsonb_typeof(p_settings->'leagueRounds') = 'string'
        and jsonb_typeof(p_settings->'qualifiers') = 'number'
        and jsonb_typeof(p_settings->'knockoutLegs') = 'string'
      ) then
        return false;
      end if;
      return p_settings->>'leagueRounds' in ('single', 'double')
        and (p_settings->>'qualifiers')::integer between 2 and 64
        and p_settings->>'knockoutLegs' in ('single', 'double');
    else
      return false;
  end case;
exception
  when invalid_text_representation or numeric_value_out_of_range then
    return false;
end;
$function$

CREATE OR REPLACE FUNCTION public.list_tournament_season_member_assignments(p_organization_id uuid, p_season_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_result jsonb;
begin
  if not public.has_tournament_season_capability(
    p_organization_id,p_season_id,'members.read'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_SEASON_ASSIGNMENT_FORBIDDEN';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',assignment.id,'membershipId',membership.id,'userId',membership.user_id,
    'role',membership.role,'status',membership.status,'assignedAt',assignment.assigned_at
  ) order by membership.role,membership.joined_at),'[]'::jsonb) into v_result
  from public.tournament_season_member_assignments assignment
  join public.tournament_organization_members membership on membership.id = assignment.membership_id
  where assignment.organization_id = p_organization_id and assignment.season_id = p_season_id;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.lock_tournament_roster(p_organization_id uuid, p_team_entry_id uuid, p_roster_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_entry public.tournament_team_entries%rowtype;
  v_roster public.tournament_rosters%rowtype;
begin
  if auth.uid() is null or not public.has_tournament_organization_capability(
    p_organization_id,
    'rosters.lock'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  select * into v_entry
  from public.tournament_team_entries
  where id = p_team_entry_id
    and organization_id = p_organization_id
    and status = 'approved'
  for update;
  select * into v_roster
  from public.tournament_rosters
  where id = p_roster_id
    and organization_id = p_organization_id
    and team_entry_id = p_team_entry_id
    and status = 'approved'
  for update;
  if v_entry.id is null or v_roster.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  update public.tournament_rosters
  set status = 'locked', locked_at = now()
  where id = v_roster.id
  returning * into v_roster;
  perform public.append_tournament_audit(
    p_organization_id,
    'roster.locked',
    'roster',
    v_roster.id,
    v_entry.id,
    v_entry.tournament_id,
    jsonb_build_object('version', v_roster.version)
  );
  return jsonb_build_object(
    'entryId', v_entry.id,
    'rosterId', v_roster.id,
    'status', v_roster.status
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.make_tournament_match_official(p_organization_id uuid, p_match_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_operation public.tournament_match_operations%rowtype;
  v_source public.tournament_match_operations%rowtype;
  v_validation jsonb;
  v_match_id uuid;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select match_id into v_match_id
  from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id;
  if v_match_id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('torneos:match-official:' || v_match_id, 0));
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_operations.make_official'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if v_operation.status = 'official' then
    return public.get_tournament_match_operation_context(
      p_organization_id, v_operation.id
    );
  end if;
  if v_operation.status <> 'validated' then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournament_match_reviews
    where match_operation_id = v_operation.id and status = 'open'
      and review_type <> 'validation'
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_MATCH_REVIEW_OPEN';
  end if;
  v_validation := public.validate_tournament_match_operation_payload(v_operation.id);
  if not (v_validation->>'valid')::boolean then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_OPERATION_INVALID';
  end if;
  if v_operation.source_operation_id is not null then
    select * into v_source from public.tournament_match_operations
    where id = v_operation.source_operation_id and match_id = v_operation.match_id for update;
    if v_source.id is null or v_source.status <> 'official'
      or not exists (
        select 1
        from public.tournament_match_reviews review
        where review.match_operation_id = v_source.id
          and review.review_type = 'correction'
          and review.status = 'open'
      )
    then
      raise exception using errcode = '55000', message = 'TORNEOS_MATCH_CORRECTION_STALE';
    end if;
    update public.tournament_match_reviews set
      status = 'approved',
      resolved_by = auth.uid(),
      resolved_at = now(),
      resolution = 'Corrección reemplazada por una nueva versión oficial'
    where match_operation_id = v_source.id
      and review_type = 'correction'
      and status = 'open';
    update public.tournament_match_operations set status = 'superseded', updated_at = now()
    where id = v_source.id;
    perform public.append_tournament_audit(
      p_organization_id, 'match_operation.superseded', 'match_operation',
      v_source.id, null, v_source.tournament_id,
      jsonb_build_object('replacementOperationId', v_operation.id)
    );
  end if;
  update public.tournament_match_operations set
    status = 'official', match_status = 'official', official_by = auth.uid(),
    official_at = now(), closed_at = now(), updated_at = now()
  where id = v_operation.id;
  perform public.append_tournament_audit(
    p_organization_id, 'match_operation.made_official', 'match_operation',
    v_operation.id, null, v_operation.tournament_id,
    jsonb_build_object('operationVersion', v_operation.operation_version)
  );
  return public.get_tournament_match_operation_context(p_organization_id, v_operation.id);
end;
$function$

CREATE OR REPLACE FUNCTION public.manage_tournament_media_consent(p_asset_id uuid, p_roster_player_id uuid, p_subject_user_id uuid, p_use_scope text, p_status text, p_legal_basis text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_asset public.tournament_media_assets%rowtype;
  v_gallery public.tournament_media_galleries%rowtype;
  v_existing public.tournament_media_consents%rowtype;
  v_consent_id uuid;
  v_replacement uuid;
  v_subject_user_id uuid;
begin
  select * into v_asset from public.tournament_media_assets where id = p_asset_id;
  if v_asset.id is null or not public.has_tournament_media_capability(
    v_asset.organization_id,'media.manage_consent'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_asset.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_asset.gallery_id::text,1)
  );
  select * into v_gallery
  from public.tournament_media_galleries
  where id = v_asset.gallery_id
  for update;
  select * into v_asset
  from public.tournament_media_assets
  where id = p_asset_id
  for update;
  if p_roster_player_id is null and p_subject_user_id is null then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_CONSENT_INVALID';
  end if;
  if p_roster_player_id is not null then
    select player.arma2_user_id
    into v_subject_user_id
    from public.tournament_media_relations relation
    join public.tournament_roster_players player
      on player.id = relation.roster_player_id
    join public.tournament_team_entries entry
      on entry.id = player.team_entry_id
    where relation.asset_id = p_asset_id
      and relation.relation_type = 'player'
      and relation.roster_player_id = p_roster_player_id
      and player.status = 'active'
      and entry.organization_id = v_asset.organization_id
      and entry.tournament_id = v_asset.tournament_id;
    if not found
      or (
        p_subject_user_id is not null
        and p_subject_user_id is distinct from v_subject_user_id
      )
    then
      raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_SCOPE_INVALID';
    end if;
  else
    v_subject_user_id := p_subject_user_id;
  end if;
  if p_roster_player_id is null and not exists (
    select 1
    from public.tournament_media_relations relation
    join public.tournament_roster_players player
      on player.id = relation.roster_player_id
    join public.tournament_team_entries entry
      on entry.id = player.team_entry_id
    where relation.asset_id = p_asset_id
      and relation.relation_type = 'player'
      and player.arma2_user_id = v_subject_user_id
      and player.status = 'active'
      and entry.organization_id = v_asset.organization_id
      and entry.tournament_id = v_asset.tournament_id
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_SCOPE_INVALID';
  end if;
  select * into v_existing
  from public.tournament_media_consents consent
  where consent.asset_id = p_asset_id
    and consent.roster_player_id is not distinct from p_roster_player_id
    and consent.subject_user_id is not distinct from v_subject_user_id
    and consent.use_scope = p_use_scope
  for update;
  if v_existing.id is not null
    and v_existing.status = p_status
    and v_existing.legal_basis is not distinct from (
      case when p_status = 'not_required'
        then nullif(btrim(p_legal_basis),'') else null end
    )
  then
    return jsonb_build_object(
      'assetId',p_asset_id,'useScope',p_use_scope,'status',p_status
    );
  end if;
  insert into public.tournament_media_consents (
    organization_id,tournament_id,asset_id,roster_player_id,subject_user_id,
    use_scope,status,legal_basis,managed_by,revoked_at
  ) values (
    v_asset.organization_id,v_asset.tournament_id,p_asset_id,p_roster_player_id,
    v_subject_user_id,p_use_scope,p_status,
    case when p_status = 'not_required' then nullif(btrim(p_legal_basis),'') else null end,
    auth.uid(),case when p_status = 'revoked' then now() else null end
  ) on conflict (
    asset_id,
    (coalesce(roster_player_id, '00000000-0000-0000-0000-000000000000'::uuid)),
    (coalesce(subject_user_id, '00000000-0000-0000-0000-000000000000'::uuid)),
    use_scope
  ) do update set
    status = excluded.status,legal_basis = excluded.legal_basis,
    managed_by = excluded.managed_by,revoked_at = excluded.revoked_at,
    updated_at = now()
  returning id into v_consent_id;
  insert into public.tournament_media_consent_events (
    organization_id,tournament_id,consent_id,asset_id,roster_player_id,
    subject_user_id,use_scope,previous_status,resulting_status,legal_basis,
    actor_user_id
  ) values (
    v_asset.organization_id,v_asset.tournament_id,v_consent_id,p_asset_id,
    p_roster_player_id,v_subject_user_id,p_use_scope,v_existing.status,p_status,
    case when p_status = 'not_required' then nullif(btrim(p_legal_basis),'') else null end,
    auth.uid()
  );
  if p_use_scope = 'view_internal'
    and p_status in ('denied','revoked')
    and v_asset.status = 'published'
  then
    update public.tournament_media_assets
    set status = 'hidden',hidden_at = now()
    where id = p_asset_id;
    if v_gallery.cover_asset_id = p_asset_id then
      select asset.id into v_replacement
      from public.tournament_media_gallery_items item
      join public.tournament_media_assets asset on asset.id = item.asset_id
      where item.gallery_id = v_gallery.id
        and asset.id <> p_asset_id
        and asset.status = 'published'
      order by item.sort_order,asset.created_at
      limit 1;
      if v_replacement is null then
        update public.tournament_media_galleries
        set status = 'archived',cover_asset_id = null,archived_at = now(),
            version = version + 1
        where id = v_gallery.id;
      else
        update public.tournament_media_galleries
        set cover_asset_id = v_replacement,version = version + 1
        where id = v_gallery.id;
      end if;
    end if;
    insert into public.tournament_media_moderation_actions (
      organization_id,tournament_id,gallery_id,asset_id,action,
      previous_status,resulting_status,reason,actor_user_id
    ) values (
      v_asset.organization_id,v_asset.tournament_id,v_asset.gallery_id,p_asset_id,
      'hide','published','hidden','Consentimiento interno denegado o revocado.',
      auth.uid()
    );
  end if;
  perform public.append_tournament_audit(
    v_asset.organization_id,'media.consent.updated','media_asset',p_asset_id,
    null,v_asset.tournament_id,jsonb_build_object(
      'useScope',p_use_scope,'status',p_status
    )
  );
  return jsonb_build_object(
    'assetId',p_asset_id,'useScope',p_use_scope,'status',p_status
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.mark_tournament_suspension_served(p_suspension_id uuid, p_match_id uuid, p_note text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_suspension public.tournament_player_suspensions%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_suspension from public.tournament_player_suspensions
  where id = p_suspension_id;
  if v_suspension.id is null or not public.has_tournament_organization_capability(
    v_suspension.organization_id, 'suspensions.mark_served'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_DISCIPLINE_FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    v_suspension.organization_id::text || ':' || v_suspension.tournament_id::text || ':'
    || v_suspension.category_id::text || ':' || v_suspension.phase_id::text || ':'
    || coalesce(v_suspension.group_id::text, 'all'),
    0
  ));
  select * into strict v_suspension from public.tournament_player_suspensions
  where id = p_suspension_id for update;
  if v_suspension.status not in ('active', 'reduced') then
    if v_suspension.status = 'served' then return v_suspension.id; end if;
    raise exception using errcode = '55000', message = 'TORNEOS_SUSPENSION_NOT_ACTIVE';
  end if;
  if not exists (
    select 1
    from public.tournament_matches match_row
    join public.tournament_competition_participants home
      on home.id = match_row.home_participant_id
    join public.tournament_competition_participants away
      on away.id = match_row.away_participant_id
    join public.tournament_match_operations operation
      on operation.match_id = match_row.id and operation.status = 'official'
    join public.tournament_match_outcomes outcome
      on outcome.match_operation_id = operation.id
      and outcome.counts_for_standings
    where match_row.id = p_match_id
      and match_row.organization_id = v_suspension.organization_id
      and match_row.tournament_id = v_suspension.tournament_id
      and match_row.id is distinct from v_suspension.source_match_id
      and v_suspension.team_entry_id in (home.team_entry_id, away.team_entry_id)
      and (
        (
          v_suspension.source_match_id is null
          and operation.official_at > v_suspension.created_at
        )
        or exists (
          select 1
          from public.tournament_match_operations source_operation
          where source_operation.match_id = v_suspension.source_match_id
            and source_operation.status in ('official', 'superseded')
            and operation.official_at > source_operation.official_at
        )
      )
      and not exists (
        select 1 from public.tournament_match_operation_players operation_player
        where operation_player.match_operation_id = operation.id
          and operation_player.roster_player_id = v_suspension.roster_player_id
          and operation_player.attendance_status not in ('absent', 'excused')
      )
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_SUSPENSION_MATCH_INVALID';
  end if;

  insert into public.tournament_suspension_served_matches (
    suspension_id, organization_id, match_id, marked_by, note
  ) values (
    v_suspension.id, v_suspension.organization_id, p_match_id, auth.uid(), p_note
  ) on conflict (suspension_id, match_id) do nothing;

  update public.tournament_player_suspensions suspension
  set served_matches = least(total_matches, (
      select count(*) from public.tournament_suspension_served_matches served
      where served.suspension_id = suspension.id
    )),
    status = case when (
      select count(*) from public.tournament_suspension_served_matches served
      where served.suspension_id = suspension.id
    ) >= total_matches then 'served' else status end,
    updated_at = now()
  where suspension.id = v_suspension.id;

  perform public.append_tournament_audit(
    v_suspension.organization_id, 'suspension.mark_served', 'player_suspension',
    v_suspension.id, v_suspension.team_entry_id, v_suspension.tournament_id,
    jsonb_build_object('matchId', p_match_id, 'note', p_note)
  );
  return v_suspension.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.open_tournament_match_operation(p_organization_id uuid, p_match_id uuid, p_override_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_fixture public.tournament_fixture_versions%rowtype;
  v_teams record;
  v_home public.tournament_team_entries%rowtype;
  v_away public.tournament_team_entries%rowtype;
  v_operation public.tournament_match_operations%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('torneos:match-operation:' || p_match_id, 0));
  select * into v_match from public.tournament_matches
  where id = p_match_id and organization_id = p_organization_id for update;
  if v_match.id is null
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_operations.open'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  select * into v_fixture from public.tournament_fixture_versions
  where id = v_match.fixture_version_id for share;
  select * into v_teams from public.tournament_match_team_entries(p_match_id);
  if v_fixture.status <> 'published' or v_fixture.invalidated_at is not null
    or v_match.status not in ('scheduled', 'ready')
    or v_teams.home_team_entry_id is null or v_teams.away_team_entry_id is null
  then
    raise exception using errcode = '22023', message = 'TORNEOS_MATCH_NOT_OPENABLE';
  end if;
  if v_match.scheduled_at is not null
    and now() < v_match.scheduled_at - interval '6 hours'
    and char_length(btrim(coalesce(p_override_reason, ''))) < 3
  then
    raise exception using errcode = '22023', message = 'TORNEOS_MATCH_OPEN_WINDOW';
  end if;
  select * into v_operation from public.tournament_match_operations
  where match_id = p_match_id
    and status in ('draft', 'submitted', 'under_review', 'validated')
  order by operation_version desc
  limit 1;
  if v_operation.id is not null then
    return public.get_tournament_match_operation_context(
      p_organization_id, v_operation.id
    );
  end if;
  if exists (
    select 1
    from public.tournament_match_operations
    where match_id = p_match_id and status = 'official'
  ) then
    raise exception using errcode = '22023',
      message = 'TORNEOS_MATCH_ALREADY_OFFICIAL';
  end if;
  perform 1
  from public.tournament_match_squads
  where match_id = p_match_id and status in ('draft', 'submitted')
  order by team_entry_id
  for update;
  select * into v_home from public.tournament_team_entries
  where id = v_teams.home_team_entry_id;
  select * into v_away from public.tournament_team_entries
  where id = v_teams.away_team_entry_id;
  insert into public.tournament_match_operations (
    organization_id, season_id, tournament_id, category_id, fixture_version_id,
    phase_id, round_id, match_id, home_team_entry_id, away_team_entry_id,
    operation_version, match_snapshot, home_team_snapshot, away_team_snapshot,
    opened_by
  ) values (
    p_organization_id, v_match.season_id, v_match.tournament_id, v_match.category_id,
    v_match.fixture_version_id, v_match.phase_id, v_match.round_id, v_match.id,
    v_home.id, v_away.id,
    coalesce((select max(operation_version) from public.tournament_match_operations
      where match_id = p_match_id), 0) + 1,
    jsonb_build_object(
      'scheduledAt', v_match.scheduled_at, 'venueId', v_match.venue_id,
      'courtId', v_match.court_id, 'durationMinutes', v_match.duration_minutes,
      'matchNumber', v_match.match_number, 'overrideReason', nullif(btrim(p_override_reason), '')
    ),
    jsonb_build_object('id', v_home.id, 'name', v_home.name, 'shortName', v_home.short_name,
      'shieldPath', v_home.shield_path, 'primaryColor', v_home.primary_color),
    jsonb_build_object('id', v_away.id, 'name', v_away.name, 'shortName', v_away.short_name,
      'shieldPath', v_away.shield_path, 'primaryColor', v_away.primary_color),
    auth.uid()
  ) returning * into v_operation;
  insert into public.tournament_match_operation_players (
    organization_id, match_operation_id, match_id, team_entry_id, roster_player_id,
    display_name_snapshot, avatar_url_snapshot, shirt_number_snapshot,
    position_snapshot, is_goalkeeper, is_captain, lineup_status, attendance_status
  )
  select player.organization_id, v_operation.id, player.match_id, player.team_entry_id,
    player.roster_player_id, player.display_name_snapshot, player.avatar_url_snapshot,
    player.shirt_number_snapshot, player.position_snapshot, player.is_goalkeeper,
    player.is_captain, player.lineup_status, player.attendance_status
  from public.tournament_match_squad_players player
  join public.tournament_match_squads squad on squad.id = player.match_squad_id
  where squad.match_id = p_match_id and squad.status = 'submitted'
    and player.callup_status = 'called_up';
  update public.tournament_match_squads set
    status = 'locked', locked_by = auth.uid(), locked_at = now(), updated_at = now()
  where match_id = p_match_id and status = 'submitted';
  perform public.append_tournament_audit(
    p_organization_id, 'match_operation.opened', 'match_operation', v_operation.id,
    null, v_match.tournament_id,
    jsonb_build_object('operationVersion', v_operation.operation_version)
  );
  return public.get_tournament_match_operation_context(p_organization_id, v_operation.id);
end;
$function$

CREATE OR REPLACE FUNCTION public.postpone_tournament_match(p_organization_id uuid, p_match_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if auth.uid() is null or char_length(v_reason) not between 3 and 500
    or not public.has_tournament_organization_capability(
      p_organization_id, 'matches.postpone'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  select match_row.* into v_match
  from public.tournament_matches match_row
  join public.tournament_fixture_versions version
    on version.id = match_row.fixture_version_id
    and version.status in ('draft', 'published')
    and version.invalidated_at is null
  where match_row.id = p_match_id
    and match_row.organization_id = p_organization_id
    and match_row.status = 'scheduled'
  for update of match_row;
  if v_match.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  insert into public.tournament_match_reschedules (
    organization_id, tournament_id, category_id, fixture_version_id, match_id,
    previous_scheduled_at, previous_venue_id, previous_court_id,
    new_scheduled_at, new_venue_id, new_court_id, reason, actor_user_id,
    previous_status, new_status
  ) values (
    v_match.organization_id, v_match.tournament_id, v_match.category_id,
    v_match.fixture_version_id, v_match.id, v_match.scheduled_at,
    v_match.venue_id, v_match.court_id, null, null, null,
    v_reason, auth.uid(), 'scheduled', 'postponed'
  );
  update public.tournament_matches
  set status = 'postponed', postponed_at = now(),
      scheduled_at = null, venue_id = null, court_id = null
  where id = v_match.id;
  perform public.append_tournament_audit(
    p_organization_id, 'match.postponed', 'match', v_match.id,
    null, v_match.tournament_id,
    jsonb_build_object(
      'reason', v_reason, 'previousScheduledAt', v_match.scheduled_at,
      'venueId', v_match.venue_id, 'courtId', v_match.court_id
    )
  );
  return jsonb_build_object('matchId', v_match.id, 'status', 'postponed');
end;
$function$

CREATE OR REPLACE FUNCTION public.preview_tournament_announcement_audience(p_announcement_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_announcement public.tournament_announcements%rowtype;
  v_count integer;
  v_teams jsonb;
  v_roles jsonb;
begin
  select * into v_announcement
  from public.tournament_announcements announcement
  where announcement.id = p_announcement_id;
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if v_announcement.id is null
    or not public.has_tournament_communications_capability(
      v_announcement.organization_id,'audiences.preview'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  select count(*),coalesce(jsonb_agg(distinct relation_type),'[]'::jsonb)
    into v_count,v_roles
  from public.resolve_tournament_announcement_recipients(p_announcement_id);
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',entry.id,'name',entry.name
  ) order by entry.name),'[]'::jsonb) into v_teams
  from public.tournament_announcement_audiences audience
  join public.tournament_team_entries entry on entry.id = audience.team_entry_id
  where audience.announcement_id = p_announcement_id;
  return jsonb_build_object(
    'announcementId',p_announcement_id,
    'estimatedRecipients',v_count,
    'roles',v_roles,
    'teams',v_teams,
    'channel','internal_only',
    'revalidatedAt',now()
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_active_tournament_fixture_draft()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_fixture_version_id uuid;
  v_fixture_status text;
  v_tournament_status text;
begin
  v_fixture_version_id := case
    when tg_op = 'DELETE' then old.fixture_version_id
    else new.fixture_version_id
  end;

  select fixture.status, tournament.status
  into v_fixture_status, v_tournament_status
  from public.tournament_fixture_versions fixture
  join public.tournaments tournament on tournament.id = fixture.tournament_id
  where fixture.id = v_fixture_version_id;

  if v_fixture_status = 'draft'
    and v_tournament_status not in ('registration', 'scheduled')
  then
    raise exception using errcode = '55000',
      message = 'TORNEOS_FIXTURE_DRAFT_READ_ONLY';
  end if;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_published_tournament_document_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if old.status in ('published','superseded')
    and (
      new.summary is distinct from old.summary
      or new.body is distinct from old.body
      or new.effective_at is distinct from old.effective_at
    )
  then
    raise exception using errcode = '23514',
      message = 'TORNEOS_DOCUMENT_VERSION_IMMUTABLE';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_referenced_tournament_offer()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if exists (
    select 1 from public.tournament_purchases purchase
    where purchase.product_code = old.product_code
      and purchase.offer_code = old.offer_code
      and purchase.offer_version = old.offer_version
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_REFERENCED_OFFER_IMMUTABLE';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_tournament_completed_competition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_row jsonb;
  v_tournament_id uuid;
  v_match_id uuid;
  v_operation_id uuid;
  v_status text;
begin
  v_row := coalesce(to_jsonb(new), to_jsonb(old));
  v_tournament_id := nullif(v_row->>'tournament_id', '')::uuid;

  if v_tournament_id is null then
    v_match_id := nullif(v_row->>'match_id', '')::uuid;
    if v_match_id is not null then
      select match_row.tournament_id into v_tournament_id
      from public.tournament_matches match_row
      where match_row.id = v_match_id;
    end if;
  end if;

  if v_tournament_id is null then
    v_operation_id := nullif(v_row->>'match_operation_id', '')::uuid;
    if v_operation_id is not null then
      select operation.tournament_id into v_tournament_id
      from public.tournament_match_operations operation
      where operation.id = v_operation_id;
    end if;
  end if;

  if v_tournament_id is null then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  select tournament.status into v_status
  from public.tournaments tournament
  where tournament.id = v_tournament_id;

  if v_status in ('completed', 'archived') then
    raise exception using errcode = '22023',
      message = 'TORNEOS_COMPETITION_READ_ONLY';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_tournament_match_child_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_operation_id uuid;
  v_operation_status text;
begin
  if tg_op = 'DELETE' then
    v_operation_id := old.match_operation_id;
  else
    v_operation_id := new.match_operation_id;
  end if;
  select status into v_operation_status
  from public.tournament_match_operations
  where id = v_operation_id;
  if v_operation_status is distinct from 'draft' then
    raise exception using errcode = '42501',
      message = 'TORNEOS_OFFICIAL_OPERATION_IMMUTABLE';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_tournament_match_operation_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'DELETE' then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_HISTORY_APPEND_ONLY';
  end if;
  if old.status in ('official', 'superseded', 'voided') and not (
    old.status = 'official'
    and new.status = 'superseded'
    and row(
      new.id, new.organization_id, new.match_id, new.operation_version,
      new.match_snapshot, new.home_team_snapshot, new.away_team_snapshot,
      new.opened_by, new.opened_at, new.submitted_by, new.submitted_at,
      new.validated_by, new.validated_at, new.official_by, new.official_at,
      new.closed_at
    ) is not distinct from row(
      old.id, old.organization_id, old.match_id, old.operation_version,
      old.match_snapshot, old.home_team_snapshot, old.away_team_snapshot,
      old.opened_by, old.opened_at, old.submitted_by, old.submitted_at,
      old.validated_by, old.validated_at, old.official_by, old.official_at,
      old.closed_at
    )
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_OFFICIAL_OPERATION_IMMUTABLE';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_tournament_match_squad_players()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_squad_status text;
begin
  select status into v_squad_status
  from public.tournament_match_squads
  where id = coalesce(new.match_squad_id, old.match_squad_id);
  if v_squad_status is distinct from 'draft' then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_SQUAD_LOCKED';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_tournament_organization_owner()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if old.role = 'owner' and old.status = 'active' then
    if tg_op = 'DELETE' then
      raise exception using
        errcode = '23514',
        message = 'TORNEOS_ACTIVE_OWNER_REQUIRED';
    end if;

    if new.organization_id is distinct from old.organization_id
      or new.user_id is distinct from old.user_id
      or new.role is distinct from old.role
      or new.status is distinct from old.status
    then
      raise exception using
        errcode = '23514',
        message = 'TORNEOS_ACTIVE_OWNER_REQUIRED';
    end if;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.protect_tournament_purchase_snapshots()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if row(
    new.organization_id,new.tournament_id,new.buyer_user_id,new.product_code,
    new.offer_code,new.offer_version,new.list_amount_snapshot,new.amount_snapshot,
    new.currency,new.provider,new.provider_environment,new.external_reference,new.idempotency_key
  ) is distinct from row(
    old.organization_id,old.tournament_id,old.buyer_user_id,old.product_code,
    old.offer_code,old.offer_version,old.list_amount_snapshot,old.amount_snapshot,
    old.currency,old.provider,old.provider_environment,old.external_reference,old.idempotency_key
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_PURCHASE_SNAPSHOT_IMMUTABLE';
  end if;
  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.publish_tournament_announcement(p_announcement_id uuid, p_expected_recipient_count integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_announcement public.tournament_announcements%rowtype;
  v_count integer;
  v_snapshot jsonb;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_announcement
  from public.tournament_announcements announcement
  where announcement.id = p_announcement_id
  for update;
  if v_announcement.id is null
    or not public.has_tournament_communications_capability(
      v_announcement.organization_id,'announcements.publish'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  if v_announcement.status = 'published' then
    return jsonb_build_object(
      'announcementId',v_announcement.id,
      'status','published',
      'recipientCount',v_announcement.published_recipient_count,
      'audienceChanged',false
    );
  end if;
  if v_announcement.status not in ('draft','scheduled') then
    raise exception using errcode = '23514', message = 'TORNEOS_COMMUNICATION_NOT_PUBLISHABLE';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(v_announcement.organization_id::text,731)
  );
  if (select count(*) from public.tournament_announcements announcement
      where announcement.organization_id = v_announcement.organization_id
        and announcement.status in ('published','superseded','archived','revoked')
        and announcement.published_at >= now() - interval '1 hour') >= 20
  then
    raise exception using errcode = '54000', message = 'TORNEOS_PUBLISH_RATE_LIMITED';
  end if;
  if not exists (
    select 1 from public.tournament_announcement_audiences audience
    where audience.announcement_id = p_announcement_id
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_AUDIENCE_REQUIRED';
  end if;
  if exists (
    select 1
    from public.tournament_announcement_links link
    where link.announcement_id = p_announcement_id
      and (
        (link.link_type = 'category' and not exists (
          select 1
          from public.tournament_categories category
          where category.id = link.resource_id
            and category.organization_id = v_announcement.organization_id
            and category.tournament_id = v_announcement.tournament_id
            and category.status = 'active'
        ))
        or (link.link_type = 'match' and not exists (
          select 1
          from public.tournament_matches match
          join public.tournament_fixture_versions fixture
            on fixture.organization_id = match.organization_id
           and fixture.id = match.fixture_version_id
           and fixture.status = 'published'
          where match.id = link.resource_id
            and match.organization_id = v_announcement.organization_id
            and match.tournament_id = v_announcement.tournament_id
        ))
        or (link.link_type = 'document' and not exists (
          select 1
          from public.tournament_documents document
          where document.id = link.resource_id
            and document.organization_id = v_announcement.organization_id
            and document.tournament_id = v_announcement.tournament_id
            and document.status = 'published'
        ))
      )
  ) then
    raise exception using errcode = '42501',
      message = 'TORNEOS_INVALID_COMMUNICATION_LINK';
  end if;

  select count(*) into v_count
  from public.resolve_tournament_announcement_recipients(p_announcement_id);
  if v_count = 0 then
    raise exception using errcode = '23514', message = 'TORNEOS_AUDIENCE_EMPTY';
  end if;
  if v_count > 5000 then
    raise exception using errcode = '54000', message = 'TORNEOS_RECIPIENT_LIMIT_REACHED';
  end if;
  select jsonb_build_object(
    'criteria',coalesce(jsonb_agg(jsonb_build_object(
      'type',audience.audience_type,
      'categoryId',audience.category_id,
      'teamEntryId',audience.team_entry_id,
      'matchId',audience.match_id
    ) order by audience.created_at,audience.id),'[]'::jsonb),
    'recipientCount',v_count,
    'resolvedAt',now()
  ) into v_snapshot
  from public.tournament_announcement_audiences audience
  where audience.announcement_id = p_announcement_id;

  insert into public.tournament_announcement_deliveries (
    organization_id,announcement_id,recipient_user_id,recipient_relation_type
  )
  select v_announcement.organization_id,p_announcement_id,user_id,relation_type
  from public.resolve_tournament_announcement_recipients(p_announcement_id)
  on conflict (announcement_id,recipient_user_id) do nothing;

  if v_announcement.supersedes_id is not null then
    update public.tournament_announcements
    set status = 'superseded'
    where id = v_announcement.supersedes_id
      and organization_id = v_announcement.organization_id
      and tournament_id = v_announcement.tournament_id
      and status = 'published';
    if not found then
      raise exception using errcode = '40001',
        message = 'TORNEOS_CORRECTION_ALREADY_SUPERSEDED';
    end if;
  end if;
  update public.tournament_announcements
  set status = 'published',published_at = now(),scheduled_for = null,
    published_recipient_count = v_count,audience_snapshot = v_snapshot
  where id = p_announcement_id;

  perform public.append_tournament_audit(
    v_announcement.organization_id,'communications.announcement_publish','announcement',
    p_announcement_id,null,v_announcement.tournament_id,
    jsonb_build_object(
      'recipientCount',v_count,
      'previewCount',p_expected_recipient_count,
      'audienceChanged',p_expected_recipient_count is not null
        and p_expected_recipient_count <> v_count,
      'channel','internal_only'
    )
  );
  return jsonb_build_object(
    'announcementId',p_announcement_id,'status','published',
    'recipientCount',v_count,
    'audienceChanged',p_expected_recipient_count is not null
      and p_expected_recipient_count <> v_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.publish_tournament_document_version(p_version_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_version public.tournament_document_versions%rowtype;
  v_document public.tournament_documents%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_version
  from public.tournament_document_versions version
  where version.id = p_version_id
  for update;
  if v_version.status = 'published' then
    return jsonb_build_object(
      'documentId',v_version.document_id,'versionId',v_version.id,'status','published'
    );
  end if;
  select * into v_document
  from public.tournament_documents document
  where document.id = v_version.document_id
  for update;
  if v_version.id is null or v_version.status <> 'draft'
    or v_document.status = 'archived'
    or not public.has_tournament_communications_capability(
      v_version.organization_id,'documents.publish'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_DOCUMENT_FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_document.id::text,733));
  update public.tournament_document_versions
  set status = 'superseded',superseded_at = now()
  where document_id = v_document.id and status = 'published';
  update public.tournament_document_versions
  set status = 'published',published_by = auth.uid(),published_at = now()
  where id = p_version_id;
  update public.tournament_documents
  set status = 'published',active_version_id = p_version_id
  where id = v_document.id;
  perform public.append_tournament_audit(
    v_document.organization_id,'communications.document_publish','tournament_document',
    v_document.id,null,v_document.tournament_id,
    jsonb_build_object('versionId',p_version_id,'version',v_version.version)
  );
  return jsonb_build_object(
    'documentId',v_document.id,'versionId',p_version_id,'status','published'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.publish_tournament_fixture(p_organization_id uuid, p_fixture_version_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_version public.tournament_fixture_versions%rowtype;
  v_previous public.tournament_fixture_versions%rowtype;
  v_validation jsonb;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select version.* into v_version
  from public.tournament_fixture_versions version
  where version.id = p_fixture_version_id
    and version.organization_id = p_organization_id
    and version.status = 'draft'
  for update;
  if v_version.id is null
    or not public.has_tournament_organization_capability(p_organization_id, 'fixture.publish')
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  perform public.assert_tournament_fixture_scope(
    p_organization_id, v_version.tournament_id, v_version.category_id,
    'fixture.publish', array['registration', 'scheduled']::text[]
  );
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:fixture:' || v_version.tournament_id::text || ':' || v_version.category_id::text, 0
  ));
  if exists (
    select 1
    from public.tournament_fixture_versions newer
    where newer.tournament_id = v_version.tournament_id
      and newer.category_id = v_version.category_id
      and newer.status = 'draft'
      and newer.version_number > v_version.version_number
  ) then
    raise exception using errcode = '40001', message = 'TORNEOS_STALE_FIXTURE_VERSION';
  end if;
  v_validation := public.validate_tournament_fixture(p_organization_id, v_version.id);
  if not (v_validation->>'valid')::boolean then
    raise exception using errcode = '23514', message = 'TORNEOS_FIXTURE_INVALID';
  end if;
  select version.* into v_previous
  from public.tournament_fixture_versions version
  where version.tournament_id = v_version.tournament_id
    and version.category_id = v_version.category_id
    and version.status = 'published'
  for update;
  if v_previous.id is not null then
    if not public.has_tournament_organization_capability(
      p_organization_id, 'fixture.supersede'
    ) then
      raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
    end if;
    update public.tournament_fixture_versions
    set status = 'superseded', superseded_at = now()
    where id = v_previous.id;
    perform public.append_tournament_audit(
      p_organization_id, 'fixture.superseded', 'fixture_version', v_previous.id,
      null, v_version.tournament_id,
      jsonb_build_object('supersededByFixtureVersionId', v_version.id)
    );
  end if;
  update public.tournament_fixture_versions
  set status = 'published', published_at = now()
  where id = v_version.id;
  update public.tournament_rounds round_row
  set status = case
      when not exists (
        select 1 from public.tournament_matches match_row
        where match_row.round_id = round_row.id
          and match_row.status not in ('scheduled', 'ready', 'cancelled')
      ) then 'scheduled'
      else 'draft'
    end
  where round_row.fixture_version_id = v_version.id
    and round_row.status <> 'locked';
  update public.tournament_phases phase
  set status = case
      when not exists (
        select 1 from public.tournament_matches match_row
        where match_row.phase_id = phase.id
          and match_row.status not in ('scheduled', 'ready', 'cancelled')
      ) then 'scheduled'
      else 'generated'
    end
  where phase.fixture_version_id = v_version.id;
  update public.tournaments
  set status = 'scheduled'
  where id = v_version.tournament_id
    and organization_id = p_organization_id
    and status = 'registration';
  perform public.append_tournament_audit(
    p_organization_id, 'fixture.published', 'fixture_version', v_version.id,
    null, v_version.tournament_id,
    jsonb_build_object(
      'categoryId', v_version.category_id,
      'versionNumber', v_version.version_number,
      'previousFixtureVersionId', v_previous.id
    )
  );
  return jsonb_build_object(
    'fixtureVersionId', v_version.id,
    'status', 'published',
    'supersededFixtureVersionId', v_previous.id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.publish_tournament_media_gallery(p_gallery_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_gallery public.tournament_media_galleries%rowtype;
  v_count integer;
begin
  select * into v_gallery
  from public.tournament_media_galleries where id = p_gallery_id;
  if v_gallery.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_gallery.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_gallery_id::text,1)
  );
  select * into v_gallery
  from public.tournament_media_galleries where id = p_gallery_id for update;
  if v_gallery.id is null or not public.has_tournament_media_capability(
    v_gallery.organization_id,'media.publish'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  if v_gallery.status = 'published' then
    return jsonb_build_object(
      'galleryId',p_gallery_id,'status','published','publishedAt',v_gallery.published_at
    );
  end if;
  if v_gallery.status not in ('draft','under_review') then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_GALLERY_NOT_PUBLISHABLE';
  end if;
  select count(*) into v_count
  from public.tournament_media_gallery_items item
  join public.tournament_media_assets asset on asset.id = item.asset_id
  where item.gallery_id = p_gallery_id;
  if v_count < 1 or v_gallery.cover_asset_id is null or not exists (
    select 1 from public.tournament_media_assets asset
    where asset.id = v_gallery.cover_asset_id
      and asset.gallery_id = p_gallery_id and asset.status = 'approved'
  ) or exists (
    select 1
    from public.tournament_media_gallery_items item
    join public.tournament_media_assets asset on asset.id = item.asset_id
    where item.gallery_id = p_gallery_id
      and asset.status <> 'approved'
  ) or exists (
    select 1
    from public.tournament_media_gallery_items item
    where item.gallery_id = p_gallery_id
      and not public.tournament_media_asset_publication_ready(item.asset_id)
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_GALLERY_NOT_PUBLISHABLE';
  end if;
  if exists (
    select 1
    from public.tournament_media_gallery_items item
    where item.gallery_id = p_gallery_id
      and not public.tournament_media_asset_has_internal_consent(item.asset_id)
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_CONSENT_REQUIRED';
  end if;

  update public.tournament_media_assets asset
  set status = 'published',published_at = now()
  where asset.gallery_id = p_gallery_id and asset.status = 'approved';
  update public.tournament_media_galleries
  set status = 'published',submitted_at = coalesce(submitted_at,now()),
      published_by = auth.uid(),published_at = now(),version = version + 1
  where id = p_gallery_id;
  perform public.append_tournament_audit(
    v_gallery.organization_id,'media.gallery.published','media_gallery',
    p_gallery_id,null,v_gallery.tournament_id,jsonb_build_object('assetCount',v_count)
  );
  return jsonb_build_object(
    'galleryId',p_gallery_id,'status','published',
    'publishedAt',now(),'assetCount',v_count
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.ready_tournament_match(p_organization_id uuid, p_match_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_match public.tournament_matches%rowtype;
begin
  if auth.uid() is null or not public.has_tournament_organization_capability(
    p_organization_id, 'matches.schedule'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  select match_row.* into v_match
  from public.tournament_matches match_row
  join public.tournament_fixture_versions version
    on version.id = match_row.fixture_version_id
    and version.status in ('draft', 'published')
    and version.invalidated_at is null
  where match_row.id = p_match_id
    and match_row.organization_id = p_organization_id
    and match_row.status = 'scheduled'
    and match_row.scheduled_at is not null
  for update of match_row;
  if v_match.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  update public.tournament_matches set status = 'ready' where id = v_match.id;
  perform public.append_tournament_audit(
    p_organization_id, 'match.ready', 'match', v_match.id,
    null, v_match.tournament_id, '{}'::jsonb
  );
  return jsonb_build_object('matchId', v_match.id, 'status', 'ready');
end;
$function$

CREATE OR REPLACE FUNCTION public.record_manual_match_availability(p_organization_id uuid, p_match_id uuid, p_roster_player_id uuid, p_response text, p_reason text, p_comment text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_player public.tournament_roster_players%rowtype;
  v_response public.tournament_match_availability_responses%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if p_response not in ('available', 'unavailable', 'maybe')
    or char_length(btrim(coalesce(p_reason, ''))) not between 3 and 500
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_AVAILABILITY';
  end if;
  select * into v_match from public.tournament_matches
  where id = p_match_id and organization_id = p_organization_id for share;
  select player.* into v_player
  from public.tournament_roster_players player
  join public.tournament_rosters roster
    on roster.id = player.roster_id
    and roster.status in ('approved', 'locked')
  where player.id = p_roster_player_id
    and player.organization_id = p_organization_id
    and player.status = 'active'
    and player.eligibility_status = 'eligible';
  if v_match.id is null or v_match.status not in ('scheduled', 'ready')
    or v_match.scheduled_at is null or now() >= v_match.scheduled_at
    or v_player.id is null
    or not public.can_manage_tournament_match_squad(
      p_organization_id, p_match_id, v_player.team_entry_id
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournament_match_operations operation
    where operation.match_id = p_match_id
      and operation.status not in ('superseded', 'voided')
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_MATCH_OPERATION_ACTIVE';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:match-availability:' || p_match_id || ':' || v_player.id, 0
  ));
  insert into public.tournament_match_availability_responses (
    organization_id, match_id, team_entry_id, roster_player_id, user_id,
    response, comment, response_source, recorded_by, manual_reason
  ) values (
    p_organization_id, p_match_id, v_player.team_entry_id, v_player.id,
    v_player.arma2_user_id, p_response, nullif(btrim(p_comment), ''),
    'manual', auth.uid(), btrim(p_reason)
  )
  on conflict (match_id, roster_player_id) do update set
    response = excluded.response, comment = excluded.comment,
    user_id = excluded.user_id, response_source = 'manual',
    recorded_by = excluded.recorded_by, manual_reason = excluded.manual_reason,
    responded_at = now(), updated_at = now()
  where public.tournament_match_availability_responses.response_source = 'manual'
  returning * into v_response;
  if v_response.id is null then
    raise exception using errcode = '55000',
      message = 'TORNEOS_MATCH_AVAILABILITY_SELF_AUTHORITATIVE';
  end if;
  perform public.append_tournament_audit(
    p_organization_id, 'match_availability.recorded_manual',
    'match_availability', v_response.id, v_player.team_entry_id,
    v_match.tournament_id, jsonb_build_object('response', p_response, 'source', 'manual')
  );
  return jsonb_build_object('id', v_response.id, 'response', v_response.response);
end;
$function$

CREATE OR REPLACE FUNCTION public.record_tournament_purchase_preference(p_purchase_id uuid, p_provider text, p_provider_environment text, p_provider_preference_id text, p_preference_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_purchase public.tournament_purchases%rowtype;
begin
  if p_provider_preference_id is null
    or char_length(btrim(p_provider_preference_id)) not between 3 and 200 then
    raise exception using errcode = '22023', message = 'TORNEOS_PREFERENCE_INVALID';
  end if;
  select * into v_purchase from public.tournament_purchases
  where id = p_purchase_id for update;
  if v_purchase.id is null or v_purchase.provider <> p_provider
    or v_purchase.provider_environment <> p_provider_environment then
    raise exception using errcode = '22023', message = 'TORNEOS_PURCHASE_INVALID';
  end if;
  if v_purchase.provider_preference_id is not null then
    if v_purchase.provider_preference_id <> btrim(p_provider_preference_id) then
      raise exception using errcode = '55000', message = 'TORNEOS_PREFERENCE_CONFLICT';
    end if;
    return public.tournament_purchase_projection(v_purchase)
      || jsonb_build_object('idempotentReplay',true);
  end if;
  if v_purchase.status <> 'created' then
    raise exception using errcode = '55000', message = 'TORNEOS_PURCHASE_TRANSITION_INVALID';
  end if;

  update public.tournament_purchases set
    status = 'preference_created',provider_status = 'created',
    provider_preference_id = btrim(p_provider_preference_id),
    preference_expires_at = coalesce(p_preference_expires_at,preference_expires_at),
    last_verified_at = now()
  where id = v_purchase.id returning * into v_purchase;
  insert into public.tournament_purchase_events (
    purchase_id,organization_id,event_type,from_status,to_status,provider_status,
    actor_type
  ) values (
    v_purchase.id,v_purchase.organization_id,'preference.created','created',
    'preference_created','created','service'
  );
  return public.tournament_purchase_projection(v_purchase)
    || jsonb_build_object('idempotentReplay',false);
end;
$function$

CREATE OR REPLACE FUNCTION public.reject_suspended_tournament_squad_player()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_match_id uuid;
  v_team_entry_id uuid;
begin
  if new.callup_status <> 'called_up' then
    return new;
  end if;
  select squad.match_id, squad.team_entry_id into v_match_id, v_team_entry_id
  from public.tournament_match_squads squad where squad.id = new.match_squad_id;
  if exists (
    select 1
    from public.tournament_player_suspensions suspension
    join public.tournament_standings_revisions revision
      on revision.id = suspension.revision_id and revision.status = 'published'
    join public.tournament_matches match_row on match_row.id = v_match_id
    where suspension.roster_player_id = new.roster_player_id
      and suspension.organization_id = new.organization_id
      and suspension.tournament_id = match_row.tournament_id
      and suspension.category_id = match_row.category_id
      and suspension.team_entry_id = v_team_entry_id
      and suspension.status in ('active', 'reduced')
      and suspension.served_matches < suspension.total_matches
      and (
        suspension.source_match_id is null
        or exists (
          select 1
          from public.tournament_matches source_match
          join public.tournament_phases source_phase on source_phase.id = source_match.phase_id
          join public.tournament_phases target_phase on target_phase.id = match_row.phase_id
          where source_match.id = suspension.source_match_id
            and (
              target_phase.sequence_number > source_phase.sequence_number
              or (
                target_phase.sequence_number = source_phase.sequence_number
                and match_row.match_number > source_match.match_number
              )
            )
        )
      )
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_PLAYER_SUSPENDED';
  end if;
  return new;
end;
$function$

