CREATE OR REPLACE FUNCTION public.reopen_tournament_competition(p_organization_id uuid, p_tournament_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tournament public.tournaments%rowtype;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  -- `tournaments.reopen` sólo la tiene el propietario.
  if not public.has_tournament_organization_capability(
    p_organization_id, 'tournaments.reopen'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if char_length(v_reason) not between 3 and 500 then
    raise exception using errcode = '22023', message = 'TORNEOS_REASON_REQUIRED';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:competition-lifecycle:' || p_tournament_id::text, 0
  ));

  select tournament.* into v_tournament
  from public.tournaments tournament
  join public.tournament_organizations organization
    on organization.id = tournament.organization_id
    and organization.status = 'active'
  where tournament.id = p_tournament_id
    and tournament.organization_id = p_organization_id
  for update of tournament;

  if v_tournament.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  if v_tournament.status = 'active' then
    return jsonb_build_object(
      'id', v_tournament.id,
      'status', v_tournament.status,
      'reopenedAt', v_tournament.reopened_at,
      'reopenCount', v_tournament.reopen_count,
      'alreadyActive', true
    );
  end if;

  if v_tournament.status <> 'completed' then
    raise exception using errcode = '22023',
      message = 'TORNEOS_INVALID_TOURNAMENT_TRANSITION';
  end if;

  -- Reabrir no reconstruye fixture ni toca resultados: sólo devuelve
  -- capacidad operativa. `completed_at` se conserva como registro de la
  -- última finalización.
  update public.tournaments
  set status = 'active',
      reopened_at = now(),
      reopen_count = coalesce(reopen_count, 0) + 1
  where id = p_tournament_id
  returning * into v_tournament;

  perform public.append_tournament_audit(
    p_organization_id, 'tournament.reopened', 'tournament', v_tournament.id,
    null, v_tournament.id,
    jsonb_build_object(
      'previousStatus', 'completed',
      'nextStatus', 'active',
      'reason', v_reason,
      'reopenCount', v_tournament.reopen_count,
      'previouslyCompletedAt', v_tournament.completed_at
    )
  );

  return jsonb_build_object(
    'id', v_tournament.id,
    'status', v_tournament.status,
    'reopenedAt', v_tournament.reopened_at,
    'reopenCount', v_tournament.reopen_count,
    'alreadyActive', false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.reopen_tournament_participants(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_set public.tournament_participant_sets%rowtype;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  perform public.assert_tournament_fixture_scope(
    p_organization_id, p_tournament_id, p_category_id,
    'participants.reopen', array['registration', 'scheduled']::text[]
  );
  if char_length(v_reason) not between 3 and 500 then
    raise exception using errcode = '22023', message = 'TORNEOS_REASON_REQUIRED';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:participants:' || p_tournament_id::text || ':' || p_category_id::text,
    0
  ));
  select participant_set.* into v_set
  from public.tournament_participant_sets participant_set
  where participant_set.organization_id = p_organization_id
    and participant_set.tournament_id = p_tournament_id
    and participant_set.category_id = p_category_id
    and participant_set.status = 'frozen'
  for update;
  if v_set.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  update public.tournament_participant_sets
  set status = 'reopened',
      reopened_by = auth.uid(),
      reopened_at = now(),
      reopen_reason = v_reason,
      invalidated_at = now()
  where id = v_set.id;
  update public.tournament_fixture_versions
  set status = 'archived', archived_at = now(), invalidated_at = now()
  where participant_set_id = v_set.id and status = 'draft';
  update public.tournament_fixture_versions
  set invalidated_at = now()
  where participant_set_id = v_set.id and status in ('published', 'superseded');
  perform public.append_tournament_audit(
    p_organization_id, 'participants.reopened', 'participant_set', v_set.id,
    null, p_tournament_id,
    jsonb_build_object(
      'categoryId', p_category_id,
      'versionNumber', v_set.version_number,
      'reason', v_reason,
      'fixtureRegenerationRequired', true
    )
  );
  return jsonb_build_object(
    'participantSetId', v_set.id,
    'status', 'reopened',
    'fixtureRegenerationRequired', true
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.reorder_tournament_media_item(p_gallery_id uuid, p_asset_id uuid, p_target_order integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_gallery public.tournament_media_galleries%rowtype;
  v_current integer;
  v_max integer;
begin
  select * into v_gallery
  from public.tournament_media_galleries where id = p_gallery_id for update;
  if v_gallery.id is null or not public.has_tournament_media_capability(
    v_gallery.organization_id,'media.update_gallery'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  if v_gallery.status not in ('draft','under_review') then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_GALLERY_IMMUTABLE';
  end if;
  select item.sort_order into v_current
  from public.tournament_media_gallery_items item
  where item.gallery_id = p_gallery_id and item.asset_id = p_asset_id
  for update;
  select coalesce(max(sort_order),0) into v_max
  from public.tournament_media_gallery_items where gallery_id = p_gallery_id;
  if v_current is null or p_target_order < 0 or p_target_order > v_max then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_ORDER_INVALID';
  end if;
  if v_current = p_target_order then
    return jsonb_build_object(
      'galleryId',p_gallery_id,'assetId',p_asset_id,'sortOrder',p_target_order
    );
  end if;
  update public.tournament_media_gallery_items
  set sort_order = sort_order + 1000000
  where gallery_id = p_gallery_id;
  if p_target_order < v_current then
    update public.tournament_media_gallery_items
    set sort_order = case
      when asset_id = p_asset_id then p_target_order
      when sort_order - 1000000 between p_target_order and v_current - 1
        then sort_order - 999999
      else sort_order - 1000000 end
    where gallery_id = p_gallery_id;
  else
    update public.tournament_media_gallery_items
    set sort_order = case
      when asset_id = p_asset_id then p_target_order
      when sort_order - 1000000 between v_current + 1 and p_target_order
        then sort_order - 1000001
      else sort_order - 1000000 end
    where gallery_id = p_gallery_id;
  end if;
  perform public.append_tournament_audit(
    v_gallery.organization_id,'media.gallery.reordered','media_gallery',
    p_gallery_id,null,v_gallery.tournament_id,
    jsonb_build_object('assetId',p_asset_id,'targetOrder',p_target_order)
  );
  return jsonb_build_object(
    'galleryId',p_gallery_id,'assetId',p_asset_id,'sortOrder',p_target_order
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.replace_tournament_announcement_audience(p_announcement_id uuid, p_audience_type text, p_category_id uuid DEFAULT NULL::uuid, p_team_entry_id uuid DEFAULT NULL::uuid, p_match_id uuid DEFAULT NULL::uuid, p_specific_user_id uuid DEFAULT NULL::uuid)
