CREATE OR REPLACE FUNCTION public.report_tournament_media_asset(p_asset_id uuid, p_reason text, p_detail text, p_request_hide boolean, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_asset public.tournament_media_assets%rowtype;
  v_existing public.tournament_media_reports%rowtype;
  v_id uuid;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_asset
  from public.tournament_media_assets where id = p_asset_id;
  if v_asset.id is null or v_asset.status <> 'published'
    or not public.can_current_user_read_media_gallery(v_asset.gallery_id)
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  if p_idempotency_key is null then
    raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(auth.uid()::text,2)
  );
  select * into v_existing
  from public.tournament_media_reports report
  where report.reporter_user_id = auth.uid()
    and report.idempotency_key = p_idempotency_key;
  if v_existing.id is not null then
    if v_existing.asset_id is distinct from p_asset_id
      or v_existing.reason is distinct from p_reason
      or v_existing.detail is distinct from nullif(btrim(p_detail),'')
      or v_existing.request_hide is distinct from p_request_hide
    then
      raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_IDEMPOTENCY_CONFLICT';
    end if;
    return jsonb_build_object(
      'reportId',v_existing.id,'status',v_existing.status
    );
  end if;
  if (
    select count(*) from public.tournament_media_reports report
    where report.reporter_user_id = auth.uid()
      and report.created_at > now() - interval '1 hour'
  ) >= 5 then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_REPORT_RATE_LIMITED';
  end if;
  insert into public.tournament_media_reports (
    organization_id,tournament_id,gallery_id,asset_id,reporter_user_id,
    reason,detail,request_hide,idempotency_key
  ) values (
    v_asset.organization_id,v_asset.tournament_id,v_asset.gallery_id,p_asset_id,
    auth.uid(),p_reason,nullif(btrim(p_detail),''),p_request_hide,p_idempotency_key
  ) returning id into v_id;
  perform public.append_tournament_audit(
    v_asset.organization_id,'media.report.created','media_report',v_id,
    null,v_asset.tournament_id,jsonb_build_object(
      'galleryId',v_asset.gallery_id,'reason',p_reason,'requestHide',p_request_hide
    )
  );
  return jsonb_build_object('reportId',v_id,'status','open');
end;
$function$

CREATE OR REPLACE FUNCTION public.request_tournament_match_correction(p_organization_id uuid, p_match_operation_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_operation public.tournament_match_operations%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null or v_operation.status <> 'official'
    or char_length(btrim(coalesce(p_reason, ''))) not between 3 and 2000
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_operations.request_correction'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if exists (
    select 1
    from public.tournament_match_reviews review
    where review.match_operation_id = v_operation.id
      and review.review_type = 'correction'
      and review.status = 'open'
  ) then
    raise exception using errcode = '55000',
      message = 'TORNEOS_MATCH_CORRECTION_EXISTS';
  end if;
  insert into public.tournament_match_reviews (
    organization_id, match_operation_id, review_type, reason, requested_by
  ) values (
    p_organization_id, v_operation.id, 'correction', btrim(p_reason), auth.uid()
  );
  perform public.append_tournament_audit(
    p_organization_id, 'match_operation.correction_requested',
    'match_operation', v_operation.id, null, v_operation.tournament_id,
    jsonb_build_object('operationVersion', v_operation.operation_version)
  );
  return public.get_tournament_match_operation_context(p_organization_id, v_operation.id);
end;
$function$

CREATE OR REPLACE FUNCTION public.request_tournament_media_upload_session(p_gallery_id uuid, p_file_name text, p_declared_mime text, p_byte_size bigint, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_gallery public.tournament_media_galleries%rowtype;
  v_existing public.tournament_media_upload_sessions%rowtype;
  v_mode text := public.tournament_media_current_pipeline_mode();
  v_tier text;
  v_extension text;
  v_file_id uuid := gen_random_uuid();
  v_token text := encode(public.gen_random_bytes(32),'hex');
  v_safe_name text;
  v_path text;
  v_session_id uuid;
  v_org_bytes bigint;
  v_tournament_bytes bigint;
  v_gallery_bytes bigint;
  v_open_sessions integer;
  v_recent_emissions integer := 0;
  v_max_file bigint;
  v_max_open integer;
  v_expires interval;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  v_tier := case v_mode
    when 'PROCESSOR_EXTERNAL' then 'processor_external'
    when 'MVP_SIMPLE' then 'mvp_simple'
    else null
  end;
  perform public.tournament_media_require_upload_tier(v_tier);

  select * into v_gallery from public.tournament_media_galleries
  where id = p_gallery_id;
  if v_gallery.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  if p_idempotency_key is null then
    raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;

  -- The actor lock serializes both ordinary emissions and credential rotation.
  -- Organization/gallery locks preserve the existing quota and ownership
  -- decisions. No lock scope is widened by the recovery path.
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(auth.uid()::text,2)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_gallery.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_gallery_id::text,1)
  );
  select * into v_gallery from public.tournament_media_galleries
  where id = p_gallery_id for share;
  if (v_tier = 'mvp_simple' and not public.tournament_media_mvp_user_can_upload(
      auth.uid(),p_gallery_id
    )) or (v_tier = 'processor_external' and not public.tournament_media_user_can_upload(
      auth.uid(),p_gallery_id
    ))
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;

  v_max_file := case when v_tier = 'mvp_simple' then 4194304 else 12582912 end;
  v_max_open := case when v_tier = 'mvp_simple' then 10 else 40 end;
  v_expires := case when v_tier = 'mvp_simple' then interval '5 minutes'
    else interval '10 minutes' end;
  v_extension := case p_declared_mime
    when 'image/jpeg' then 'jpg' when 'image/png' then 'png'
    when 'image/webp' then 'webp' else null end;
  if v_extension is null or p_byte_size is null
    or p_byte_size < 1 or p_byte_size > v_max_file
    or not (
      (p_declared_mime = 'image/jpeg' and lower(p_file_name) ~ '\.(jpe?g)$')
      or (p_declared_mime = 'image/png' and lower(p_file_name) ~ '\.png$')
      or (p_declared_mime = 'image/webp' and lower(p_file_name) ~ '\.webp$')
    )
  then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_FILE_INVALID';
  end if;

  -- More than one historical attempt may now carry the same logical key. The
  -- newest row is authoritative; the partial unique index guarantees at most
  -- one live `issued` attempt for this actor/organization/key.
  select * into v_existing
  from public.tournament_media_upload_sessions session
  where session.organization_id = v_gallery.organization_id
    and session.requested_by = auth.uid()
    and session.idempotency_key = p_idempotency_key
  order by
    (session.status = 'issued' and session.expires_at > now()) desc,
    session.created_at desc,
    session.id desc
  limit 1
  for update;

  if v_existing.id is not null then
    if v_existing.gallery_id is distinct from p_gallery_id
      or v_existing.requested_mime is distinct from p_declared_mime
      or v_existing.requested_size is distinct from p_byte_size
      or v_existing.processing_tier is distinct from v_tier
      or right(v_existing.safe_name,char_length(v_extension) + 1)
        is distinct from '.' || v_extension
    then
      raise exception using errcode = '22023',
        message = 'TORNEOS_MEDIA_IDEMPOTENCY_CONFLICT';
    end if;

    -- A consumed request already completed its logical operation. Never
    -- resurrect it into a second upload or detach it from its asset.
    if v_existing.asset_id is not null or v_existing.consumed_at is not null then
      raise exception using errcode = '22023',
        message = 'TORNEOS_MEDIA_IDEMPOTENCY_CONFLICT';
    end if;

    -- A live assetless intent with an unused path is reusable. Rotate the
    -- credential because only its hash is persisted; returning NULL cannot
    -- prove that the caller still has a usable token.
    if v_existing.status = 'issued'
      and v_existing.expires_at > now()
      and v_existing.token_hash ~ '^[0-9a-f]{64}$'
      and not exists (
        select 1 from public.tournament_media_assets asset
        where asset.internal_path = v_existing.internal_path
      )
      and not exists (
        select 1 from storage.objects object
        where object.bucket_id = v_existing.bucket
          and object.name = v_existing.internal_path
      )
    then
      update public.tournament_media_upload_sessions
      set token_hash = encode(public.digest(v_token,'sha256'),'hex')
      where id = v_existing.id;
      return jsonb_build_object(
        'sessionId',v_existing.id,'safeName',v_existing.safe_name,
        'expiresAt',v_existing.expires_at,'token',v_token,'reused',true,
        'processingTier',v_existing.processing_tier,'uploadReady',true,
        'requiresStagingStorageSigner',false
      );
    end if;

    -- Preserve the old row/path for scoped cleanup. Only an outstanding issued
    -- row must be closed before the partial uniqueness rule permits a new
    -- attempt. A written-but-unfinalized object is failed rather than called
    -- expired so the audit state reflects why its path was abandoned.
    if v_existing.status = 'issued' then
      update public.tournament_media_upload_sessions
      set status = case
        when v_existing.expires_at <= now() then 'expired'
        else 'failed'
      end
      where id = v_existing.id;
    end if;
  end if;

  select
    coalesce((select sum(asset.byte_size) from public.tournament_media_assets asset
      where asset.organization_id = v_gallery.organization_id and asset.status <> 'revoked'),0)
    + coalesce((select sum(session.requested_size)
      from public.tournament_media_upload_sessions session
      where session.organization_id = v_gallery.organization_id
        and session.status = 'issued' and session.expires_at > now()),0)
  into v_org_bytes;
  select
    coalesce((select sum(asset.byte_size) from public.tournament_media_assets asset
      where asset.tournament_id = v_gallery.tournament_id and asset.status <> 'revoked'),0)
    + coalesce((select sum(session.requested_size)
      from public.tournament_media_upload_sessions session
      where session.tournament_id = v_gallery.tournament_id
        and session.status = 'issued' and session.expires_at > now()),0)
  into v_tournament_bytes;
  select
    coalesce((select sum(asset.byte_size) from public.tournament_media_assets asset
      where asset.gallery_id = p_gallery_id and asset.status <> 'revoked'),0)
    + coalesce((select sum(session.requested_size)
      from public.tournament_media_upload_sessions session
      where session.gallery_id = p_gallery_id
        and session.status = 'issued' and session.expires_at > now()),0)
  into v_gallery_bytes;
  select count(*) into v_open_sessions
  from public.tournament_media_upload_sessions session
  where session.requested_by = auth.uid() and session.status = 'issued'
    and session.expires_at > now();

  if v_tier = 'mvp_simple' then
    select count(*) into v_recent_emissions
    from public.tournament_media_upload_sessions session
    where session.requested_by = auth.uid()
      and session.created_at > now() - interval '15 minutes';
    if v_recent_emissions >= 30 then
      raise exception using errcode = 'P0001',
        message = 'TORNEOS_MEDIA_MVP_RATE_LIMITED';
    end if;
  end if;

  if v_open_sessions >= v_max_open then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_QUOTA_EXCEEDED';
  end if;

  v_safe_name := 'foto-' || substr(replace(v_file_id::text,'-',''),1,12)
    || '.' || v_extension;
  v_path := v_gallery.organization_id::text || '/' || v_gallery.tournament_id::text
    || '/' || v_gallery.id::text || '/' || v_file_id::text || '.' || v_extension;
  insert into public.tournament_media_upload_sessions (
    organization_id,tournament_id,gallery_id,requested_by,token_hash,
    internal_path,safe_name,requested_mime,requested_size,max_size,
    processing_tier,idempotency_key,quota_snapshot,expires_at
  ) values (
    v_gallery.organization_id,v_gallery.tournament_id,v_gallery.id,auth.uid(),
    encode(public.digest(v_token,'sha256'),'hex'),v_path,v_safe_name,
    p_declared_mime,p_byte_size,v_max_file,v_tier,p_idempotency_key,
    jsonb_build_object(
      'organizationBytes',v_org_bytes,'tournamentBytes',v_tournament_bytes,
      'galleryBytes',v_gallery_bytes,'maxFileBytes',v_max_file,
      'processingTier',v_tier
    ),now() + v_expires
  ) returning id into v_session_id;
  perform public.append_tournament_audit(
    v_gallery.organization_id,'media.upload_session.issued',
    'media_upload_session',v_session_id,null,v_gallery.tournament_id,
    jsonb_build_object(
      'galleryId',v_gallery.id,'byteSize',p_byte_size,'processingTier',v_tier,
      'replacesSessionId',v_existing.id
    )
  );
  return jsonb_build_object(
    'sessionId',v_session_id,'safeName',v_safe_name,
    'expiresAt',now() + v_expires,'token',v_token,'reused',false,
    'processingTier',v_tier,'uploadReady',true,
    'requiresStagingStorageSigner',false
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.request_tournament_player_portrait_upload(p_actor_user_id uuid, p_organization_id uuid, p_roster_player_id uuid, p_mime_type text, p_byte_size bigint, p_width integer, p_height integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_player public.tournament_roster_players%ROWTYPE;
  v_entry public.tournament_team_entries%ROWTYPE;
  v_portrait_id uuid := gen_random_uuid();
  v_extension text;
  v_path text;
BEGIN
  IF NOT public.can_manage_tournament_player_portrait_as(
    p_organization_id, p_roster_player_id, p_actor_user_id
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_PORTRAIT_FORBIDDEN';
  END IF;
  IF p_mime_type NOT IN ('image/jpeg', 'image/png', 'image/webp')
    OR p_byte_size NOT BETWEEN 1 AND 8388608
    OR p_width NOT BETWEEN 1 AND 12000
    OR p_height NOT BETWEEN 1 AND 12000
    OR p_width::bigint * p_height::bigint > 36000000
  THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TORNEOS_PORTRAIT_FILE_INVALID';
  END IF;

  SELECT * INTO v_player
  FROM public.tournament_roster_players player
  WHERE player.organization_id = p_organization_id
    AND player.id = p_roster_player_id
    AND player.status = 'active';
  IF v_player.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_PORTRAIT_FORBIDDEN';
  END IF;
  SELECT * INTO v_entry
  FROM public.tournament_team_entries entry
  WHERE entry.organization_id = p_organization_id
    AND entry.id = v_player.team_entry_id;

  v_extension := CASE p_mime_type
    WHEN 'image/jpeg' THEN 'jpg'
    WHEN 'image/png' THEN 'png'
    WHEN 'image/webp' THEN 'webp'
  END;
  v_path := 'organizations/' || p_organization_id::text
    || '/roster-players/' || p_roster_player_id::text
    || '/' || v_portrait_id::text || '.' || v_extension;

  INSERT INTO public.tournament_player_portraits (
    id, organization_id, tournament_id, team_entry_id, roster_player_id,
    object_path, mime_type, byte_size, width, height, uploaded_by
  ) VALUES (
    v_portrait_id, p_organization_id, v_entry.tournament_id,
    v_player.team_entry_id, p_roster_player_id, v_path, p_mime_type,
    p_byte_size, p_width, p_height, p_actor_user_id
  );

  RETURN jsonb_build_object(
    'portraitId', v_portrait_id,
    'bucket', 'tournament-player-portraits',
    'objectPath', v_path,
    'imageRef', jsonb_build_object(
      'kind', 'player_portrait', 'id', v_portrait_id, 'variant', 'original'
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.request_tournament_team_photo_upload(p_actor_user_id uuid, p_organization_id uuid, p_team_entry_id uuid, p_mime_type text, p_byte_size bigint, p_width integer, p_height integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_entry public.tournament_team_entries%ROWTYPE;
  v_photo_id uuid := gen_random_uuid();
  v_path text;
BEGIN
  IF NOT public.can_manage_tournament_team_visual_assets_as(
    p_organization_id, p_team_entry_id, p_actor_user_id, 'team_entries.update'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_TEAM_PHOTO_FORBIDDEN';
  END IF;
  IF p_mime_type NOT IN ('image/jpeg', 'image/png', 'image/webp')
    OR p_byte_size NOT BETWEEN 1 AND 8388608
    OR p_width NOT BETWEEN 1 AND 12000
    OR p_height NOT BETWEEN 1 AND 12000
    OR p_width::bigint * p_height::bigint > 36000000
  THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TORNEOS_TEAM_PHOTO_FILE_INVALID';
  END IF;

  SELECT * INTO v_entry
  FROM public.tournament_team_entries entry
  WHERE entry.organization_id = p_organization_id
    AND entry.id = p_team_entry_id;
  IF v_entry.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_TEAM_PHOTO_FORBIDDEN';
  END IF;

  v_path := 'organizations/' || p_organization_id::text
    || '/team-entries/' || p_team_entry_id::text
    || '/' || v_photo_id::text || '.' || CASE p_mime_type
      WHEN 'image/jpeg' THEN 'jpg'
      WHEN 'image/png' THEN 'png'
      WHEN 'image/webp' THEN 'webp'
    END;

  INSERT INTO public.tournament_team_photos (
    id, organization_id, tournament_id, team_entry_id, object_path, mime_type,
    byte_size, width, height, uploaded_by
  ) VALUES (
    v_photo_id, p_organization_id, v_entry.tournament_id, p_team_entry_id,
    v_path, p_mime_type, p_byte_size, p_width, p_height, p_actor_user_id
  );

  RETURN jsonb_build_object(
    'teamPhotoId', v_photo_id,
    'bucket', 'tournament-team-photos',
    'objectPath', v_path,
    'imageRef', jsonb_build_object(
      'kind', 'team_photo', 'id', v_photo_id, 'variant', 'original'
    )
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reschedule_tournament_match(p_organization_id uuid, p_match_id uuid, p_scheduled_at timestamp with time zone, p_venue_id uuid, p_court_id uuid, p_duration_minutes integer, p_reason text, p_override_warnings boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_validation jsonb;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if auth.uid() is null or char_length(v_reason) not between 3 and 500
    or not public.has_tournament_organization_capability(
      p_organization_id, 'matches.reschedule'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  select match_row.* into v_match from public.tournament_matches match_row
  join public.tournament_fixture_versions version
    on version.id = match_row.fixture_version_id
    and version.status in ('draft', 'published')
    and version.invalidated_at is null
  where match_row.id = p_match_id
    and match_row.organization_id = p_organization_id
    and match_row.status in ('scheduled', 'postponed')
  for update of match_row;
  if v_match.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:schedule:court:' || p_court_id::text, 0
  ));
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:schedule:team:' || participant_id::text, 0
  ))
  from unnest(array_remove(
    array[v_match.home_participant_id, v_match.away_participant_id],
    null
  )) participant_id
  order by participant_id;
  v_validation := public.validate_tournament_match_schedule(
    p_organization_id, p_match_id, p_scheduled_at,
    p_venue_id, p_court_id, p_duration_minutes
  );
  if jsonb_array_length(v_validation->'blockers') > 0 then
    raise exception using errcode = '23514', message = 'TORNEOS_SCHEDULE_CONFLICT';
  end if;
  if jsonb_array_length(v_validation->'warnings') > 0 and (
    not p_override_warnings
    or not public.has_tournament_organization_capability(
      p_organization_id, 'schedule_conflicts.override'
    )
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_SCHEDULE_WARNING_CONFIRMATION';
  end if;
  insert into public.tournament_match_reschedules (
    organization_id, tournament_id, category_id, fixture_version_id, match_id,
    previous_scheduled_at, previous_venue_id, previous_court_id,
    new_scheduled_at, new_venue_id, new_court_id, reason, actor_user_id,
    previous_status, new_status
  ) values (
    v_match.organization_id, v_match.tournament_id, v_match.category_id,
    v_match.fixture_version_id, v_match.id, v_match.scheduled_at,
    v_match.venue_id, v_match.court_id, p_scheduled_at, p_venue_id, p_court_id,
    v_reason, auth.uid(), v_match.status, 'scheduled'
  );
  update public.tournament_matches
  set scheduled_at = p_scheduled_at, venue_id = p_venue_id, court_id = p_court_id,
      duration_minutes = p_duration_minutes, status = 'scheduled', postponed_at = null
  where id = v_match.id;
  if p_override_warnings and jsonb_array_length(v_validation->'warnings') > 0 then
    perform public.append_tournament_audit(
      p_organization_id, 'schedule_conflicts.overridden', 'match', v_match.id,
      null, v_match.tournament_id,
      jsonb_build_object('reason', v_reason, 'warnings', v_validation->'warnings')
    );
  end if;
  perform public.append_tournament_audit(
    p_organization_id, 'match.rescheduled', 'match', v_match.id,
    null, v_match.tournament_id,
    jsonb_build_object(
      'reason', v_reason,
      'previousScheduledAt', v_match.scheduled_at,
      'newScheduledAt', p_scheduled_at,
      'previousVenueId', v_match.venue_id, 'newVenueId', p_venue_id,
      'previousCourtId', v_match.court_id, 'newCourtId', p_court_id
    )
  );
  return jsonb_build_object('matchId', v_match.id, 'status', 'scheduled');
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_effective_tournament_entitlements_at(p_organization_id uuid, p_tournament_id uuid, p_as_of timestamp with time zone, p_participant_only boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_season_id uuid;
begin
  if p_tournament_id is null then return null; end if;
  select season_id into v_season_id from public.tournaments
  where organization_id = p_organization_id and id = p_tournament_id;
  if v_season_id is null then return null; end if;
  return public.resolve_effective_tournament_season_entitlements_at(
    p_organization_id,v_season_id,p_as_of,p_participant_only,p_tournament_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_effective_tournament_season_entitlements_at(p_organization_id uuid, p_season_id uuid, p_as_of timestamp with time zone, p_participant_only boolean DEFAULT false, p_tournament_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_plan text := 'FREE';
  v_source text := 'default_free';
  v_policy public.tournament_plan_catalog%rowtype;
  v_offer public.tournament_commercial_offers%rowtype;
  v_capabilities jsonb := '{}'::jsonb;
  v_admin_usage integer := 0;
begin
  if p_organization_id is null or p_season_id is null or p_as_of is null then return null; end if;
  if not exists (
    select 1 from public.tournament_seasons season
    where season.organization_id = p_organization_id and season.id = p_season_id
  ) then return null; end if;
  if p_tournament_id is not null and not exists (
    select 1 from public.tournaments tournament
    where tournament.organization_id = p_organization_id
      and tournament.season_id = p_season_id and tournament.id = p_tournament_id
  ) then return null; end if;
  select 'PREMIUM',grant_row.source into v_plan,v_source
  from public.tournament_season_plan_grants grant_row
  where grant_row.organization_id = p_organization_id and grant_row.season_id = p_season_id
    and public.is_tournament_season_plan_grant_effective(grant_row.id)
  order by case grant_row.source when 'purchase' then 0 else 1 end,
    grant_row.granted_at,grant_row.id limit 1;
  if not found then v_plan := 'FREE'; v_source := 'default_free'; end if;
  select * into v_policy from public.tournament_plan_catalog where plan_code = v_plan;
  select * into v_offer from public.tournament_commercial_offers offer
  where offer.product_code = 'torneos_premium' and offer.valid_from <= p_as_of
    and (offer.valid_until is null or offer.valid_until > p_as_of)
  order by (offer.availability = 'available') desc,offer.valid_from desc,offer.offer_version desc limit 1;
  select coalesce(jsonb_object_agg(catalog.capability,
    case when p_participant_only and not catalog.participant_enabled then false
      else coalesce(tournament_override.enabled,
        case when v_plan = 'PREMIUM' then catalog.premium_enabled else catalog.free_enabled end,false)
    end order by catalog.capability),'{}'::jsonb)
  into v_capabilities
  from public.tournament_entitlement_capabilities catalog
  left join public.tournament_entitlement_overrides tournament_override
    on p_tournament_id is not null
   and tournament_override.organization_id = p_organization_id
   and tournament_override.tournament_id = p_tournament_id
   and tournament_override.capability = catalog.capability
   and (tournament_override.expires_at is null or tournament_override.expires_at > p_as_of);
  select count(*)::integer into v_admin_usage
  from public.tournament_organization_members membership
  where membership.organization_id = p_organization_id and membership.status = 'active'
    and membership.role in ('admin','collaborator');
  return jsonb_build_object(
    'schemaVersion',4,'plan',v_plan,'assignmentSource',v_source,'requiresPremium',false,
    'scope',jsonb_build_object('type','season','organizationId',p_organization_id,
      'seasonId',p_season_id,'tournamentId',p_tournament_id,
      'audience',case when p_participant_only then 'participant' else 'organization_member' end),
    'pricing',jsonb_build_object('currency',v_offer.currency,'listPrice',v_offer.list_amount,
      'launchPrice',v_offer.amount,'billingModel','one_time','scope','season'),
    'offer',jsonb_build_object('code',v_offer.offer_code,'version',v_offer.offer_version,
      'label',v_offer.offer_label,'validUntil',v_offer.valid_until,'availability',v_offer.availability),
    'capabilities',v_capabilities,
    'limits',jsonb_build_object('galleryAssetLimit',v_policy.gallery_asset_limit,
      'administrativeCollaboratorLimit',v_policy.administrative_collaborator_limit),
    'media',jsonb_build_object('galleryAssetLimit',v_policy.gallery_asset_limit,
      'essentialAssetsCountTowardLimit',false),
    'administration',jsonb_build_object('currentAdministrativeSeatUsage',v_admin_usage,
      'administrativeSeatLimit',v_policy.administrative_collaborator_limit,
      'ownerIncluded',true,'ownerCountsTowardLimit',false),
    'social',jsonb_build_object('baseFamilyLimit',case when v_plan = 'PREMIUM' then 11 else 3 end,
      'premiumResultStyles',v_plan = 'PREMIUM'),
    'branding',jsonb_build_object('mode',v_policy.branding_mode,
      'arma2Visible',true,'canRemoveArma2',v_plan = 'PREMIUM',
      'label','Arma2 Torneos')
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_tournament_qualification(p_revision_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_revision public.tournament_standings_revisions%rowtype;
  v_source public.tournament_match_sources%rowtype;
  v_slot public.tournament_qualification_slots%rowtype;
  v_participant uuid;
  v_existing uuid;
  v_count integer := 0;
  v_blocked integer := 0;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_revision from public.tournament_standings_revisions
  where id = p_revision_id and status = 'published' for share;
  if v_revision.id is null or not public.has_tournament_organization_capability(
    v_revision.organization_id, 'qualification.resolve'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_QUALIFICATION_FORBIDDEN';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 3 then
    raise exception using errcode = '22023', message = 'TORNEOS_QUALIFICATION_REASON_REQUIRED';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    v_revision.organization_id::text || ':' || v_revision.tournament_id::text || ':'
    || v_revision.category_id::text || ':' || v_revision.phase_id::text || ':'
    || coalesce(v_revision.group_id::text, 'all'),
    0
  ));
  if exists (
    select 1 from public.tournament_matches match_row
    where match_row.fixture_version_id = v_revision.fixture_version_id
      and match_row.phase_id = v_revision.phase_id
      and match_row.group_id is not distinct from v_revision.group_id
      and match_row.status <> 'cancelled'
      and (
        match_row.home_participant_id is null
        or match_row.away_participant_id is null
        or not exists (
          select 1
          from public.tournament_match_operations operation
          join public.tournament_match_outcomes outcome
            on outcome.match_operation_id = operation.id
            and outcome.counts_for_standings
            and not outcome.requires_resolution
          where operation.match_id = match_row.id
            and operation.status = 'official'
        )
      )
  ) or exists (
    select 1 from public.tournament_match_outcomes outcome
    join public.tournament_match_operations operation
      on operation.id = outcome.match_operation_id and operation.status = 'official'
    join public.tournament_matches match_row on match_row.id = operation.match_id
    where match_row.fixture_version_id = v_revision.fixture_version_id
      and match_row.phase_id = v_revision.phase_id
      and match_row.group_id is not distinct from v_revision.group_id
      and outcome.requires_resolution
  ) or exists (
    select 1
    from public.tournament_match_reviews review
    join public.tournament_match_operations operation
      on operation.id = review.match_operation_id
    join public.tournament_matches match_row on match_row.id = operation.match_id
    where match_row.fixture_version_id = v_revision.fixture_version_id
      and match_row.phase_id = v_revision.phase_id
      and match_row.group_id is not distinct from v_revision.group_id
      and review.status = 'open'
      and review.review_type in (
        'correction', 'dispute_future', 'administrative_resolution'
      )
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_QUALIFICATION_INCOMPLETE';
  end if;
  if exists (
    select 1 from public.tournament_team_standings standing
    where standing.revision_id = v_revision.id
      and standing.classification_status = 'manual_review'
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_QUALIFICATION_AMBIGUOUS';
  end if;

  for v_source in
    select source.*
    from public.tournament_match_sources source
    where source.fixture_version_id = v_revision.fixture_version_id
      and (
        (source.source_type = 'group_position'
          and source.group_id is not distinct from v_revision.group_id)
        or (source.source_type = 'league_position'
          and source.source_phase_id = v_revision.phase_id)
        or (
          source.source_type in ('winner_of_match', 'loser_of_match')
          and exists (
            select 1 from public.tournament_matches source_match
            where source_match.id = source.source_match_id
              and source_match.phase_id = v_revision.phase_id
              and source_match.group_id is not distinct from v_revision.group_id
          )
        )
      )
    order by source.match_id, source.side
  loop
    if v_source.source_type in ('winner_of_match', 'loser_of_match') then
      select case
        when v_source.source_type = 'winner_of_match' then
          case when score.home_score > score.away_score
              or (
                score.home_score = score.away_score
                and score.home_penalties > score.away_penalties
              )
            then source_match.home_participant_id
            when score.away_score > score.home_score
              or (
                score.home_score = score.away_score
                and score.away_penalties > score.home_penalties
              )
            then source_match.away_participant_id end
        else
          case when score.home_score < score.away_score
              or (
                score.home_score = score.away_score
                and score.home_penalties < score.away_penalties
              )
            then source_match.home_participant_id
            when score.away_score < score.home_score
              or (
                score.home_score = score.away_score
                and score.away_penalties < score.home_penalties
              )
            then source_match.away_participant_id end
        end
      into v_participant
      from public.tournament_matches source_match
      join public.tournament_match_operations operation
        on operation.match_id = source_match.id and operation.status = 'official'
      join public.tournament_match_outcomes outcome
        on outcome.match_operation_id = operation.id
        and not outcome.requires_resolution
      join public.tournament_match_scores score
        on score.match_operation_id = operation.id
      where source_match.id = v_source.source_match_id;
    else
      select standing.participant_id into v_participant
      from public.tournament_team_standings standing
      where standing.revision_id = v_revision.id
        and standing.position = coalesce(
          v_source.position_number, v_source.rank_number
        );
    end if;
    if v_participant is null then
      raise exception using errcode = '55000', message = 'TORNEOS_QUALIFICATION_AMBIGUOUS';
    end if;

    insert into public.tournament_qualification_slots (
      organization_id, tournament_id, category_id, fixture_version_id,
      source_phase_id, source_group_id, match_source_id, slot_type, rank_number
    ) values (
      v_revision.organization_id, v_revision.tournament_id, v_revision.category_id,
      v_revision.fixture_version_id, v_revision.phase_id, v_revision.group_id,
      v_source.id, v_source.source_type,
      coalesce(v_source.position_number, v_source.rank_number, 1)
    )
    on conflict (match_source_id) do update set status = 'active'
    returning * into v_slot;

    select case when v_source.side = 'home'
      then match_row.home_participant_id else match_row.away_participant_id end
    into v_existing
    from public.tournament_matches match_row
    where match_row.id = v_source.match_id
    for update;

    if exists (
      select 1
      from public.tournament_qualification_resolutions resolution
      where resolution.slot_id = v_slot.id
        and resolution.status = 'manual'
    ) then
      raise exception using errcode = '55000', message = 'TORNEOS_QUALIFICATION_MANUAL_LOCKED';
    end if;

    if v_existing is not null and v_existing <> v_participant and exists (
      select 1 from public.tournament_match_operations operation
      where operation.match_id = v_source.match_id
    ) then
      update public.tournament_qualification_resolutions
      set status = 'superseded', superseded_at = now()
      where slot_id = v_slot.id and status in ('resolved', 'blocked', 'manual');

      insert into public.tournament_qualification_resolutions (
        organization_id, tournament_id, category_id, fixture_version_id,
        standings_revision_id, slot_id, participant_id, target_match_id,
        target_side, status, reason, resolved_by
      ) values (
        v_revision.organization_id, v_revision.tournament_id, v_revision.category_id,
        v_revision.fixture_version_id, v_revision.id, v_slot.id, v_participant,
        v_source.match_id, v_source.side, 'blocked',
        'El cruce posterior ya tiene un acta y requiere resolución manual.',
        auth.uid()
      )
      on conflict do nothing;
      v_blocked := v_blocked + 1;
      continue;
    end if;

    update public.tournament_qualification_resolutions
    set status = 'superseded', superseded_at = now()
    where slot_id = v_slot.id and status in ('resolved', 'blocked', 'manual');

    insert into public.tournament_qualification_resolutions (
      organization_id, tournament_id, category_id, fixture_version_id,
      standings_revision_id, slot_id, participant_id, target_match_id,
      target_side, status, reason, resolved_by
    ) values (
      v_revision.organization_id, v_revision.tournament_id, v_revision.category_id,
      v_revision.fixture_version_id, v_revision.id, v_slot.id, v_participant,
      v_source.match_id, v_source.side, 'resolved', btrim(p_reason), auth.uid()
    );

    update public.tournament_matches
    set home_participant_id = case when v_source.side = 'home'
        then v_participant else home_participant_id end,
      away_participant_id = case when v_source.side = 'away'
        then v_participant else away_participant_id end,
      updated_at = now()
    where id = v_source.match_id;
    v_count := v_count + 1;
  end loop;

  perform public.append_tournament_audit(
    v_revision.organization_id, 'qualification.resolve', 'standings_revision',
    v_revision.id, null, v_revision.tournament_id,
    jsonb_build_object('resolved', v_count, 'blocked', v_blocked, 'reason', btrim(p_reason))
  );
  return jsonb_build_object('resolved', v_count, 'blocked', v_blocked);
end;
$function$

CREATE OR REPLACE FUNCTION public.respond_match_availability(p_match_id uuid, p_response text, p_comment text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_player public.tournament_roster_players%rowtype;
  v_match public.tournament_matches%rowtype;
  v_response public.tournament_match_availability_responses%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if p_response not in ('available', 'unavailable', 'maybe') then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_AVAILABILITY';
  end if;
  select * into v_match from public.tournament_matches where id = p_match_id for share;
  select player.* into v_player
  from public.tournament_roster_players player
  join public.tournament_rosters roster
    on roster.id = player.roster_id and roster.status in ('approved', 'locked')
  cross join lateral public.tournament_match_team_entries(p_match_id) teams
  where player.arma2_user_id = auth.uid()
    and player.team_entry_id in (teams.home_team_entry_id, teams.away_team_entry_id)
    and player.status = 'active' and player.eligibility_status = 'eligible'
  limit 1;
  if v_match.id is null or v_match.status not in ('scheduled', 'ready')
    or v_match.scheduled_at is null or now() >= v_match.scheduled_at
    or v_player.id is null
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournament_match_operations operation
    where operation.match_id = p_match_id
      and operation.status not in ('superseded', 'voided')
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_MATCH_OPERATION_ACTIVE';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:match-availability:' || p_match_id || ':' || v_player.id, 0
  ));
  insert into public.tournament_match_availability_responses (
    organization_id, match_id, team_entry_id, roster_player_id, user_id,
    response, comment, response_source, recorded_by
  ) values (
    v_match.organization_id, p_match_id, v_player.team_entry_id, v_player.id,
    auth.uid(), p_response, nullif(btrim(p_comment), ''), 'self', auth.uid()
  )
  on conflict (match_id, roster_player_id) do update set
    response = excluded.response,
    comment = excluded.comment,
    user_id = excluded.user_id,
    response_source = 'self',
    recorded_by = excluded.recorded_by,
    manual_reason = null,
    responded_at = now(),
    updated_at = now()
  returning * into v_response;
  perform public.append_tournament_audit(
    v_match.organization_id, 'match_availability.responded',
    'match_availability', v_response.id, v_player.team_entry_id,
    v_match.tournament_id, jsonb_build_object('response', p_response, 'source', 'self')
  );
  return jsonb_build_object(
    'id', v_response.id, 'matchId', p_match_id,
    'rosterPlayerId', v_player.id, 'response', v_response.response
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.restore_tournament_match_unscheduled(p_organization_id uuid, p_match_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if auth.uid() is null or char_length(v_reason) not between 3 and 500
    or not public.has_tournament_organization_capability(
      p_organization_id, 'matches.reschedule'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  select match_row.* into v_match from public.tournament_matches match_row
  join public.tournament_fixture_versions version
    on version.id = match_row.fixture_version_id
    and version.status in ('draft', 'published')
    and version.invalidated_at is null
  where match_row.id = p_match_id and match_row.organization_id = p_organization_id
    and match_row.status = 'postponed'
  for update of match_row;
  if v_match.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  insert into public.tournament_match_reschedules (
    organization_id, tournament_id, category_id, fixture_version_id, match_id,
    previous_scheduled_at, previous_venue_id, previous_court_id,
    new_scheduled_at, new_venue_id, new_court_id, reason, actor_user_id,
    previous_status, new_status
  ) values (
    v_match.organization_id, v_match.tournament_id, v_match.category_id,
    v_match.fixture_version_id, v_match.id, v_match.scheduled_at,
    v_match.venue_id, v_match.court_id, null, null, null,
    v_reason, auth.uid(), 'postponed', 'unscheduled'
  );
  update public.tournament_matches
  set status = 'unscheduled', scheduled_at = null, venue_id = null, court_id = null,
      postponed_at = null
  where id = v_match.id;
  perform public.append_tournament_audit(
    p_organization_id, 'match.restored_unscheduled', 'match', v_match.id,
    null, v_match.tournament_id, jsonb_build_object('reason', v_reason)
  );
  return jsonb_build_object('matchId', v_match.id, 'status', 'unscheduled');
end;
$function$

CREATE OR REPLACE FUNCTION public.review_tournament_match_operation(p_organization_id uuid, p_match_operation_id uuid, p_decision text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_operation public.tournament_match_operations%rowtype;
  v_review public.tournament_match_reviews%rowtype;
  v_outcome_type text;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null or v_operation.status not in ('submitted', 'under_review')
    or p_decision not in ('approved', 'rejected')
    or char_length(btrim(coalesce(p_reason, ''))) not between 3 and 2000
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_operations.review'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  select * into v_review from public.tournament_match_reviews
  where match_operation_id = v_operation.id and review_type = 'validation'
    and status = 'open' for update;
  if v_review.id is null then
    raise exception using errcode = '55000', message = 'TORNEOS_MATCH_REVIEW_NOT_OPEN';
  end if;
  update public.tournament_match_reviews set
    status = p_decision, resolved_by = auth.uid(), resolved_at = now(),
    resolution = btrim(p_reason)
  where id = v_review.id;
  select outcome_type into v_outcome_type
  from public.tournament_match_outcomes
  where match_operation_id = v_operation.id;
  update public.tournament_match_operations set
    status = case when p_decision = 'approved' then 'under_review' else 'draft' end,
    match_status = case when p_decision = 'approved' then match_status else
      case
        when v_outcome_type = 'played' then 'played'
        when v_outcome_type = 'suspended' then 'suspended'
        when v_outcome_type = 'abandoned' then 'abandoned'
        when v_outcome_type in (
          'home_no_show', 'away_no_show', 'double_no_show',
          'walkover_home', 'walkover_away', 'administrative_result'
        ) then 'administrative'
        else 'ready'
      end end,
    submitted_by = case when p_decision = 'approved' then submitted_by else null end,
    submitted_at = case when p_decision = 'approved' then submitted_at else null end,
    updated_at = now()
  where id = v_operation.id;
  perform public.append_tournament_audit(
    p_organization_id, 'match_operation.reviewed', 'match_operation',
    v_operation.id, null, v_operation.tournament_id,
    jsonb_build_object('decision', p_decision)
  );
  return public.get_tournament_match_operation_context(p_organization_id, v_operation.id);
end;
$function$

CREATE OR REPLACE FUNCTION public.review_tournament_team_entry(p_organization_id uuid, p_team_entry_id uuid, p_decision text, p_reason text, p_issues jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_entry public.tournament_team_entries%rowtype;
  v_roster public.tournament_rosters%rowtype;
  v_validation jsonb;
begin
  if auth.uid() is null or not public.has_tournament_organization_capability(
    p_organization_id,
    case when p_decision = 'approved' then 'team_entries.approve'
         when p_decision = 'rejected' then 'team_entries.reject'
         else 'team_entries.review' end
  ) then raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN'; end if;
  if p_decision not in ('changes_requested', 'approved', 'rejected')
    or char_length(btrim(coalesce(p_reason, ''))) not between 3 and 1200
    or jsonb_typeof(coalesce(p_issues, '[]'::jsonb)) <> 'array'
  then raise exception using errcode = '22023', message = 'TORNEOS_INVALID_REVIEW'; end if;
  select * into v_entry from public.tournament_team_entries
  where id = p_team_entry_id and organization_id = p_organization_id
    and status = 'submitted' for update;
  select * into v_roster from public.tournament_rosters
  where team_entry_id = p_team_entry_id and status = 'submitted'
  order by version desc limit 1 for update;
  if v_entry.id is null or v_roster.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if not exists (
    select 1
    from public.tournament_organizations organization
    join public.tournaments tournament
      on tournament.organization_id = organization.id
    join public.tournament_categories category
      on category.organization_id = tournament.organization_id
      and category.tournament_id = tournament.id
    where organization.id = p_organization_id
      and organization.status = 'active'
      and tournament.id = v_entry.tournament_id
      and tournament.status in ('registration', 'scheduled')
      and category.id = v_entry.category_id
      and category.status = 'active'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if p_decision = 'approved' then
    perform pg_advisory_xact_lock(hashtextextended(v_entry.tournament_id::text || ':' || v_entry.category_id::text, 0));
    v_validation := public.validate_tournament_roster(p_organization_id, p_team_entry_id, v_roster.id);
    if not (v_validation->>'valid')::boolean then
      raise exception using errcode = '23514', message = 'TORNEOS_ROSTER_INCOMPLETE', detail = v_validation::text;
    end if;
    update public.tournament_rosters set status = 'approved', approved_at = now()
    where id = v_roster.id returning * into v_roster;
    update public.tournament_roster_players set
      eligibility_status = case
        when eligibility_status = 'pending'
          and not (
            select settings.require_individual_player_approval
            from public.tournament_roster_settings settings
            where settings.organization_id = p_organization_id
              and settings.tournament_id = v_entry.tournament_id
          )
        then 'eligible'
        else eligibility_status
      end
    where roster_id = v_roster.id and status = 'active';
    update public.tournament_team_entries set
      status = 'approved', reviewed_by = auth.uid(), reviewed_at = now(),
      approved_at = now(), rejected_at = null
    where id = v_entry.id returning * into v_entry;
  elsif p_decision = 'changes_requested' then
    update public.tournament_rosters set status = 'changes_requested'
    where id = v_roster.id returning * into v_roster;
    update public.tournament_team_entries set
      status = 'changes_requested', reviewed_by = auth.uid(), reviewed_at = now()
    where id = v_entry.id returning * into v_entry;
  else
    update public.tournament_team_entries set
      status = 'rejected', reviewed_by = auth.uid(), reviewed_at = now(),
      rejected_at = now()
    where id = v_entry.id returning * into v_entry;
  end if;
  insert into public.tournament_team_reviews (
    organization_id, team_entry_id, roster_id, decision, reason, issues, created_by
  ) values (
    p_organization_id, v_entry.id, v_roster.id, p_decision, btrim(p_reason),
    coalesce(p_issues, '[]'::jsonb), auth.uid()
  );
  perform public.append_tournament_audit(
    p_organization_id, 'team_entry.' || p_decision, 'team_entry', v_entry.id,
    v_entry.id, v_entry.tournament_id,
    jsonb_build_object('rosterId', v_roster.id, 'issueCount', jsonb_array_length(coalesce(p_issues, '[]'::jsonb)))
  );
  return jsonb_build_object('entryId', v_entry.id, 'rosterId', v_roster.id, 'status', v_entry.status, 'validation', v_validation);
end;
$function$

CREATE OR REPLACE FUNCTION public.revoke_tournament_announcement(p_announcement_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_announcement public.tournament_announcements%rowtype;
begin
  select * into v_announcement
  from public.tournament_announcements announcement
  where announcement.id = p_announcement_id
  for update;
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if v_announcement.id is null
    or not public.has_tournament_communications_capability(
      v_announcement.organization_id,'announcements.revoke'
    )
    or v_announcement.status <> 'published'
    or p_reason is null or char_length(btrim(p_reason)) < 4
  then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  update public.tournament_announcements
  set status = 'revoked',revoked_at = now(),revoked_reason = btrim(p_reason)
  where id = p_announcement_id;
  update public.tournament_announcement_deliveries
  set status = 'revoked',revoked_at = now()
  where announcement_id = p_announcement_id
    and status <> 'archived';
  perform public.append_tournament_audit(
    v_announcement.organization_id,'communications.announcement_revoke','announcement',
    p_announcement_id,null,v_announcement.tournament_id,
    jsonb_build_object('reason',btrim(p_reason))
  );
  return p_announcement_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.revoke_tournament_media_service_attestation(p_service text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_service not in ('signer','processor') then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_ATTESTATION_INVALID';
  end if;
  delete from public.tournament_media_service_attestations where service = p_service;
  return jsonb_build_object('service',p_service,'revoked',true);
end;
$function$

CREATE OR REPLACE FUNCTION public.revoke_tournament_player_portrait_publication(p_organization_id uuid, p_portrait_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_portrait public.tournament_player_portraits%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_AUTH_REQUIRED';
  END IF;
  SELECT * INTO v_portrait FROM public.tournament_player_portraits
  WHERE id = p_portrait_id AND organization_id = p_organization_id
    AND lifecycle_status IN ('active', 'delete_pending') FOR UPDATE;
  IF v_portrait.id IS NULL OR NOT public.can_moderate_tournament_team_visual_assets_as(
    p_organization_id, v_portrait.team_entry_id, auth.uid(), 'roster_players.update'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_PORTRAIT_FORBIDDEN';
  END IF;
  UPDATE public.tournament_player_portraits
  SET publication_consent = 'revoked', consent_actor_user_id = auth.uid(),
      consent_changed_at = now(), updated_at = now()
  WHERE id = p_portrait_id;
  PERFORM public.append_tournament_audit(
    p_organization_id, 'portrait.publication_revoked', 'player_portrait',
    p_portrait_id, v_portrait.team_entry_id, v_portrait.tournament_id,
    jsonb_build_object('rosterPlayerId', v_portrait.roster_player_id)
  );
  RETURN jsonb_build_object('portraitId', p_portrait_id,
    'publicationConsent', 'revoked');
END;
$function$

CREATE OR REPLACE FUNCTION public.revoke_tournament_points_adjustment(p_adjustment_id uuid, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_adjustment public.tournament_points_adjustments%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_adjustment
  from public.tournament_points_adjustments
  where id = p_adjustment_id;
  if v_adjustment.id is null or not public.has_tournament_organization_capability(
    v_adjustment.organization_id, 'standings.override'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_STANDINGS_FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    v_adjustment.organization_id::text || ':' || v_adjustment.tournament_id::text || ':'
    || v_adjustment.category_id::text || ':' || v_adjustment.phase_id::text || ':'
    || coalesce(v_adjustment.group_id::text, 'all'),
    0
  ));
  select * into strict v_adjustment
  from public.tournament_points_adjustments
  where id = p_adjustment_id for update;
  if v_adjustment.status = 'revoked' then return v_adjustment.id; end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 3 then
    raise exception using errcode = '22023', message = 'TORNEOS_STANDINGS_REASON_REQUIRED';
  end if;
  update public.tournament_points_adjustments
  set status = 'revoked', revoked_at = now()
  where id = v_adjustment.id;
  perform public.append_tournament_audit(
    v_adjustment.organization_id, 'standings.points_adjust_revoke',
    'points_adjustment', v_adjustment.id, null, v_adjustment.tournament_id,
    jsonb_build_object('reason', btrim(p_reason))
  );
  return v_adjustment.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.revoke_tournament_team_invitation(p_organization_id uuid, p_invitation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_invitation public.tournament_team_invitations%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_invitation from public.tournament_team_invitations
  where id = p_invitation_id and organization_id = p_organization_id;
  if v_invitation.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  perform 1
  from public.tournament_team_entries entry
  where entry.id = v_invitation.team_entry_id
    and entry.organization_id = p_organization_id
  for update;
  select * into v_invitation from public.tournament_team_invitations
  where id = p_invitation_id and organization_id = p_organization_id for update;
  if v_invitation.id is null or v_invitation.status not in ('pending', 'accepted')
    or not public.has_tournament_organization_capability(p_organization_id, 'team_managers.revoke')
  then raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN'; end if;
  update public.tournament_team_invitations set status = 'revoked', revoked_at = now()
  where id = v_invitation.id;
  update public.tournament_team_managers set status = 'revoked', revoked_at = now()
  where id = v_invitation.manager_id
    and organization_id = v_invitation.organization_id
    and team_entry_id = v_invitation.team_entry_id
    and status in ('pending', 'active');
  perform public.append_tournament_audit(
    p_organization_id,
    case
      when v_invitation.status = 'accepted' then 'team_manager.revoked'
      else 'team_manager.invitation_revoked'
    end,
    'team_manager',
    v_invitation.manager_id, v_invitation.team_entry_id,
    v_invitation.tournament_id, '{}'::jsonb
  );
  return jsonb_build_object('invitationId', v_invitation.id, 'status', 'revoked');
end;
$function$

CREATE OR REPLACE FUNCTION public.revoke_tournament_team_photo(p_organization_id uuid, p_team_photo_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_photo public.tournament_team_photos%ROWTYPE;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_AUTH_REQUIRED';
  END IF;
  SELECT * INTO v_photo
  FROM public.tournament_team_photos photo
  WHERE photo.id = p_team_photo_id
    AND photo.organization_id = p_organization_id
    AND photo.lifecycle_status = 'active'
    AND photo.editorial_status = 'approved'
  FOR UPDATE;
  IF v_photo.id IS NULL OR NOT public.can_moderate_tournament_team_visual_assets_as(
    p_organization_id, v_photo.team_entry_id, auth.uid(), 'team_entries.update'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_TEAM_PHOTO_FORBIDDEN';
  END IF;

  UPDATE public.tournament_team_photos
  SET lifecycle_status = 'replaced', replaced_at = now(), replaced_by_id = NULL,
      revoked_at = now(), revoked_by = auth.uid(), updated_at = now()
  WHERE id = p_team_photo_id;

  PERFORM public.append_tournament_audit(
    p_organization_id, 'team_photo.revoked', 'team_photo', p_team_photo_id,
    v_photo.team_entry_id, v_photo.tournament_id, '{}'::jsonb
  );

  RETURN jsonb_build_object('teamPhotoId', p_team_photo_id, 'revoked', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.save_match_squad(p_organization_id uuid, p_match_id uuid, p_team_entry_id uuid, p_players jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_roster public.tournament_rosters%rowtype;
  v_squad public.tournament_match_squads%rowtype;
  v_player jsonb;
  v_roster_player public.tournament_roster_players%rowtype;
  v_team_size integer;
  v_substitutes_limit integer;
  v_starters integer;
  v_captains integer;
  v_called_up integer;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if jsonb_typeof(coalesce(p_players, '[]'::jsonb)) <> 'array'
    or jsonb_array_length(coalesce(p_players, '[]'::jsonb)) > 80
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_MATCH_SQUAD';
  end if;
  select * into v_match from public.tournament_matches
  where id = p_match_id and organization_id = p_organization_id for update;
  if v_match.id is null or v_match.status not in ('scheduled', 'ready')
    or not public.can_manage_tournament_match_squad(
      p_organization_id, p_match_id, p_team_entry_id
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournament_match_operations operation
    where operation.match_id = p_match_id
      and operation.status not in ('superseded', 'voided')
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_MATCH_OPERATION_ACTIVE';
  end if;
  select * into v_roster from public.tournament_rosters
  where team_entry_id = p_team_entry_id and status in ('approved', 'locked')
  order by version desc limit 1;
  if v_roster.id is null then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_ROSTER_NOT_APPROVED';
  end if;
  select coalesce(category.team_size, tournament.team_size),
    coalesce(tournament.substitutes_limit, tournament.team_size)
  into v_team_size, v_substitutes_limit
  from public.tournament_categories category
  join public.tournaments tournament on tournament.id = category.tournament_id
  where category.id = v_match.category_id;
  select count(*) filter (where value->>'lineupStatus' = 'starter'),
    count(*) filter (where coalesce((value->>'isCaptain')::boolean, false)),
    count(*) filter (where value->>'callupStatus' = 'called_up')
  into v_starters, v_captains, v_called_up
  from jsonb_array_elements(p_players);
  if v_starters > v_team_size or v_captains > 1
    or v_called_up > v_team_size + v_substitutes_limit
  then
    raise exception using errcode = '23514', message = 'TORNEOS_INVALID_MATCH_SQUAD';
  end if;
  insert into public.tournament_match_squads (
    organization_id, match_id, team_entry_id, roster_id, created_by
  ) values (
    p_organization_id, p_match_id, p_team_entry_id, v_roster.id, auth.uid()
  )
  on conflict (match_id, team_entry_id) where status <> 'superseded'
  do update set updated_at = now()
  returning * into v_squad;
  if v_squad.status <> 'draft' then
    raise exception using errcode = '55000', message = 'TORNEOS_MATCH_SQUAD_LOCKED';
  end if;
  delete from public.tournament_match_squad_players
  where match_squad_id = v_squad.id;
  for v_player in select value from jsonb_array_elements(p_players)
  loop
    select * into v_roster_player
    from public.tournament_roster_players
    where id = (v_player->>'rosterPlayerId')::uuid
      and roster_id = v_roster.id and team_entry_id = p_team_entry_id
      and status = 'active' and eligibility_status = 'eligible';
    if v_roster_player.id is null then
      raise exception using errcode = '23514', message = 'TORNEOS_MATCH_PLAYER_OUT_OF_SCOPE';
    end if;
    insert into public.tournament_match_squad_players (
      organization_id, match_squad_id, match_id, roster_player_id, team_entry_id,
      availability_status, callup_status, lineup_status, shirt_number_snapshot,
      position_snapshot, display_name_snapshot, avatar_url_snapshot,
      is_goalkeeper, is_captain, attendance_status
    ) values (
      p_organization_id, v_squad.id, p_match_id, v_roster_player.id, p_team_entry_id,
      coalesce((
        select availability.response
        from public.tournament_match_availability_responses availability
        where availability.match_id = p_match_id
          and availability.roster_player_id = v_roster_player.id
      ), 'no_response'),
      coalesce(v_player->>'callupStatus', 'not_called_up'),
      coalesce(v_player->>'lineupStatus', 'not_in_match_squad'),
      v_roster_player.shirt_number, v_roster_player.primary_position,
      v_roster_player.display_name, v_roster_player.avatar_url,
      v_roster_player.is_goalkeeper,
      coalesce((v_player->>'isCaptain')::boolean, false),
      coalesce(v_player->>'attendanceStatus', 'unknown')
    );
  end loop;
  perform public.append_tournament_audit(
    p_organization_id, 'match_squad.saved', 'match_squad', v_squad.id,
    p_team_entry_id, v_match.tournament_id,
    jsonb_build_object('players', jsonb_array_length(p_players))
  );
  return public.get_match_squad_context(p_organization_id, p_match_id, p_team_entry_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.save_tournament_draw_pots(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_pots jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_set public.tournament_participant_sets%rowtype;
  v_pot jsonb;
  v_member jsonb;
  v_pot_id uuid;
  v_pot_count integer := 0;
  v_member_count integer := 0;
begin
  perform public.assert_tournament_fixture_scope(
    p_organization_id, p_tournament_id, p_category_id,
    'draw.manage', array['registration', 'scheduled']::text[]
  );
  if jsonb_typeof(p_pots) <> 'array' or jsonb_array_length(p_pots) > 32 then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_DRAW_POTS';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:draw:' || p_tournament_id::text || ':' || p_category_id::text, 0
  ));
  select participant_set.* into v_set
  from public.tournament_participant_sets participant_set
  where participant_set.organization_id = p_organization_id
    and participant_set.tournament_id = p_tournament_id
    and participant_set.category_id = p_category_id
    and participant_set.status = 'frozen'
  for update;
  if v_set.id is null or exists (
    select 1 from public.tournament_groups group_row
    where group_row.participant_set_id = v_set.id and group_row.status = 'published'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_DRAW_NOT_EDITABLE';
  end if;
  delete from public.tournament_draw_pot_members member
  using public.tournament_draw_pots pot
  where member.pot_id = pot.id and pot.participant_set_id = v_set.id;
  delete from public.tournament_draw_pots pot where pot.participant_set_id = v_set.id;
  update public.tournament_competition_participants
  set pot_number = null, seed_number = null
  where participant_set_id = v_set.id;
  for v_pot in select value from jsonb_array_elements(p_pots)
  loop
    if jsonb_typeof(v_pot) <> 'object'
      or coalesce((v_pot->>'number')::integer, 0) <= 0
      or char_length(btrim(coalesce(v_pot->>'name', ''))) not between 1 and 80
      or jsonb_typeof(coalesce(v_pot->'members', '[]'::jsonb)) <> 'array'
    then
      raise exception using errcode = '22023', message = 'TORNEOS_INVALID_DRAW_POTS';
    end if;
    insert into public.tournament_draw_pots (
      organization_id, tournament_id, category_id, participant_set_id,
      name, number, sort_order
    ) values (
      p_organization_id, p_tournament_id, p_category_id, v_set.id,
      btrim(v_pot->>'name'), (v_pot->>'number')::integer,
      coalesce((v_pot->>'sortOrder')::integer, v_pot_count)
    ) returning id into v_pot_id;
    v_pot_count := v_pot_count + 1;
    for v_member in
      select value from jsonb_array_elements(coalesce(v_pot->'members', '[]'::jsonb))
    loop
      if not exists (
        select 1 from public.tournament_competition_participants participant
        where participant.id = (v_member->>'participantId')::uuid
          and participant.participant_set_id = v_set.id
          and participant.status = 'active'
      ) then
        raise exception using errcode = '23514', message = 'TORNEOS_INVALID_DRAW_PARTICIPANT';
      end if;
      insert into public.tournament_draw_pot_members (
        pot_id, participant_id, seed_number
      ) values (
        v_pot_id,
        (v_member->>'participantId')::uuid,
        nullif(v_member->>'seedNumber', '')::integer
      );
      update public.tournament_competition_participants
      set pot_number = (v_pot->>'number')::integer,
          seed_number = nullif(v_member->>'seedNumber', '')::integer
      where id = (v_member->>'participantId')::uuid;
      v_member_count := v_member_count + 1;
    end loop;
  end loop;
  perform public.append_tournament_audit(
    p_organization_id, 'draw.pots_saved', 'participant_set', v_set.id,
    null, p_tournament_id,
    jsonb_build_object(
      'categoryId', p_category_id,
      'potCount', v_pot_count,
      'memberCount', v_member_count
    )
  );
  return jsonb_build_object(
    'participantSetId', v_set.id,
    'potCount', v_pot_count,
    'memberCount', v_member_count
  );
exception
  when unique_violation then
    raise exception using errcode = '23505', message = 'TORNEOS_DUPLICATE_DRAW_ASSIGNMENT';
end;
$function$

CREATE OR REPLACE FUNCTION public.save_tournament_match_operation_draft(p_organization_id uuid, p_match_operation_id uuid, p_match_status text, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_operation public.tournament_match_operations%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null or v_operation.status <> 'draft'
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_operations.update_draft'
    )
    or p_match_status not in (
      'ready', 'in_progress', 'suspended', 'abandoned',
      'played', 'administrative', 'voided'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  update public.tournament_match_operations
  set match_status = p_match_status, notes = nullif(btrim(p_notes), ''), updated_at = now()
  where id = p_match_operation_id;
  return public.get_tournament_match_operation_context(p_organization_id, p_match_operation_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.save_tournament_schedule_windows(p_organization_id uuid, p_tournament_id uuid, p_windows jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_window jsonb;
  v_count integer := 0;
  v_category_id uuid;
  v_venue_id uuid;
  v_court_id uuid;
begin
  if auth.uid() is null
    or not public.has_tournament_organization_capability(
      p_organization_id, 'schedule_windows.manage'
    )
    or jsonb_typeof(p_windows) <> 'array'
    or jsonb_array_length(p_windows) > 500
    or not exists (
      select 1 from public.tournaments tournament
      join public.tournament_organizations organization
        on organization.id = tournament.organization_id
      where tournament.id = p_tournament_id
        and tournament.organization_id = p_organization_id
        and tournament.status <> 'archived'
        and organization.status = 'active'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:windows:' || p_tournament_id::text, 0
  ));
  update public.tournament_schedule_windows
  set status = 'archived', archived_at = now()
  where organization_id = p_organization_id
    and tournament_id = p_tournament_id
    and status = 'active';
  for v_window in select value from jsonb_array_elements(p_windows)
  loop
    if jsonb_typeof(v_window) <> 'object' then
      raise exception using errcode = '22023', message = 'TORNEOS_INVALID_SCHEDULE_WINDOW';
    end if;
    v_category_id := nullif(v_window->>'categoryId', '')::uuid;
    v_venue_id := nullif(v_window->>'venueId', '')::uuid;
    v_court_id := nullif(v_window->>'courtId', '')::uuid;
    if v_category_id is not null and not exists (
      select 1 from public.tournament_categories category
      where category.id = v_category_id
        and category.organization_id = p_organization_id
        and category.tournament_id = p_tournament_id
        and category.status = 'active'
    ) then
      raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
    end if;
    if v_venue_id is not null and not exists (
      select 1
      from public.tournament_venues venue
      where venue.id = v_venue_id
        and venue.organization_id = p_organization_id
        and venue.status = 'active'
    ) then
      raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
    end if;
    if v_court_id is not null and not exists (
      select 1 from public.tournament_courts court
      join public.tournament_venues venue on venue.id = court.venue_id
      where court.id = v_court_id and court.organization_id = p_organization_id
        and court.venue_id = v_venue_id
        and court.status = 'active' and venue.status = 'active'
    ) then
      raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
    end if;
    insert into public.tournament_schedule_windows (
      organization_id, tournament_id, category_id, venue_id, court_id,
      day_of_week, specific_date, starts_at, ends_at, slot_duration_minutes,
      buffer_minutes, window_type, notes
    ) values (
      p_organization_id, p_tournament_id, v_category_id, v_venue_id, v_court_id,
      nullif(v_window->>'dayOfWeek', '')::smallint,
      nullif(v_window->>'specificDate', '')::date,
      (v_window->>'startsAt')::time, (v_window->>'endsAt')::time,
      (v_window->>'slotDurationMinutes')::integer,
      coalesce((v_window->>'bufferMinutes')::integer, 0),
      coalesce(v_window->>'windowType', 'availability'),
      nullif(btrim(coalesce(v_window->>'notes', '')), '')
    );
    v_count := v_count + 1;
  end loop;
  perform public.append_tournament_audit(
    p_organization_id, 'schedule_windows.saved', 'tournament', p_tournament_id,
    null, p_tournament_id, jsonb_build_object('windowCount', v_count)
  );
  return jsonb_build_object('tournamentId', p_tournament_id, 'windowCount', v_count);
end;
$function$

CREATE OR REPLACE FUNCTION public.schedule_tournament_match(p_organization_id uuid, p_match_id uuid, p_scheduled_at timestamp with time zone, p_venue_id uuid, p_court_id uuid, p_duration_minutes integer, p_override_warnings boolean DEFAULT false, p_override_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_validation jsonb;
  v_reason text := btrim(coalesce(p_override_reason, ''));
begin
  if auth.uid() is null
    or not public.has_tournament_organization_capability(
      p_organization_id, 'matches.schedule'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  select match_row.* into v_match
  from public.tournament_matches match_row
  join public.tournament_fixture_versions version
    on version.id = match_row.fixture_version_id
    and version.status in ('draft', 'published')
    and version.invalidated_at is null
  where match_row.id = p_match_id
    and match_row.organization_id = p_organization_id
    and match_row.status = 'unscheduled'
  for update of match_row;
  if v_match.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:schedule:court:' || p_court_id::text, 0
  ));
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:schedule:team:' || participant_id::text, 0
  ))
  from unnest(array_remove(
    array[v_match.home_participant_id, v_match.away_participant_id],
    null
  )) participant_id
  order by participant_id;
  v_validation := public.validate_tournament_match_schedule(
    p_organization_id, p_match_id, p_scheduled_at,
    p_venue_id, p_court_id, p_duration_minutes
  );
  if jsonb_array_length(v_validation->'blockers') > 0 then
    raise exception using errcode = '23514', message = 'TORNEOS_SCHEDULE_CONFLICT';
  end if;
  if jsonb_array_length(v_validation->'warnings') > 0 and (
    not p_override_warnings
    or char_length(v_reason) not between 3 and 500
    or not public.has_tournament_organization_capability(
      p_organization_id, 'schedule_conflicts.override'
    )
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_SCHEDULE_WARNING_CONFIRMATION';
  end if;
  update public.tournament_matches
  set scheduled_at = p_scheduled_at, venue_id = p_venue_id, court_id = p_court_id,
      duration_minutes = p_duration_minutes, status = 'scheduled',
      postponed_at = null
  where id = v_match.id;
  if p_override_warnings and jsonb_array_length(v_validation->'warnings') > 0 then
    perform public.append_tournament_audit(
      p_organization_id, 'schedule_conflicts.overridden', 'match', v_match.id,
      null, v_match.tournament_id,
      jsonb_build_object('reason', v_reason, 'warnings', v_validation->'warnings')
    );
  end if;
  perform public.append_tournament_audit(
    p_organization_id, 'match.scheduled', 'match', v_match.id,
    null, v_match.tournament_id,
    jsonb_build_object(
      'scheduledAt', p_scheduled_at, 'venueId', p_venue_id,
      'courtId', p_court_id, 'durationMinutes', p_duration_minutes
    )
  );
  return jsonb_build_object(
    'matchId', v_match.id, 'status', 'scheduled',
    'scheduledAt', p_scheduled_at, 'warnings', v_validation->'warnings'
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.schedule_tournament_match_resumption(p_organization_id uuid, p_match_operation_id uuid, p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_venue_id uuid DEFAULT NULL::uuid, p_court_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_operation public.tournament_match_operations%rowtype;
  v_resumption public.tournament_match_resumptions%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null or v_operation.status <> 'draft'
    or v_operation.match_status <> 'suspended'
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_outcomes.manage'
    )
    or char_length(btrim(coalesce(p_reason, ''))) not between 3 and 1000
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  insert into public.tournament_match_resumptions (
    organization_id, match_operation_id, scheduled_at, venue_id, court_id,
    status, reason, created_by
  ) values (
    p_organization_id, v_operation.id, p_scheduled_at, p_venue_id, p_court_id,
    case when p_scheduled_at is null then 'pending' else 'scheduled' end,
    btrim(p_reason), auth.uid()
  )
  on conflict (match_operation_id) where status in ('pending', 'scheduled')
  do update set
    scheduled_at = excluded.scheduled_at,
    venue_id = excluded.venue_id,
    court_id = excluded.court_id,
    status = excluded.status,
    reason = excluded.reason
  returning * into v_resumption;
  perform public.append_tournament_audit(
    p_organization_id, 'match_operation.resumption_planned',
    'match_resumption', v_resumption.id, null, v_operation.tournament_id,
    jsonb_build_object('status', v_resumption.status)
  );
  return to_jsonb(v_resumption);
end;
$function$

CREATE OR REPLACE FUNCTION public.set_active_tournament_context(p_organization_id uuid, p_season_id uuid, p_tournament_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(
    p_organization_id,
    'workspace.access'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_CONTEXT_FORBIDDEN';
  end if;
  perform 1
  from public.tournament_seasons season
  where season.id = p_season_id
    and season.organization_id = p_organization_id
    and season.status <> 'archived'
  for share;

  if not found then
    raise exception using errcode = '42501', message = 'TORNEOS_CONTEXT_FORBIDDEN';
  end if;

  if p_tournament_id is not null then
    perform 1
    from public.tournaments tournament
    where tournament.id = p_tournament_id
      and tournament.organization_id = p_organization_id
      and tournament.season_id = p_season_id
      and tournament.status <> 'archived'
    for share;

    if not found then
      raise exception using errcode = '42501', message = 'TORNEOS_CONTEXT_FORBIDDEN';
    end if;
  end if;

  insert into public.user_tournament_context_preferences (
    user_id,
    organization_id,
    active_season_id,
    active_tournament_id
  )
  values (v_user_id, p_organization_id, p_season_id, p_tournament_id)
  on conflict (user_id, organization_id) do update
  set active_season_id = excluded.active_season_id,
      active_tournament_id = excluded.active_tournament_id;

  return jsonb_build_object(
    'organizationId', p_organization_id,
    'activeSeasonId', p_season_id,
    'activeTournamentId', p_tournament_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.set_tournament_announcement_audience(p_announcement_id uuid, p_audience_type text, p_category_id uuid DEFAULT NULL::uuid, p_team_entry_id uuid DEFAULT NULL::uuid, p_match_id uuid DEFAULT NULL::uuid, p_specific_user_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_announcement public.tournament_announcements%rowtype;
  v_id uuid;
begin
  select * into v_announcement
  from public.tournament_announcements announcement
  where announcement.id = p_announcement_id
  for update;
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if v_announcement.id is null
    or v_announcement.status not in ('draft','scheduled')
    or not public.has_tournament_communications_capability(
      v_announcement.organization_id,'announcements.update_draft'
    )
    or (
      v_announcement.author_user_id <> auth.uid()
      and not public.has_tournament_communications_capability(
        v_announcement.organization_id,'announcements.publish'
      )
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  if (select count(*) from public.tournament_announcement_audiences audience
      where audience.announcement_id = p_announcement_id) >= 12
  then
    raise exception using errcode = '54000', message = 'TORNEOS_AUDIENCE_LIMIT_REACHED';
  end if;
  if p_audience_type = 'category' and not exists (
    select 1 from public.tournament_categories category
    where category.id = p_category_id
      and category.organization_id = v_announcement.organization_id
      and category.tournament_id = v_announcement.tournament_id
      and category.status = 'active'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_INVALID_AUDIENCE';
  elsif p_audience_type = 'team' and not exists (
    select 1 from public.tournament_team_entries entry
    where entry.id = p_team_entry_id
      and entry.organization_id = v_announcement.organization_id
      and entry.tournament_id = v_announcement.tournament_id
      and entry.status = 'approved'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_INVALID_AUDIENCE';
  elsif p_audience_type in ('match','home_team','away_team') and not exists (
    select 1 from public.tournament_matches match
    join public.tournament_fixture_versions fixture
      on fixture.id = match.fixture_version_id
     and fixture.organization_id = match.organization_id
     and fixture.status = 'published'
    where match.id = p_match_id
      and match.organization_id = v_announcement.organization_id
      and match.tournament_id = v_announcement.tournament_id
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_INVALID_AUDIENCE';
  end if;

  insert into public.tournament_announcement_audiences (
    organization_id,announcement_id,audience_type,category_id,team_entry_id,
    match_id,specific_user_id,created_by
  ) values (
    v_announcement.organization_id,p_announcement_id,p_audience_type,
    p_category_id,p_team_entry_id,p_match_id,p_specific_user_id,auth.uid()
  )
  on conflict on constraint tournament_announcement_audiences_unique
  do update set created_by = excluded.created_by
  returning id into v_id;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_tournament_announcement_link(p_announcement_id uuid, p_link_type text, p_resource_id uuid, p_external_url text, p_label text, p_sort_order integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_announcement public.tournament_announcements%rowtype;
  v_id uuid;
  v_valid boolean := false;
begin
  select * into v_announcement
  from public.tournament_announcements announcement
  where announcement.id = p_announcement_id
  for update;
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if v_announcement.id is null
    or v_announcement.status not in ('draft','scheduled')
    or not public.has_tournament_communications_capability(
      v_announcement.organization_id,'announcements.update_draft'
    )
    or (
      v_announcement.author_user_id <> auth.uid()
      and not public.has_tournament_communications_capability(
        v_announcement.organization_id,'announcements.publish'
      )
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  if (select count(*) from public.tournament_announcement_links link
      where link.announcement_id = p_announcement_id) >= 5
  then
    raise exception using errcode = '54000', message = 'TORNEOS_LINK_LIMIT_REACHED';
  end if;
  if p_link_type = 'external' then
    v_valid := p_external_url ~
      '^https://[A-Za-z0-9.-]+(?::[0-9]{1,5})?(?:/[^[:space:]]*)?$';
  elsif p_link_type = 'tournament' then
    v_valid := p_resource_id = v_announcement.tournament_id;
  elsif p_link_type = 'category' then
    v_valid := exists (
      select 1 from public.tournament_categories category
      where category.id = p_resource_id
        and category.organization_id = v_announcement.organization_id
        and category.tournament_id = v_announcement.tournament_id
        and category.status = 'active'
    );
  elsif p_link_type = 'match' then
    v_valid := exists (
      select 1 from public.tournament_matches match
      join public.tournament_fixture_versions fixture
        on fixture.organization_id = match.organization_id
       and fixture.id = match.fixture_version_id
       and fixture.status = 'published'
      where match.id = p_resource_id
        and match.organization_id = v_announcement.organization_id
        and match.tournament_id = v_announcement.tournament_id
    );
  elsif p_link_type in ('round','standings','discipline') then
    v_valid := p_resource_id = v_announcement.tournament_id;
  elsif p_link_type = 'document' then
    v_valid := exists (
      select 1 from public.tournament_documents document
      where document.id = p_resource_id
        and document.organization_id = v_announcement.organization_id
        and document.tournament_id = v_announcement.tournament_id
        and document.status = 'published'
    );
  end if;
  if not v_valid then
    raise exception using errcode = '42501', message = 'TORNEOS_INVALID_COMMUNICATION_LINK';
  end if;

  insert into public.tournament_announcement_links (
    organization_id,announcement_id,link_type,resource_id,external_url,label,sort_order
  ) values (
    v_announcement.organization_id,p_announcement_id,p_link_type,p_resource_id,
    nullif(btrim(coalesce(p_external_url,'')),''),btrim(p_label),p_sort_order
  )
  on conflict (announcement_id,sort_order) do update
  set link_type = excluded.link_type,resource_id = excluded.resource_id,
    external_url = excluded.external_url,label = excluded.label
  returning id into v_id;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_tournament_branding_reference(p_organization_id uuid, p_entity_kind text, p_entity_id uuid, p_path text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_previous_path text;
  v_tournament_id uuid;
  v_audit_team_id uuid;
  v_expected_folder text;
  v_synced_participant_count integer := 0;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_AUTH_REQUIRED';
  END IF;

  v_expected_folder := CASE p_entity_kind
    WHEN 'organization' THEN 'organizations'
    WHEN 'tournament' THEN 'tournaments'
    WHEN 'team' THEN 'teams'
    ELSE NULL
  END;

  IF v_expected_folder IS NULL OR p_entity_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TORNEOS_BRANDING_INVALID_REFERENCE';
  END IF;

  IF p_path IS NOT NULL AND (
    NOT public.is_tournament_branding_path(p_path, v_expected_folder)
    OR split_part(p_path, '/', 1)::uuid <> p_organization_id
    OR split_part(p_path, '/', 3)::uuid <> p_entity_id
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TORNEOS_BRANDING_INVALID_REFERENCE';
  END IF;

  IF p_entity_kind = 'organization' THEN
    IF p_entity_id <> p_organization_id
      OR NOT public.has_tournament_organization_capability(
        p_organization_id,
        'organization.update'
      )
    THEN
      RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_BRANDING_FORBIDDEN';
    END IF;

    SELECT organization.logo_path
    INTO v_previous_path
    FROM public.tournament_organizations organization
    WHERE organization.id = p_organization_id
      AND organization.status = 'active'
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_BRANDING_FORBIDDEN';
    END IF;

    UPDATE public.tournament_organizations
    SET logo_path = p_path
    WHERE id = p_organization_id;
  ELSIF p_entity_kind = 'tournament' THEN
    IF NOT public.has_tournament_organization_capability(
      p_organization_id,
      'tournaments.update'
    ) THEN
      RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_BRANDING_FORBIDDEN';
    END IF;

    SELECT tournament.logo_path, tournament.id
    INTO v_previous_path, v_tournament_id
    FROM public.tournaments tournament
    WHERE tournament.id = p_entity_id
      AND tournament.organization_id = p_organization_id
      AND tournament.status <> 'archived'
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_BRANDING_FORBIDDEN';
    END IF;

    UPDATE public.tournaments
    SET logo_path = p_path
    WHERE id = p_entity_id;
  ELSE
    IF NOT public.can_update_tournament_team_branding(
      p_organization_id,
      p_entity_id
    ) THEN
      RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_BRANDING_FORBIDDEN';
    END IF;

    SELECT entry.shield_path, entry.tournament_id, entry.id
    INTO v_previous_path, v_tournament_id, v_audit_team_id
    FROM public.tournament_team_entries entry
    WHERE entry.id = p_entity_id
      AND entry.organization_id = p_organization_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_BRANDING_FORBIDDEN';
    END IF;

    UPDATE public.tournament_team_entries
    SET shield_path = p_path
    WHERE id = p_entity_id;

    -- Participant snapshots keep competitive identity frozen (name, colors,
    -- seeding and membership) while projecting the current visual identity.
    -- Existing fixture, standings and public RPCs already render this field.
    UPDATE public.tournament_competition_participants participant
    SET snapshot_shield_path = p_path
    WHERE participant.organization_id = p_organization_id
      AND participant.team_entry_id = p_entity_id;
    GET DIAGNOSTICS v_synced_participant_count = ROW_COUNT;
  END IF;

  PERFORM public.append_tournament_audit(
    p_organization_id,
    'branding.' || p_entity_kind || CASE WHEN p_path IS NULL THEN '.removed' ELSE '.updated' END,
    p_entity_kind || '_branding',
    p_entity_id,
    v_audit_team_id,
    v_tournament_id,
    jsonb_build_object(
      'hadPrevious', v_previous_path IS NOT NULL,
      'hasCurrent', p_path IS NOT NULL,
      'previousPath', v_previous_path,
      'path', p_path,
      'syncedParticipantCount', v_synced_participant_count
    )
  );

  RETURN jsonb_build_object(
    'entityKind', p_entity_kind,
    'entityId', p_entity_id,
    'previousPath', v_previous_path,
    'path', p_path
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.set_tournament_entitlement_override(p_organization_id uuid, p_tournament_id uuid, p_capability text, p_enabled boolean, p_expires_at timestamp with time zone, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_override_id uuid;
BEGIN
  IF p_enabled IS NULL
    OR p_reason IS NULL
    OR btrim(p_reason) <> p_reason
    OR char_length(p_reason) NOT BETWEEN 8 AND 500
    OR (p_expires_at IS NOT NULL AND p_expires_at <= now())
    OR NOT EXISTS (
      SELECT 1 FROM public.tournament_entitlement_capabilities catalog
      WHERE catalog.capability = p_capability
    )
    OR NOT EXISTS (
      SELECT 1 FROM public.tournament_organizations organization
      WHERE organization.id = p_organization_id
    )
  THEN
    RAISE EXCEPTION USING errcode = '22023', message = 'TORNEOS_ENTITLEMENT_OVERRIDE_INVALID';
  END IF;

  IF p_tournament_id IS NULL THEN
    INSERT INTO public.tournament_organization_entitlement_overrides (
      organization_id,capability,enabled,expires_at,reason
    ) VALUES (
      p_organization_id,p_capability,p_enabled,p_expires_at,p_reason
    )
    ON CONFLICT (organization_id,capability) DO UPDATE SET
      enabled = excluded.enabled,
      expires_at = excluded.expires_at,
      reason = excluded.reason
    RETURNING id INTO v_override_id;
  ELSE
    IF NOT EXISTS (
      SELECT 1 FROM public.tournaments tournament
      WHERE tournament.organization_id = p_organization_id
        AND tournament.id = p_tournament_id
    ) THEN
      RAISE EXCEPTION USING errcode = '22023', message = 'TORNEOS_ENTITLEMENT_SCOPE_INVALID';
    END IF;
    INSERT INTO public.tournament_entitlement_overrides (
      organization_id,tournament_id,capability,enabled,expires_at,reason
    ) VALUES (
      p_organization_id,p_tournament_id,p_capability,p_enabled,p_expires_at,p_reason
    )
    ON CONFLICT (organization_id,tournament_id,capability) DO UPDATE SET
      enabled = excluded.enabled,
      expires_at = excluded.expires_at,
      reason = excluded.reason
    RETURNING id INTO v_override_id;
  END IF;

  INSERT INTO public.tournament_audit_log (
    organization_id,actor_user_id,actor_type,action,resource_type,
    resource_id,tournament_id,metadata
  ) VALUES (
    p_organization_id,NULL,'system','entitlement.override_added',
    'entitlement_override',v_override_id,p_tournament_id,
    jsonb_build_object(
      'capability',p_capability,'enabled',p_enabled,
      'expiresAt',p_expires_at,'scope',CASE WHEN p_tournament_id IS NULL
        THEN 'organization' ELSE 'tournament' END
    )
  );
  RETURN v_override_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_tournament_match_score(p_organization_id uuid, p_match_operation_id uuid, p_score jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_operation public.tournament_match_operations%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null or v_operation.status <> 'draft'
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_scores.manage'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if p_score->>'scoreType' in ('administrative', 'walkover')
    and not public.has_tournament_organization_capability(
      p_organization_id, 'match_administrative_results.manage'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  insert into public.tournament_match_scores (
    match_operation_id, organization_id, match_id, home_score, away_score,
    home_score_first_half, away_score_first_half, home_penalties, away_penalties,
    score_type
  ) values (
    v_operation.id, p_organization_id, v_operation.match_id,
    (p_score->>'homeScore')::smallint, (p_score->>'awayScore')::smallint,
    (p_score->>'homeScoreFirstHalf')::smallint,
    (p_score->>'awayScoreFirstHalf')::smallint,
    (p_score->>'homePenalties')::smallint, (p_score->>'awayPenalties')::smallint,
    p_score->>'scoreType'
  )
  on conflict (match_operation_id) do update set
    home_score = excluded.home_score, away_score = excluded.away_score,
    home_score_first_half = excluded.home_score_first_half,
    away_score_first_half = excluded.away_score_first_half,
    home_penalties = excluded.home_penalties, away_penalties = excluded.away_penalties,
    score_type = excluded.score_type, updated_at = now();
  perform public.append_tournament_audit(
    p_organization_id, 'match_operation.score_set', 'match_operation',
    v_operation.id, null, v_operation.tournament_id,
    jsonb_build_object(
      'homeScore', (p_score->>'homeScore')::integer,
      'awayScore', (p_score->>'awayScore')::integer,
      'scoreType', p_score->>'scoreType'
    )
  );
  return public.get_tournament_match_operation_context(p_organization_id, v_operation.id);
end;
$function$

CREATE OR REPLACE FUNCTION public.set_tournament_media_cover(p_gallery_id uuid, p_asset_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_gallery public.tournament_media_galleries%rowtype;
begin
  select * into v_gallery
  from public.tournament_media_galleries where id = p_gallery_id;
  if v_gallery.id is null or not public.has_tournament_media_capability(
    v_gallery.organization_id,'media.set_cover'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_gallery.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_gallery.id::text,1)
  );
  select * into v_gallery
  from public.tournament_media_galleries
  where id = p_gallery_id
  for update;
  if v_gallery.status not in ('draft','under_review') then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_GALLERY_IMMUTABLE';
  end if;
  if not exists (
    select 1 from public.tournament_media_assets asset
    where asset.id = p_asset_id and asset.gallery_id = p_gallery_id
      and asset.status in ('approved','published')
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_COVER_INVALID';
  end if;
  update public.tournament_media_galleries
  set cover_asset_id = p_asset_id,version = version + 1
  where id = p_gallery_id;
  perform public.append_tournament_audit(
    v_gallery.organization_id,'media.gallery.cover_set','media_gallery',
    p_gallery_id,null,v_gallery.tournament_id,jsonb_build_object('assetId',p_asset_id)
  );
  return jsonb_build_object('galleryId',p_gallery_id,'coverAssetId',p_asset_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.set_tournament_player_portrait_crop(p_organization_id uuid, p_portrait_id uuid, p_focal_x numeric, p_focal_y numeric, p_zoom numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_portrait public.tournament_player_portraits%ROWTYPE;
  v_focal_x numeric(5,4);
  v_focal_y numeric(5,4);
  v_zoom numeric(6,4);
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_AUTH_REQUIRED';
  END IF;
  IF p_focal_x IS NULL OR p_focal_y IS NULL
    OR p_focal_x < 0 OR p_focal_x > 1
    OR p_focal_y < 0 OR p_focal_y > 1
  THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TORNEOS_PORTRAIT_FOCAL_INVALID';
  END IF;
  IF p_zoom IS NULL OR p_zoom < 1 OR p_zoom > 4 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TORNEOS_PORTRAIT_ZOOM_INVALID';
  END IF;
  v_focal_x := round(p_focal_x, 4);
  v_focal_y := round(p_focal_y, 4);
  v_zoom := round(p_zoom, 4);

  SELECT * INTO v_portrait FROM public.tournament_player_portraits
  WHERE id = p_portrait_id AND organization_id = p_organization_id
    AND lifecycle_status = 'active' FOR UPDATE;
  IF v_portrait.id IS NULL OR NOT public.can_manage_tournament_player_portrait_as(
    p_organization_id, v_portrait.roster_player_id, auth.uid()
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_PORTRAIT_FORBIDDEN';
  END IF;

  UPDATE public.tournament_player_portraits
  SET focal_x = v_focal_x, focal_y = v_focal_y, crop_zoom = v_zoom, updated_at = now()
  WHERE id = p_portrait_id;

  PERFORM public.append_tournament_audit(
    p_organization_id, 'portrait.crop_updated', 'player_portrait', p_portrait_id,
    v_portrait.team_entry_id, v_portrait.tournament_id,
    jsonb_build_object(
      'rosterPlayerId', v_portrait.roster_player_id,
      'focalX', v_focal_x, 'focalY', v_focal_y, 'cropZoom', v_zoom
    )
  );
  RETURN jsonb_build_object(
    'portraitId', p_portrait_id, 'focalX', v_focal_x, 'focalY', v_focal_y,
    'cropZoom', v_zoom
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.set_tournament_player_portrait_editorial_status(p_organization_id uuid, p_portrait_id uuid, p_editorial_status text)
 RETURNS jsonb
