CREATE OR REPLACE FUNCTION public.set_tournament_public_page_published(p_organization_id uuid, p_tournament_id uuid, p_published boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_tournament public.tournaments%ROWTYPE;
  v_organization public.tournament_organizations%ROWTYPE;
  v_season public.tournament_seasons%ROWTYPE;
  v_page public.tournament_public_pages%ROWTYPE;
  v_candidate text;
  v_prefix text;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_AUTH_REQUIRED';
  END IF;
  IF p_published IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TORNEOS_PUBLIC_PAGE_INVALID_STATE';
  END IF;
  IF NOT public.has_tournament_organization_capability(
    p_organization_id,
    'tournaments.update'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_PUBLIC_PAGE_FORBIDDEN';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_tournament_id::text, 20260810)
  );

  SELECT tournament.*
  INTO v_tournament
  FROM public.tournaments tournament
  WHERE tournament.id = p_tournament_id
    AND tournament.organization_id = p_organization_id
  FOR UPDATE;
  IF v_tournament.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_PUBLIC_PAGE_FORBIDDEN';
  END IF;

  SELECT organization.* INTO v_organization
  FROM public.tournament_organizations organization
  WHERE organization.id = p_organization_id;
  SELECT season.* INTO v_season
  FROM public.tournament_seasons season
  WHERE season.id = v_tournament.season_id
    AND season.organization_id = p_organization_id;

  IF p_published AND (
    v_organization.status <> 'active'
    OR v_season.status = 'archived'
    OR v_tournament.status NOT IN ('registration', 'scheduled', 'active', 'completed')
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'TORNEOS_PUBLIC_PAGE_NOT_PUBLISHABLE';
  END IF;

  SELECT page.*
  INTO v_page
  FROM public.tournament_public_pages page
  WHERE page.tournament_id = p_tournament_id
    AND page.organization_id = p_organization_id
  FOR UPDATE;

  IF p_published THEN
    IF v_page.tournament_id IS NULL THEN
      v_prefix := regexp_replace(
        left(v_organization.slug || '-' || v_tournament.slug, 82),
        '-+$',
        ''
      );
      LOOP
        v_candidate := v_prefix || '-' || left(
          replace(gen_random_uuid()::text, '-', ''),
          10
        );
        EXIT WHEN NOT EXISTS (
          SELECT 1
          FROM public.tournament_public_pages candidate
          WHERE candidate.public_slug = v_candidate
        );
      END LOOP;

      INSERT INTO public.tournament_public_pages (
        tournament_id,
        organization_id,
        public_slug,
        status,
        published_by,
        published_at
      ) VALUES (
        p_tournament_id,
        p_organization_id,
        v_candidate,
        'published',
        v_actor,
        now()
      )
      RETURNING * INTO v_page;
    ELSE
      UPDATE public.tournament_public_pages
      SET status = 'published',
          published_by = v_actor,
          published_at = now(),
          unpublished_by = NULL,
          unpublished_at = NULL,
          updated_at = now()
      WHERE tournament_id = p_tournament_id
      RETURNING * INTO v_page;
    END IF;
  ELSIF v_page.tournament_id IS NOT NULL THEN
    UPDATE public.tournament_public_pages
    SET status = 'unpublished',
        unpublished_by = v_actor,
        unpublished_at = now(),
        updated_at = now()
    WHERE tournament_id = p_tournament_id
    RETURNING * INTO v_page;
  END IF;

  IF v_page.tournament_id IS NOT NULL THEN
    PERFORM public.append_tournament_audit(
      p_organization_id,
      CASE WHEN p_published THEN 'public_page.published' ELSE 'public_page.unpublished' END,
      'tournament_public_page',
      p_tournament_id,
      NULL,
      p_tournament_id,
      jsonb_build_object('published', p_published)
    );
  END IF;

  RETURN public.get_tournament_public_page_settings(
    p_organization_id,
    p_tournament_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.set_tournament_social_permission(p_organization_id uuid, p_user_id uuid, p_can_export boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_role text;
begin
  if not public.has_tournament_social_capability(
    p_organization_id, 'social.manage_permissions'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_SOCIAL_FORBIDDEN';
  end if;
  select membership.role into v_role
  from public.tournament_organization_members membership
  where membership.organization_id = p_organization_id
    and membership.user_id = p_user_id
    and membership.status = 'active';
  if v_role is distinct from 'collaborator' then
    -- Owners and admins already hold everything; nobody else is a member.
    raise exception using errcode = '22023', message = 'TORNEOS_SOCIAL_GRANT_INVALID';
  end if;
  insert into public.tournament_social_permissions (
    organization_id, user_id, can_export, granted_by
  ) values (
    p_organization_id, p_user_id, coalesce(p_can_export, false), auth.uid()
  ) on conflict (organization_id, user_id) do update set
    can_export = excluded.can_export,
    granted_by = excluded.granted_by,
    updated_at = now();
  perform public.append_tournament_audit(
    p_organization_id,
    case when coalesce(p_can_export, false)
      then 'social.export.granted' else 'social.export.revoked' end,
    'organization_member', p_user_id, null, null, '{}'::jsonb
  );
  return jsonb_build_object(
    'organizationId', p_organization_id, 'userId', p_user_id,
    'canExport', coalesce(p_can_export, false)
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.set_tournament_team_photo_editorial_status(p_organization_id uuid, p_team_photo_id uuid, p_editorial_status text, p_review_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_photo public.tournament_team_photos%ROWTYPE;
  v_reason text := nullif(btrim(coalesce(p_review_reason, '')), '');
  v_previous_current_id uuid;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_AUTH_REQUIRED';
  END IF;
  IF p_editorial_status NOT IN ('approved', 'rejected')
    OR (p_editorial_status = 'approved' AND v_reason IS NOT NULL)
    OR (v_reason IS NOT NULL AND char_length(v_reason) > 500)
  THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TORNEOS_TEAM_PHOTO_STATE_INVALID';
  END IF;

  SELECT * INTO v_photo
  FROM public.tournament_team_photos photo
  WHERE photo.id = p_team_photo_id
    AND photo.organization_id = p_organization_id
    AND photo.lifecycle_status = 'active'
    AND photo.editorial_status = 'pending_review'
  FOR UPDATE;
  -- Una fila que no existe, que ya tiene veredicto o que está en otro estado no
  -- se distingue de una prohibida: las dos respuestas son la misma puerta
  -- cerrada, y separarlas sería contar qué hay del otro lado.
  IF v_photo.id IS NULL OR NOT public.can_moderate_tournament_team_visual_assets_as(
    p_organization_id, v_photo.team_entry_id, auth.uid(), 'team_entries.update'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_TEAM_PHOTO_FORBIDDEN';
  END IF;

  PERFORM 1 FROM public.tournament_team_entries entry
  WHERE entry.id = v_photo.team_entry_id FOR UPDATE;

  IF p_editorial_status = 'approved' THEN
    SELECT photo.id INTO v_previous_current_id
    FROM public.tournament_team_photos photo
    WHERE photo.team_entry_id = v_photo.team_entry_id
      AND photo.lifecycle_status = 'active'
      AND photo.editorial_status = 'approved'
    FOR UPDATE;

    IF v_previous_current_id IS NOT NULL THEN
      UPDATE public.tournament_team_photos
      SET lifecycle_status = 'replaced', replaced_by_id = v_photo.id,
          replaced_at = now(), updated_at = now()
      WHERE id = v_previous_current_id;
    END IF;

    UPDATE public.tournament_team_photos
    SET editorial_status = 'approved', reviewed_by = auth.uid(),
        reviewed_at = now(), approved_at = now(), updated_at = now()
    WHERE id = p_team_photo_id;
  ELSE
    UPDATE public.tournament_team_photos
    SET editorial_status = 'rejected', reviewed_by = auth.uid(),
        reviewed_at = now(), review_reason = v_reason, updated_at = now()
    WHERE id = p_team_photo_id;
  END IF;

  PERFORM public.append_tournament_audit(
    p_organization_id,
    CASE WHEN p_editorial_status = 'approved'
      THEN 'team_photo.approved' ELSE 'team_photo.rejected' END,
    'team_photo', p_team_photo_id, v_photo.team_entry_id, v_photo.tournament_id,
    jsonb_build_object(
      'editorialStatus', p_editorial_status,
      'reviewReason', v_reason,
      'replacedTeamPhotoId', v_previous_current_id
    )
  );

  RETURN jsonb_build_object(
    'teamPhotoId', p_team_photo_id,
    'editorialStatus', p_editorial_status,
    'reviewReason', v_reason,
    'replacedTeamPhotoId', v_previous_current_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.set_tournament_team_visual_policy(p_organization_id uuid, p_tournament_id uuid, p_policy text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_previous_policy text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_AUTH_REQUIRED';
  END IF;
  IF p_policy IS NULL OR p_policy NOT IN (
    'organization_only', 'delegates', 'roster'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TORNEOS_VISUAL_POLICY_INVALID';
  END IF;
  IF NOT public.has_tournament_organization_capability(
    p_organization_id, 'tournaments.update'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_VISUAL_POLICY_FORBIDDEN';
  END IF;

  SELECT tournament.team_visual_management_policy
  INTO v_previous_policy
  FROM public.tournaments tournament
  WHERE tournament.id = p_tournament_id
    AND tournament.organization_id = p_organization_id
    AND tournament.status <> 'archived'
  FOR UPDATE;

  IF v_previous_policy IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_VISUAL_POLICY_FORBIDDEN';
  END IF;

  IF v_previous_policy IS DISTINCT FROM p_policy THEN
    UPDATE public.tournaments
    SET team_visual_management_policy = p_policy
    WHERE id = p_tournament_id;

    -- Auditoría por el mecanismo existente: actor y timestamp los pone
    -- append_tournament_audit, el antes y el después viajan en la metadata.
    PERFORM public.append_tournament_audit(
      p_organization_id,
      'tournament.team_visual_policy_updated',
      'tournament_team_visual_policy',
      p_tournament_id,
      NULL,
      p_tournament_id,
      jsonb_build_object(
        'previousPolicy', v_previous_policy,
        'policy', p_policy
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'organizationId', p_organization_id,
    'tournamentId', p_tournament_id,
    'previousPolicy', v_previous_policy,
    'policy', p_policy,
    'canUpdate', true
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.set_tournament_workspace_preference(p_workspace_type text, p_organization_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'TORNEOS_AUTH_REQUIRED';
  end if;

  if p_workspace_type = 'personal' then
    if p_organization_id is not null then
      raise exception using
        errcode = '22023',
        message = 'TORNEOS_INVALID_WORKSPACE';
    end if;
  elsif p_workspace_type = 'tournament_organization' then
    if p_organization_id is null
      or not public.has_tournament_organization_capability(
        p_organization_id,
        'workspace.access'
      )
    then
      raise exception using
        errcode = '42501',
        message = 'TORNEOS_WORKSPACE_FORBIDDEN';
    end if;
  else
    raise exception using
      errcode = '22023',
      message = 'TORNEOS_INVALID_WORKSPACE';
  end if;

  insert into public.user_workspace_preferences (
    user_id,
    workspace_type,
    active_organization_id
  )
  values (
    v_user_id,
    p_workspace_type,
    p_organization_id
  )
  on conflict (user_id) do update
  set workspace_type = excluded.workspace_type,
      active_organization_id = excluded.active_organization_id;

  return jsonb_build_object(
    'workspaceType', p_workspace_type,
    'activeOrganizationId', p_organization_id
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.start_tournament_competition(p_organization_id uuid, p_tournament_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tournament public.tournaments%rowtype;
  v_active_categories integer;
  v_categories_without_fixture integer;
  v_unscheduled integer;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(
    p_organization_id, 'tournaments.start'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:competition-lifecycle:' || p_tournament_id::text, 0
  ));

  select tournament.* into v_tournament
  from public.tournaments tournament
  join public.tournament_organizations organization
    on organization.id = tournament.organization_id
    and organization.status = 'active'
  where tournament.id = p_tournament_id
    and tournament.organization_id = p_organization_id
  for update of tournament;

  if v_tournament.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  if v_tournament.status = 'active' then
    -- Idempotencia: repetir la operación sobre una competencia ya En juego no
    -- es un error y no reescribe `started_at`.
    return jsonb_build_object(
      'id', v_tournament.id,
      'status', v_tournament.status,
      'startedAt', v_tournament.started_at,
      'alreadyStarted', true,
      'unscheduledMatches', (
        select count(*)
        from public.tournament_matches match_row
        join public.tournament_fixture_versions fixture
          on fixture.id = match_row.fixture_version_id
          and fixture.status = 'published'
          and fixture.invalidated_at is null
        where match_row.tournament_id = v_tournament.id
          and match_row.scheduled_at is null
          and match_row.status <> 'cancelled'
      )
    );
  end if;

  if v_tournament.status <> 'scheduled' then
    raise exception using errcode = '22023',
      message = 'TORNEOS_INVALID_TOURNAMENT_TRANSITION';
  end if;

  select count(*) into v_active_categories
  from public.tournament_categories category
  where category.organization_id = p_organization_id
    and category.tournament_id = p_tournament_id
    and category.status = 'active';

  if v_active_categories = 0 then
    raise exception using errcode = '23514',
      message = 'TORNEOS_COMPETITION_WITHOUT_CATEGORIES';
  end if;

  select count(*) into v_categories_without_fixture
  from public.tournament_categories category
  where category.organization_id = p_organization_id
    and category.tournament_id = p_tournament_id
    and category.status = 'active'
    and not exists (
      select 1
      from public.tournament_fixture_versions fixture
      where fixture.organization_id = category.organization_id
        and fixture.tournament_id = category.tournament_id
        and fixture.category_id = category.id
        and fixture.status = 'published'
        and fixture.invalidated_at is null
    );

  if v_categories_without_fixture > 0 then
    raise exception using errcode = '23514',
      message = 'TORNEOS_COMPETITION_FIXTURE_NOT_PUBLISHED';
  end if;

  -- Los partidos sin horario no impiden comenzar: se programan después.
  select count(*) into v_unscheduled
  from public.tournament_matches match_row
  join public.tournament_fixture_versions fixture
    on fixture.id = match_row.fixture_version_id
    and fixture.status = 'published'
    and fixture.invalidated_at is null
  where match_row.tournament_id = p_tournament_id
    and match_row.scheduled_at is null
    and match_row.status <> 'cancelled';

  update public.tournaments
  set status = 'active',
      started_at = now()
  where id = p_tournament_id
  returning * into v_tournament;

  perform public.append_tournament_audit(
    p_organization_id, 'tournament.started', 'tournament', v_tournament.id,
    null, v_tournament.id,
    jsonb_build_object(
      'previousStatus', 'scheduled',
      'nextStatus', 'active',
      'activeCategories', v_active_categories,
      'unscheduledMatches', v_unscheduled
    )
  );

  return jsonb_build_object(
    'id', v_tournament.id,
    'status', v_tournament.status,
    'startedAt', v_tournament.started_at,
    'alreadyStarted', false,
    'unscheduledMatches', v_unscheduled
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_match_squad(p_organization_id uuid, p_match_id uuid, p_team_entry_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_squad public.tournament_match_squads%rowtype;
  v_match public.tournament_matches%rowtype;
  v_team_size integer;
  v_substitutes_limit integer;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_match from public.tournament_matches
  where id = p_match_id and organization_id = p_organization_id for update;
  select * into v_squad from public.tournament_match_squads
  where match_id = p_match_id and team_entry_id = p_team_entry_id
    and status = 'draft' for update;
  if v_match.id is null or v_match.status not in ('scheduled', 'ready')
    or v_squad.id is null
    or not public.can_manage_tournament_match_squad(
      p_organization_id, p_match_id, p_team_entry_id
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournament_match_operations operation
    where operation.match_id = p_match_id
      and operation.status not in ('superseded', 'voided')
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_MATCH_OPERATION_ACTIVE';
  end if;
  select coalesce(category.team_size, tournament.team_size),
    coalesce(tournament.substitutes_limit, tournament.team_size)
  into v_team_size, v_substitutes_limit
  from public.tournament_categories category
  join public.tournaments tournament on tournament.id = category.tournament_id
  where category.id = v_match.category_id;
  if (select count(*) from public.tournament_match_squad_players
      where match_squad_id = v_squad.id and lineup_status = 'starter') <> v_team_size
    or (select count(*) from public.tournament_match_squad_players
      where match_squad_id = v_squad.id and callup_status = 'called_up' and is_captain) <> 1
    or (select count(*) from public.tournament_match_squad_players
      where match_squad_id = v_squad.id and callup_status = 'called_up')
      > v_team_size + v_substitutes_limit
    or (select count(*) from public.tournament_match_squad_players
      where match_squad_id = v_squad.id and lineup_status = 'starter'
        and is_goalkeeper) < 1
    or (select count(*) from public.tournament_match_squad_players
      where match_squad_id = v_squad.id and lineup_status = 'starter'
        and is_captain) <> 1
    or exists (
      select 1
      from public.tournament_match_squad_players player
      where player.match_squad_id = v_squad.id
        and (
          player.lineup_status = 'starter'
          or player.is_captain
        )
        and player.attendance_status in ('absent', 'excused')
    )
  then
    raise exception using errcode = '23514', message = 'TORNEOS_INVALID_MATCH_SQUAD';
  end if;
  update public.tournament_match_squads set
    status = 'submitted', submitted_by = auth.uid(), submitted_at = now(), updated_at = now()
  where id = v_squad.id returning * into v_squad;
  perform public.append_tournament_audit(
    p_organization_id, 'match_squad.submitted', 'match_squad', v_squad.id,
    p_team_entry_id, v_match.tournament_id, '{}'::jsonb
  );
  return public.get_match_squad_context(p_organization_id, p_match_id, p_team_entry_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_tournament_match_operation(p_organization_id uuid, p_match_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_operation public.tournament_match_operations%rowtype;
  v_validation jsonb;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null or v_operation.status <> 'draft'
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_operations.submit'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  v_validation := public.validate_tournament_match_operation_payload(v_operation.id);
  if not (v_validation->>'valid')::boolean then
    raise exception using errcode = '23514',
      message = 'TORNEOS_MATCH_OPERATION_INVALID',
      detail = v_validation->'errors'::text;
  end if;
  update public.tournament_match_operations set
    status = 'submitted', match_status = 'awaiting_validation',
    submitted_by = auth.uid(), submitted_at = now(), updated_at = now()
  where id = v_operation.id;
  insert into public.tournament_match_reviews (
    organization_id, match_operation_id, review_type, reason, requested_by
  ) values (
    p_organization_id, v_operation.id, 'validation',
    'Acta presentada para validación', auth.uid()
  );
  perform public.append_tournament_audit(
    p_organization_id, 'match_operation.submitted', 'match_operation',
    v_operation.id, null, v_operation.tournament_id,
    jsonb_build_object('operationVersion', v_operation.operation_version)
  );
  return public.get_tournament_match_operation_context(p_organization_id, v_operation.id);
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_tournament_team_entry(p_organization_id uuid, p_team_entry_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_entry public.tournament_team_entries%rowtype;
  v_roster public.tournament_rosters%rowtype;
  v_validation jsonb;
begin
  select * into v_entry from public.tournament_team_entries
  where id = p_team_entry_id and organization_id = p_organization_id for update;
  select * into v_roster from public.tournament_rosters
  where team_entry_id = p_team_entry_id and status in ('draft', 'changes_requested')
  order by version desc limit 1 for update;
  if v_entry.id is null or v_entry.status not in ('in_progress', 'changes_requested')
    or not public.can_edit_tournament_team_entry(
      p_organization_id,
      p_team_entry_id
    )
  then raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN'; end if;
  if not exists (
    select 1 from public.tournament_team_managers
    where team_entry_id = p_team_entry_id and status = 'active'
  ) then raise exception using errcode = '23514', message = 'TORNEOS_MANAGER_REQUIRED'; end if;
  v_validation := public.validate_tournament_roster(p_organization_id, p_team_entry_id, v_roster.id);
  if not (v_validation->>'valid')::boolean then
    raise exception using errcode = '23514', message = 'TORNEOS_ROSTER_INCOMPLETE',
      detail = v_validation::text;
  end if;
  update public.tournament_rosters set status = 'submitted', submitted_at = now()
  where id = v_roster.id returning * into v_roster;
  update public.tournament_team_entries set
    status = 'submitted', submitted_by = auth.uid(), submitted_at = now(),
    reviewed_by = null, reviewed_at = null, rejected_at = null
  where id = v_entry.id returning * into v_entry;
  perform public.append_tournament_audit(
    p_organization_id, 'team_entry.submitted', 'team_entry', v_entry.id,
    v_entry.id, v_entry.tournament_id,
    jsonb_build_object('rosterId', v_roster.id, 'version', v_roster.version)
  );
  return jsonb_build_object('entryId', v_entry.id, 'rosterId', v_roster.id, 'status', v_entry.status, 'validation', v_validation);
end;
$function$

CREATE OR REPLACE FUNCTION public.supersede_tournament_fixture(p_organization_id uuid, p_fixture_version_id uuid, p_idempotency_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_version public.tournament_fixture_versions%rowtype;
begin
  if auth.uid() is null
    or not public.has_tournament_organization_capability(
      p_organization_id, 'fixture.supersede'
