CREATE OR REPLACE FUNCTION public.tournament_media_attestation_rejection(p_service text, p_capabilities jsonb, p_ttl_seconds integer)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_allowed text[] := public.tournament_media_capability_allowlist(p_service);
  v_caps jsonb;
  v_evidence jsonb;
  v_self_test jsonb;
  v_checks jsonb;
  v_key text;
  v_probed_at timestamp with time zone;
  v_signatures_at timestamp with time zone;
  v_max_ttl integer := case p_service when 'processor' then 900 else 3600 end;
begin
  if v_allowed is null then
    return 'service_unknown';
  end if;
  if p_ttl_seconds is null or p_ttl_seconds < 60 or p_ttl_seconds > v_max_ttl then
    return 'ttl_out_of_range';
  end if;
  if jsonb_typeof(coalesce(p_capabilities,'null'::jsonb)) <> 'object' then
    return 'payload_not_object';
  end if;
  -- No stray top-level keys: the envelope is exactly two members.
  if exists (
    select 1 from jsonb_object_keys(p_capabilities) as envelope_key
    where envelope_key not in ('capabilities','evidence')
  ) then
    return 'envelope_unknown_key';
  end if;

  v_caps := p_capabilities -> 'capabilities';
  v_evidence := p_capabilities -> 'evidence';
  if jsonb_typeof(coalesce(v_caps,'null'::jsonb)) <> 'object'
    or jsonb_typeof(coalesce(v_evidence,'null'::jsonb)) <> 'object'
  then
    return 'envelope_incomplete';
  end if;

  -- Capabilities: allowlisted names, boolean values, nothing else.
  for v_key in select capability_key from jsonb_object_keys(v_caps) as capability_key loop
    if not (v_key = any (v_allowed)) then
      return 'capability_not_allowlisted:' || v_key;
    end if;
    if jsonb_typeof(v_caps -> v_key) <> 'boolean' then
      return 'capability_not_boolean:' || v_key;
    end if;
  end loop;

  -- Backend binding.
  if coalesce(v_evidence->>'backendFingerprint','')
    <> public.tournament_media_backend_fingerprint()
  then
    return 'backend_fingerprint_mismatch';
  end if;

  -- Freshness of the probe itself, independent of the row's own expiry.
  begin
    v_probed_at := (v_evidence->>'probedAt')::timestamp with time zone;
  exception when others then
    v_probed_at := null;
  end;
  if v_probed_at is null
    or v_probed_at > now() + interval '2 minutes'
    or v_probed_at < now() - interval '10 minutes'
  then
    return 'probe_stale';
  end if;

  -- Self-test: it has to exist, it has to have passed, and every capability
  -- claimed true has to name a check that also passed.
  v_self_test := v_evidence -> 'selfTest';
  if jsonb_typeof(coalesce(v_self_test,'null'::jsonb)) <> 'object'
    or coalesce((v_self_test->>'passed')::boolean, false) is not true
  then
    return 'self_test_absent';
  end if;
  v_checks := v_self_test -> 'checks';
  if jsonb_typeof(coalesce(v_checks,'null'::jsonb)) <> 'object' then
    return 'self_test_checks_absent';
  end if;
  for v_key in
    select capability_key from jsonb_object_keys(v_caps) as capability_key
    where coalesce((v_caps ->> capability_key)::boolean, false)
  loop
    if coalesce((v_checks ->> v_key)::boolean, false) is not true then
      return 'self_test_missing_check:' || v_key;
    end if;
  end loop;

  if p_service = 'processor' then
    if not (coalesce(v_evidence->>'workerType','')
      = any (public.tournament_media_worker_type_allowlist()))
    then
      return 'worker_type_not_allowlisted';
    end if;
    -- A pixel tier without a named, versioned codec is a claim, not evidence.
    if coalesce((v_caps->>'pixelDecode')::boolean, false)
      or coalesce((v_caps->>'pixelTranscode')::boolean, false)
    then
      if coalesce(v_evidence#>>'{codec,name}','') !~ '^[a-z0-9][a-z0-9._+-]{1,40}$'
        or coalesce(v_evidence#>>'{codec,version}','') !~ '^[0-9][0-9a-zA-Z._+-]{0,30}$'
      then
        return 'codec_evidence_absent';
      end if;
    end if;
    if coalesce((v_caps->>'antivirusScanning')::boolean, false) then
      if coalesce(v_evidence#>>'{antivirus,name}','') !~ '^[a-z0-9][a-z0-9._+-]{1,40}$'
        or coalesce(v_evidence#>>'{antivirus,version}','') !~ '^[0-9][0-9a-zA-Z._+-]{0,30}$'
      then
        return 'antivirus_evidence_absent';
      end if;
      begin
        v_signatures_at := (v_evidence#>>'{antivirus,signaturesAt}')::timestamp with time zone;
      exception when others then
        v_signatures_at := null;
      end;
      -- Definitions older than a week are treated as no antivirus at all.
      if v_signatures_at is null
        or v_signatures_at > now() + interval '1 day'
        or v_signatures_at < now() - interval '7 days'
      then
        return 'antivirus_signatures_stale';
      end if;
    end if;
  end if;

  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.tournament_media_effective_readiness()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_mode text := public.tournament_media_current_pipeline_mode();
  v_robust jsonb;
  v_storage jsonb := public.tournament_media_storage_contract_status();
  v_storage_ready boolean;
  v_simple_contract boolean;
  v_ready boolean := false;
  v_blockers jsonb := '[]'::jsonb;
BEGIN
  v_storage_ready :=
    coalesce((v_storage->>'bucketPresent')::boolean,false)
    AND coalesce((v_storage->>'bucketPrivate')::boolean,false)
    AND coalesce((v_storage->>'publicUrlDisabled')::boolean,false)
    AND coalesce((v_storage->>'servicePoliciesPresent')::boolean,false)
    AND coalesce((v_storage->>'clientWriteBlocked')::boolean,false);

  v_simple_contract :=
    pg_catalog.to_regprocedure(
      'public.request_tournament_media_upload_session(uuid,text,text,bigint,uuid)'
    ) IS NOT NULL
    AND pg_catalog.to_regprocedure(
      'public.tournament_media_require_upload_tier(text)'
    ) IS NOT NULL
    AND pg_catalog.to_regprocedure(
      'public.tournament_media_mvp_user_can_upload(uuid,uuid)'
    ) IS NOT NULL
    AND pg_catalog.to_regprocedure(
      'public.authorize_tournament_media_upload_target(uuid,text,uuid)'
    ) IS NOT NULL
    AND pg_catalog.to_regprocedure(
      'public.complete_tournament_media_simple_upload(uuid,uuid,text,text,bigint,integer,integer,text,boolean)'
    ) IS NOT NULL
    AND pg_catalog.to_regprocedure(
      'public.fail_tournament_media_upload_session(uuid,text)'
    ) IS NOT NULL;

  IF v_mode = 'PROCESSOR_EXTERNAL' THEN
    v_robust := public.tournament_media_pipeline_readiness();
    RETURN v_robust || jsonb_build_object(
      'mode',v_mode,'processingTier','processor_external',
      'maxSelectedFileBytes',50331648,'maxConcurrentUploads',3,
      'maxEdge',12000,'allowHeicTranscode',true
    );
  ELSIF v_mode = 'MVP_SIMPLE' THEN
    v_ready := v_storage_ready AND v_simple_contract;
    IF NOT coalesce((v_storage->>'bucketPresent')::boolean,false) THEN
      v_blockers := v_blockers || '"storage.bucket_absent"'::jsonb;
    ELSIF NOT coalesce((v_storage->>'bucketPrivate')::boolean,false) THEN
      v_blockers := v_blockers || '"storage.bucket_public"'::jsonb;
    END IF;
    IF NOT coalesce((v_storage->>'servicePoliciesPresent')::boolean,false) THEN
      v_blockers := v_blockers || '"storage.service_policies_absent"'::jsonb;
    END IF;
    IF NOT coalesce((v_storage->>'clientWriteBlocked')::boolean,false) THEN
      v_blockers := v_blockers || '"storage.client_write_open"'::jsonb;
    END IF;
    IF NOT v_simple_contract THEN
      v_blockers := v_blockers || '"simple.contract_absent"'::jsonb;
    END IF;
    RETURN jsonb_build_object(
      'mode',v_mode,'processingTier','mvp_simple',
      'bucket','tournament-media',
      'private',coalesce((v_storage->>'bucketPrivate')::boolean,false),
      'uploadReady',v_ready,
      'storageReady',v_storage_ready,
      'simpleContractReady',v_simple_contract,
      'signerReady',null,'processorReady',null,
      'blockers',v_blockers,
      'storage',v_storage,
      'maxSelectedFileBytes',8388608,'maxFileBytes',4194304,
      'maxPixels',2560000,'maxEdge',1600,
      'maxBatchFiles',10,'maxConcurrentUploads',2,
      'signedUrlTtlSeconds',300,'allowHeicTranscode',false,
      -- These are honest reduced-tier claims, not attestations.
      'pixelTranscode',false,'antivirusScanning',false
    );
  END IF;
  RETURN jsonb_build_object(
    'mode','DISABLED','processingTier',null,
    'bucket','tournament-media','private',true,'uploadReady',false,
    'blockers',jsonb_build_array('pipeline.disabled'),
    'maxSelectedFileBytes',8388608,'maxFileBytes',4194304,
    'maxPixels',2560000,'maxEdge',1600,
    'maxBatchFiles',10,'maxConcurrentUploads',2,
    'signedUrlTtlSeconds',300,'allowHeicTranscode',false,
    'pixelTranscode',false,'antivirusScanning',false
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.tournament_media_pipeline_readiness()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_storage jsonb := public.tournament_media_storage_contract_status();
  v_signer public.tournament_media_service_attestations%rowtype;
  v_processor public.tournament_media_service_attestations%rowtype;
  v_signer_caps jsonb := '{}'::jsonb;
  v_processor_caps jsonb := '{}'::jsonb;
  v_processor_evidence jsonb := '{}'::jsonb;
  v_processor_present boolean;
  v_storage_ready boolean;
  v_signer_ready boolean;
  v_processor_ready boolean;
  v_pixel_decode boolean;
  v_pixel_transcode boolean;
  v_metadata boolean;
  v_antivirus boolean;
  v_cleanup boolean;
  v_cleanup_contract boolean;
  v_upload_ready boolean;
  v_blockers text[] := array[]::text[];
begin
  select * into v_signer
  from public.tournament_media_service_attestations
  where service = 'signer' and expires_at > now();
  select * into v_processor
  from public.tournament_media_service_attestations
  where service = 'processor' and expires_at > now();

  if v_signer.service is not null then
    v_signer_caps := coalesce(v_signer.capabilities -> 'capabilities', '{}'::jsonb);
  end if;
  v_processor_present := v_processor.service is not null;
  if v_processor_present then
    v_processor_caps := coalesce(v_processor.capabilities -> 'capabilities', '{}'::jsonb);
    v_processor_evidence := coalesce(v_processor.capabilities -> 'evidence', '{}'::jsonb);
  end if;

  v_storage_ready := (v_storage->>'bucketPresent')::boolean
    and (v_storage->>'bucketPrivate')::boolean
    and (v_storage->>'publicUrlDisabled')::boolean
    and (v_storage->>'servicePoliciesPresent')::boolean
    and (v_storage->>'clientWriteBlocked')::boolean;

  v_signer_ready := v_signer.service is not null
    and coalesce((v_signer_caps->>'signedUploadUrls')::boolean, false)
    and coalesce((v_signer_caps->>'signedReadUrls')::boolean, false)
    and coalesce((v_signer_caps->>'derivesPathServerSide')::boolean, false);

  -- Baseline processor duties. The pixel, metadata and antivirus tiers are
  -- separate gates below; none of them may be inferred from this one.
  v_processor_ready := v_processor_present
    and coalesce((v_processor_caps->>'contentSniffing')::boolean, false)
    and coalesce((v_processor_caps->>'checksumVerification')::boolean, false)
    and coalesce((v_processor_caps->>'variantGeneration')::boolean, false)
    and coalesce((v_processor_caps->>'storageReadWrite')::boolean, false)
    and coalesce(v_processor_evidence->>'workerType','')
      = any (public.tournament_media_worker_type_allowlist());

  v_pixel_decode := v_processor_present
    and coalesce((v_processor_caps->>'pixelDecode')::boolean, false);
  v_pixel_transcode := v_processor_present
    and coalesce((v_processor_caps->>'pixelTranscode')::boolean, false);
  v_metadata := v_processor_present
    and coalesce((v_processor_caps->>'metadataStrippingApplied')::boolean, false);
  v_antivirus := v_processor_present
    and coalesce((v_processor_caps->>'antivirusScanning')::boolean, false);

  -- Cleanup needs both halves: the sweeping contracts have to exist in this
  -- database, and the worker has to say it can execute them.
  v_cleanup_contract :=
    pg_catalog.to_regprocedure('public.cleanup_tournament_media_upload_sessions(integer)') is not null
    and pg_catalog.to_regprocedure('public.cleanup_tournament_media_processing_jobs(integer)') is not null;
  v_cleanup := v_cleanup_contract
    and v_processor_present
    and coalesce((v_processor_caps->>'cleanup')::boolean, false);

  if not (v_storage->>'bucketPresent')::boolean then
    v_blockers := v_blockers || 'storage.bucket_absent'::text;
  elsif not (v_storage->>'bucketPrivate')::boolean then
    v_blockers := v_blockers || 'storage.bucket_public'::text;
  end if;
  if not (v_storage->>'servicePoliciesPresent')::boolean then
    v_blockers := v_blockers || 'storage.service_policies_absent'::text;
  end if;
  if not (v_storage->>'clientWriteBlocked')::boolean then
    v_blockers := v_blockers || 'storage.client_write_open'::text;
  end if;
  if not v_signer_ready then
    v_blockers := v_blockers || 'service.signer_unattested'::text;
  end if;
  if not v_processor_ready then
    v_blockers := v_blockers || 'service.processor_unattested'::text;
  end if;
  if not v_pixel_decode then
    v_blockers := v_blockers || 'processor.pixel_decode_absent'::text;
  end if;
  if not v_pixel_transcode then
    v_blockers := v_blockers || 'processor.pixel_transcode_absent'::text;
  end if;
  if not v_metadata then
    v_blockers := v_blockers || 'processor.metadata_sanitization_absent'::text;
  end if;
  if not v_antivirus then
    v_blockers := v_blockers || 'processor.antivirus_absent'::text;
  end if;
  if not v_cleanup then
    v_blockers := v_blockers || 'cleanup.unavailable'::text;
  end if;

  v_upload_ready := v_storage_ready and v_signer_ready and v_processor_ready
    and v_pixel_decode and v_pixel_transcode and v_metadata
    and v_antivirus and v_cleanup;

  return jsonb_build_object(
    'bucket','tournament-media',
    'private',true,
    'uploadReady',v_upload_ready,
    'storageReady',v_storage_ready,
    'signerReady',v_signer_ready,
    'processorReady',v_processor_ready,
    'pixelDecodeReady',v_pixel_decode,
    'pixelTranscodeReady',v_pixel_transcode,
    'metadataSanitizationReady',v_metadata,
    'antivirusReady',v_antivirus,
    'cleanupReady',v_cleanup,
    'blockers',to_jsonb(v_blockers),
    'signer',case when v_signer.service is null then null else jsonb_build_object(
      'release',v_signer.release,'capabilities',v_signer_caps,
      'expiresAt',v_signer.expires_at
    ) end,
    'processor',case when not v_processor_present then null else jsonb_build_object(
      'release',v_processor.release,'capabilities',v_processor_caps,
      'workerType',v_processor_evidence->>'workerType',
      'codec',v_processor_evidence->'codec',
      'antivirus',jsonb_build_object(
        'name',v_processor_evidence#>>'{antivirus,name}',
        'version',v_processor_evidence#>>'{antivirus,version}',
        'signaturesAt',v_processor_evidence#>>'{antivirus,signaturesAt}'
      ),
      'expiresAt',v_processor.expires_at
    ) end,
    'storage',v_storage,
    'maxFileBytes',12582912,'maxPixels',36000000,
    'allowedMime',jsonb_build_array('image/jpeg','image/png','image/webp'),
    'maxBatchFiles',40,'signedUrlTtlSeconds',300,
    -- Kept for the existing projections. Both are now derived, never constants.
    'pixelTranscode',v_pixel_transcode,
    'antivirusScanning',v_antivirus
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.tournament_media_require_pipeline_ready()
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not coalesce(
    (public.tournament_media_pipeline_readiness()->>'uploadReady')::boolean, false
  ) then
    raise exception using errcode = '55000',
      message = 'TORNEOS_MEDIA_PIPELINE_NOT_READY';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.tournament_media_require_upload_tier(p_processing_tier text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_mode text := public.tournament_media_current_pipeline_mode();
BEGIN
  IF p_processing_tier = 'processor_external' THEN
    IF v_mode <> 'PROCESSOR_EXTERNAL'
      OR NOT coalesce(
        (public.tournament_media_pipeline_readiness()->>'uploadReady')::boolean,false
      )
    THEN
      RAISE EXCEPTION USING errcode = '55000',
        message = 'TORNEOS_MEDIA_PIPELINE_NOT_READY';
    END IF;
  ELSIF p_processing_tier = 'mvp_simple' THEN
    IF v_mode <> 'MVP_SIMPLE'
      OR NOT coalesce(
        (public.tournament_media_effective_readiness()->>'uploadReady')::boolean,false
      )
    THEN
      RAISE EXCEPTION USING errcode = '55000',
        message = 'TORNEOS_MEDIA_PIPELINE_NOT_READY';
    END IF;
  ELSE
    RAISE EXCEPTION USING errcode = '55000',
      message = 'TORNEOS_MEDIA_PIPELINE_NOT_READY';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.tournament_media_variant_geometry(p_kind text, p_width integer, p_height integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v_box integer := public.tournament_media_variant_box(p_kind);
  v_longest integer;
  v_width integer;
  v_height integer;
begin
  if p_kind = 'original' then
    return jsonb_build_object('kind','original','width',p_width,'height',p_height);
  end if;
  if v_box is null or p_width is null or p_height is null
    or p_width < 1 or p_height < 1
  then
    return null;
  end if;
  v_longest := greatest(p_width, p_height);
  if v_longest <= v_box then
    v_width := p_width;
    v_height := p_height;
  else
    -- floor(x + 0.5) so PostgreSQL, JavaScript and TypeScript agree bit for bit.
    v_width := greatest(1, floor((p_width::numeric * v_box) / v_longest + 0.5)::integer);
    v_height := greatest(1, floor((p_height::numeric * v_box) / v_longest + 0.5)::integer);
  end if;
  return jsonb_build_object('kind',p_kind,'width',v_width,'height',v_height);
end;
$function$

CREATE OR REPLACE FUNCTION public.tournament_media_variant_plan(p_width integer, p_height integer)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select coalesce(jsonb_agg(
    public.tournament_media_variant_geometry(kind, p_width, p_height)
    order by ordinality
  ), '[]'::jsonb)
  from unnest(array['thumbnail','grid','detail']::text[])
    with ordinality as variant(kind, ordinality);
$function$

CREATE OR REPLACE FUNCTION public.tournament_registration_checklist(p_organization_id uuid, p_tournament_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tournament public.tournaments%rowtype;
  v_errors text[] := array[]::text[];
  v_warnings text[] := array[]::text[];
  v_category_count integer;
  v_tiebreak_count integer;
  v_tiebreak_min smallint;
  v_tiebreak_max smallint;
  v_has_scoring boolean;
  v_has_discipline boolean;
  v_season_valid boolean;
  v_has_fair_play_tiebreak boolean;
  v_fair_play_enabled boolean;
begin
  if auth.uid() is null
    or not public.has_tournament_organization_capability(
      p_organization_id,
      'tournaments.read'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  select tournament.*
  into v_tournament
  from public.tournaments tournament
  where tournament.id = p_tournament_id
    and tournament.organization_id = p_organization_id
    and tournament.status <> 'archived';

  if v_tournament.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  select exists (
    select 1
    from public.tournament_seasons season
    where season.id = v_tournament.season_id
      and season.organization_id = p_organization_id
      and season.status <> 'archived'
  ) into v_season_valid;

  select count(*) into v_category_count
  from public.tournament_categories category
  where category.organization_id = p_organization_id
    and category.tournament_id = p_tournament_id
    and category.status = 'active';

  select count(*), min(rule.sort_order), max(rule.sort_order)
  into v_tiebreak_count, v_tiebreak_min, v_tiebreak_max
  from public.tournament_tiebreak_rules rule
  where rule.organization_id = p_organization_id
    and rule.tournament_id = p_tournament_id;

  select exists (
    select 1
    from public.tournament_tiebreak_rules rule
    where rule.organization_id = p_organization_id
      and rule.tournament_id = p_tournament_id
      and rule.criterion = 'fair_play'
  ) into v_has_fair_play_tiebreak;

  select exists(
    select 1 from public.tournament_scoring_rules rule
    where rule.organization_id = p_organization_id
      and rule.tournament_id = p_tournament_id
  ) into v_has_scoring;

  select exists(
    select 1
    from public.tournament_discipline_rules rule
    where rule.organization_id = p_organization_id
      and rule.tournament_id = p_tournament_id
  ) into v_has_discipline;

  select coalesce(bool_or(rule.fair_play_enabled), false)
  into v_fair_play_enabled
  from public.tournament_discipline_rules rule
  where rule.organization_id = p_organization_id
    and rule.tournament_id = p_tournament_id;

  if not v_season_valid then
    v_errors := array_append(v_errors, 'season');
  end if;
  if char_length(v_tournament.name) < 3 then
    v_errors := array_append(v_errors, 'name');
  end if;
  if v_tournament.sport_modality is null then
    v_errors := array_append(v_errors, 'sport_modality');
  end if;
  if v_tournament.competition_format is null
    or not public.is_valid_tournament_format_settings(
      v_tournament.competition_format,
      v_tournament.format_settings
    )
  then
    v_errors := array_append(v_errors, 'competition_format');
  end if;
  if v_tournament.start_date is not null
    and v_tournament.end_date is not null
    and v_tournament.end_date < v_tournament.start_date
  then
    v_errors := array_append(v_errors, 'dates');
  end if;
  if v_category_count < 1 then
    v_errors := array_append(v_errors, 'categories');
  end if;
  if not v_has_scoring then
    v_errors := array_append(v_errors, 'scoring');
  end if;
  if v_tiebreak_count < 1
    or v_tiebreak_min <> 1
    or v_tiebreak_max <> v_tiebreak_count
  then
    v_errors := array_append(v_errors, 'tiebreaks');
  end if;
  if not v_has_discipline
    or (v_has_fair_play_tiebreak and not v_fair_play_enabled)
  then
    v_errors := array_append(v_errors, 'discipline');
  end if;
  if v_tournament.start_date is null then
    v_warnings := array_append(v_warnings, 'start_date');
  end if;
  if v_tournament.registration_opens_at is null
    or v_tournament.registration_closes_at is null
  then
    v_warnings := array_append(v_warnings, 'registration_dates');
  end if;

  return jsonb_build_object(
    'ready', cardinality(v_errors) = 0,
    'errors', to_jsonb(v_errors),
    'warnings', to_jsonb(v_warnings),
    'checks', jsonb_build_object(
      'information', char_length(v_tournament.name) >= 3,
      'season', v_season_valid,
      'modality', v_tournament.sport_modality is not null,
      'format', public.is_valid_tournament_format_settings(
        v_tournament.competition_format,
        v_tournament.format_settings
      ),
      'categories', v_category_count > 0,
      'scoring', v_has_scoring,
      'tiebreaks', (
        v_tiebreak_count > 0
        and v_tiebreak_min = 1
        and v_tiebreak_max = v_tiebreak_count
      ),
      'discipline', (
        v_has_discipline
        and (not v_has_fair_play_tiebreak or v_fair_play_enabled)
      )
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.tournament_season_member_assignment_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_membership public.tournament_organization_members%rowtype;
  v_limit integer;
  v_usage integer;
begin
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(new.organization_id::text || ':' || new.season_id::text,87)
  );
  select * into v_membership from public.tournament_organization_members
  where id = new.membership_id for share;
  if v_membership.id is null
    or v_membership.organization_id <> new.organization_id
    or v_membership.status <> 'active'
    or v_membership.role not in ('admin','collaborator') then
    raise exception using errcode = '22023', message = 'TORNEOS_SEASON_ASSIGNMENT_INVALID';
  end if;
  select catalog.administrative_collaborator_limit into v_limit
  from public.tournament_plan_catalog catalog
  where catalog.plan_code = case when exists (
    select 1 from public.tournament_season_plan_grants grant_row
    where grant_row.organization_id = new.organization_id
      and grant_row.season_id = new.season_id
      and public.is_tournament_season_plan_grant_effective(grant_row.id)
  ) then 'PREMIUM' else 'FREE' end;
  select count(*)::integer into v_usage
  from public.tournament_season_member_assignments assignment
  where assignment.organization_id = new.organization_id
    and assignment.season_id = new.season_id
    and (tg_op = 'INSERT' or assignment.id <> new.id);
  if v_usage >= v_limit then
    raise exception using errcode = '23514',
      message = 'TORNEOS_SEASON_COLLABORATOR_LIMIT_REACHED',
      detail = jsonb_build_object('limit',v_limit,'usage',v_usage,'seasonId',new.season_id)::text;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.transition_tournament_media_asset(p_asset_id uuid, p_action text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_asset public.tournament_media_assets%rowtype;
  v_gallery public.tournament_media_galleries%rowtype;
  v_next text;
  v_replacement uuid;
  v_capability text := 'media.review';
BEGIN
  SELECT * INTO v_asset FROM public.tournament_media_assets WHERE id = p_asset_id;
  IF v_asset.id IS NULL THEN
    RAISE EXCEPTION USING errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  END IF;
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_asset.organization_id::text,0)
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_asset.gallery_id::text,1)
  );
  SELECT * INTO v_gallery FROM public.tournament_media_galleries
  WHERE id = v_asset.gallery_id FOR UPDATE;
  SELECT * INTO v_asset FROM public.tournament_media_assets
  WHERE id = p_asset_id FOR UPDATE;
  IF p_action IN ('hide','revoke','request_deletion') THEN
    v_capability := 'media.revoke';
  END IF;
  IF NOT public.has_tournament_media_capability(
    v_asset.organization_id,v_capability
  ) THEN
    RAISE EXCEPTION USING errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  END IF;
  v_next := CASE
    WHEN p_action = 'approve' AND v_asset.status = 'pending_review' THEN 'approved'
    WHEN p_action = 'reject' AND v_asset.status = 'pending_review' THEN 'rejected'
    WHEN p_action = 'hide' AND v_asset.status IN ('approved','published') THEN 'hidden'
    -- Restaurar sólo existe mientras la galería todavía puede mostrar la foto.
    -- `archived` y `revoked` no aparecen en ninguna de las dos ramas: no hay
    -- rama que las contemple y por eso caen al ELSE NULL.
    WHEN p_action = 'restore' AND v_asset.status = 'hidden'
      AND v_gallery.status = 'published' AND v_asset.published_at IS NOT NULL
      THEN 'published'
    WHEN p_action = 'restore' AND v_asset.status = 'hidden'
      AND v_gallery.status IN ('draft','under_review','published')
      THEN 'approved'
    WHEN p_action IN ('revoke','request_deletion')
      AND v_asset.status IN ('pending_review','approved','published','hidden') THEN 'revoked'
    ELSE NULL END;
  IF v_next IS NULL THEN
    RAISE EXCEPTION USING errcode = '22023', message = 'TORNEOS_MEDIA_TRANSITION_INVALID';
  END IF;
  IF p_action IN ('reject','hide','revoke','request_deletion')
    AND (p_reason IS NULL OR char_length(btrim(p_reason)) < 3)
  THEN
    RAISE EXCEPTION USING errcode = '22023', message = 'TORNEOS_REASON_REQUIRED';
  END IF;
  IF p_action IN ('approve','restore')
    AND v_asset.processing_tier = 'processor_external'
    AND (
      SELECT count(*) <> 4 OR count(*) FILTER (
        WHERE variant.status = 'ready' AND variant.metadata_stripped
      ) <> 4
      FROM public.tournament_media_variants variant
      WHERE variant.asset_id = p_asset_id
        AND variant.kind IN ('thumbnail','grid','detail','original')
    )
  THEN
    RAISE EXCEPTION USING errcode = '22023', message = 'TORNEOS_MEDIA_PROCESSING_REQUIRED';
  END IF;
  IF v_next = 'published'
    AND NOT public.tournament_media_asset_has_internal_consent(p_asset_id)
  THEN
    RAISE EXCEPTION USING errcode = '22023', message = 'TORNEOS_MEDIA_CONSENT_REQUIRED';
  END IF;
  UPDATE public.tournament_media_assets
  SET status = v_next,
    approved_by = CASE WHEN v_next = 'approved' THEN auth.uid() ELSE approved_by END,
    approved_at = CASE WHEN v_next = 'approved' THEN now() ELSE approved_at END,
    hidden_at = CASE WHEN v_next = 'hidden' THEN now() ELSE NULL END,
    revoked_at = CASE WHEN v_next = 'revoked' THEN now() ELSE revoked_at END
  WHERE id = p_asset_id;
  IF v_gallery.status IN ('draft','under_review') AND v_next IN ('rejected','revoked') THEN
    DELETE FROM public.tournament_media_gallery_items
    WHERE gallery_id = v_gallery.id AND asset_id = p_asset_id;
    UPDATE public.tournament_media_galleries
    SET cover_asset_id = CASE WHEN cover_asset_id = p_asset_id THEN NULL ELSE cover_asset_id END,
      version = version + 1 WHERE id = v_gallery.id;
  ELSIF v_gallery.status IN ('draft','under_review') AND v_next = 'hidden'
    AND v_gallery.cover_asset_id = p_asset_id
  THEN
    UPDATE public.tournament_media_galleries
    SET cover_asset_id = NULL,version = version + 1 WHERE id = v_gallery.id;
  END IF;
  IF v_gallery.status = 'published' AND p_action IN ('hide','revoke','request_deletion')
    AND v_gallery.cover_asset_id = p_asset_id
  THEN
    SELECT asset.id INTO v_replacement
    FROM public.tournament_media_gallery_items item
    JOIN public.tournament_media_assets asset ON asset.id = item.asset_id
    WHERE item.gallery_id = v_gallery.id AND asset.id <> p_asset_id
      AND asset.status = 'published'
    ORDER BY item.sort_order,asset.created_at LIMIT 1;
    IF v_replacement IS NULL THEN
      UPDATE public.tournament_media_galleries
      SET status = 'archived',cover_asset_id = NULL,archived_at = now(),
        version = version + 1 WHERE id = v_gallery.id;
    ELSE
      UPDATE public.tournament_media_galleries
      SET cover_asset_id = v_replacement,version = version + 1
      WHERE id = v_gallery.id;
    END IF;
  END IF;
  INSERT INTO public.tournament_media_moderation_actions (
    organization_id,tournament_id,gallery_id,asset_id,action,
    previous_status,resulting_status,reason,actor_user_id
  ) VALUES (
    v_asset.organization_id,v_asset.tournament_id,v_asset.gallery_id,p_asset_id,
    p_action,v_asset.status,v_next,nullif(btrim(p_reason),''),auth.uid()
  );
  PERFORM public.append_tournament_audit(
    v_asset.organization_id,'media.asset.' || p_action,'media_asset',p_asset_id,
    null,v_asset.tournament_id,jsonb_build_object(
      'galleryId',v_asset.gallery_id,'from',v_asset.status,'to',v_next
    )
  );
  RETURN jsonb_build_object('assetId',p_asset_id,'status',v_next);
END;
$function$

CREATE OR REPLACE FUNCTION public.update_draft_fixture(p_organization_id uuid, p_fixture_version_id uuid, p_action text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_version public.tournament_fixture_versions%rowtype;
  v_phase public.tournament_phases%rowtype;
  v_round public.tournament_rounds%rowtype;
  v_match public.tournament_matches%rowtype;
  v_id uuid;
  v_number integer;
begin
  if auth.uid() is null or jsonb_typeof(p_payload) <> 'object' then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select version.* into v_version
  from public.tournament_fixture_versions version
  join public.tournament_organizations organization
    on organization.id = version.organization_id and organization.status = 'active'
  join public.tournaments tournament
    on tournament.id = version.tournament_id and tournament.status <> 'archived'
  join public.tournament_categories category
    on category.id = version.category_id and category.status = 'active'
  where version.id = p_fixture_version_id
    and version.organization_id = p_organization_id
    and version.status = 'draft'
  for update of version;
  if v_version.id is null or not public.has_tournament_organization_capability(
    p_organization_id,
    case
      when p_action = 'create_match' then 'matches.create'
      when p_action in ('create_round', 'lock_round') then 'rounds.manage'
      else 'fixture.update_draft'
    end
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if p_action = 'create_phase' then
    select coalesce(max(phase.sequence_number), 0) + 1 into v_number
    from public.tournament_phases phase where phase.fixture_version_id = v_version.id;
    insert into public.tournament_phases (
      organization_id, tournament_id, category_id, fixture_version_id,
      name, phase_type, sequence_number, status, configuration
    ) values (
      v_version.organization_id, v_version.tournament_id, v_version.category_id,
      v_version.id, btrim(p_payload->>'name'), p_payload->>'phaseType',
      coalesce((p_payload->>'sequenceNumber')::integer, v_number),
      'draft', coalesce(p_payload->'configuration', '{}'::jsonb)
    ) returning id into v_id;
  elsif p_action = 'create_round' then
    select phase.* into v_phase from public.tournament_phases phase
    where phase.id = (p_payload->>'phaseId')::uuid
      and phase.fixture_version_id = v_version.id;
    if v_phase.id is null then
      raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
    end if;
    select coalesce(max(round_row.round_number), 0) + 1 into v_number
    from public.tournament_rounds round_row
    where round_row.phase_id = v_phase.id
      and round_row.group_id is not distinct from nullif(p_payload->>'groupId', '')::uuid;
    if nullif(p_payload->>'groupId', '') is not null and not exists (
      select 1
      from public.tournament_groups group_row
      where group_row.id = (p_payload->>'groupId')::uuid
        and group_row.fixture_version_id = v_version.id
        and group_row.phase_id = v_phase.id
        and group_row.participant_set_id = v_version.participant_set_id
        and group_row.status <> 'archived'
    ) then
      raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
    end if;
    insert into public.tournament_rounds (
      organization_id, tournament_id, category_id, fixture_version_id,
      phase_id, group_id, round_number, name, status, sort_order
    ) values (
      v_version.organization_id, v_version.tournament_id, v_version.category_id,
      v_version.id, v_phase.id, nullif(p_payload->>'groupId', '')::uuid,
      coalesce((p_payload->>'roundNumber')::integer, v_number),
      btrim(p_payload->>'name'), 'draft',
      coalesce((p_payload->>'sortOrder')::integer, v_number - 1)
    ) returning id into v_id;
  elsif p_action = 'create_match' then
    select round_row.* into v_round from public.tournament_rounds round_row
    where round_row.id = (p_payload->>'roundId')::uuid
      and round_row.fixture_version_id = v_version.id;
    if v_round.id is null then
      raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
    end if;
    select coalesce(max(match_row.match_number), 0) + 1 into v_number
    from public.tournament_matches match_row
    where match_row.fixture_version_id = v_version.id;
    insert into public.tournament_matches (
      organization_id, season_id, tournament_id, category_id,
      participant_set_id, fixture_version_id, phase_id, group_id, round_id,
      match_number, home_participant_id, away_participant_id, status,
      duration_minutes, created_by
    ) values (
      v_version.organization_id, v_version.season_id, v_version.tournament_id,
      v_version.category_id, v_version.participant_set_id, v_version.id,
      v_round.phase_id, v_round.group_id, v_round.id,
      coalesce((p_payload->>'matchNumber')::integer, v_number),
      nullif(p_payload->>'homeParticipantId', '')::uuid,
      nullif(p_payload->>'awayParticipantId', '')::uuid,
      'unscheduled', coalesce((p_payload->>'durationMinutes')::integer, 60),
      auth.uid()
    ) returning id into v_id;
    perform public.insert_tournament_match_source(
      v_id, 'home', coalesce(
        p_payload->'homeSource',
        jsonb_build_object('type', 'participant', 'participantId', p_payload->>'homeParticipantId')
      )
    );
    perform public.insert_tournament_match_source(
      v_id, 'away', coalesce(
        p_payload->'awaySource',
        jsonb_build_object('type', 'participant', 'participantId', p_payload->>'awayParticipantId')
      )
    );
  elsif p_action = 'delete_match' then
    select match_row.* into v_match
    from public.tournament_matches match_row
    where match_row.id = (p_payload->>'matchId')::uuid
      and match_row.fixture_version_id = v_version.id
    for update;
    if v_match.id is null or exists (
      select 1 from public.tournament_match_sources source
      where source.source_match_id = v_match.id
    ) then
      raise exception using errcode = '23514', message = 'TORNEOS_MATCH_HAS_DEPENDENCIES';
    end if;
    delete from public.tournament_match_sources where match_id = v_match.id;
    delete from public.tournament_matches where id = v_match.id;
    v_id := v_match.id;
  elsif p_action = 'lock_round' then
    update public.tournament_rounds
    set status = 'locked', locked_at = now()
    where id = (p_payload->>'roundId')::uuid
      and fixture_version_id = v_version.id
      and status in ('draft', 'scheduled')
      and exists (
        select 1 from public.tournament_matches match_row
        where match_row.round_id = tournament_rounds.id
          and match_row.status <> 'cancelled'
      )
      and not exists (
        select 1 from public.tournament_matches match_row
        where match_row.round_id = tournament_rounds.id
          and match_row.status not in ('scheduled', 'postponed', 'ready', 'cancelled')
      )
    returning id into v_id;
    if v_id is null then
      raise exception using errcode = '23514', message = 'TORNEOS_INVALID_ROUND_TRANSITION';
    end if;
  else
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_FIXTURE_ACTION';
  end if;
  perform public.append_tournament_audit(
    p_organization_id, 'fixture.draft_updated', 'fixture_version', v_version.id,
    null, v_version.tournament_id,
    jsonb_build_object('action', p_action, 'resourceId', v_id)
  );
  return jsonb_build_object('fixtureVersionId', v_version.id, 'resourceId', v_id, 'action', p_action);
end;
$function$

CREATE OR REPLACE FUNCTION public.update_my_tournament_notification_preferences(p_tournament_id uuid, p_general boolean, p_match_changes boolean, p_callups boolean, p_discipline boolean, p_documents boolean, p_summaries boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tournament public.tournaments%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.can_access_tournament_communications(p_tournament_id) then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  select * into v_tournament from public.tournaments where id = p_tournament_id;
  insert into public.tournament_notification_preferences (
    organization_id,tournament_id,user_id,general_enabled,match_changes_enabled,
    callups_enabled,discipline_enabled,documents_enabled,summaries_enabled
  ) values (
    v_tournament.organization_id,p_tournament_id,auth.uid(),
    coalesce(p_general,true),coalesce(p_match_changes,true),
    coalesce(p_callups,true),coalesce(p_discipline,true),
    coalesce(p_documents,true),coalesce(p_summaries,true)
  )
  on conflict (tournament_id,user_id) do update set
    general_enabled = excluded.general_enabled,
    match_changes_enabled = excluded.match_changes_enabled,
    callups_enabled = excluded.callups_enabled,
    discipline_enabled = excluded.discipline_enabled,
    documents_enabled = excluded.documents_enabled,
    summaries_enabled = excluded.summaries_enabled;
  return public.get_my_tournament_notification_preferences(p_tournament_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.update_tournament_announcement_draft(p_announcement_id uuid, p_title text, p_summary text, p_body text, p_priority text, p_acknowledgement_mode text, p_scheduled_for timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_announcement public.tournament_announcements%rowtype;
begin
  select * into v_announcement
  from public.tournament_announcements announcement
  where announcement.id = p_announcement_id
  for update;
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if v_announcement.id is null
    or v_announcement.status not in ('draft','scheduled')
    or not public.has_tournament_communications_capability(
      v_announcement.organization_id,'announcements.update_draft'
    )
    or (
      v_announcement.author_user_id <> auth.uid()
      and not public.has_tournament_communications_capability(
        v_announcement.organization_id,'announcements.publish'
      )
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  if p_scheduled_for is not null
    and not public.has_tournament_communications_capability(
      v_announcement.organization_id,'announcements.schedule'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;

  update public.tournament_announcements
  set title = btrim(p_title),summary = btrim(p_summary),body = btrim(p_body),
    priority = coalesce(p_priority,'normal'),
    acknowledgement_mode = coalesce(p_acknowledgement_mode,'none'),
    scheduled_for = p_scheduled_for,
    status = case when p_scheduled_for is null then 'draft' else 'scheduled' end
  where id = p_announcement_id;
  perform public.append_tournament_audit(
    v_announcement.organization_id,'communications.announcement_update','announcement',
    p_announcement_id,null,v_announcement.tournament_id,'{}'::jsonb
  );
  return p_announcement_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_tournament_configuration(p_organization_id uuid, p_tournament_id uuid, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tournament public.tournaments%rowtype;
  v_patch jsonb := coalesce(p_patch, '{}'::jsonb);
  v_name text;
  v_slug text;
  v_modality text;
  v_format text;
  v_gender text;
  v_team_size smallint;
  v_substitutes smallint;
  v_start_date date;
  v_end_date date;
  v_registration_opens timestamptz;
  v_registration_closes timestamptz;
  v_format_settings jsonb;
  v_scoring jsonb;
  v_discipline jsonb;
  v_tiebreaks jsonb;
  v_criterion text;
  v_position smallint := 0;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(
    p_organization_id,
    'tournaments.update'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if jsonb_typeof(v_patch) <> 'object'
    or exists (
      select 1
      from jsonb_object_keys(v_patch) key
      where key not in (
        'name', 'slug', 'description', 'sportModality', 'competitionFormat',
        'genderCategory', 'teamSize', 'substitutesLimit', 'startDate', 'endDate',
        'registrationOpensAt', 'registrationClosesAt', 'formatSettings',
        'scoring', 'tiebreaks', 'discipline'
      )
    )
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_PATCH';
  end if;

  select tournament.* into v_tournament
  from public.tournaments tournament
  where tournament.id = p_tournament_id
    and tournament.organization_id = p_organization_id
  for update;

  if v_tournament.id is null or v_tournament.status not in ('draft', 'registration') then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  v_name := case
    when v_patch ? 'name' then btrim(v_patch->>'name')
    else v_tournament.name
  end;
  v_slug := case
    when v_patch ? 'slug'
      then public.normalize_tournament_competition_slug(v_patch->>'slug')
    else v_tournament.slug
  end;
  v_modality := coalesce(v_patch->>'sportModality', v_tournament.sport_modality);
  v_format := coalesce(v_patch->>'competitionFormat', v_tournament.competition_format);
  v_gender := coalesce(v_patch->>'genderCategory', v_tournament.gender_category);
  v_team_size := coalesce((v_patch->>'teamSize')::smallint, v_tournament.team_size);
  v_substitutes := case
    when v_patch ? 'substitutesLimit' then (v_patch->>'substitutesLimit')::smallint
    else v_tournament.substitutes_limit
  end;
  v_start_date := case
    when v_patch ? 'startDate' then nullif(v_patch->>'startDate', '')::date
    else v_tournament.start_date
  end;
  v_end_date := case
    when v_patch ? 'endDate' then nullif(v_patch->>'endDate', '')::date
    else v_tournament.end_date
  end;
  v_registration_opens := case
    when v_patch ? 'registrationOpensAt'
      then nullif(v_patch->>'registrationOpensAt', '')::timestamptz
    else v_tournament.registration_opens_at
  end;
  v_registration_closes := case
    when v_patch ? 'registrationClosesAt'
      then nullif(v_patch->>'registrationClosesAt', '')::timestamptz
    else v_tournament.registration_closes_at
  end;
  v_format_settings := case
    when v_patch ? 'formatSettings' then v_patch->'formatSettings'
    when v_patch ? 'competitionFormat' then case v_format
      when 'league' then '{"rounds":"single","qualifiers":0}'::jsonb
      when 'knockout' then '{"legs":"single","thirdPlace":false}'::jsonb
      when 'groups' then '{"groupCount":2,"qualifiersPerGroup":1,"rounds":"single"}'::jsonb
      when 'groups_and_playoffs' then '{"groupCount":2,"qualifiersPerGroup":1,"groupRounds":"single","knockoutLegs":"single"}'::jsonb
      else '{"leagueRounds":"single","qualifiers":2,"knockoutLegs":"single"}'::jsonb
    end
    else v_tournament.format_settings
  end;

  if char_length(v_name) not between 3 and 100
    or char_length(v_slug) not between 3 and 64
    or v_gender not in ('male', 'female', 'mixed', 'open')
    or v_team_size not between 5 and 11
    or v_substitutes not between 0 and 30
    or not exists (
      select 1 from public.tournament_sport_modalities modality
      where modality.code = v_modality
    )
    or not public.is_valid_tournament_format_settings(v_format, v_format_settings)
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_TOURNAMENT';
  end if;
  if v_start_date is not null and v_end_date is not null and v_end_date < v_start_date then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_DATES';
  end if;
  if v_registration_opens is not null
    and v_registration_closes is not null
    and v_registration_closes < v_registration_opens
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_DATES';
  end if;

  begin
    update public.tournaments
    set name = v_name,
        slug = v_slug,
        description = case
          when v_patch ? 'description' then nullif(btrim(v_patch->>'description'), '')
          else description
        end,
        sport_modality = v_modality,
        competition_format = v_format,
        gender_category = v_gender,
        team_size = v_team_size,
        substitutes_limit = v_substitutes,
        start_date = v_start_date,
        end_date = v_end_date,
        registration_opens_at = v_registration_opens,
        registration_closes_at = v_registration_closes,
        format_settings = v_format_settings
    where id = p_tournament_id
    returning * into v_tournament;
  exception when unique_violation then
    raise exception using errcode = '23505', message = 'TORNEOS_TOURNAMENT_SLUG_TAKEN';
  end;

  if v_patch ? 'scoring' then
    if not public.has_tournament_organization_capability(
      p_organization_id,
      'competition_rules.update'
    ) then
      raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
    end if;
    v_scoring := v_patch->'scoring';
    if jsonb_typeof(v_scoring) <> 'object'
      or exists (
        select 1
        from jsonb_object_keys(v_scoring) key
        where key not in (
          'pointsWin',
          'pointsDraw',
          'pointsLoss',
          'pointsWalkoverWin',
          'pointsWalkoverLoss',
          'allowManualPointsAdjustment',
          'allowAdministrativeResult'
        )
      )
    then
      raise exception using errcode = '22023', message = 'TORNEOS_INVALID_SCORING';
    end if;
    update public.tournament_scoring_rules
    set points_win = coalesce((v_scoring->>'pointsWin')::smallint, points_win),
        points_draw = coalesce((v_scoring->>'pointsDraw')::smallint, points_draw),
        points_loss = coalesce((v_scoring->>'pointsLoss')::smallint, points_loss),
        points_walkover_win = case
          when v_scoring ? 'pointsWalkoverWin'
            then nullif(v_scoring->>'pointsWalkoverWin', '')::smallint
          else points_walkover_win
        end,
        points_walkover_loss = case
          when v_scoring ? 'pointsWalkoverLoss'
            then nullif(v_scoring->>'pointsWalkoverLoss', '')::smallint
          else points_walkover_loss
        end,
        allow_manual_points_adjustment = coalesce(
          (v_scoring->>'allowManualPointsAdjustment')::boolean,
          allow_manual_points_adjustment
        ),
        allow_administrative_result = coalesce(
          (v_scoring->>'allowAdministrativeResult')::boolean,
          allow_administrative_result
        )
    where tournament_id = p_tournament_id
      and organization_id = p_organization_id;
  end if;

  if v_patch ? 'tiebreaks' then
    if not public.has_tournament_organization_capability(
      p_organization_id,
      'competition_rules.update'
    ) then
      raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
    end if;
    v_tiebreaks := v_patch->'tiebreaks';
    if jsonb_typeof(v_tiebreaks) <> 'array'
      or jsonb_array_length(v_tiebreaks) not between 1 and 7
      or (
        select count(*) <> count(distinct criterion)
        from jsonb_array_elements_text(v_tiebreaks) item(criterion)
      )
      or exists (
        select 1
        from jsonb_array_elements_text(v_tiebreaks) item(criterion)
        where criterion not in (
          'goal_difference',
          'goals_for',
          'head_to_head',
          'matches_won',
          'fair_play',
          'playoff_match',
          'draw'
        )
      )
    then
      raise exception using errcode = '22023', message = 'TORNEOS_INVALID_TIEBREAKS';
    end if;

    delete from public.tournament_tiebreak_rules
    where organization_id = p_organization_id
      and tournament_id = p_tournament_id;
    for v_criterion in select jsonb_array_elements_text(v_tiebreaks)
    loop
      v_position := v_position + 1;
      insert into public.tournament_tiebreak_rules (
        organization_id,
        tournament_id,
        criterion,
        sort_order
      )
      values (p_organization_id, p_tournament_id, v_criterion, v_position);
    end loop;
  end if;

  if v_patch ? 'discipline' then
    if not public.has_tournament_organization_capability(
      p_organization_id,
      'competition_rules.update'
    ) then
      raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
    end if;
    v_discipline := v_patch->'discipline';
    if jsonb_typeof(v_discipline) <> 'object'
      or exists (
        select 1
        from jsonb_object_keys(v_discipline) key
        where key not in (
          'yellowsForSuspension',
          'suspensionMatches',
          'directRedSuggestedMatches',
          'doubleYellowCountsAsRed',
          'resetYellowsEachStage',
          'fairPlayEnabled',
          'yellowFairPlayPoints',
          'redFairPlayPoints'
        )
      )
    then
      raise exception using errcode = '22023', message = 'TORNEOS_INVALID_DISCIPLINE';
    end if;
    update public.tournament_discipline_rules
    set yellows_for_suspension = coalesce(
          (v_discipline->>'yellowsForSuspension')::smallint,
          yellows_for_suspension
        ),
        suspension_matches = coalesce(
          (v_discipline->>'suspensionMatches')::smallint,
          suspension_matches
        ),
        direct_red_suggested_matches = case
          when v_discipline ? 'directRedSuggestedMatches'
            then nullif(v_discipline->>'directRedSuggestedMatches', '')::smallint
          else direct_red_suggested_matches
        end,
        double_yellow_counts_as_red = coalesce(
          (v_discipline->>'doubleYellowCountsAsRed')::boolean,
          double_yellow_counts_as_red
        ),
        reset_yellows_each_stage = coalesce(
          (v_discipline->>'resetYellowsEachStage')::boolean,
          reset_yellows_each_stage
        ),
        fair_play_enabled = coalesce(
          (v_discipline->>'fairPlayEnabled')::boolean,
          fair_play_enabled
        ),
        yellow_fair_play_points = coalesce(
          (v_discipline->>'yellowFairPlayPoints')::smallint,
          yellow_fair_play_points
        ),
        red_fair_play_points = coalesce(
          (v_discipline->>'redFairPlayPoints')::smallint,
          red_fair_play_points
        )
    where tournament_id = p_tournament_id
      and organization_id = p_organization_id;
  end if;

  return jsonb_build_object(
    'id', v_tournament.id,
    'organizationId', v_tournament.organization_id,
    'seasonId', v_tournament.season_id,
    'name', v_tournament.name,
    'slug', v_tournament.slug,
    'status', v_tournament.status
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_tournament_court(p_organization_id uuid, p_court_id uuid, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_court public.tournament_courts%rowtype;
  v_status text;
  v_capability text;
begin
  if auth.uid() is null or jsonb_typeof(p_patch) <> 'object' or exists (
    select 1 from jsonb_object_keys(p_patch) key
    where key not in ('name', 'sportModality', 'notes', 'status')
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_PATCH';
  end if;
  v_status := coalesce(p_patch->>'status', 'active');
  v_capability := case when v_status = 'archived' then 'courts.archive' else 'courts.update' end;
  if not public.has_tournament_organization_capability(p_organization_id, v_capability) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  select court.* into v_court from public.tournament_courts court
  join public.tournament_venues venue
    on venue.id = court.venue_id and venue.status = 'active'
  where court.id = p_court_id and court.organization_id = p_organization_id
    and court.status = 'active'
  for update of court;
  if v_court.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  update public.tournament_courts
  set name = case when p_patch ? 'name' then btrim(p_patch->>'name') else name end,
      sport_modality = case when p_patch ? 'sportModality'
        then p_patch->>'sportModality' else sport_modality end,
      notes = case when p_patch ? 'notes'
        then nullif(btrim(p_patch->>'notes'), '') else notes end,
      status = v_status,
      archived_at = case when v_status = 'archived' then now() else null end
  where id = v_court.id returning * into v_court;
  perform public.append_tournament_audit(
    p_organization_id,
    case when v_status = 'archived' then 'court.archived' else 'court.updated' end,
    'court', v_court.id, null, null, jsonb_build_object('status', v_status)
  );
  return jsonb_build_object('id', v_court.id, 'name', v_court.name, 'status', v_court.status);
end;
$function$

CREATE OR REPLACE FUNCTION public.update_tournament_document_draft(p_version_id uuid, p_summary text, p_body text, p_effective_at timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_version public.tournament_document_versions%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_version
  from public.tournament_document_versions version
  where version.id = p_version_id
  for update;
  if v_version.id is null
    or v_version.status <> 'draft'
    or not public.has_tournament_communications_capability(
      v_version.organization_id,'documents.update_draft'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_DOCUMENT_FORBIDDEN';
  end if;
  update public.tournament_document_versions
  set summary = btrim(p_summary),body = btrim(p_body),effective_at = p_effective_at
  where id = p_version_id;
  return p_version_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.update_tournament_media_gallery(p_gallery_id uuid, p_title text, p_description text, p_visibility text, p_submit_for_review boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_gallery public.tournament_media_galleries%rowtype;
begin
  select * into v_gallery
  from public.tournament_media_galleries
  where id = p_gallery_id;
  if v_gallery.id is null or not public.has_tournament_media_capability(
    v_gallery.organization_id,'media.update_gallery'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_gallery.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_gallery.id::text,1)
  );
  select * into v_gallery
  from public.tournament_media_galleries
  where id = p_gallery_id
  for update;
  if v_gallery.status not in ('draft','under_review') then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_GALLERY_IMMUTABLE';
  end if;
  if p_visibility = 'match_participants' and v_gallery.match_id is null then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_VISIBILITY_INVALID';
  end if;
  update public.tournament_media_galleries
  set title = btrim(p_title),
      description = nullif(btrim(p_description),''),
      visibility = p_visibility,
      status = case when p_submit_for_review then 'under_review' else status end,
      submitted_at = case when p_submit_for_review
        then coalesce(submitted_at,now()) else submitted_at end,
      version = version + 1
  where id = p_gallery_id;
  perform public.append_tournament_audit(
    v_gallery.organization_id,
    case when p_submit_for_review then 'media.gallery.submitted' else 'media.gallery.updated' end,
    'media_gallery',p_gallery_id,null,v_gallery.tournament_id,
    jsonb_build_object('visibility',p_visibility)
  );
  return jsonb_build_object(
    'galleryId',p_gallery_id,
    'status',case when p_submit_for_review then 'under_review' else v_gallery.status end
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_tournament_organization(p_organization_id uuid, p_name text DEFAULT NULL::text, p_slug text DEFAULT NULL::text, p_status text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_name text;
  v_slug text;
  v_role text;
  v_organization public.tournament_organizations%rowtype;
  v_reserved_slugs constant text[] := array[
    'admin', 'api', 'app', 'auth', 'login', 'logout', 'profile',
    'torneos', 'tournaments', 'settings', 'support', 'www'
  ];
begin
  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'TORNEOS_AUTH_REQUIRED';
  end if;

  if not public.has_tournament_organization_capability(
    p_organization_id,
    'organization.update'
  ) then
    raise exception using
      errcode = '42501',
      message = 'TORNEOS_ORGANIZATION_FORBIDDEN';
  end if;

  select membership.role
  into v_role
  from public.tournament_organization_members membership
  where membership.organization_id = p_organization_id
    and membership.user_id = v_user_id
    and membership.status = 'active';

  select organization.*
  into v_organization
  from public.tournament_organizations organization
  where organization.id = p_organization_id
  for update;

  if v_organization.id is null then
    raise exception using
      errcode = '42501',
      message = 'TORNEOS_ORGANIZATION_FORBIDDEN';
  end if;

  v_name := case
    when p_name is null then v_organization.name
    else btrim(p_name)
  end;
  v_slug := case
    when p_slug is null then v_organization.slug
    else public.normalize_tournament_organization_slug(p_slug)
  end;

  if char_length(v_name) not between 3 and 80 then
    raise exception using
      errcode = '22023',
      message = 'TORNEOS_INVALID_NAME';
  end if;

  if char_length(v_slug) not between 3 and 48
    or v_slug !~ '^[a-z0-9](?:[a-z0-9-]{1,46}[a-z0-9])$'
    or v_slug = any(v_reserved_slugs)
  then
    raise exception using
      errcode = '22023',
      message = 'TORNEOS_INVALID_SLUG';
  end if;

  if p_status is not null and p_status not in ('active', 'archived') then
    raise exception using
      errcode = '22023',
      message = 'TORNEOS_INVALID_STATUS';
  end if;

  if p_status is not null
    and p_status is distinct from v_organization.status
    and not public.has_tournament_organization_capability(
      p_organization_id,
      'organization.archive'
    )
  then
    raise exception using
      errcode = '42501',
      message = 'TORNEOS_ARCHIVE_FORBIDDEN';
  end if;

  begin
    update public.tournament_organizations
    set name = v_name,
        slug = v_slug,
        status = coalesce(p_status, status),
        archived_at = case
          when coalesce(p_status, status) = 'archived'
            then coalesce(archived_at, now())
          else null
        end
    where id = p_organization_id
    returning * into v_organization;
  exception
    when unique_violation then
      raise exception using
        errcode = '23505',
        message = 'TORNEOS_SLUG_TAKEN';
  end;

  if v_organization.status = 'archived' then
    update public.user_workspace_preferences
    set workspace_type = 'personal',
        active_organization_id = null
    where active_organization_id = v_organization.id;
  end if;

  return jsonb_build_object(
    'id', v_organization.id,
    'name', v_organization.name,
    'slug', v_organization.slug,
    'logoPath', v_organization.logo_path,
    'status', v_organization.status,
    'createdAt', v_organization.created_at,
    'role', v_role,
    'capabilities', to_jsonb(public.tournament_role_capabilities(v_role))
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.update_tournament_roster_player(p_organization_id uuid, p_team_entry_id uuid, p_roster_player_id uuid, p_shirt_number smallint, p_primary_position text, p_secondary_position text, p_is_goalkeeper boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_player public.tournament_roster_players%rowtype;
  v_roster public.tournament_rosters%rowtype;
  v_entry public.tournament_team_entries%rowtype;
  v_settings public.tournament_roster_settings%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_player from public.tournament_roster_players
  where id = p_roster_player_id and organization_id = p_organization_id
    and team_entry_id = p_team_entry_id and status = 'active' for update;
  select * into v_roster from public.tournament_rosters where id = v_player.roster_id;
  select * into v_entry from public.tournament_team_entries where id = p_team_entry_id;
  select * into v_settings from public.tournament_roster_settings where tournament_id = v_entry.tournament_id;
  if v_player.id is null or v_roster.status not in ('draft', 'changes_requested')
    or not public.can_edit_tournament_team_entry(
      p_organization_id,
      p_team_entry_id
    )
  then raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN'; end if;
  if v_settings.unique_shirt_numbers and p_shirt_number is not null and exists (
    select 1 from public.tournament_roster_players
    where roster_id = v_player.roster_id and status = 'active'
      and shirt_number = p_shirt_number and id <> v_player.id
  ) then raise exception using errcode = '23505', message = 'TORNEOS_DUPLICATE_SHIRT_NUMBER'; end if;
  update public.tournament_roster_players set
    shirt_number = p_shirt_number,
    primary_position = p_primary_position,
    secondary_position = p_secondary_position,
    is_goalkeeper = coalesce(p_is_goalkeeper, false)
  where id = v_player.id returning * into v_player;
  perform public.append_tournament_audit(
    p_organization_id, 'roster_player.updated', 'roster_player', v_player.id,
    p_team_entry_id, v_entry.tournament_id, '{}'::jsonb
  );
  return jsonb_build_object('id', v_player.id, 'updatedAt', v_player.updated_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.update_tournament_season(p_organization_id uuid, p_season_id uuid, p_name text DEFAULT NULL::text, p_slug text DEFAULT NULL::text, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_status text DEFAULT NULL::text, p_clear_start_date boolean DEFAULT false, p_clear_end_date boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_season public.tournament_seasons%rowtype;
  v_name text; v_slug text; v_start_date date; v_end_date date;
begin
  if auth.uid() is null then raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED'; end if;
  if not public.has_tournament_season_capability(
    p_organization_id,p_season_id,
    case when p_status = 'archived' then 'seasons.archive' else 'seasons.update' end
  ) then raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN'; end if;
  select * into v_season from public.tournament_seasons
  where id = p_season_id and organization_id = p_organization_id for update;
  if v_season.id is null or v_season.status = 'archived' then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if p_status is not null and not (
    (v_season.status = 'draft' and p_status in ('active','archived'))
    or (v_season.status = 'active' and p_status = 'completed')
    or (v_season.status = 'completed' and p_status = 'archived')
  ) then raise exception using errcode = '22023', message = 'TORNEOS_INVALID_SEASON_TRANSITION'; end if;
  if p_status = 'archived' and exists (
    select 1 from public.tournaments where organization_id = p_organization_id
      and season_id = p_season_id and status <> 'archived'
  ) then raise exception using errcode = '23514', message = 'TORNEOS_SEASON_HAS_TOURNAMENTS'; end if;
  v_name := case when p_name is null then v_season.name else btrim(p_name) end;
  v_slug := case when p_slug is null then v_season.slug else public.normalize_tournament_competition_slug(p_slug) end;
  v_start_date := case when p_clear_start_date then null else coalesce(p_start_date,v_season.start_date) end;
  v_end_date := case when p_clear_end_date then null else coalesce(p_end_date,v_season.end_date) end;
  if char_length(v_name) not between 3 and 80 or char_length(v_slug) not between 3 and 48
    or (v_start_date is not null and v_end_date is not null and v_end_date < v_start_date) then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_SEASON';
  end if;
  begin
    update public.tournament_seasons set name=v_name,slug=v_slug,start_date=v_start_date,
      end_date=v_end_date,status=coalesce(p_status,status),
      archived_at=case when p_status='archived' then now() else archived_at end
    where id=p_season_id returning * into v_season;
  exception when unique_violation then
    raise exception using errcode='23505',message='TORNEOS_SEASON_SLUG_TAKEN';
  end;
  if v_season.status='archived' then
    update public.user_tournament_context_preferences set active_season_id=null,active_tournament_id=null
    where organization_id=p_organization_id and active_season_id=p_season_id;
  end if;
  return jsonb_build_object('id',v_season.id,'organizationId',v_season.organization_id,
    'name',v_season.name,'slug',v_season.slug,'status',v_season.status,
    'startDate',v_season.start_date,'endDate',v_season.end_date,
    'createdAt',v_season.created_at,'updatedAt',v_season.updated_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.update_tournament_team_entry(p_organization_id uuid, p_team_entry_id uuid, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_entry public.tournament_team_entries%rowtype;
  v_name text;
begin
  if auth.uid() is null or jsonb_typeof(p_patch) <> 'object' or exists (
    select 1 from jsonb_object_keys(p_patch) key
    where key not in ('name', 'shortName', 'primaryColor', 'secondaryColor', 'shieldPath')
  ) then raise exception using errcode = '22023', message = 'TORNEOS_INVALID_PATCH'; end if;

  select * into v_entry from public.tournament_team_entries
  where id = p_team_entry_id and organization_id = p_organization_id for update;
  if v_entry.id is null or not public.can_edit_tournament_team_entry(
    p_organization_id,
    p_team_entry_id
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if v_entry.status not in ('draft', 'invited', 'in_progress', 'changes_requested') then
    raise exception using errcode = '23514', message = 'TORNEOS_ENTRY_NOT_EDITABLE';
  end if;
  v_name := case when p_patch ? 'name' then btrim(p_patch->>'name') else v_entry.name end;
  if char_length(v_name) not between 2 and 100 then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_TEAM_ENTRY';
  end if;
  update public.tournament_team_entries set
    name = v_name,
    short_name = case when p_patch ? 'shortName' then nullif(btrim(p_patch->>'shortName'), '') else short_name end,
    primary_color = case when p_patch ? 'primaryColor' then nullif(p_patch->>'primaryColor', '') else primary_color end,
    secondary_color = case when p_patch ? 'secondaryColor' then nullif(p_patch->>'secondaryColor', '') else secondary_color end,
    shield_path = case when p_patch ? 'shieldPath' then nullif(p_patch->>'shieldPath', '') else shield_path end,
    status = case when status in ('draft', 'invited') then 'in_progress' else status end
  where id = p_team_entry_id returning * into v_entry;
  perform public.append_tournament_audit(
    p_organization_id, 'team_entry.updated', 'team_entry', v_entry.id,
    v_entry.id, v_entry.tournament_id, jsonb_build_object('fields', (select jsonb_agg(key) from jsonb_object_keys(p_patch) key))
  );
  return jsonb_build_object('entryId', v_entry.id, 'status', v_entry.status, 'updatedAt', v_entry.updated_at);
end;
$function$

CREATE OR REPLACE FUNCTION public.update_tournament_venue(p_organization_id uuid, p_venue_id uuid, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_venue public.tournament_venues%rowtype;
  v_status text;
  v_capability text;
begin
  if auth.uid() is null or jsonb_typeof(p_patch) <> 'object' or exists (
    select 1 from jsonb_object_keys(p_patch) key
    where key not in (
      'name', 'address', 'placeId', 'latitude', 'longitude',
      'locality', 'timezone', 'notes', 'status'
    )
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_PATCH';
  end if;
  v_status := coalesce(p_patch->>'status', 'active');
  v_capability := case when v_status = 'archived' then 'venues.archive' else 'venues.update' end;
  if not public.has_tournament_organization_capability(p_organization_id, v_capability) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if p_patch ? 'timezone' and not exists (
    select 1
    from pg_catalog.pg_timezone_names zone
    where zone.name = p_patch->>'timezone'
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_TIMEZONE';
  end if;
  select venue.* into v_venue from public.tournament_venues venue
  where venue.id = p_venue_id and venue.organization_id = p_organization_id
    and venue.status = 'active'
  for update;
  if v_venue.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  update public.tournament_venues
  set name = case when p_patch ? 'name' then btrim(p_patch->>'name') else name end,
      address = case when p_patch ? 'address' then btrim(p_patch->>'address') else address end,
      place_id = case when p_patch ? 'placeId'
        then nullif(btrim(p_patch->>'placeId'), '') else place_id end,
      latitude = case when p_patch ? 'latitude' then (p_patch->>'latitude')::double precision else latitude end,
      longitude = case when p_patch ? 'longitude' then (p_patch->>'longitude')::double precision else longitude end,
      locality = case when p_patch ? 'locality'
        then nullif(btrim(p_patch->>'locality'), '') else locality end,
      timezone = case when p_patch ? 'timezone' then p_patch->>'timezone' else timezone end,
      notes = case when p_patch ? 'notes' then nullif(btrim(p_patch->>'notes'), '') else notes end,
      status = v_status,
      archived_at = case when v_status = 'archived' then now() else null end
  where id = v_venue.id returning * into v_venue;
  if v_status = 'archived' then
    update public.tournament_courts
    set status = 'archived', archived_at = now()
    where venue_id = v_venue.id and status = 'active';
  end if;
  perform public.append_tournament_audit(
    p_organization_id,
    case when v_status = 'archived' then 'venue.archived' else 'venue.updated' end,
    'venue', v_venue.id, null, null, jsonb_build_object('status', v_status)
  );
  return jsonb_build_object('id', v_venue.id, 'name', v_venue.name, 'status', v_venue.status);
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_tournament_fixture(p_organization_id uuid, p_fixture_version_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_version public.tournament_fixture_versions%rowtype;
  v_blockers jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_item record;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select version.* into v_version
  from public.tournament_fixture_versions version
  where version.id = p_fixture_version_id
    and version.organization_id = p_organization_id;
  if v_version.id is null or not public.can_read_tournament_fixture_scope(
    p_organization_id, v_version.tournament_id
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if v_version.invalidated_at is not null then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'participants_changed', 'resourceId', v_version.id
    ));
  end if;
  for v_item in
    select match_row.id
    from public.tournament_matches match_row
    where match_row.fixture_version_id = v_version.id
      and match_row.home_participant_id is not null
      and match_row.home_participant_id = match_row.away_participant_id
  loop
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'self_match', 'resourceId', v_item.id
    ));
  end loop;
  for v_item in
    select match_row.id
    from public.tournament_matches match_row
    where match_row.fixture_version_id = v_version.id
      and match_row.status <> 'cancelled'
      and (select count(*) from public.tournament_match_sources source
        where source.match_id = match_row.id) <> 2
  loop
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'incomplete_match_sources', 'resourceId', v_item.id
    ));
  end loop;
  for v_item in
    select min(left_match.id::text)::uuid as id
    from public.tournament_matches left_match
    join public.tournament_matches right_match
      on right_match.fixture_version_id = left_match.fixture_version_id
      and right_match.id > left_match.id
      and right_match.phase_id = left_match.phase_id
      and right_match.leg_number = left_match.leg_number
      and least(right_match.home_participant_id, right_match.away_participant_id)
        = least(left_match.home_participant_id, left_match.away_participant_id)
      and greatest(right_match.home_participant_id, right_match.away_participant_id)
        = greatest(left_match.home_participant_id, left_match.away_participant_id)
    where left_match.fixture_version_id = v_version.id
      and left_match.status <> 'cancelled' and right_match.status <> 'cancelled'
    group by least(left_match.home_participant_id, left_match.away_participant_id),
      greatest(left_match.home_participant_id, left_match.away_participant_id),
      left_match.phase_id, left_match.leg_number
  loop
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'duplicate_pairing', 'resourceId', v_item.id
    ));
  end loop;
  for v_item in
    select match_row.id
    from public.tournament_matches match_row
    join public.tournament_match_sources source on source.match_id = match_row.id
    where match_row.fixture_version_id = v_version.id
      and match_row.status <> 'cancelled'
      and source.source_type = 'bye'
  loop
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'playable_bye_match', 'resourceId', v_item.id
    ));
  end loop;
  for v_item in
    select group_row.id
    from public.tournament_groups group_row
    where group_row.fixture_version_id = v_version.id
      and group_row.status = 'published'
      and not exists (
        select 1 from public.tournament_group_members member
        where member.group_id = group_row.id
      )
  loop
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'empty_published_group', 'resourceId', v_item.id
    ));
  end loop;
  for v_item in
    select phase.id
    from public.tournament_phases phase
    where phase.fixture_version_id = v_version.id
      and phase.phase_type = 'groups'
      and exists (
        select 1
        from public.tournament_competition_participants participant
        where participant.participant_set_id = v_version.participant_set_id
          and participant.status = 'active'
          and (
            select count(*)
            from public.tournament_group_members member
            join public.tournament_groups group_row on group_row.id = member.group_id
            where member.participant_id = participant.id
              and group_row.fixture_version_id = v_version.id
              and group_row.phase_id = phase.id
              and group_row.status = 'published'
          ) <> 1
      )
  loop
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'incomplete_group_assignment', 'resourceId', v_item.id
    ));
  end loop;
  if not exists (
    select 1 from public.tournament_phases phase
    where phase.fixture_version_id = v_version.id and phase.status <> 'archived'
  ) or not exists (
    select 1 from public.tournament_matches match_row
    where match_row.fixture_version_id = v_version.id and match_row.status <> 'cancelled'
  ) then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'fixture_incomplete', 'resourceId', v_version.id
    ));
  end if;
  for v_item in
    select round_row.id, max(load) - min(load) as delta
    from (
      select round_row.id, participant.id as participant_id,
        count(match_row.id) filter (
          where participant.id in (match_row.home_participant_id, match_row.away_participant_id)
        ) as load
      from public.tournament_rounds round_row
      cross join public.tournament_competition_participants participant
      left join public.tournament_matches match_row on match_row.round_id = round_row.id
        and match_row.status <> 'cancelled'
      where round_row.fixture_version_id = v_version.id
        and participant.participant_set_id = v_version.participant_set_id
      group by round_row.id, participant.id
    ) round_row
    group by round_row.id
    having max(load) - min(load) > 1
  loop
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
      'code', 'uneven_round_load', 'resourceId', v_item.id
    ));
  end loop;
  return jsonb_build_object(
    'valid', jsonb_array_length(v_blockers) = 0,
    'blockers', v_blockers,
    'warnings', v_warnings,
    'checkedAt', now()
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_tournament_fixture_member_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_left_set uuid;
  v_right_set uuid;
  v_group public.tournament_groups%rowtype;
begin
  if tg_table_name = 'tournament_draw_pot_members' then
    select pot.participant_set_id, participant.participant_set_id
    into v_left_set, v_right_set
    from public.tournament_draw_pots pot
    cross join public.tournament_competition_participants participant
    where pot.id = new.pot_id and participant.id = new.participant_id;
  else
    select group_row.* into v_group
    from public.tournament_groups group_row
    where group_row.id = new.group_id;
    select participant.participant_set_id into v_right_set
    from public.tournament_competition_participants participant
    where participant.id = new.participant_id;
    v_left_set := v_group.participant_set_id;
  end if;
  if v_left_set is null or v_left_set is distinct from v_right_set then
    raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
  end if;
  if tg_table_name = 'tournament_group_members' then
    perform pg_advisory_xact_lock(hashtextextended(
      'torneos:group-member:' || coalesce(v_group.fixture_version_id::text, 'draw')
        || ':' || coalesce(v_group.phase_id::text, v_group.participant_set_id::text)
        || ':' || new.participant_id::text,
      0
    ));
    if exists (
      select 1
      from public.tournament_group_members existing
      join public.tournament_groups existing_group on existing_group.id = existing.group_id
      where existing.participant_id = new.participant_id
        and existing.group_id <> new.group_id
        and existing_group.participant_set_id = v_group.participant_set_id
        and existing_group.fixture_version_id is not distinct from v_group.fixture_version_id
        and existing_group.phase_id is not distinct from v_group.phase_id
        and existing_group.status <> 'archived'
    ) then
      raise exception using errcode = '23505', message = 'TORNEOS_DUPLICATE_GROUP_PARTICIPANT';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_tournament_group_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_version public.tournament_fixture_versions%rowtype;
begin
  if new.fixture_version_id is null then
    if new.phase_id is not null then
      raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
    end if;
    return new;
  end if;
  select version.* into v_version
  from public.tournament_fixture_versions version
  where version.id = new.fixture_version_id;
  if v_version.id is null
    or v_version.organization_id <> new.organization_id
    or v_version.tournament_id <> new.tournament_id
    or v_version.category_id <> new.category_id
    or v_version.participant_set_id <> new.participant_set_id
  then
    raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_tournament_match_operation(p_organization_id uuid, p_match_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_operation public.tournament_match_operations%rowtype;
  v_validation jsonb;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null or v_operation.status <> 'under_review'
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_operations.validate'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if v_operation.submitted_by = auth.uid() then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_DUAL_CONTROL_REQUIRED';
  end if;
  v_validation := public.validate_tournament_match_operation_payload(v_operation.id);
  if not (v_validation->>'valid')::boolean then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_OPERATION_INVALID';
  end if;
  update public.tournament_match_operations set
    status = 'validated', validated_by = auth.uid(), validated_at = now(), updated_at = now()
  where id = v_operation.id;
  perform public.append_tournament_audit(
    p_organization_id, 'match_operation.validated', 'match_operation',
    v_operation.id, null, v_operation.tournament_id, '{}'::jsonb
  );
  return public.get_tournament_match_operation_context(p_organization_id, v_operation.id);
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_tournament_match_operation_payload(p_match_operation_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_operation public.tournament_match_operations%rowtype;
  v_outcome public.tournament_match_outcomes%rowtype;
  v_score public.tournament_match_scores%rowtype;
  v_home_goals integer;
  v_away_goals integer;
  v_home_shootout_goals integer;
  v_away_shootout_goals integer;
  v_errors jsonb := '[]'::jsonb;
begin
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id;
  if v_operation.id is null or not public.can_read_tournament_match_operation(
    v_operation.organization_id, v_operation.match_id
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  select * into v_outcome from public.tournament_match_outcomes
  where match_operation_id = v_operation.id;
  select * into v_score from public.tournament_match_scores
  where match_operation_id = v_operation.id;
  if v_outcome.match_operation_id is null then
    v_errors := v_errors || jsonb_build_array('outcome_required');
  end if;
  if coalesce(v_outcome.requires_resolution, false) then
    v_errors := v_errors || jsonb_build_array('resolution_pending');
  end if;
  if v_outcome.outcome_type in (
    'played', 'walkover_home', 'walkover_away', 'administrative_result',
    'home_no_show', 'away_no_show', 'double_no_show'
  ) and v_score.match_operation_id is null then
    v_errors := v_errors || jsonb_build_array('score_required');
  end if;
  if v_score.match_operation_id is not null and not (
    (v_outcome.outcome_type = 'played'
      and v_score.score_type in ('played', 'series_leg'))
    or (v_outcome.outcome_type in ('walkover_home', 'walkover_away')
      and v_score.score_type = 'walkover')
    or (v_outcome.outcome_type in (
      'administrative_result', 'home_no_show', 'away_no_show', 'double_no_show'
    ) and v_score.score_type = 'administrative')
    or (v_outcome.outcome_type in ('suspended', 'abandoned')
      and v_score.score_type in ('played', 'administrative'))
  ) then
    v_errors := v_errors || jsonb_build_array('score_outcome_mismatch');
  end if;
  if v_outcome.outcome_type in (
    'walkover_home', 'walkover_away',
    'home_no_show', 'away_no_show', 'double_no_show',
    'administrative_result',
    'postponed_before_start', 'cancelled', 'not_played'
  )
    and v_outcome.counts_for_player_stats
  then
    v_errors := v_errors || jsonb_build_array('walkover_player_stats_forbidden');
  end if;
  if v_outcome.outcome_type in (
    'postponed_before_start', 'cancelled', 'not_played'
  ) and v_score.match_operation_id is not null then
    v_errors := v_errors || jsonb_build_array('score_not_allowed_for_outcome');
  end if;
  if v_outcome.outcome_type in (
    'postponed_before_start', 'cancelled', 'not_played',
    'walkover_home', 'walkover_away', 'administrative_result',
    'home_no_show', 'away_no_show', 'double_no_show'
  ) and exists (
    select 1
    from public.tournament_match_events event
    where event.match_operation_id = v_operation.id
      and event.voided_at is null
      and event.event_type in (
        'goal', 'own_goal', 'assist', 'penalty_goal', 'penalty_missed',
        'yellow_card', 'second_yellow', 'red_card',
        'substitution_in', 'substitution_out'
      )
  ) then
    v_errors := v_errors || jsonb_build_array('events_not_allowed_for_outcome');
  end if;
  if v_outcome.outcome_type in (
    'walkover_home', 'walkover_away', 'administrative_result',
    'home_no_show', 'away_no_show', 'double_no_show',
    'suspended', 'abandoned', 'cancelled', 'not_played'
  ) and char_length(btrim(coalesce(v_outcome.reason_text, ''))) < 3 then
    v_errors := v_errors || jsonb_build_array('outcome_reason_required');
  end if;
  if v_outcome.administrative_home_score is not null and (
    v_score.match_operation_id is null
    or v_outcome.administrative_home_score <> v_score.home_score
    or v_outcome.administrative_away_score <> v_score.away_score
  ) then
    v_errors := v_errors || jsonb_build_array('administrative_score_mismatch');
  end if;
  if v_outcome.outcome_type not in (
    'walkover_home', 'walkover_away', 'administrative_result',
    'home_no_show', 'away_no_show', 'double_no_show'
  ) and v_outcome.administrative_home_score is not null then
    v_errors := v_errors || jsonb_build_array('administrative_score_forbidden');
  end if;
  if v_score.home_penalties is not null and (
    v_outcome.outcome_type <> 'played'
    or v_score.home_score <> v_score.away_score
    or v_score.home_penalties = v_score.away_penalties
  ) then
    v_errors := v_errors || jsonb_build_array('penalty_score_invalid');
  end if;
  if exists (
    select 1
    from public.tournament_match_events assist
    left join public.tournament_match_events goal
      on goal.id = assist.related_event_id
      and goal.match_operation_id = assist.match_operation_id
      and goal.team_entry_id = assist.team_entry_id
      and goal.event_type in ('goal', 'penalty_goal')
      and not (goal.event_type = 'penalty_goal' and goal.period = 'penalties')
      and goal.voided_at is null
    where assist.match_operation_id = v_operation.id
      and assist.event_type = 'assist'
      and assist.voided_at is null
      and (
        goal.id is null
        or goal.roster_player_id is null
        or goal.roster_player_id = assist.roster_player_id
      )
  ) then
    v_errors := v_errors || jsonb_build_array('assist_without_goal');
  end if;
  if exists (
    select 1
    from public.tournament_match_events exited
    left join public.tournament_match_events entered
      on entered.related_event_id = exited.id
      and entered.match_operation_id = exited.match_operation_id
      and entered.event_type = 'substitution_in'
      and entered.voided_at is null
    where exited.match_operation_id = v_operation.id
      and exited.event_type = 'substitution_out'
      and exited.voided_at is null
      and entered.id is null
  ) then
    v_errors := v_errors || jsonb_build_array('substitution_pair_required');
  end if;
  if exists (
    select 1
    from public.tournament_match_events second_yellow
    where second_yellow.match_operation_id = v_operation.id
      and second_yellow.event_type = 'second_yellow'
      and second_yellow.voided_at is null
      and not exists (
        select 1
        from public.tournament_match_events first_yellow
        where first_yellow.match_operation_id = v_operation.id
          and first_yellow.roster_player_id = second_yellow.roster_player_id
          and first_yellow.event_type = 'yellow_card'
          and first_yellow.sequence_number < second_yellow.sequence_number
          and first_yellow.voided_at is null
      )
  ) then
    v_errors := v_errors || jsonb_build_array('second_yellow_without_first');
  end if;
  if v_outcome.counts_for_player_stats and v_score.score_type in ('played', 'series_leg') then
    select count(*) filter (where event.team_entry_id = v_operation.home_team_entry_id),
      count(*) filter (where event.team_entry_id = v_operation.away_team_entry_id)
    into v_home_goals, v_away_goals
    from public.tournament_match_events event
    where event.match_operation_id = v_operation.id
      and event.voided_at is null
      and event.event_type in ('goal', 'penalty_goal', 'own_goal')
      and not (event.event_type = 'penalty_goal' and event.period = 'penalties');
    if v_home_goals <> v_score.home_score or v_away_goals <> v_score.away_score then
      v_errors := v_errors || jsonb_build_array('score_events_mismatch');
    end if;
  end if;
  if v_score.home_penalties is not null and exists (
    select 1
    from public.tournament_match_events event
    where event.match_operation_id = v_operation.id
      and event.voided_at is null
      and event.period = 'penalties'
      and event.event_type in ('penalty_goal', 'penalty_missed')
  ) then
    select count(*) filter (
        where event.team_entry_id = v_operation.home_team_entry_id
          and event.event_type = 'penalty_goal'
      ),
      count(*) filter (
        where event.team_entry_id = v_operation.away_team_entry_id
          and event.event_type = 'penalty_goal'
      )
    into v_home_shootout_goals, v_away_shootout_goals
    from public.tournament_match_events event
    where event.match_operation_id = v_operation.id
      and event.voided_at is null
      and event.period = 'penalties';
    if v_home_shootout_goals <> v_score.home_penalties
      or v_away_shootout_goals <> v_score.away_penalties
    then
      v_errors := v_errors || jsonb_build_array('penalty_events_mismatch');
    end if;
  end if;
  if v_outcome.outcome_type = 'suspended' and (
    not v_outcome.requires_resolution
    and not exists (
      select 1 from public.tournament_match_resumptions
      where match_operation_id = v_operation.id and status in ('pending', 'scheduled')
    )
  ) then
    v_errors := v_errors || jsonb_build_array('suspension_resolution_required');
  end if;
  if v_outcome.outcome_type in ('home_no_show', 'walkover_away')
    and exists (
      select 1 from public.tournament_match_operation_players player
      where player.match_operation_id = v_operation.id
        and player.team_entry_id = v_operation.home_team_entry_id
        and player.attendance_status in ('present', 'late')
    )
  then
    v_errors := v_errors || jsonb_build_array('home_no_show_presence_conflict');
  end if;
  if v_outcome.outcome_type in ('away_no_show', 'walkover_home')
    and exists (
      select 1 from public.tournament_match_operation_players player
      where player.match_operation_id = v_operation.id
        and player.team_entry_id = v_operation.away_team_entry_id
        and player.attendance_status in ('present', 'late')
    )
  then
    v_errors := v_errors || jsonb_build_array('away_no_show_presence_conflict');
  end if;
  if v_outcome.outcome_type = 'double_no_show'
    and exists (
      select 1 from public.tournament_match_operation_players player
      where player.match_operation_id = v_operation.id
        and player.attendance_status in ('present', 'late')
    )
  then
    v_errors := v_errors || jsonb_build_array('double_no_show_presence_conflict');
  end if;
  return jsonb_build_object(
    'valid', jsonb_array_length(v_errors) = 0,
    'errors', v_errors
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_tournament_match_operation_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_source public.tournament_match_operations%rowtype;
begin
  if new.source_operation_id is null then
    return new;
  end if;
  select * into v_source
  from public.tournament_match_operations
  where id = new.source_operation_id;
  if v_source.id is null
    or v_source.organization_id <> new.organization_id
    or v_source.match_id <> new.match_id
    or new.operation_version <> (
      select coalesce(max(operation.operation_version), 0) + 1
      from public.tournament_match_operations operation
      where operation.match_id = new.match_id
        and operation.id <> new.id
    )
  then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_CORRECTION_SCOPE';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_tournament_match_player_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_player public.tournament_roster_players%rowtype;
  v_roster public.tournament_rosters%rowtype;
  v_squad public.tournament_match_squads%rowtype;
  v_teams record;
begin
  select * into v_player
  from public.tournament_roster_players
  where id = new.roster_player_id;
  if v_player.id is not null then
    select * into v_roster
    from public.tournament_rosters
    where id = v_player.roster_id;
  end if;
  select * into v_teams
  from public.tournament_match_team_entries(new.match_id);
  if v_player.id is null
    or v_player.organization_id <> new.organization_id
    or v_player.team_entry_id <> new.team_entry_id
    or v_player.status <> 'active'
    or v_player.eligibility_status <> 'eligible'
    or v_roster.id is null
    or v_roster.status not in ('approved', 'locked')
    or new.team_entry_id not in (
      v_teams.home_team_entry_id, v_teams.away_team_entry_id
    )
  then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_PLAYER_OUT_OF_SCOPE';
  end if;
  if tg_table_name = 'tournament_match_squad_players' then
    select * into v_squad
    from public.tournament_match_squads where id = new.match_squad_id;
    if v_squad.id is null or v_player.roster_id <> v_squad.roster_id then
      raise exception using errcode = '23514', message = 'TORNEOS_MATCH_PLAYER_OUT_OF_SCOPE';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_tournament_match_schedule(p_organization_id uuid, p_match_id uuid, p_scheduled_at timestamp with time zone, p_venue_id uuid, p_court_id uuid, p_duration_minutes integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_version public.tournament_fixture_versions%rowtype;
  v_tournament public.tournaments%rowtype;
  v_season public.tournament_seasons%rowtype;
  v_category public.tournament_categories%rowtype;
  v_venue public.tournament_venues%rowtype;
  v_court public.tournament_courts%rowtype;
  v_round public.tournament_rounds%rowtype;
  v_duration integer;
  v_buffer integer := 0;
  v_minimum_rest integer := 720;
  v_end timestamptz;
  v_match_end timestamptz;
  v_local_date date;
  v_local_end_date date;
  v_local_time time;
  v_blockers jsonb := '[]'::jsonb;
  v_warnings jsonb := '[]'::jsonb;
  v_other record;
begin
  if auth.uid() is null or p_scheduled_at is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select match_row.* into v_match
  from public.tournament_matches match_row
  where match_row.id = p_match_id and match_row.organization_id = p_organization_id;
  if v_match.id is null or not public.can_read_tournament_fixture_scope(
    p_organization_id, v_match.tournament_id
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  select version.* into v_version from public.tournament_fixture_versions version
  where version.id = v_match.fixture_version_id;
  select tournament.* into v_tournament from public.tournaments tournament
  where tournament.id = v_match.tournament_id;
  select season.* into v_season from public.tournament_seasons season
  where season.id = v_match.season_id;
  select category.* into v_category from public.tournament_categories category
  where category.id = v_match.category_id;
  select venue.* into v_venue from public.tournament_venues venue
  where venue.id = p_venue_id;
  select court.* into v_court from public.tournament_courts court
  where court.id = p_court_id;
  select round_row.* into v_round from public.tournament_rounds round_row
  where round_row.id = v_match.round_id;
  v_duration := coalesce(p_duration_minutes, v_match.duration_minutes);
  if v_duration not between 15 and 240 then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code', 'invalid_duration'));
  end if;
  if v_venue.id is null or v_court.id is null
    or v_venue.organization_id <> p_organization_id
    or v_court.organization_id <> p_organization_id
    or v_court.venue_id <> v_venue.id
  then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code', 'foreign_resource'));
  elsif v_venue.status <> 'active' or v_court.status <> 'active' then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code', 'archived_resource'));
  elsif v_court.sport_modality <> coalesce(v_category.sport_modality, v_tournament.sport_modality) then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code', 'incompatible_modality'));
  end if;
  if v_match.home_participant_id is not null
    and v_match.home_participant_id = v_match.away_participant_id
  then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code', 'self_match'));
  end if;
  if v_match.home_participant_id is null or v_match.away_participant_id is null
    or (
      select count(*)
      from public.tournament_match_sources source
      where source.match_id = v_match.id
    ) <> 2
  then
    v_blockers := v_blockers || jsonb_build_array(
      jsonb_build_object('code', 'unresolved_or_invalid_sources')
    );
  end if;
  if v_version.status not in ('draft', 'published')
    or v_version.invalidated_at is not null
    or v_tournament.status = 'archived'
    or v_category.status = 'archived'
    or v_match.status not in ('unscheduled', 'scheduled', 'postponed')
  then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code', 'inactive_fixture'));
  end if;
  if v_venue.id is not null then
    v_local_date := (p_scheduled_at at time zone v_venue.timezone)::date;
    v_local_time := (p_scheduled_at at time zone v_venue.timezone)::time;
    v_local_end_date := (
      (p_scheduled_at + make_interval(mins => coalesce(v_duration, 0)))
      at time zone v_venue.timezone
    )::date;
  else
    v_local_date := p_scheduled_at::date;
    v_local_time := p_scheduled_at::time;
    v_local_end_date := (
      p_scheduled_at + make_interval(mins => coalesce(v_duration, 0))
    )::date;
  end if;
  if (v_season.start_date is not null and v_local_date < v_season.start_date)
    or (v_season.end_date is not null and v_local_end_date > v_season.end_date)
    or (v_tournament.start_date is not null and v_local_date < v_tournament.start_date)
    or (v_tournament.end_date is not null and v_local_end_date > v_tournament.end_date)
    or (v_round.starts_at is not null and p_scheduled_at < v_round.starts_at)
    or (
      v_round.ends_at is not null
      and p_scheduled_at + make_interval(mins => coalesce(v_duration, 0)) > v_round.ends_at
    )
  then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code', 'outside_date_range'));
  end if;
  select coalesce(max(schedule_window.buffer_minutes), 0) into v_buffer
  from public.tournament_schedule_windows schedule_window
  where schedule_window.organization_id = p_organization_id
    and schedule_window.tournament_id = v_match.tournament_id
    and schedule_window.status = 'active'
    and schedule_window.window_type = 'availability'
    and (schedule_window.category_id is null or schedule_window.category_id = v_match.category_id)
    and (schedule_window.venue_id is null or schedule_window.venue_id = p_venue_id)
    and (schedule_window.court_id is null or schedule_window.court_id = p_court_id)
    and (
      schedule_window.specific_date = v_local_date
      or schedule_window.day_of_week = extract(isodow from v_local_date)::smallint
    )
    and v_local_time >= schedule_window.starts_at
    and v_local_time + make_interval(mins => v_duration) <= schedule_window.ends_at;
  v_match_end := p_scheduled_at + make_interval(mins => v_duration);
  v_end := v_match_end + make_interval(mins => v_buffer);
  if exists (
    select 1 from public.tournament_schedule_windows schedule_window
    where schedule_window.organization_id = p_organization_id
      and schedule_window.tournament_id = v_match.tournament_id
      and schedule_window.status = 'active'
      and schedule_window.window_type = 'availability'
      and (schedule_window.category_id is null or schedule_window.category_id = v_match.category_id)
      and (schedule_window.venue_id is null or schedule_window.venue_id = p_venue_id)
      and (schedule_window.court_id is null or schedule_window.court_id = p_court_id)
  ) and not exists (
    select 1 from public.tournament_schedule_windows schedule_window
    where schedule_window.organization_id = p_organization_id
      and schedule_window.tournament_id = v_match.tournament_id
      and schedule_window.status = 'active'
      and schedule_window.window_type = 'availability'
      and (schedule_window.category_id is null or schedule_window.category_id = v_match.category_id)
      and (schedule_window.venue_id is null or schedule_window.venue_id = p_venue_id)
      and (schedule_window.court_id is null or schedule_window.court_id = p_court_id)
      and (schedule_window.specific_date = v_local_date
        or schedule_window.day_of_week = extract(isodow from v_local_date)::smallint)
      and v_local_time >= schedule_window.starts_at
      and v_local_time + make_interval(mins => v_duration) <= schedule_window.ends_at
  ) then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code', 'outside_schedule_window'));
  end if;
  if exists (
    select 1 from public.tournament_schedule_windows schedule_window
    where schedule_window.organization_id = p_organization_id
      and schedule_window.tournament_id = v_match.tournament_id
      and schedule_window.status = 'active'
      and schedule_window.window_type in ('block', 'closure')
      and (schedule_window.category_id is null or schedule_window.category_id = v_match.category_id)
      and (schedule_window.venue_id is null or schedule_window.venue_id = p_venue_id)
      and (schedule_window.court_id is null or schedule_window.court_id = p_court_id)
      and (schedule_window.specific_date = v_local_date
        or schedule_window.day_of_week = extract(isodow from v_local_date)::smallint)
      and v_local_time < schedule_window.ends_at
      and v_local_time + make_interval(mins => v_duration) > schedule_window.starts_at
  ) then
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object('code', 'blocked_schedule_window'));
  end if;
  for v_other in
    select other.id from public.tournament_matches other
    where other.id <> v_match.id
      and other.organization_id = p_organization_id
      and other.court_id = p_court_id
      and other.scheduled_at is not null
      and other.status not in ('cancelled', 'completed')
      and other.scheduled_at < v_end
      and other.scheduled_at
        + make_interval(mins => coalesce(other.duration_minutes, 60) + v_buffer)
        > p_scheduled_at
  loop
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'court_overlap', 'resourceId', v_other.id
    ));
  end loop;
  for v_other in
    select other.id from public.tournament_matches other
    where other.id <> v_match.id
      and other.organization_id = p_organization_id
      and other.scheduled_at is not null
      and other.status not in ('cancelled', 'completed')
      and other.scheduled_at < v_end
      and other.scheduled_at + make_interval(mins => coalesce(other.duration_minutes, 60))
        > p_scheduled_at
      and array_remove(array[other.home_participant_id, other.away_participant_id], null)
        && array_remove(array[v_match.home_participant_id, v_match.away_participant_id], null)
  loop
    v_blockers := v_blockers || jsonb_build_array(jsonb_build_object(
      'code', 'team_overlap', 'resourceId', v_other.id
    ));
  end loop;
  v_minimum_rest := coalesce(
    (v_version.configuration_snapshot->>'minimumRestMinutes')::integer, 720
  );
  for v_other in
    select other.id, case
      when other.scheduled_at >= v_match_end then
        extract(epoch from (other.scheduled_at - v_match_end)) / 60
      when p_scheduled_at >= (
        other.scheduled_at + make_interval(mins => coalesce(other.duration_minutes, 60))
      ) then
        extract(epoch from (
          p_scheduled_at
          - (other.scheduled_at + make_interval(mins => coalesce(other.duration_minutes, 60)))
        )) / 60
      else 0
    end as minutes
    from public.tournament_matches other
    where other.id <> v_match.id
      and other.organization_id = p_organization_id
      and other.scheduled_at is not null
      and other.status not in ('cancelled', 'completed')
      and array_remove(array[other.home_participant_id, other.away_participant_id], null)
        && array_remove(array[v_match.home_participant_id, v_match.away_participant_id], null)
      and case
        when other.scheduled_at >= v_match_end then
          extract(epoch from (other.scheduled_at - v_match_end)) / 60
        when p_scheduled_at >= (
          other.scheduled_at + make_interval(mins => coalesce(other.duration_minutes, 60))
        ) then
          extract(epoch from (
            p_scheduled_at
            - (other.scheduled_at + make_interval(mins => coalesce(other.duration_minutes, 60)))
          )) / 60
        else 0
      end < v_minimum_rest
  loop
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object(
      'code', 'short_rest', 'resourceId', v_other.id, 'minutes', round(v_other.minutes)
    ));
  end loop;
  if exists (
    select 1
    from unnest(array_remove(
      array[v_match.home_participant_id, v_match.away_participant_id],
      null
    )) candidate_participant(id)
    where (
      select count(*)
      from public.tournament_matches other
      where other.id <> v_match.id
        and other.tournament_id = v_match.tournament_id
        and (other.scheduled_at at time zone v_venue.timezone)::date = v_local_date
        and other.status <> 'cancelled'
        and candidate_participant.id in (
          other.home_participant_id,
          other.away_participant_id
        )
    ) >= coalesce(
      (v_version.configuration_snapshot->>'maximumMatchesPerDay')::integer, 1
    )
  ) then
    v_warnings := v_warnings || jsonb_build_array(jsonb_build_object('code', 'heavy_day_load'));
  end if;
  return jsonb_build_object(
    'valid', jsonb_array_length(v_blockers) = 0,
    'blockers', v_blockers,
    'warnings', v_warnings,
    'bufferMinutes', v_buffer,
    'checkedAt', now()
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_tournament_match_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_version public.tournament_fixture_versions%rowtype;
  v_round public.tournament_rounds%rowtype;
  v_group public.tournament_groups%rowtype;
  v_court public.tournament_courts%rowtype;
begin
  select version.* into v_version
  from public.tournament_fixture_versions version
  where version.id = new.fixture_version_id;
  select round_row.* into v_round
  from public.tournament_rounds round_row
  where round_row.id = new.round_id;
  if v_version.id is null or v_round.id is null
    or v_version.organization_id <> new.organization_id
    or v_version.season_id <> new.season_id
    or v_version.tournament_id <> new.tournament_id
    or v_version.category_id <> new.category_id
    or v_version.participant_set_id <> new.participant_set_id
    or v_round.fixture_version_id <> new.fixture_version_id
    or v_round.phase_id <> new.phase_id
  then
    raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
  end if;
  if new.group_id is not null then
    select group_row.* into v_group
    from public.tournament_groups group_row
    where group_row.id = new.group_id;
    if v_group.id is null
      or v_group.organization_id <> new.organization_id
      or v_group.tournament_id <> new.tournament_id
      or v_group.category_id <> new.category_id
      or v_group.fixture_version_id <> new.fixture_version_id
      or v_group.phase_id <> new.phase_id
      or v_round.group_id is distinct from new.group_id
    then
      raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
    end if;
  elsif v_round.group_id is not null then
    raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
  end if;
  if new.court_id is not null then
    select court.* into v_court
    from public.tournament_courts court
    where court.id = new.court_id;
    if v_court.id is null
      or v_court.organization_id <> new.organization_id
      or v_court.venue_id <> new.venue_id
    then
      raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_tournament_match_source_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_match public.tournament_matches%rowtype;
  v_source_match public.tournament_matches%rowtype;
  v_participant public.tournament_competition_participants%rowtype;
  v_group public.tournament_groups%rowtype;
  v_phase public.tournament_phases%rowtype;
  v_tie_count integer;
  v_tie_last_match integer;
begin
  select match_row.* into v_match
  from public.tournament_matches match_row
  where match_row.id = new.match_id;
  if v_match.id is null
    or v_match.organization_id <> new.organization_id
    or v_match.tournament_id <> new.tournament_id
    or v_match.category_id <> new.category_id
    or v_match.fixture_version_id <> new.fixture_version_id
  then
    raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
  end if;
  if new.participant_id is not null then
    select participant.* into v_participant
    from public.tournament_competition_participants participant
    where participant.id = new.participant_id;
    if v_participant.id is null
      or v_participant.organization_id <> new.organization_id
      or v_participant.tournament_id <> new.tournament_id
      or v_participant.category_id <> new.category_id
      or v_participant.participant_set_id <> v_match.participant_set_id
    then
      raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
    end if;
  end if;
  if new.group_id is not null then
    select group_row.* into v_group
    from public.tournament_groups group_row
    where group_row.id = new.group_id;
    if v_group.id is null
      or v_group.organization_id <> new.organization_id
      or v_group.tournament_id <> new.tournament_id
      or v_group.category_id <> new.category_id
      or v_group.fixture_version_id <> new.fixture_version_id
    then
      raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
    end if;
  end if;
  if new.source_phase_id is not null then
    select phase.* into v_phase
    from public.tournament_phases phase
    where phase.id = new.source_phase_id;
    if v_phase.id is null
      or v_phase.organization_id <> new.organization_id
      or v_phase.tournament_id <> new.tournament_id
      or v_phase.category_id <> new.category_id
      or v_phase.fixture_version_id <> new.fixture_version_id
      or v_phase.sequence_number >= (
        select target_phase.sequence_number
        from public.tournament_phases target_phase
        where target_phase.id = v_match.phase_id
      )
    then
      raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
    end if;
  end if;
  if new.source_match_id is not null then
    select source_match.* into v_source_match
    from public.tournament_matches source_match
    where source_match.id = new.source_match_id;
    if v_source_match.id is null
      or v_source_match.fixture_version_id <> new.fixture_version_id
    then
      raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
    end if;
    if v_source_match.match_number >= v_match.match_number
    then
      raise exception using errcode = '23514', message = 'TORNEOS_CYCLIC_MATCH_SOURCE';
    end if;
  end if;
  if new.source_tie_key is not null then
    select count(*), max(tie_match.match_number)
    into v_tie_count, v_tie_last_match
    from public.tournament_matches tie_match
    where tie_match.fixture_version_id = new.fixture_version_id
      and tie_match.tie_key = new.source_tie_key;
    if v_tie_count <> 2 or v_tie_last_match >= v_match.match_number then
      raise exception using errcode = '23514', message = 'TORNEOS_CYCLIC_MATCH_SOURCE';
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_tournament_match_squad_scope()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_roster public.tournament_rosters%rowtype;
  v_match public.tournament_matches%rowtype;
  v_teams record;
begin
  select * into v_match
  from public.tournament_matches
  where id = new.match_id and organization_id = new.organization_id;
  select * into v_roster
  from public.tournament_rosters
  where id = new.roster_id
    and organization_id = new.organization_id
    and team_entry_id = new.team_entry_id;
  select * into v_teams
  from public.tournament_match_team_entries(new.match_id);
  if v_match.id is null
    or v_roster.id is null
    or v_roster.status not in ('approved', 'locked')
    or new.team_entry_id not in (
      v_teams.home_team_entry_id, v_teams.away_team_entry_id
    )
  then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_SQUAD_SCOPE';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.validate_tournament_roster(p_organization_id uuid, p_team_entry_id uuid, p_roster_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_entry public.tournament_team_entries%rowtype;
  v_settings public.tournament_roster_settings%rowtype;
  v_count integer;
  v_goalkeepers integer;
  v_missing_numbers integer;
  v_missing_positions integer;
  v_repeated_numbers integer;
  v_cross_team integer;
  v_pending_eligibility integer;
  v_errors text[] := array[]::text[];
  v_warnings text[] := array[]::text[];
begin
  if auth.uid() is null or not public.can_read_tournament_team_entry(
    p_organization_id, p_team_entry_id
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  select * into v_entry from public.tournament_team_entries
  where id = p_team_entry_id and organization_id = p_organization_id;
  select * into v_settings from public.tournament_roster_settings
  where tournament_id = v_entry.tournament_id and organization_id = p_organization_id;

  if v_entry.id is null or v_settings.tournament_id is null or not exists (
    select 1 from public.tournament_rosters
    where id = p_roster_id and team_entry_id = p_team_entry_id
      and organization_id = p_organization_id
  ) or not exists (
    select 1
    from public.tournament_organizations organization
    join public.tournaments tournament
      on tournament.organization_id = organization.id
    join public.tournament_categories category
      on category.organization_id = tournament.organization_id
      and category.tournament_id = tournament.id
    where organization.id = p_organization_id
      and organization.status = 'active'
      and tournament.id = v_entry.tournament_id
      and tournament.status <> 'archived'
      and category.id = v_entry.category_id
      and category.status = 'active'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  select
    count(*),
    count(*) filter (where is_goalkeeper),
    count(*) filter (where shirt_number is null),
    count(*) filter (where primary_position is null),
    count(*) filter (where eligibility_status <> 'eligible')
  into v_count, v_goalkeepers, v_missing_numbers, v_missing_positions,
    v_pending_eligibility
  from public.tournament_roster_players
  where roster_id = p_roster_id and status = 'active';

  select count(*) into v_repeated_numbers from (
    select shirt_number
    from public.tournament_roster_players
    where roster_id = p_roster_id and status = 'active' and shirt_number is not null
    group by shirt_number having count(*) > 1
  ) repeated;

  select count(*) into v_cross_team
  from public.tournament_roster_players current_player
  join public.tournament_team_entries current_entry
    on current_entry.id = current_player.team_entry_id
  join public.tournament_roster_players other_player
    on other_player.team_entry_id <> current_player.team_entry_id
    and other_player.status = 'active'
    and (
      (
        current_player.arma2_user_id is not null
        and other_player.arma2_user_id = current_player.arma2_user_id
      )
      or (
        current_player.provisional_player_id is not null
        and other_player.provisional_player_id = current_player.provisional_player_id
      )
    )
  join public.tournament_team_entries other_entry
    on other_entry.id = other_player.team_entry_id
    and other_entry.tournament_id = current_entry.tournament_id
    and other_entry.category_id = current_entry.category_id
    and other_entry.status = 'approved'
  where current_player.roster_id = p_roster_id
    and current_player.status = 'active'
    and num_nonnulls(
      current_player.arma2_user_id,
      current_player.provisional_player_id
    ) = 1;

  if v_count < v_settings.minimum_players then v_errors := array_append(v_errors, 'minimum_players'); end if;
  if v_count > v_settings.maximum_players then v_errors := array_append(v_errors, 'maximum_players'); end if;
  if v_goalkeepers < v_settings.minimum_goalkeepers then v_errors := array_append(v_errors, 'minimum_goalkeepers'); end if;
  if v_settings.shirt_number_required and v_missing_numbers > 0 then v_errors := array_append(v_errors, 'shirt_number_required'); end if;
  if v_settings.position_required and v_missing_positions > 0 then v_errors := array_append(v_errors, 'position_required'); end if;
  if v_settings.unique_shirt_numbers and v_repeated_numbers > 0 then v_errors := array_append(v_errors, 'duplicate_shirt_number'); end if;
  if not v_settings.allow_player_multiple_teams and v_cross_team > 0 then v_errors := array_append(v_errors, 'player_already_approved'); end if;
  if v_settings.require_individual_player_approval and v_pending_eligibility > 0 then
    v_errors := array_append(v_errors, 'player_approval_required');
  end if;

  if exists (
    select 1
    from public.tournament_roster_players left_player
    join public.tournament_roster_players right_player
      on right_player.roster_id = left_player.roster_id
      and right_player.id > left_player.id
      and public.normalize_tournament_person_name(right_player.display_name)
        = public.normalize_tournament_person_name(left_player.display_name)
    where left_player.roster_id = p_roster_id
      and left_player.status = 'active'
      and right_player.status = 'active'
  ) then
    v_warnings := array_append(v_warnings, 'similar_player_names');
  end if;

  return jsonb_build_object(
    'valid', cardinality(v_errors) = 0,
    'errors', to_jsonb(v_errors),
    'warnings', to_jsonb(v_warnings),
    'counts', jsonb_build_object(
      'players', v_count,
      'goalkeepers', v_goalkeepers,
      'minimumPlayers', v_settings.minimum_players,
      'maximumPlayers', v_settings.maximum_players
    )
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.void_tournament_match_event(p_organization_id uuid, p_event_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_event public.tournament_match_events%rowtype;
  v_operation public.tournament_match_operations%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_event from public.tournament_match_events
  where id = p_event_id and organization_id = p_organization_id;
  select * into v_operation from public.tournament_match_operations
  where id = v_event.match_operation_id and organization_id = p_organization_id
  for update;
  select * into v_event from public.tournament_match_events
  where id = p_event_id and organization_id = p_organization_id
  for update;
  if v_event.id is null or v_event.voided_at is not null or v_operation.status <> 'draft'
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_events.void'
    )
    or char_length(btrim(coalesce(p_reason, ''))) not between 3 and 500
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  update public.tournament_match_events set
    voided_at = now(), voided_by = auth.uid(), void_reason = btrim(p_reason)
  where id = p_event_id returning * into v_event;
  perform public.append_tournament_audit(
    p_organization_id, 'match_event.voided', 'match_event', v_event.id,
    v_event.team_entry_id, v_operation.tournament_id,
    jsonb_build_object('eventType', v_event.event_type)
  );
  return to_jsonb(v_event);
end;
$function$

CREATE OR REPLACE FUNCTION public.void_tournament_match_operation(p_organization_id uuid, p_match_operation_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_operation public.tournament_match_operations%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null or v_operation.status in ('official', 'superseded', 'voided')
    or char_length(btrim(coalesce(p_reason, ''))) not between 3 and 1000
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_operations.void'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  update public.tournament_match_operations set
    status = 'voided', match_status = 'voided', notes = btrim(p_reason),
    closed_at = now(), updated_at = now()
  where id = v_operation.id;
  perform public.append_tournament_audit(
    p_organization_id, 'match_operation.voided', 'match_operation',
    v_operation.id, null, v_operation.tournament_id, '{}'::jsonb
  );
  return public.get_tournament_match_operation_context(p_organization_id, v_operation.id);
end;
$function$

CREATE OR REPLACE FUNCTION public.withdraw_tournament_competition_participant(p_organization_id uuid, p_tournament_id uuid, p_team_entry_id uuid, p_reason_code text, p_reason_text text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_tournament public.tournaments%rowtype;
  v_participant public.tournament_competition_participants%rowtype;
  v_entry public.tournament_team_entries%rowtype;
  v_reason_code text := btrim(coalesce(p_reason_code, ''));
  v_reason_text text := nullif(btrim(coalesce(p_reason_text, '')), '');
  v_open_operations integer;
  v_match_ids uuid[];
  v_affected integer;
  v_preserved integer;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(
    p_organization_id, 'participants.withdraw'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if v_reason_code not in (
    'voluntary_resignation', 'sanction_exclusion', 'regulatory_breach', 'other'
  ) then
    raise exception using errcode = '22023',
      message = 'TORNEOS_WITHDRAWAL_REASON_INVALID';
  end if;
  if v_reason_code = 'other'
    and char_length(coalesce(v_reason_text, '')) < 3
  then
    raise exception using errcode = '22023',
      message = 'TORNEOS_WITHDRAWAL_NOTE_REQUIRED';
  end if;
  if char_length(coalesce(v_reason_text, '')) > 2000 then
    raise exception using errcode = '22023',
      message = 'TORNEOS_WITHDRAWAL_NOTE_TOO_LONG';
  end if;

  -- (1) Lock de competencia y participante.
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:competition-lifecycle:' || p_tournament_id::text, 0
  ));

  select tournament.* into v_tournament
  from public.tournaments tournament
  join public.tournament_organizations organization
    on organization.id = tournament.organization_id
    and organization.status = 'active'
  where tournament.id = p_tournament_id
    and tournament.organization_id = p_organization_id
  for update of tournament;

  if v_tournament.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  -- (2) El retiro estructural pertenece a una competencia ya consolidada:
  -- participantes congelados y fixture publicado.
  if v_tournament.status not in ('scheduled', 'active') then
    raise exception using errcode = '22023',
      message = 'TORNEOS_INVALID_TOURNAMENT_TRANSITION';
  end if;

  select entry.* into v_entry
  from public.tournament_team_entries entry
  where entry.id = p_team_entry_id
    and entry.organization_id = p_organization_id
    and entry.tournament_id = p_tournament_id
  for update;

  if v_entry.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  select participant.* into v_participant
  from public.tournament_competition_participants participant
  join public.tournament_fixture_versions fixture
    on fixture.organization_id = participant.organization_id
    and fixture.tournament_id = participant.tournament_id
    and fixture.category_id = participant.category_id
    and fixture.participant_set_id = participant.participant_set_id
    and fixture.status = 'published'
    and fixture.invalidated_at is null
  where participant.organization_id = p_organization_id
    and participant.tournament_id = p_tournament_id
    and participant.team_entry_id = p_team_entry_id
  order by participant.created_at desc
  limit 1
  for update of participant;

  if v_participant.id is null then
    raise exception using errcode = '42501',
      message = 'TORNEOS_PARTICIPANT_NOT_IN_COMPETITION';
  end if;

  if v_participant.status <> 'active' then
    raise exception using errcode = '22023',
      message = 'TORNEOS_PARTICIPANT_ALREADY_WITHDRAWN';
  end if;

  -- (3) Un acta abierta bloquea el retiro: cerrarla o anularla es una decisión
  -- deportiva del organizador, no algo que esta operación deba destruir.
  select count(*) into v_open_operations
  from public.tournament_match_operations operation
  join public.tournament_matches match_row
    on match_row.id = operation.match_id
  where match_row.tournament_id = p_tournament_id
    and (
      match_row.home_participant_id = v_participant.id
      or match_row.away_participant_id = v_participant.id
    )
    and operation.status in (
      'draft', 'submitted', 'under_review', 'validated', 'correction_requested'
    );

  if v_open_operations > 0 then
    raise exception using errcode = '22023',
      message = 'TORNEOS_PARTICIPANT_HAS_OPEN_OPERATIONS',
      detail = v_open_operations::text;
  end if;

  -- (4) Compromisos futuros todavía abiertos. Un partido con cualquier acta
  -- viva —oficial incluida— queda intacto: el pasado deportivo no se reescribe.
  select array_agg(match_row.id order by match_row.match_number)
  into v_match_ids
  from public.tournament_matches match_row
  join public.tournament_fixture_versions fixture
    on fixture.id = match_row.fixture_version_id
    and fixture.status = 'published'
    and fixture.invalidated_at is null
  where match_row.organization_id = p_organization_id
    and match_row.tournament_id = p_tournament_id
    and match_row.status <> 'cancelled'
    and (
      match_row.home_participant_id = v_participant.id
      or match_row.away_participant_id = v_participant.id
    )
    and not exists (
      select 1
      from public.tournament_match_operations operation
      where operation.match_id = match_row.id
        and operation.status not in ('superseded', 'voided')
    );

  v_affected := coalesce(array_length(v_match_ids, 1), 0);

  select count(*) into v_preserved
  from public.tournament_matches match_row
  where match_row.tournament_id = p_tournament_id
    and (
      match_row.home_participant_id = v_participant.id
      or match_row.away_participant_id = v_participant.id
    )
    and (v_match_ids is null or not (match_row.id = any(v_match_ids)));

  -- (5) Fecha libre estructural: el partido se conserva con sus dos equipos
  -- originales, en un estado terminal que no exige jugarse, no otorga puntos
  -- ni estadísticas y guarda la razón.
  if v_affected > 0 then
    update public.tournament_matches
    set status = 'cancelled',
        cancelled_at = now(),
        cancelled_by = auth.uid(),
        cancellation_reason_code = 'withdrawal_bye',
        cancellation_reason_text = left(
          coalesce(v_reason_text, 'Retiro del equipo durante la competencia.'), 500
        ),
        withdrawn_participant_id = v_participant.id
    where id = any(v_match_ids);
  end if;

  -- (6) Auditoría estructurada antes de tocar el participante.
  perform public.append_tournament_audit(
    p_organization_id, 'participant.withdrawn', 'competition_participant',
    v_participant.id, v_entry.id, p_tournament_id,
    jsonb_build_object(
      'teamEntryId', v_entry.id,
      'teamName', v_participant.snapshot_name,
      'categoryId', v_participant.category_id,
      'participantSetId', v_participant.participant_set_id,
      'previousParticipantStatus', v_participant.status,
      'previousEntryStatus', v_entry.status,
      'tournamentStatus', v_tournament.status,
      'reasonCode', v_reason_code,
      'reasonText', left(coalesce(v_reason_text, ''), 2000),
      'affectedMatchCount', v_affected,
      'preservedMatchCount', v_preserved,
      'affectedMatchIds', to_jsonb(coalesce(v_match_ids[1:50], array[]::uuid[]))
    )
  );

  -- (7) Recién ahora se marca el retiro.
  update public.tournament_competition_participants
  set status = 'withdrawn',
      withdrawn_at = now(),
      withdrawn_by = auth.uid(),
      withdrawal_reason_code = v_reason_code,
      withdrawal_reason_text = v_reason_text
  where id = v_participant.id
  returning * into v_participant;

  if v_entry.status = 'approved' then
    update public.tournament_team_entries
    set status = 'withdrawn',
        withdrawn_at = now(),
        updated_at = now()
    where id = v_entry.id;
  end if;

  return jsonb_build_object(
    'participantId', v_participant.id,
    'teamEntryId', v_entry.id,
    'status', v_participant.status,
    'reasonCode', v_reason_code,
    'withdrawnAt', v_participant.withdrawn_at,
    'byeMatchCount', v_affected,
    'preservedMatchCount', v_preserved,
    'byeMatchIds', to_jsonb(coalesce(v_match_ids, array[]::uuid[]))
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.withdraw_tournament_team_entry(p_organization_id uuid, p_team_entry_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_entry public.tournament_team_entries%rowtype;
begin
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_entry from public.tournament_team_entries
  where id = p_team_entry_id and organization_id = p_organization_id for update;
  if v_entry.id is null or v_entry.status not in ('draft','invited','in_progress','changes_requested','approved')
    or not (
      public.has_tournament_organization_capability(p_organization_id, 'team_entries.withdraw')
      or exists (
        select 1
        from public.tournament_team_managers manager
        where manager.team_entry_id = v_entry.id
          and manager.organization_id = v_entry.organization_id
          and manager.user_id = auth.uid()
          and manager.status = 'active'
          and manager.role in ('captain', 'delegate')
      )
    )
    or not exists (
      select 1
      from public.tournaments tournament
      join public.tournament_categories category
        on category.organization_id = tournament.organization_id
        and category.tournament_id = tournament.id
      where tournament.id = v_entry.tournament_id
        and tournament.organization_id = p_organization_id
        and tournament.status in ('draft', 'registration')
        and category.id = v_entry.category_id
        and category.status = 'active'
    )
  then raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN'; end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 3 then
    raise exception using errcode = '22023', message = 'TORNEOS_REASON_REQUIRED';
  end if;
  update public.tournament_team_entries set status = 'withdrawn', withdrawn_at = now()
  where id = v_entry.id returning * into v_entry;
  perform public.append_tournament_audit(
    p_organization_id, 'team_entry.withdrawn', 'team_entry', v_entry.id,
    v_entry.id, v_entry.tournament_id, jsonb_build_object('reason', left(btrim(p_reason), 240))
  );
  return jsonb_build_object('entryId', v_entry.id, 'status', v_entry.status);
end;
$function$
